#[derive(Clone, Debug, Eq, PartialEq)]
pub struct EngineError {
    message: String,
}

impl EngineError {
    pub fn new(message: impl Into<String>) -> Self {
        Self {
            message: message.into(),
        }
    }
}

impl fmt::Display for EngineError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(&self.message)
    }
}

impl std::error::Error for EngineError {}

#[derive(Clone, Debug)]
struct ManaActivation {
    /// Full declaration for an ordered world-sensitive activation. Legacy pure
    /// projections carry no shadow execution or invented decision.
    declaration: Option<Box<LegalAction>>,
    source_id: String,
    origin: Option<ManaProgramOrigin>,
    symbols: Vec<String>,
    life_cost: i32,
    activation_requirement: ManaRequirement,
    sacrifices_source: bool,
}

#[derive(Clone, Debug)]
struct ManaChoice {
    /// Intrinsic/granted base production before event transformations.
    /// Printed rule producers retain their rule-index program instead.
    intrinsic_symbols: Option<Vec<String>>,
    origin: Option<ManaProgramOrigin>,
    symbols: Vec<String>,
    snow: bool,
    life_cost: i32,
    spend_restriction: Option<Value>,
    activation_requirement: ManaRequirement,
    sacrifices_source: bool,
}

#[derive(Clone, Debug, Default)]
struct ManaPayment {
    ordered: bool,
    activations: Vec<ManaActivation>,
    phyrexian_life_paid: i32,
    pool_indices: Vec<usize>,
    pool_symbols: Vec<String>,
    cant_be_countered: bool,
}

#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct ManaPaymentSearchState {
    requirement_colored: BTreeMap<String, i32>,
    requirement_generic: i32,
    requirement_hybrid: Vec<Vec<String>>,
    requirement_phyrexian: BTreeMap<String, i32>,
    requirement_snow: i32,
    remaining_life: i32,
    symbols: BTreeMap<String, usize>,
    snow_mana: usize,
    used_pool: Vec<bool>,
    used_sources: Vec<bool>,
}

fn mana_payment_decision(payment: &ManaPayment) -> Value {
    let mut decisions = payment
        .activations
        .iter()
        .map(|activation| {
            let mut receipt = json!({
                "lifePaid": activation.life_cost,
                "mana": activation.symbols,
                "ruleIndex": activation.origin.as_ref().and_then(ManaProgramOrigin::native_index),
                "sacrificesSource": activation.sacrifices_source,
                "sourceId": activation.source_id,
            });
            if let Some(origin @ ManaProgramOrigin::Granted { .. }) = &activation.origin {
                receipt["grantedManaProgram"] = json!(origin);
            }
            if let Some(declaration) = &activation.declaration {
                receipt["activationDeclaration"] = json!(declaration);
            }
            receipt
        })
        .collect::<Vec<_>>();
    if payment.phyrexian_life_paid > 0 {
        decisions.push(json!({
            "kind": "phyrexianManaPayment",
            "lifePaid": payment.phyrexian_life_paid,
            "mana": [],
            "ruleIndex": null,
            "sourceId": null,
        }));
    }
    if payment.cant_be_countered || !payment.pool_symbols.is_empty() || payment.ordered {
        let mut metadata = json!({
            "kind": "manaPaymentMetadata",
            "cantBeCountered": payment.cant_be_countered,
            "manaPoolSymbols": payment.pool_symbols,
        });
        if payment.ordered {
            metadata["orderedManaPayment"] = Value::Bool(true);
        }
        decisions.push(metadata);
    }
    Value::Array(decisions)
}

fn mana_spent_from_cast_decisions(decisions: &BTreeMap<String, Value>) -> i32 {
    if mana_postcost_ordered::is_ordered_payment(decisions) {
        return decisions
            .get("manaPoolPayment")
            .and_then(Value::as_array)
            .and_then(|indices| i32::try_from(indices.len()).ok())
            .unwrap_or(0);
    }
    let activated_mana = decisions
        .get("manaPayment")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter(|payment| value_kind(payment) != Some("phyrexianManaPayment"))
        .map(|payment| {
            payment["mana"]
                .as_array()
                .map(|symbols| symbols.len())
                .unwrap_or(0)
        })
        .sum::<usize>();
    let pooled_mana = decisions
        .get("manaPoolPayment")
        .and_then(Value::as_array)
        .map(|indices| indices.len())
        .unwrap_or(0);
    i32::try_from(activated_mana.saturating_add(pooled_mana)).unwrap_or(i32::MAX)
}

fn mana_colors_spent_from_cast_decisions(decisions: &BTreeMap<String, Value>) -> i32 {
    if mana_postcost_ordered::is_ordered_payment(decisions) {
        return decisions
            .get("manaPayment")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter(|entry| value_kind(entry) == Some("manaPaymentMetadata"))
            .flat_map(|entry| entry["manaPoolSymbols"].as_array().into_iter().flatten())
            .filter_map(Value::as_str)
            .filter(|symbol| matches!(*symbol, "W" | "U" | "B" | "R" | "G"))
            .collect::<BTreeSet<_>>()
            .len() as i32;
    }
    let colors = decisions
        .get("manaPayment")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .flat_map(|payment| {
            payment["mana"]
                .as_array()
                .into_iter()
                .flatten()
                .chain(payment["manaPoolSymbols"].as_array().into_iter().flatten())
        })
        .filter_map(Value::as_str)
        .filter(|symbol| matches!(*symbol, "W" | "U" | "B" | "R" | "G"))
        .collect::<BTreeSet<_>>()
        .len();
    i32::try_from(colors).unwrap_or(5)
}

fn mana_symbol_spent_count(decisions: &BTreeMap<String, Value>, wanted: &str) -> usize {
    decisions
        .get("manaPayment")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .flat_map(|payment| {
            payment["mana"]
                .as_array()
                .into_iter()
                .flatten()
                .chain(payment["manaPoolSymbols"].as_array().into_iter().flatten())
        })
        .filter_map(Value::as_str)
        .filter(|symbol| symbol.eq_ignore_ascii_case(wanted))
        .count()
}

