fn default_opening_hand_size() -> usize {
    7
}

fn default_max_hand_size() -> usize {
    DEFAULT_MAX_HAND_SIZE
}

fn is_false(value: &bool) -> bool {
    !value
}

fn stack_object_is_spell(object: &StackObject) -> bool {
    object.ability_kind.is_none() && object.ability_rule.is_none()
}

fn stable_client_seed(seed: u64, player_id: &str) -> u64 {
    player_id
        .bytes()
        .fold(seed ^ 0xCBF2_9CE4_8422_2325, |value, byte| {
            (value ^ u64::from(byte)).wrapping_mul(0x0000_0100_0000_01B3)
        })
}

fn decision_state_summary(state: &GameState) -> DecisionStateSummary {
    DecisionStateSummary {
        turn_number: state.turn_number,
        step: state.step.clone(),
        active_player_id: state.players[state.active_player].id.clone(),
        priority_player_id: state
            .priority_player
            .and_then(|index| state.players.get(index))
            .map(|player| player.id.clone()),
        stack_depth: state.stack.len(),
        event_count: state.events.len(),
        players: state
            .players
            .iter()
            .map(|player| ClientPlayerStateSummary {
                id: player.id.clone(),
                has_lost: player.has_lost,
                life: player.life,
                library_count: player.library.len(),
                hand_count: player.hand.len(),
                battlefield_count: player.battlefield.len(),
                graveyard_count: player.graveyard.len(),
                exile_count: player.exile.len(),
                sideboard_count: player.sideboard.len(),
            })
            .collect(),
    }
}

fn duplicate_zone_object_ids(state: &GameState) -> Vec<String> {
    let mut seen = BTreeSet::new();
    let mut duplicates = BTreeSet::new();
    for player in &state.players {
        for card in player
            .library
            .iter()
            .chain(&player.hand)
            .chain(&player.battlefield)
            .chain(&player.graveyard)
            .chain(&player.exile)
            .chain(&player.sideboard)
            .chain(&player.command_zone)
        {
            if !seen.insert(card.instance_id.clone()) {
                duplicates.insert(card.instance_id.clone());
            }
        }
    }
    for object in state
        .stack
        .iter()
        .filter(|object| stack_object_is_spell(object))
    {
        if !seen.insert(object.card.instance_id.clone()) {
            duplicates.insert(object.card.instance_id.clone());
        }
    }
    duplicates.into_iter().collect()
}

fn value_kind(value: &Value) -> Option<&str> {
    value.as_object()?.get("kind")?.as_str()
}

fn value_contains_string(value: &Value, expected: &str) -> bool {
    match value {
        Value::String(value) => value == expected,
        Value::Array(values) => values
            .iter()
            .any(|value| value_contains_string(value, expected)),
        Value::Object(values) => values
            .values()
            .any(|value| value_contains_string(value, expected)),
        Value::Null | Value::Bool(_) | Value::Number(_) => false,
    }
}

fn type_line_contains(type_line: &str, value: &str) -> bool {
    type_line
        .split(|character: char| !character.is_alphanumeric())
        .any(|part| part.eq_ignore_ascii_case(value))
}

fn has_card_type(card: &CardDefinition, card_type: &str) -> bool {
    type_line_contains(&card.type_line, card_type)
}

fn split_type_line(type_line: &str) -> Option<(&str, &str)> {
    [" \u{2014} ", " - ", " \u{2013} "]
        .into_iter()
        .find_map(|separator| type_line.split_once(separator))
}

fn type_line_subtypes(type_line: &str) -> &str {
    split_type_line(type_line)
        .map(|(_, subtypes)| subtypes)
        .unwrap_or_default()
}

fn has_card_subtype(card: &CardDefinition, subtype: &str) -> bool {
    type_line_contains(type_line_subtypes(&card.type_line), subtype)
}

fn is_land(card: &CardDefinition) -> bool {
    has_card_type(card, "land")
}

fn is_creature(card: &CardDefinition) -> bool {
    has_card_type(card, "creature")
}

fn is_instant(card: &CardDefinition) -> bool {
    has_card_type(card, "instant")
}

fn is_sorcery(card: &CardDefinition) -> bool {
    has_card_type(card, "sorcery")
}

fn is_deck_library_card(card: &CardDefinition) -> bool {
    !card.is_sideboard
        && !card.is_token
        && !card.is_game_piece
        && !has_card_type(card, "token")
        && !is_commander_definition(card)
}

fn is_deck_library_card_for_mode(card: &CardDefinition, game_mode: GameMode) -> bool {
    if game_mode == GameMode::Training {
        !card.is_sideboard && !card.is_token && !card.is_game_piece && !has_card_type(card, "token")
    } else {
        is_deck_library_card(card)
    }
}

fn is_sideboard_card(card: &CardDefinition) -> bool {
    card.is_sideboard && !card.is_token && !card.is_game_piece && !has_card_type(card, "token")
}

fn card_instance(player_id: &str, definition: &CardDefinition, index: usize) -> CardInstance {
    let mut card = CardInstance {
        instance_id: format!("{player_id}:{}:{index}", definition.id),
        definition: definition.clone(),
        printed_definition: Some(definition.clone()),
        owner: player_id.to_string(),
        controller: player_id.to_string(),
        tapped: false,
        summoning_sick: false,
        damage_marked: 0,
        power_modifier: 0,
        toughness_modifier: 0,
        counters: BTreeMap::new(),
        flags: BTreeMap::new(),
        battle_protector: None,
        attached_to: None,
    };
    apply_card_face(&mut card, 0);
    card
}

fn apply_card_face(card: &mut CardInstance, face_index: usize) -> bool {
    let printed = card
        .printed_definition
        .as_ref()
        .unwrap_or(&card.definition)
        .clone();
    let Some(face) = printed.printed_rules().iter().find_map(|rule| {
        (value_kind(rule) == Some("rulesMarker"))
            .then(|| rule["transformFaces"].as_array())
            .flatten()
            .and_then(|faces| faces.get(face_index))
    }) else {
        return false;
    };

    let mut definition = printed.clone();
    definition.name = face["name"].as_str().unwrap_or(&printed.name).to_string();
    definition.type_line = face["typeLine"]
        .as_str()
        .unwrap_or(&printed.type_line)
        .to_string();
    definition.mana_cost = face["manaCost"].as_str().unwrap_or_default().to_string();
    definition.power = face
        .get("power")
        .filter(|value| !value.is_null())
        .and_then(Value::as_str)
        .map(ToOwned::to_owned);
    definition.toughness = face
        .get("toughness")
        .filter(|value| !value.is_null())
        .and_then(Value::as_str)
        .map(ToOwned::to_owned);
    definition.printed_rules_mut().retain(|rule| {
        rule["activeFaceIndex"]
            .as_u64()
            .is_none_or(|index| index == face_index as u64)
    });
    let starting_loyalty = face["loyalty"]
        .as_str()
        .and_then(|loyalty| loyalty.parse::<i32>().ok());
    for rule in definition.printed_rules_mut() {
        if value_kind(rule) != Some("rulesMarker") || !rule["transformFaces"].is_array() {
            continue;
        }
        if let Some(starting_loyalty) = starting_loyalty {
            rule["startingLoyalty"] = Value::from(starting_loyalty);
        } else if let Some(rule) = rule.as_object_mut() {
            rule.remove("startingLoyalty");
        }
    }
    definition.printed_rules_mut().extend(
        card.definition
            .printed_rules()
            .iter()
            .filter(|rule| rule.get("activeFaceIndex").is_none())
            .filter(|rule| !printed.printed_rules().contains(rule))
            .cloned(),
    );
    if let Some(starting_loyalty) = face["loyalty"]
        .as_str()
        .and_then(|value| value.parse::<i32>().ok())
    {
        definition.printed_rules_mut().push(json!({
            "kind": "rulesMarker",
            "activeFaceIndex": face_index,
            "startingLoyalty": { "kind": "integer", "value": starting_loyalty },
        }));
    }
    card.definition = definition;
    if face_index == 0 {
        card.flags.remove("transformed");
    } else {
        card.flags.insert("transformed".to_string(), true);
    }
    true
}

fn split_face_definitions(card: &CardDefinition) -> Vec<CardDefinition> {
    let Some(faces) = card.printed_rules().iter().find_map(|rule| {
        (value_kind(rule) == Some("rulesMarker"))
            .then(|| rule["splitFaces"].as_array())
            .flatten()
    }) else {
        return Vec::new();
    };
    faces
        .iter()
        .filter_map(|face| {
            let mut definition = card.clone();
            definition.name = face["name"].as_str()?.to_string();
            definition.type_line = face["typeLine"].as_str()?.to_string();
            definition.mana_cost = face["manaCost"].as_str().unwrap_or_default().to_string();
            definition.power = face["power"].as_str().map(ToOwned::to_owned);
            definition.toughness = face["toughness"].as_str().map(ToOwned::to_owned);
            definition.set_printed_rules(face["rules"].as_array()?.clone());
            Some(definition)
        })
        .collect()
}

fn replace_exact_json_string(value: &mut Value, from: &str, to: &str) {
    match value {
        Value::Array(values) => {
            for value in values {
                replace_exact_json_string(value, from, to);
            }
        }
        Value::Object(values) => {
            for value in values.values_mut() {
                replace_exact_json_string(value, from, to);
            }
        }
        Value::String(text) if text == from => *text = to.to_string(),
        _ => {}
    }
}

fn namespace_rule_declarations(rule: &mut Value, namespace: &str) {
    let decision_ids = rule["declaration"]["decisions"]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(|decision| decision["id"].as_str().map(ToOwned::to_owned))
        .collect::<Vec<_>>();
    for decision_id in decision_ids {
        replace_exact_json_string(rule, &decision_id, &format!("{namespace}:{decision_id}"));
    }
}

fn fused_split_definition(card: &CardDefinition) -> Option<CardDefinition> {
    let faces = split_face_definitions(card);
    if faces.len() < 2
        || !faces.iter().all(|face| {
            face.printed_rules().iter().any(|rule| {
                value_kind(rule) == Some("keywordAbility")
                    && value_kind(&rule["ability"]) == Some("fuse")
            })
        })
    {
        return None;
    }
    let mut definition = card.clone();
    definition.mana_cost = faces
        .iter()
        .map(|face| face.mana_cost.as_str())
        .collect::<String>();
    definition.set_printed_rules(
        faces
            .into_iter()
            .enumerate()
            .flat_map(|(face_index, face)| {
                face.into_printed_rules()
                    .into_iter()
                    .map(move |mut rule| {
                        namespace_rule_declarations(&mut rule, &format!("fuse{face_index}"));
                        rule
                    })
                    .collect::<Vec<_>>()
            })
            .collect(),
    );
    Some(definition)
}

fn apply_split_face(card: &mut CardInstance, face_index: usize) -> bool {
    let printed = card
        .printed_definition
        .as_ref()
        .unwrap_or(&card.definition)
        .clone();
    let Some(definition) = split_face_definitions(&printed).into_iter().nth(face_index) else {
        return false;
    };
    card.definition = definition;
    true
}

fn is_permanent(card: &CardDefinition) -> bool {
    !is_instant(card) && !is_sorcery(card) && !is_land(card)
}

fn is_commander_definition(card: &CardDefinition) -> bool {
    card.is_commander
        || card.printed_rules().iter().any(|rule| {
            value_kind(rule) == Some("rulesMarker") && rule["text"].as_str() == Some("Commander")
        })
}

fn is_deck_commander_card(card: &CardDefinition) -> bool {
    !card.is_sideboard
        && !card.is_token
        && !card.is_game_piece
        && !has_card_type(card, "token")
        && is_commander_definition(card)
}

fn is_room_definition(card: &CardDefinition) -> bool {
    card.type_line
        .split("//")
        .any(|face| type_line_contains(face, "Room"))
        && card.mana_cost.contains("//")
}

fn room_mana_costs(card: &CardDefinition) -> Vec<String> {
    card.mana_cost
        .split("//")
        .map(str::trim)
        .filter(|cost| !cost.is_empty())
        .map(ToOwned::to_owned)
        .collect()
}

fn integer_value(value: &Value) -> Option<i32> {
    if let Some(number) = value.as_i64() {
        return i32::try_from(number).ok();
    }
    if value_kind(value) == Some("integer") {
        return value["value"]
            .as_i64()
            .and_then(|number| i32::try_from(number).ok());
    }
    None
}

fn exact_quantity_value(value: &Value) -> Option<i32> {
    (value_kind(value) == Some("exactly"))
        .then(|| integer_value(&value["value"]))
        .flatten()
        .filter(|quantity| *quantity > 0)
}

fn divide_integer(left: i32, right: i32, rounding: &Value) -> Option<i32> {
    if right == 0 {
        return None;
    }
    let quotient = left.checked_div(right).unwrap_or(i32::MAX);
    let remainder = left.checked_rem(right).unwrap_or(0);
    if remainder == 0 {
        return Some(quotient);
    }
    let same_sign = (left < 0) == (right < 0);
    Some(match rounding.as_str().unwrap_or("down") {
        "up" if same_sign => quotient.saturating_add(1),
        "down" if !same_sign => quotient.saturating_sub(1),
        "up" | "down" => quotient,
        _ => return None,
    })
}

fn parse_stat(value: &Option<String>) -> i32 {
    value
        .as_deref()
        .and_then(|raw| raw.parse::<i32>().ok())
        .unwrap_or(0)
}

fn current_power(card: &CardInstance) -> i32 {
    parse_stat(&card.definition.power) + card.counters.get("+1/+1").copied().unwrap_or(0)
        - card.counters.get("-1/-1").copied().unwrap_or(0)
        + card.power_modifier
}

fn cards_can_match_distinct_colors(
    card_colors: &[BTreeSet<String>],
    available: &BTreeSet<String>,
) -> bool {
    fn assign(
        card_colors: &[BTreeSet<String>],
        available: &BTreeSet<String>,
        used: &mut BTreeSet<String>,
        index: usize,
    ) -> bool {
        if index == card_colors.len() {
            return true;
        }
        let candidates = card_colors[index]
            .iter()
            .filter(|color| available.contains(*color) && !used.contains(*color))
            .cloned()
            .collect::<Vec<_>>();
        for color in candidates {
            used.insert(color.clone());
            let matched = assign(card_colors, available, used, index + 1);
            used.remove(&color);
            if matched {
                return true;
            }
        }
        false
    }

    let mut ordered = card_colors.to_vec();
    ordered.sort_by_key(BTreeSet::len);
    assign(&ordered, available, &mut BTreeSet::new(), 0)
}

fn current_toughness(card: &CardInstance) -> i32 {
    parse_stat(&card.definition.toughness) + card.counters.get("+1/+1").copied().unwrap_or(0)
        - card.counters.get("-1/-1").copied().unwrap_or(0)
        + card.toughness_modifier
}

fn reset_after_leaving_battlefield(card: &mut CardInstance) {
    if let Some(printed_definition) = &card.printed_definition {
        card.definition = printed_definition.clone();
    }
    card.tapped = false;
    card.summoning_sick = false;
    card.damage_marked = 0;
    card.power_modifier = 0;
    card.toughness_modifier = 0;
    card.counters.clear();
    card.flags.clear();
    card.battle_protector = None;
    card.attached_to = None;
    apply_card_face(card, 0);
}

fn card_color_symbols(card: &CardDefinition) -> BTreeSet<String> {
    let mut symbols = parse_mana_symbols(&card.mana_cost)
        .into_iter()
        .flat_map(|symbol| {
            symbol
                .split('/')
                .filter(|part| ["W", "U", "B", "R", "G"].contains(part))
                .map(ToOwned::to_owned)
                .collect::<Vec<_>>()
        })
        .collect::<BTreeSet<_>>();
    for symbol in card
        .printed_rules()
        .iter()
        .flat_map(|rule| rule["colorIndicator"].as_array().into_iter().flatten())
        .filter_map(Value::as_str)
    {
        symbols.insert(symbol.to_string());
    }
    for symbol in card
        .printed_rules()
        .iter()
        .filter(|rule| value_kind(rule) == Some("rulesMarker"))
        .flat_map(|rule| rule["colorIdentity"].as_array().into_iter().flatten())
        .filter_map(Value::as_str)
        .filter(|symbol| ["W", "U", "B", "R", "G"].contains(symbol))
    {
        symbols.insert(symbol.to_string());
    }
    symbols
}

fn card_matches_protection_quality(card: &CardDefinition, quality: &str) -> bool {
    let quality = quality
        .trim()
        .trim_start_matches("from ")
        .trim_end_matches('s');
    if quality.eq_ignore_ascii_case("everything") {
        return true;
    }
    if quality.eq_ignore_ascii_case("spells that are one or more color")
        || quality.eq_ignore_ascii_case("spells that are one or more colors")
    {
        return !card_color_symbols(card).is_empty();
    }
    if let Some(symbol) = color_name_to_symbol(quality) {
        return card_color_symbols(card).contains(symbol);
    }
    has_card_type(card, quality) || type_line_contains(&card.type_line, quality)
}

fn activation_limit_flag(limit: &Value, turn_number: u32, _rule_index: usize) -> Option<String> {
    let id = limit["id"].as_str()?;
    Some(match value_kind(limit) {
        Some("oncePerTurn") => format!("{id}:turn:{turn_number}"),
        Some("oncePerGameObject") => id.to_string(),
        _ => return None,
    })
}

fn activation_limit_use_prefix(limit: &Value, rule_index: usize) -> Option<String> {
    if value_kind(limit) != Some("oncePerGameObjectAbility") {
        return None;
    }
    Some(format!(
        "{}:ability:{rule_index}:use:",
        limit["id"].as_str()?
    ))
}

fn activation_limit_use_count(permanent: &CardInstance, limit: &Value, rule_index: usize) -> usize {
    activation_limit_use_prefix(limit, rule_index).map_or(0, |prefix| {
        permanent
            .flags
            .iter()
            .filter(|(flag, used)| **used && flag.starts_with(&prefix))
            .count()
    })
}

fn phyrexian_life_payment(
    mana: &[(String, bool)],
    requirement: &ManaRequirement,
    remaining_life: i32,
) -> Option<i32> {
    #[derive(Clone)]
    enum Obligation {
        Symbol(String),
        Hybrid(Vec<String>),
        Snow,
        Any,
        Phyrexian(String),
    }

    let mut obligations = Vec::new();
    for (symbol, required) in &requirement.colored {
        for _ in 0..(*required).max(0) {
            obligations.push(Obligation::Symbol(symbol.clone()));
        }
    }
    for _ in 0..requirement.snow.max(0) {
        obligations.push(Obligation::Snow);
    }
    obligations.extend(requirement.hybrid.iter().cloned().map(Obligation::Hybrid));
    for _ in 0..requirement.generic.max(0) {
        obligations.push(Obligation::Any);
    }
    for (symbol, required) in &requirement.phyrexian {
        for _ in 0..(*required).max(0) {
            obligations.push(Obligation::Phyrexian(symbol.clone()));
        }
    }

    fn search(
        obligations: &[Obligation],
        obligation_index: usize,
        mana: &[(String, bool)],
        used: &mut [bool],
        life_paid: i32,
        remaining_life: i32,
    ) -> Option<i32> {
        if life_paid > remaining_life {
            return None;
        }
        let Some(obligation) = obligations.get(obligation_index) else {
            return Some(life_paid);
        };
        let mut best = None;
        let mut examined = BTreeSet::new();
        for (index, (symbol, snow)) in mana.iter().enumerate() {
            if used[index] || !examined.insert((symbol.clone(), *snow)) {
                continue;
            }
            let matches = match obligation {
                Obligation::Symbol(required) => symbol == required,
                Obligation::Hybrid(options) => options.contains(symbol),
                Obligation::Snow => *snow,
                Obligation::Any => true,
                Obligation::Phyrexian(required) => symbol == required,
            };
            if !matches {
                continue;
            }
            used[index] = true;
            if let Some(payment) = search(
                obligations,
                obligation_index + 1,
                mana,
                used,
                life_paid,
                remaining_life,
            ) {
                best = Some(best.map_or(payment, |current: i32| current.min(payment)));
            }
            used[index] = false;
        }
        if matches!(obligation, Obligation::Phyrexian(_))
            && let Some(payment) = search(
                obligations,
                obligation_index + 1,
                mana,
                used,
                life_paid.saturating_add(2),
                remaining_life,
            )
        {
            best = Some(best.map_or(payment, |current| current.min(payment)));
        }
        best
    }

    search(
        &obligations,
        0,
        mana,
        &mut vec![false; mana.len()],
        0,
        remaining_life,
    )
}

fn rule_contains_kind(value: &Value, expected: &str) -> bool {
    if value_kind(value) == Some(expected) {
        return true;
    }
    match value {
        Value::Array(values) => values
            .iter()
            .any(|child| rule_contains_kind(child, expected)),
        Value::Object(object) => object
            .values()
            .any(|child| rule_contains_kind(child, expected)),
        _ => false,
    }
}

fn count_rule_kind(value: &Value, expected: &str) -> usize {
    usize::from(value_kind(value) == Some(expected))
        + match value {
            Value::Array(values) => values
                .iter()
                .map(|child| count_rule_kind(child, expected))
                .sum(),
            Value::Object(object) => object
                .values()
                .map(|child| count_rule_kind(child, expected))
                .sum(),
            _ => 0,
        }
}

use phase_ordinal::main_phase_ordinal_of_step;

/// Printed keyword count of an object off the battlefield (a spell).
fn keyword_count(card: &CardDefinition, keyword: &str) -> usize {
    object_predicate::DefinitionView::new(card)
        .keyword_rules()
        .map(|rule| count_rule_kind(rule, keyword))
        .sum()
}

/// Printed keyword of an object off the battlefield: band gates are read at
/// rest. A permanent's readers are `permanent_printed_has_keyword` and the
/// effective `permanent_has_effective_keyword`.
fn has_keyword(card: &CardDefinition, keyword: &str) -> bool {
    object_predicate::DefinitionView::new(card).has_keyword(keyword)
}

/// Printed keyword of a permanent, behind its band gates. Characteristic
/// readers that must not recurse into the effective layer use it.
fn permanent_printed_has_keyword(permanent: &CardInstance, keyword: &str) -> bool {
    object_predicate::DefinitionView::for_permanent(permanent).has_keyword(keyword)
}

fn stored_decision_value<'a>(card: &'a CardDefinition, decision_id: &str) -> Option<&'a str> {
    card.printed_rules().iter().find_map(|rule| {
        (value_kind(rule) == Some("storedDecisionValue")
            && rule["decisionId"].as_str() == Some(decision_id))
        .then(|| rule["value"].as_str())
        .flatten()
    })
}

fn ward_costs<'a>(rules: impl IntoIterator<Item = &'a Value>) -> Vec<Value> {
    rules
        .into_iter()
        .filter_map(|rule| match value_kind(rule) {
            Some("keywordAbility") => {
                ward_ability_supported(&rule["ability"]).then(|| rule["ability"]["cost"].clone())
            }
            Some("keywordAbilityGroup") => rule["abilities"]
                .as_array()
                .into_iter()
                .flatten()
                .find(|ability| ward_ability_supported(ability))
                .map(|ability| ability["cost"].clone()),
            _ => None,
        })
        .collect()
}

fn mana_options_from_value(value: &Value) -> Vec<Vec<String>> {
    if let Some(mana) = value.as_str() {
        let symbols = parse_mana_symbols(mana);
        return (!symbols.is_empty())
            .then_some(symbols)
            .into_iter()
            .collect();
    }
    match value_kind(value) {
        Some("chooseOne") => value["options"]
            .as_array()
            .into_iter()
            .flatten()
            .flat_map(mana_options_from_value)
            .collect(),
        Some("chooseColor") => ["W", "U", "B", "R", "G"]
            .iter()
            .map(|symbol| {
                vec![
                    symbol.to_string();
                    value["amount"]
                        .as_u64()
                        .and_then(|amount| usize::try_from(amount).ok())
                        .unwrap_or(1)
                ]
            })
            .collect(),
        Some("chooseColors") => {
            let amount = integer_value(&value["amount"])
                .and_then(|amount| usize::try_from(amount).ok())
                .unwrap_or(1)
                .min(5);
            let mut options = vec![Vec::new()];
            for _ in 0..amount {
                options = options
                    .into_iter()
                    .flat_map(|prefix| {
                        ["W", "U", "B", "R", "G"].into_iter().map(move |symbol| {
                            let mut option = prefix.clone();
                            option.push(symbol.to_string());
                            option
                        })
                    })
                    .collect();
            }
            options
        }
        _ => Vec::new(),
    }
}

fn basic_land_mana(card: &CardDefinition) -> Vec<Vec<String>> {
    [
        ("Plains", "W"),
        ("Island", "U"),
        ("Swamp", "B"),
        ("Mountain", "R"),
        ("Forest", "G"),
        ("Wastes", "C"),
    ]
    .iter()
    .filter(|(subtype, _)| has_card_subtype(card, subtype))
    .map(|(_, symbol)| vec![symbol.to_string()])
    .collect()
}

/// A definition predicate. A battlefield permanent passes
/// `DefinitionView::for_permanent` so its band-gated printed abilities are read.
fn matches_card_filter<'a>(
    card: impl Into<object_predicate::DefinitionView<'a>>,
    filter: &Value,
) -> bool {
    object_predicate::matches_object_predicate(card.into(), filter)
}

fn matches_card_filter_with_decisions<'a>(
    view: impl Into<object_predicate::DefinitionView<'a>>,
    filter: &Value,
    decisions: &BTreeMap<String, Value>,
) -> bool {
    let view = view.into();
    let card = view.definition();
    match value_kind(filter) {
        Some("manaValueParity") => filter["parity"]["decisionId"]
            .as_str()
            .and_then(|decision_id| decisions.get(decision_id))
            .and_then(Value::as_str)
            .is_some_and(|parity| match parity {
                "odd" => mana_value(card) % 2 != 0,
                "even" => mana_value(card) % 2 == 0,
                _ => false,
            }),
        Some("chosenCreatureType") => filter["decisionId"]
            .as_str()
            .and_then(|decision_id| decisions.get(decision_id))
            .and_then(|value| {
                value.as_str().or_else(|| {
                    value
                        .as_array()
                        .and_then(|values| values.first())
                        .and_then(Value::as_str)
                })
            })
            .is_some_and(|chosen_type| {
                view.has_keyword("changeling") || has_card_subtype(card, chosen_type)
            }),
        Some("compare")
            if matches!(
                value_kind(&filter["right"]),
                Some("sourceCastXValue" | "decisionResult")
            ) =>
        {
            let left = match value_kind(&filter["left"]) {
                Some("manaValueOf") => mana_value(card),
                Some("powerOf") => card
                    .power
                    .as_deref()
                    .and_then(|value| value.parse::<i32>().ok())
                    .unwrap_or(0),
                Some("toughnessOf") => card
                    .toughness
                    .as_deref()
                    .and_then(|value| value.parse::<i32>().ok())
                    .unwrap_or(0),
                Some("colorCountOf") => card_color_symbols(card).len() as i32,
                _ => return false,
            };
            let decision_id = if value_kind(&filter["right"]) == Some("sourceCastXValue") {
                Some("xValue")
            } else {
                filter["right"]["decisionId"].as_str()
            };
            let Some(right) = decisions
                .get(decision_id.unwrap_or_default())
                .and_then(Value::as_i64)
                .and_then(|value| i32::try_from(value).ok())
            else {
                return false;
            };
            match filter["operator"].as_str() {
                Some(">=") => left >= right,
                Some(">") => left > right,
                Some("<=") => left <= right,
                Some("<") => left < right,
                Some("==") => left == right,
                _ => false,
            }
        }
        Some("or") => filter["operands"].as_array().is_some_and(|values| {
            values
                .iter()
                .any(|value| matches_card_filter_with_decisions(view, value, decisions))
        }),
        Some("and") => filter["operands"].as_array().is_some_and(|values| {
            values
                .iter()
                .all(|value| matches_card_filter_with_decisions(view, value, decisions))
        }),
        Some("not") => !matches_card_filter_with_decisions(view, &filter["operand"], decisions),
        _ => matches_card_filter(view, filter),
    }
}

fn spell_cast_event_matches_filter(event: &GameEvent, filter: &Value) -> bool {
    if filter.is_null() {
        return true;
    }
    match value_kind(filter) {
        Some("and") => filter["operands"].as_array().is_some_and(|values| {
            values
                .iter()
                .all(|value| spell_cast_event_matches_filter(event, value))
        }),
        Some("or") => filter["operands"].as_array().is_some_and(|values| {
            values
                .iter()
                .any(|value| spell_cast_event_matches_filter(event, value))
        }),
        Some("not") => !spell_cast_event_matches_filter(event, &filter["operand"]),
        Some("cardTypeContains" | "subtypeContains" | "typeLineContains") => filter["value"]
            .as_str()
            .zip(event.detail["typeLine"].as_str())
            .is_some_and(|(value, type_line)| type_line_contains(type_line, value)),
        Some("nameEquals") => filter["value"]
            .as_str()
            .zip(event.detail["cardName"].as_str())
            .is_some_and(|(value, name)| name.eq_ignore_ascii_case(value)),
        Some("isLegendary") => event.detail["typeLine"]
            .as_str()
            .is_some_and(|type_line| type_line.starts_with("Legendary ")),
        _ => false,
    }
}

/// CR 122.1: the number of counters on an object (of the named kind, or of
/// every kind) lies within the atom's bounds; at least one by default.
fn counter_presence_matches(counters: &BTreeMap<String, i32>, filter: &Value) -> bool {
    let count = filter["counter"].as_str().map_or_else(
        || {
            counters
                .values()
                .filter(|count| **count > 0)
                .map(|count| i64::from(*count))
                .sum()
        },
        |counter| i64::from(counters.get(counter).copied().unwrap_or(0).max(0)),
    );
    let minimum = integer_value(&filter["minimum"]).map_or(1, i64::from);
    count >= minimum
        && integer_value(&filter["maximum"]).is_none_or(|maximum| count <= i64::from(maximum))
}

fn matches_permanent_filter(card: &CardInstance, filter: &Value) -> bool {
    match value_kind(filter) {
        Some("isTapped") => card.tapped,
        Some("isAttacking") => card.flags.get("attacking").copied().unwrap_or(false),
        Some("isBlocking") => card.flags.get("blocking").copied().unwrap_or(false),
        Some("hasCounter") => counter_presence_matches(&card.counters, filter),
        Some("hasDesignation") => permanent_has_designation(card, filter),
        Some("enteredThisTurn") => card.flags.get("enteredThisTurn").copied().unwrap_or(false),
        Some("or") => filter["operands"].as_array().is_some_and(|values| {
            values
                .iter()
                .any(|value| matches_permanent_filter(card, value))
        }),
        Some("and") => filter["operands"].as_array().is_some_and(|values| {
            values
                .iter()
                .all(|value| matches_permanent_filter(card, value))
        }),
        Some("not") => !matches_permanent_filter(card, &filter["operand"]),
        _ => matches_card_filter(
            object_predicate::DefinitionView::for_permanent(card),
            filter,
        ),
    }
}

fn card_filter_supported(filter: &Value) -> bool {
    match value_kind(filter) {
        Some(
            "cardTypeContains"
            | "subtypeContains"
            | "typeLineContains"
            | "nameEquals"
            | "nameStartsWith"
            | "colorContains"
            | "colorDoesNotContain",
        ) => filter["value"].is_string(),
        Some("manaCostEquals") => filter["value"]
            .as_str()
            .is_some_and(|value| parse_mana_requirement(value).is_some()),
        Some("chosenCreatureType" | "chosenCardType" | "chosenColor") => {
            filter["decisionId"].is_string()
        }
        Some(
            "isToken"
            | "isCommander"
            | "isLegendary"
            | "isBasic"
            | "isPermanentCard"
            | "manaCostContainsX"
            | "historic"
            | "hasActivatedAbility",
        ) => true,
        Some("totalPowerAndToughnessAtMost") => {
            integer_value(&filter["value"]).is_some_and(|value| value >= 0)
        }
        Some("manaValueParity") => {
            value_kind(&filter["parity"]) == Some("decisionResult")
                && filter["parity"]["decisionId"].is_string()
        }
        Some("hasKeyword") => filter["value"].is_string(),
        Some("dealtDamageToPlayerThisTurn") => {
            event_history::dealt_damage_to_player_supported(filter)
        }
        Some("compare") => {
            matches!(
                value_kind(&filter["left"]),
                Some("manaValueOf" | "powerOf" | "toughnessOf" | "colorCountOf")
            ) && value_kind(&filter["left"]["object"]) == Some("candidate")
                && numeric_expression_supported(&filter["right"])
                // Only target-candidate domains bind the source's value.
                && !source_bound_operands::contains_source_operand(filter)
                && matches!(
                    filter["operator"].as_str(),
                    Some(">=" | ">" | "<=" | "<" | "==")
                )
        }
        Some(
            "isTapped"
            | "enteredThisTurn"
            | "isAttacking"
            | "isAttackingAlone"
            | "isUnblockedAttacker"
            | "isBlocking"
            | "isEquipped"
            | "isModified"
            | "hasAttachedAura"
            | "dealtDamageThisTurn"
            | "enteredGraveyardThisTurn"
            | "dealtDamageToControllerThisTurn"
            | "wasDealtDamageThisTurn"
            | "attackedThisTurn"
            | "blockedThisTurn",
        ) => true,
        Some("or" | "and") => filter["operands"]
            .as_array()
            .is_some_and(|values| !values.is_empty() && values.iter().all(card_filter_supported)),
        Some("not") => card_filter_supported(&filter["operand"]),
        None => filter.is_null(),
        _ => false,
    }
}

/// CR 701.37b, 702.112b, 701.60b: a designation stays on the permanent
/// until it leaves the battlefield; it is the permanent's flag of that name.
fn permanent_has_designation(card: &CardInstance, filter: &Value) -> bool {
    filter["designation"]
        .as_str()
        .is_some_and(|designation| card.flags.get(designation).copied().unwrap_or(false))
}

fn permanent_filter_supported(filter: &Value) -> bool {
    match value_kind(filter) {
        Some("hasDesignation") => matches!(
            filter["designation"].as_str(),
            Some("monstrous" | "renowned" | "suspected" | "kicked" | "faceDown")
        ),
        Some("hasCounter") => {
            filter.get("counter").is_none_or(Value::is_string)
                && filter
                    .get("minimum")
                    .is_none_or(|minimum| integer_value(minimum).is_some_and(|value| value >= 0))
                && filter
                    .get("maximum")
                    .is_none_or(|maximum| integer_value(maximum).is_some_and(|value| value >= 0))
        }
        Some("or" | "and") => filter["operands"].as_array().is_some_and(|values| {
            !values.is_empty() && values.iter().all(permanent_filter_supported)
        }),
        Some("not") => permanent_filter_supported(&filter["operand"]),
        _ => card_filter_supported(filter),
    }
}

fn mana_value(card: &CardDefinition) -> i32 {
    parse_mana_symbols(&card.mana_cost)
        .into_iter()
        .map(|symbol| {
            symbol
                .parse::<i32>()
                .unwrap_or_else(|_| i32::from(symbol != "X"))
        })
        .sum()
}

fn distinct_card_types<'a>(
    cards: impl IntoIterator<Item = &'a CardDefinition>,
) -> BTreeSet<&'static str> {
    const CARD_TYPES: [&str; 9] = [
        "Artifact",
        "Battle",
        "Creature",
        "Enchantment",
        "Instant",
        "Kindred",
        "Land",
        "Planeswalker",
        "Sorcery",
    ];
    cards
        .into_iter()
        .flat_map(|card| {
            CARD_TYPES
                .into_iter()
                .filter(move |card_type| has_card_type(card, card_type))
        })
        .collect()
}

fn mana_value_with_decisions(card: &CardDefinition, decisions: &BTreeMap<String, Value>) -> i32 {
    let variable_symbols = parse_mana_symbols(&card.mana_cost)
        .into_iter()
        .filter(|symbol| symbol == "X")
        .count() as i32;
    let variable_value = decisions
        .get("xValue")
        .and_then(Value::as_i64)
        .and_then(|value| i32::try_from(value).ok())
        .unwrap_or(0)
        .max(0);
    mana_value(card) + variable_symbols * variable_value
}

fn stack_filter_supported(filter: &Value) -> bool {
    match value_kind(filter) {
        Some("cardTypeContains") => filter["value"].is_string(),
        Some("subtypeContains") => card_filter_supported(filter),
        Some("isLegendary") => true,
        Some("colorContains") => filter["value"].is_string(),
        Some("compare") => {
            matches!(
                value_kind(&filter["left"]),
                Some("manaValueOf" | "powerOf" | "toughnessOf" | "colorCountOf")
            ) && value_kind(&filter["left"]["object"]) == Some("candidate")
                && integer_value(&filter["right"]).is_some()
                && matches!(
                    filter["operator"].as_str(),
                    Some(">=" | ">" | "<=" | "<" | "==")
                )
        }
        Some("or" | "and") => filter["operands"].as_array().is_some_and(|operands| {
            !operands.is_empty() && operands.iter().all(stack_filter_supported)
        }),
        Some("not") => stack_filter_supported(&filter["operand"]),
        None => filter.is_null(),
        _ => false,
    }
}

fn matches_stack_filter(card: &CardDefinition, filter: &Value) -> bool {
    match value_kind(filter) {
        Some("subtypeContains") => matches_card_filter(card, filter),
        Some("cardTypeContains") => filter["value"]
            .as_str()
            .is_some_and(|value| has_card_type(card, value)),
        Some("colorContains") => filter["value"].as_str().is_some_and(|color| {
            color_name_to_symbol(color)
                .is_some_and(|symbol| card_color_symbols(card).contains(symbol))
        }),
        Some("isLegendary") => card
            .type_line
            .split_whitespace()
            .any(|word| word.eq_ignore_ascii_case("Legendary")),
        Some("isBasic") => card
            .type_line
            .split_whitespace()
            .any(|word| word.eq_ignore_ascii_case("Basic")),
        Some("compare") => {
            let left = match value_kind(&filter["left"]) {
                Some("manaValueOf") => mana_value(card),
                Some("powerOf") => parse_stat(&card.power),
                Some("toughnessOf") => parse_stat(&card.toughness),
                Some("colorCountOf") => card_color_symbols(card).len() as i32,
                _ => return false,
            };
            let right = integer_value(&filter["right"]).unwrap_or(0);
            match filter["operator"].as_str() {
                Some(">=") => left >= right,
                Some(">") => left > right,
                Some("<=") => left <= right,
                Some("<") => left < right,
                Some("==") => left == right,
                _ => false,
            }
        }
        Some("or") => filter["operands"].as_array().is_some_and(|operands| {
            operands
                .iter()
                .any(|value| matches_stack_filter(card, value))
        }),
        Some("and") => filter["operands"].as_array().is_some_and(|operands| {
            operands
                .iter()
                .all(|value| matches_stack_filter(card, value))
        }),
        Some("not") => !matches_stack_filter(card, &filter["operand"]),
        None => filter.is_null(),
        _ => false,
    }
}

fn stack_item_filter_supported(filter: &Value) -> bool {
    match value_kind(filter) {
        Some("isSpell" | "isActivatedAbility" | "isTriggeredAbility" | "isColorless") => true,
        Some("cardTypeContains") => filter["value"].is_string(),
        Some("or" | "and") => filter["operands"].as_array().is_some_and(|operands| {
            !operands.is_empty() && operands.iter().all(stack_item_filter_supported)
        }),
        Some("compare") => {
            value_kind(&filter["left"]) == Some("targetCountOf")
                && value_kind(&filter["left"]["object"]) == Some("candidate")
                && matches!(
                    filter["operator"].as_str(),
                    Some(">=" | ">" | "<=" | "<" | "==")
                )
                && integer_value(&filter["right"]).is_some()
        }
        None => filter.is_null(),
        _ => false,
    }
}

fn matches_stack_item_filter(object: &StackObject, filter: &Value) -> bool {
    match value_kind(filter) {
        Some("isSpell") => stack_object_is_spell(object),
        Some("isActivatedAbility") => object.ability_kind.as_deref() == Some("activatedAbility"),
        Some("isTriggeredAbility") => object.ability_kind.as_deref() == Some("triggeredAbility"),
        Some("isColorless") => card_color_symbols(&object.card.definition).is_empty(),
        Some("cardTypeContains") => matches_stack_filter(&object.card.definition, filter),
        Some("or") => filter["operands"].as_array().is_some_and(|operands| {
            operands
                .iter()
                .any(|operand| matches_stack_item_filter(object, operand))
        }),
        Some("and") => filter["operands"].as_array().is_some_and(|operands| {
            operands
                .iter()
                .all(|operand| matches_stack_item_filter(object, operand))
        }),
        Some("compare") => {
            let right = integer_value(&filter["right"]).unwrap_or(0).max(0) as usize;
            match filter["operator"].as_str() {
                Some(">=") => object.targets.len() >= right,
                Some(">") => object.targets.len() > right,
                Some("<=") => object.targets.len() <= right,
                Some("<") => object.targets.len() < right,
                Some("==") => object.targets.len() == right,
                _ => false,
            }
        }
        None => filter.is_null(),
        _ => false,
    }
}

fn numeric_expression_supported(expression: &Value) -> bool {
    if integer_value(expression).is_some() {
        return true;
    }
    match value_kind(expression) {
        Some("cardsDiscardedThisTurn") => true,
        Some("eachColorAmongPermanents") => {
            player_reference_supported(&expression["player"])
                && expression.get("where").is_none_or(card_filter_supported)
        }
        Some("startingDeckSizeAtLeast") => {
            integer_value(&expression["threshold"]).is_some_and(|threshold| threshold > 0)
                && integer_value(&expression["amount"]).is_some_and(|amount| amount >= 0)
        }
        Some("countPermanents") => {
            permanent_filter_supported(&expression["where"])
                && expression
                    .get("player")
                    .is_none_or(player_reference_supported)
                && expression.get("allPlayers").is_none_or(Value::is_boolean)
                && expression
                    .get("excludeSource")
                    .is_none_or(Value::is_boolean)
                && expression
                    .get("ownership")
                    .is_none_or(|value| matches!(value.as_str(), Some("owned" | "notOwned")))
        }
        Some("greatestSharedCreatureTypeCount") => {
            player_reference_supported(&expression["player"])
        }
        Some("countAttackingCreatures") => player_reference_supported(&expression["player"]),
        Some("countPermanentsControlledByOpponents") => {
            player_reference_supported(&expression["player"])
                && card_filter_supported(&expression["where"])
        }
        Some("countDistinctPermanentNames") => {
            player_reference_supported(&expression["player"])
                && card_filter_supported(&expression["where"])
        }
        Some("countDistinctPowers" | "countDistinctColors") => {
            player_reference_supported(&expression["player"])
                && card_filter_supported(&expression["where"])
                && expression
                    .get("excludeSource")
                    .is_none_or(Value::is_boolean)
        }
        Some("countDistinctCardTypes") => {
            object_predicate::distinct_card_type_filter_supported(&expression["where"])
                && match value_kind(&expression["zone"]) {
                    Some("graveyard") => player_reference_supported(&expression["zone"]["player"]),
                    Some("anyGraveyard") => true,
                    _ => false,
                }
        }
        Some("countDecisionCardsMatching") => {
            expression["decisionId"].is_string() && card_filter_supported(&expression["where"])
        }
        Some("countAttachedPermanents") => {
            value_kind(&expression["attachmentSource"]) == Some("self")
                && card_filter_supported(&expression["where"])
                && expression
                    .get("excludeSource")
                    .is_none_or(Value::is_boolean)
        }
        Some("countAttachments") => {
            matches!(
                value_kind(&expression["object"]),
                Some("self" | "abilitySource")
            ) && card_filter_supported(&expression["where"])
        }
        Some("countBoundObjects") => expression["binding"].is_string(),
        Some("add" | "subtract" | "multiply" | "absoluteDifference") => {
            numeric_expression_supported(&expression["left"])
                && numeric_expression_supported(&expression["right"])
                || value_kind(expression) == Some("multiply")
                    && numeric_expression_supported(&expression["value"])
                    && numeric_expression_supported(&expression["factor"])
        }
        Some("powerDifferenceOfChosenObjects") => expression["decisionId"].is_string(),
        Some("divide") => {
            numeric_expression_supported(&expression["left"])
                && numeric_expression_supported(&expression["right"])
                && matches!(expression["round"].as_str(), Some("up" | "down"))
        }
        Some("domainCount") => player_reference_supported(&expression["player"]),
        Some("greatestPower" | "greatestToughness") => {
            player_reference_supported(&expression["player"])
                && card_filter_supported(&expression["where"])
        }
        Some("greatestPowerAmongCards") => {
            value_kind(&expression["zone"]) == Some("graveyard")
                && player_reference_supported(&expression["zone"]["player"])
                && card_filter_supported(&expression["where"])
        }
        Some("sumPowers") => {
            player_reference_supported(&expression["player"])
                && card_filter_supported(&expression["where"])
        }
        Some("greatestOpponentPermanentCount") => {
            expression
                .get("player")
                .is_none_or(player_reference_supported)
                && card_filter_supported(&expression["where"])
        }
        Some("countOpponents" | "countOpponentsAttackedThisCombat") => {
            player_reference_supported(&expression["player"])
        }
        Some("countOpponentsWithPermanent") => {
            player_reference_supported(&expression["player"])
                && card_filter_supported(&expression["where"])
        }
        Some(
            "countPlayers" | "minimumHandSize" | "greatestHandSize" | "greatestOpponentHandSize",
        ) => expression.get("where").is_none_or(card_filter_supported),
        Some("countPlayerZonesByCardCount") => {
            matches!(
                expression["zone"].as_str(),
                Some("graveyard" | "hand" | "library")
            ) && matches!(expression["operator"].as_str(), Some(">=" | "<="))
                && integer_value(&expression["count"]).is_some_and(|count| count >= 0)
        }
        Some("triggeringPermanentCounterCount" | "deadPermanentPower") => true,
        Some("countCounters") => {
            (matches!(
                value_kind(&expression["object"]),
                Some("self" | "abilitySource")
            ) || target_reference_supported(&expression["object"]))
                && expression.get("counter").is_none_or(Value::is_string)
        }
        Some("countCountersOnPermanents") => {
            player_reference_supported(&expression["player"])
                && card_filter_supported(&expression["where"])
                && expression["counter"].is_string()
        }
        Some("devotion") => {
            player_reference_supported(&expression["player"]) && expression["color"].is_string()
        }
        Some("devotionToChosenColor" | "commanderColorIdentityCount") => {
            player_reference_supported(&expression["player"])
        }
        Some("countCards") if value_kind(&expression["zone"]) == Some("exile") => {
            // CR 607.2a: the cards exiled with a linked source.
            matches!(
                value_kind(&expression["zone"]["linkedSource"]),
                Some("self" | "abilitySource")
            ) && expression.get("where").is_none_or(card_filter_supported)
                && expression.get("allPlayers").is_none()
        }
        Some("countCards") => {
            matches!(
                value_kind(&expression["zone"]),
                Some("graveyard" | "hand" | "library")
            ) && player_reference_supported(&expression["zone"]["player"])
                && card_filter_supported(&expression["where"])
                && expression.get("allPlayers").is_none_or(Value::is_boolean)
        }
        Some("countManaSymbolsInTriggeringSpell") => expression["symbol"]
            .as_str()
            .is_some_and(|symbol| matches!(symbol, "W" | "U" | "B" | "R" | "G")),
        Some("sumManaValues") => {
            matches!(
                value_kind(&expression["zone"]),
                Some("battlefield" | "graveyard" | "hand")
            ) && player_reference_supported(&expression["zone"]["player"])
                && card_filter_supported(&expression["where"])
        }
        Some("greatestManaValue") => {
            (matches!(
                value_kind(&expression["zone"]),
                Some("graveyard" | "hand" | "library")
            ) && player_reference_supported(&expression["zone"]["player"])
                || expression.get("zone").is_none()
                    && player_reference_supported(&expression["player"]))
                && card_filter_supported(&expression["where"])
        }
        Some("sumEventValuesThisTurn") => {
            player_reference_supported(&expression["player"])
                && expression["eventKind"].as_str() == Some("spellCast")
                && expression["detailField"].as_str() == Some("manaValue")
                && expression
                    .get("excludeSource")
                    .is_none_or(Value::is_boolean)
        }
        Some("countPlayerCounters") => {
            player_reference_supported(&expression["player"]) && expression["counter"].is_string()
        }
        Some("countPlaneswalkerTypes") => player_reference_supported(&expression["player"]),
        Some("countDefendingPlayerPermanents") => {
            value_kind(&expression["attacker"]) == Some("self")
                && card_filter_supported(&expression["where"])
        }
        Some("powerOf" | "toughnessOf") => {
            matches!(
                value_kind(&expression["object"]),
                Some("self" | "abilitySource" | "candidate")
            ) || target_reference_supported(&expression["object"])
                || entry_observation::observed_object_reference_supported(&expression["object"])
        }
        Some("counterCountOf") => {
            (matches!(
                value_kind(&expression["object"]),
                Some("self" | "abilitySource")
            ) || target_reference_supported(&expression["object"]))
                && expression["counter"].is_string()
        }
        Some("abilitySourceLastKnownPower") => true,
        Some("manaValueOf") => {
            target_reference_supported(&expression["object"])
                || entry_observation::observed_object_reference_supported(&expression["object"])
                || (value_kind(&expression["object"]) == Some("boundObject")
                    && expression["object"]["binding"].is_string())
        }
        Some("lifeGainedThisTurn" | "lifeLostThisTurn") => {
            player_reference_supported(&expression["player"])
        }
        Some("lifeTotal") => player_reference_supported(&expression["player"]),
        Some("manaPoolSize") => player_reference_supported(&expression["player"]),
        Some("manaPoolSymbolCount") => {
            player_reference_supported(&expression["player"])
                && matches!(
                    expression["symbol"].as_str(),
                    Some("W" | "U" | "B" | "R" | "G" | "C")
                )
        }
        Some("countEvents" | "countEventsThisTurn" | "countEventsPreviousTurn") => {
            event_history::event_history_supported(expression)
        }
        Some("countTurnsTaken") => singular_player_reference_supported(&expression["player"]),
        Some("boundValue") => expression["id"].is_string(),
        Some("decisionResult") => expression["decisionId"].is_string(),
        Some("triggeringSpellManaValue" | "triggeringSpellManaSpent") => true,
        Some("manaSpentToCastSource" | "colorsOfManaSpentToCastSource") => true,
        Some("manaSpentToCast") => mana_payment::mana_spent_to_cast_supported(expression),
        Some("opponentExtremum") => opponent_extremum::opponent_extremum_supported(expression),
        Some("sourceCastXValue") => true,
        Some("countObjects") => object_expression_supported(&expression["objects"]),
        Some("maximumManaValue") => {
            object_expression_supported(&expression["collection"])
                && expression
                    .get("variableManaSymbolsEqual")
                    .is_none_or(|value| integer_value(value).is_some() || value.is_i64())
        }
        Some("minimum" | "maximum") => expression["operands"].as_array().is_some_and(|operands| {
            !operands.is_empty() && operands.iter().all(numeric_expression_supported)
        }),
        Some("negate") => numeric_expression_supported(&expression["operand"]),
        Some("conditionalValue") => {
            condition_supported(&expression["condition"])
                && numeric_expression_supported(&expression["ifTrue"])
                && numeric_expression_supported(&expression["ifFalse"])
        }
        _ => false,
    }
}

fn object_expression_supported(expression: &Value) -> bool {
    match value_kind(expression) {
        Some("self" | "abilitySource") => true,
        Some("opponentsOf") => player_reference_supported(&expression["player"]),
        Some("attachedObject") => value_kind(&expression["attachment"]) == Some("self"),
        Some("chosenTargets" | "chosenObjects") => expression["id"].is_string(),
        Some("eachPermanent") => {
            !(expression.get("player").is_some() && expression.get("players").is_some())
                && expression
                    .get("players")
                    .is_none_or(player_query::population_supported)
                && expression
                    .get("player")
                    .is_none_or(player_query::population_supported)
                // The battlefield domain evaluates permanent state (counters).
                && expression.get("where").is_none_or(permanent_filter_supported)
                && expression
                    .get("excludeSource")
                    .is_none_or(Value::is_boolean)
                && expression
                    .get("excludeSourceController")
                    .is_none_or(Value::is_boolean)
                && expression
                    .get("exclude")
                    .is_none_or(object_expression_supported)
        }
        Some("cardsExiledWithSource" | "triggeringCard") => true,
        Some("libraryTopCards") => {
            library_zone_supported(&expression["zone"])
                && numeric_expression_supported(&expression["count"])
        }
        Some("boundObjects") => expression["binding"].is_string(),
        Some("decisionResult") => expression["decisionId"].is_string(),
        Some("setDifference") => {
            object_expression_supported(&expression["left"])
                && object_expression_supported(&expression["right"])
        }
        Some("filterObjects") => {
            object_expression_supported(&expression["objects"])
                && card_filter_supported(&expression["where"])
        }
        Some("cardsInZone") => {
            matches!(
                value_kind(&expression["zone"]),
                Some("graveyard" | "hand" | "exile" | "library")
            ) && player_query::zone_holders_supported(&expression["zone"])
                && expression.get("where").is_none_or(|predicate| {
                    // The card-zone domain evaluates definition data only
                    // (runtime_collections); a battlefield-state atom there
                    // is refused here, not at resolution.
                    card_filter_supported(predicate)
                        && object_predicate::try_map_predicate_leaves(predicate, 0, &mut |leaf| {
                            if object_predicate::definition_atom_supported(leaf) {
                                Ok(leaf.clone())
                            } else {
                                Err(EngineError::new("not a definition atom"))
                            }
                        })
                        .is_ok()
                })
        }
        Some("cardsDrawnThisTurn") => {
            player_reference_supported(&expression["player"])
                && value_kind(&expression["zone"]) == Some("hand")
                && player_reference_supported(&expression["zone"]["player"])
        }
        Some("union") => expression["sets"]
            .as_array()
            .is_some_and(|sets| !sets.is_empty() && sets.iter().all(object_expression_supported)),
        _ => false,
    }
}

fn object_collection_expression_supported(expression: &Value) -> bool {
    matches!(
        value_kind(expression),
        Some(
            "chosenTargets"
                | "chosenObjects"
                | "eachPermanent"
                | "boundObjects"
                | "decisionResult"
                | "setDifference"
                | "filterObjects"
                | "cardsInZone"
                | "cardsDrawnThisTurn"
                | "union"
        )
    ) && object_expression_supported(expression)
}

fn library_zone_supported(zone: &Value) -> bool {
    value_kind(zone) == Some("library") && player_reference_supported(&zone["player"])
}

fn card_choice_candidates_supported(candidates: &Value) -> bool {
    if value_kind(candidates) != Some("cards") {
        return false;
    }
    let zone_supported = match value_kind(&candidates["zone"]) {
        Some("library" | "graveyard" | "exile" | "hand") => {
            player_reference_supported(&candidates["zone"]["player"])
        }
        Some("outsideGame") => true,
        _ => false,
    };
    let filter_supported = match value_kind(&candidates["where"]) {
        Some("ownedBy") => player_reference_supported(&candidates["where"]["player"]),
        _ => card_filter_supported(&candidates["where"]),
    };
    zone_supported && filter_supported
}

fn condition_supported(condition: &Value) -> bool {
    match value_kind(condition) {
        Some("objectOnBattlefield") => {
            object_context::object_context_reference_supported(&condition["object"])
        }
        Some("bindingNotEmpty") => condition["binding"].is_string(),
        Some("sourceOnBattlefield") => true,
        Some("sourceIsSuspended") => true,
        Some("sourceInZone") => matches!(condition["zone"].as_str(), Some("exile" | "battlefield")),
        Some("sourceFlagSet") => condition["flag"].is_string(),
        Some("sourceIsModified") => true,
        Some("sourceIsCreature") => true,
        Some("objectIsAttacking") => target_reference_supported(&condition["object"]),
        Some("wasCastWithAlternativeCost") => condition["mode"].is_string(),
        Some("notYourTurn") => true,
        Some("triggeringSpellManaSourceMatches") => card_filter_supported(&condition["where"]),
        Some("manaSymbolsSpentToCastSource") => {
            condition["symbols"].as_array().is_some_and(|symbols| {
                !symbols.is_empty()
                    && symbols.iter().all(|symbol| {
                        symbol
                            .as_str()
                            .is_some_and(|symbol| matches!(symbol, "W" | "U" | "B" | "R" | "G"))
                    })
            })
        }
        Some("noManaSpentToCastTargetSpell") => target_reference_supported(&condition["spell"]),
        Some("not") => condition_supported(&condition["operand"]),
        Some("or" | "and") => condition["operands"]
            .as_array()
            .is_some_and(|values| !values.is_empty() && values.iter().all(condition_supported)),
        Some("controlsPermanent") => {
            card_filter_supported(&condition["where"])
                && condition.get("excludeSource").is_none_or(Value::is_boolean)
                && condition.get("excludeName").is_none_or(Value::is_string)
        }
        Some("hasEnduringStory" | "hasCityBlessing") => {
            player_reference_supported(&condition["player"])
        }
        Some("playerQuantifier") => player_quantifier::player_quantifier_supported(condition),
        Some("playersEqual") => {
            player_reference_supported(&condition["left"])
                && player_reference_supported(&condition["right"])
        }
        Some("compare") => {
            matches!(
                condition["operator"].as_str(),
                Some(">=" | ">" | "<=" | "<" | "==")
            ) && numeric_expression_supported(&condition["left"])
                && numeric_expression_supported(&condition["right"])
        }
        Some("decisionWas" | "costWasPaid") => {
            condition["decisionId"].is_string()
                && condition.get("required").is_none_or(Value::is_boolean)
                && condition
                    .get("value")
                    .is_none_or(|value| value.is_boolean())
        }
        Some("selectionContains") => {
            value_kind(&condition["selection"]) == Some("decisionResult")
                && condition["selection"]["decisionId"].is_string()
                && condition["value"].is_string()
        }
        Some("selectionCountAtLeast") => {
            value_kind(&condition["selection"]) == Some("decisionResult")
                && condition["selection"]["decisionId"].is_string()
                && condition["value"].is_string()
                && integer_value(&condition["minimum"]).is_some_and(|minimum| minimum >= 1)
        }
        Some("selectionNotEmpty") => {
            value_kind(&condition["selection"]) == Some("decisionResult")
                && condition["selection"]["decisionId"].is_string()
        }
        Some("wasKicked") => value_kind(&condition["spell"]) == Some("self"),
        Some("kickerCostWasPaid") => {
            value_kind(&condition["spell"]) == Some("self") && condition["cost"].is_string()
        }
        Some("wasCast") => value_kind(&condition["object"]) == Some("self"),
        Some("wasCastFromHand") => value_kind(&condition["object"]) == Some("self"),
        Some("wasCastFromZone") => {
            value_kind(&condition["object"]) == Some("self")
                && matches!(
                    condition["zone"].as_str(),
                    Some("graveyard" | "hand" | "exile" | "commandZone")
                )
        }
        Some("isPrepared") => matches!(
            value_kind(&condition["object"]),
            Some("self" | "abilitySource")
        ),
        Some("hasCardType") => {
            matches!(
                value_kind(&condition["object"]),
                Some("self" | "abilitySource")
            ) && condition["value"].is_string()
        }
        Some("objectMatchesFilter") => {
            object_condition::object_condition_reference_supported(&condition["object"])
                && permanent_filter_supported(&condition["where"])
        }
        Some("controllerIsBeingAttacked") => true,
        Some("sorceryTiming" | "ninjutsuTiming") => true,
        Some("duringControllerMainPhase") => player_reference_supported(&condition["player"]),
        Some("duringControllerTurn") => player_reference_supported(&condition["player"]),
        Some("isTapped" | "isBlocking") => {
            matches!(
                value_kind(&condition["object"]),
                Some("self" | "abilitySource")
            )
        }
        Some("isAttacking") => {
            matches!(
                value_kind(&condition["object"]),
                Some("self" | "abilitySource")
            )
        }
        Some("classLevelIs") => {
            matches!(
                value_kind(&condition["object"]),
                Some("self" | "abilitySource")
            ) && integer_value(&condition["value"]).is_some_and(|level| (1..=3).contains(&level))
        }
        Some("delirium") => player_reference_supported(&condition["player"]),
        Some("completedDungeon") => {
            player_reference_supported(&condition["player"])
                && condition.get("name").is_none_or(Value::is_string)
        }
        Some("targetsShareCreatureType") => condition["targets"]
            .as_array()
            .is_some_and(|targets| targets.len() == 2 && targets.iter().all(Value::is_string)),
        Some("sourceAttackingAlone") => true,
        Some("controlledCreatureAttackingAlone") => {
            player_reference_supported(&condition["player"])
        }
        Some("sourceNeedsEcho") => true,
        _ => false,
    }
}

/// CR 702.5a / 303.4a: the candidate set an `enchant` keyword ability allows,
/// shared by Aura-spell target declaration, resolution legality and the
/// state-based action for an illegally attached Aura.
fn enchant_candidates_shape(enchant_ability: &Value) -> Value {
    if enchant_ability.get("zone").is_some() {
        json!({
            "kind": "cards",
            "zone": enchant_ability["zone"].clone(),
            "where": enchant_ability["where"].clone(),
        })
    } else {
        let mut candidates = json!({
            "kind": "permanents",
            "where": enchant_ability["where"].clone(),
        });
        if enchant_ability.get("controller").is_some() {
            candidates["controller"] = enchant_ability["controller"].clone();
        }
        candidates
    }
}

/// The `enchant` keyword ability of a card definition, if it has one.
fn enchant_ability_of(definition: &CardDefinition) -> Option<&Value> {
    definition.printed_rules().iter().find_map(|rule| {
        (value_kind(rule) == Some("keywordAbility")
            && value_kind(&rule["ability"]) == Some("enchant"))
        .then_some(&rule["ability"])
    })
}

fn target_candidates_supported(candidates: &Value) -> bool {
    let candidates = &source_bound_operands::with_placeholder_bindings(candidates);
    match value_kind(candidates) {
        Some("players" | "anyTarget") => true,
        Some("permanents") => {
            permanent_filter_supported(&candidates["where"])
                && candidates.get("controller").is_none_or(|controller| {
                    player_reference_supported(controller)
                        || (value_kind(controller) == Some("opponentsOf")
                            && player_reference_supported(&controller["player"]))
                        || player_complement_reference_supported(controller)
                })
                && candidates
                    .get("excludeSource")
                    .is_none_or(Value::is_boolean)
                && candidates
                    .get("exclude")
                    .is_none_or(target_reference_supported)
                && candidates
                    .get("excludeInstanceId")
                    .is_none_or(Value::is_string)
                && candidates
                    .get("ownership")
                    .is_none_or(|value| matches!(value.as_str(), Some("owned" | "notOwned")))
                && candidates
                    .get("ignoreTargetingRestrictions")
                    .is_none_or(Value::is_boolean)
                && candidates
                    .get("uniqueNameAmongController")
                    .is_none_or(Value::is_boolean)
        }
        Some("cards") => {
            (value_kind(&candidates["zone"]) == Some("anyGraveyard")
                || matches!(
                    value_kind(&candidates["zone"]),
                    Some("graveyard" | "exile" | "hand")
                ) && player_reference_supported(&candidates["zone"]["player"]))
                && card_filter_supported(&candidates["where"])
                && candidates
                    .get("owner")
                    .is_none_or(player_reference_supported)
                && candidates
                    .get("excludeSource")
                    .is_none_or(Value::is_boolean)
        }
        Some("spells") => {
            candidates.get("where").is_none_or(stack_filter_supported)
                && candidates.get("controller").is_none_or(|controller| {
                    player_reference_supported(controller)
                        || player_complement_reference_supported(controller)
                })
                && candidates.get("singleTarget").is_none_or(Value::is_boolean)
                && candidates
                    .get("includeAbilities")
                    .is_none_or(Value::is_boolean)
                && candidates
                    .get("targetingControllerOrPermanent")
                    .is_none_or(Value::is_boolean)
                && candidates
                    .get("targetingControlledPermanentWhere")
                    .is_none_or(card_filter_supported)
        }
        Some("stackObjects") => stack_filter_supported(&candidates["where"]),
        Some("stackItems") => {
            stack_item_filter_supported(&candidates["where"])
                && candidates.get("controller").is_none_or(|controller| {
                    player_reference_supported(controller)
                        || player_complement_reference_supported(controller)
                })
        }
        Some("union") => candidates["sets"]
            .as_array()
            .is_some_and(|sets| !sets.is_empty() && sets.iter().all(target_candidates_supported)),
        _ => false,
    }
}

fn target_reference_supported(reference: &Value) -> bool {
    matches!(
        value_kind(reference),
        Some("triggeringPermanent" | "triggeringStackObject" | "cardExiledWithSource")
    ) || (matches!(
        value_kind(reference),
        Some("chosenTarget" | "chosenObject" | "boundValue")
    ) && reference["id"].is_string())
        || (matches!(
            value_kind(reference),
            Some("boundObject" | "singleBoundObject")
        ) && reference["binding"].is_string())
        || value_kind(reference) == Some("blockingPermanent")
        || value_kind(reference) == Some("combatCounterpart")
        || (value_kind(reference) == Some("attachedPermanent")
            && value_kind(&reference["attachment"]) == Some("self"))
}

fn move_operation_supported(operation: &Value) -> bool {
    let from_supported = matches!(value_kind(&operation["from"]), Some("graveyard" | "hand"))
        && player_reference_supported(&operation["from"]["player"]);
    let objects_supported = object_expression_supported(&operation["objects"])
        || target_reference_supported(&operation["objects"]);
    from_supported && objects_supported && value_kind(&operation["to"]) == Some("exile")
}

fn player_reference_supported(reference: &Value) -> bool {
    match value_kind(reference) {
        Some("controllerOfObject") => {
            object_context::object_context_reference_supported(&reference["object"])
        }
        Some("controllerOf" | "ownerOf") => {
            matches!(
                value_kind(&reference["object"]),
                Some("self" | "abilitySource")
            ) || target_reference_supported(&reference["object"])
                // The observed entering object: live, else last known.
                || entry_observation::observed_object_reference_supported(&reference["object"])
        }
        Some("abilityController") => true,
        Some("eachPlayer") => true,
        Some("triggeringPlayer") => true,
        Some("controllerOfAttachedPermanent") => {
            value_kind(&reference["attachment"]) == Some("self")
        }
        Some("opponentsOf") => player_reference_supported(&reference["player"]),
        // CR 102.3: every player but the named one, teammates included.
        Some("playersExcept") => player_complement_reference_supported(reference),
        Some("chosenTarget" | "chosenObject" | "boundValue") => reference["id"].is_string(),
        _ => false,
    }
}

fn singular_player_reference_supported(reference: &Value) -> bool {
    !matches!(
        value_kind(reference),
        Some("eachPlayer" | "opponentsOf" | "playersExcept")
    ) && player_reference_supported(reference)
}

fn player_complement_reference_supported(reference: &Value) -> bool {
    value_kind(reference) == Some("playersExcept")
        && matches!(
            value_kind(&reference["player"]),
            Some("abilityController" | "controllerOf")
        )
        && (value_kind(&reference["player"]) == Some("abilityController")
            || matches!(
                value_kind(&reference["player"]["object"]),
                Some("self" | "abilitySource")
            ))
}

fn player_set_reference_supported(reference: &Value) -> bool {
    match value_kind(reference) {
        Some("randomPlayer") => true,
        Some("randomOpponentOf") => player_reference_supported(&reference["player"]),
        _ => player_reference_supported(reference),
    }
}

fn keyword_kind_supported(value: &Value) -> bool {
    if value_kind(value).is_some_and(landwalk::is_landwalk_keyword) {
        return true;
    }
    matches!(
        value_kind(value),
        Some(
            "cantBlock"
                | "cantAttack"
                | "cantBeBlocked"
                | "attackEachCombatIfAble"
                | "blockEachCombatIfAble"
                | "changeling"
                | "deathtouch"
                | "devoid"
                | "defender"
                | "delve"
                | "doubleStrike"
                | "fear"
                | "flanking"
                | "flash"
                | "flashIfTargetsCommander"
                | "firstStrike"
                | "flying"
                | "sunburst"
                | "haste"
                | "hexproof"
                | "horsemanship"
                | "indestructible"
                | "infect"
                | "intimidate"
                | "lifelink"
                | "menace"
                | "mustBeBlockedIfAble"
                | "allMustBlockIfAble"
                | "maxOneBlocker"
                | "openingHandBattlefield"
                | "prowess"
                | "persist"
                | "protectionFromOpponents"
                | "reach"
                | "readAhead"
                | "riot"
                | "shadow"
                | "splitSecond"
                | "exalted"
                | "shroud"
                | "skulk"
                | "storied"
                | "trample"
                | "umbraArmor"
                | "undying"
                | "vigilance"
                | "wither"
        )
    ) || (value_kind(value) == Some("toxic")
        && integer_value(&value["count"]).is_some_and(|count| count > 0))
}

/// CR 702.16a: protection from qualities the engine evaluates by name.
fn protection_ability_supported(value: &Value) -> bool {
    value_kind(value) == Some("protection")
        && value["from"].as_array().is_some_and(|qualities| {
            !qualities.is_empty() && qualities.iter().all(Value::is_string)
        })
}

fn ward_ability_supported(value: &Value) -> bool {
    value_kind(value) == Some("ward") && cost_supported(&value["cost"])
}

fn conditional_flash_ability_supported(value: &Value) -> bool {
    (value_kind(value) == Some("flashIfControls") && card_filter_supported(&value["where"]))
        || (value_kind(value) == Some("flashIfGraveyardThreshold")
            && card_filter_supported(&value["where"])
            && integer_value(&value["minimum"]).is_some_and(|minimum| minimum > 0))
}

fn paradigm_ability_supported(value: &Value) -> bool {
    value_kind(value) == Some("paradigm") && value["spellName"].is_string()
}

fn cycling_ability_supported(value: &Value) -> bool {
    value_kind(value) == Some("cycling")
        && cost_supported(&value["cost"])
        && value["activationZone"].as_str() == Some("hand")
        && value["costs"]
            .as_array()
            .is_some_and(|costs| costs.len() == 1 && costs.iter().all(cost_supported))
        && value["effects"].as_array().is_some_and(|effects| {
            effects.len() == 1
                && value_kind(&effects[0]) == Some("drawCards")
                && player_reference_supported(&effects[0]["player"])
                && integer_value(&effects[0]["count"]) == Some(1)
        })
}

fn kicker_ability_supported(value: &Value) -> bool {
    value_kind(value) == Some("kicker")
        && (cost_supported(&value["cost"])
            || value["costs"]
                .as_array()
                .is_some_and(|costs| costs.len() >= 2 && costs.iter().all(cost_supported)))
        && !value["repeatable"].as_bool().unwrap_or(false)
}

fn escalate_ability_supported(value: &Value) -> bool {
    value_kind(value) == Some("escalate") && cost_supported(&value["cost"])
}

fn escalate_cost(card: &CardDefinition) -> Option<&Value> {
    card.printed_rules()
        .iter()
        .filter(|rule| value_kind(rule) == Some("keywordAbility"))
        .find_map(|rule| {
            escalate_ability_supported(&rule["ability"]).then(|| &rule["ability"]["cost"])
        })
}

fn escalate_payment_count(decisions: &BTreeMap<String, Value>) -> usize {
    decisions
        .get("chosenModes")
        .and_then(Value::as_array)
        .map(|modes| modes.len().saturating_sub(1))
        .unwrap_or(0)
}

fn companion_ability_supported(value: &Value) -> bool {
    value_kind(value) == Some("companion")
        && match value_kind(&value["deckCondition"]) {
            Some("minimumDeckSizeExtra") => {
                integer_value(&value["deckCondition"]["count"]).is_some_and(|count| count >= 0)
            }
            Some("noRepeatedManaSymbol") => true,
            _ => false,
        }
        && value_kind(&value["acquisitionCost"]) == Some("payMana")
        && cost_supported(&value["acquisitionCost"])
        && value_kind(&value["timing"]) == Some("sorceryTiming")
}

fn companion_ability(card: &CardDefinition) -> Option<&Value> {
    card.printed_rules()
        .iter()
        .filter(|rule| value_kind(rule) == Some("keywordAbility"))
        .find_map(|rule| companion_ability_supported(&rule["ability"]).then(|| &rule["ability"]))
}

fn companion_deck_condition_met(
    ability: &Value,
    main_deck_size: usize,
    game_mode: GameMode,
    cards: &[CardDefinition],
) -> bool {
    let minimum_deck_size = match game_mode {
        GameMode::Legacy | GameMode::Free => crate::game_rules::LEGACY_MINIMUM_DECK_SIZE,
        GameMode::Commander | GameMode::DuelCommander => crate::game_rules::COMMANDER_DECK_SIZE,
        GameMode::Training => crate::game_rules::TRAINING_DECK_SIZE,
        GameMode::Training2 => crate::game_rules::TRAINING2_DECK_SIZE,
    };
    match value_kind(&ability["deckCondition"]) {
        Some("minimumDeckSizeExtra") => integer_value(&ability["deckCondition"]["count"])
            .and_then(|extra| usize::try_from(extra).ok())
            .is_some_and(|extra| main_deck_size >= minimum_deck_size.saturating_add(extra)),
        Some("noRepeatedManaSymbol") => cards
            .iter()
            .filter(|card| is_deck_library_card_for_mode(card, game_mode))
            .all(|card| {
                let mut seen = BTreeSet::new();
                parse_mana_symbols(&card.mana_cost)
                    .into_iter()
                    .all(|symbol| seen.insert(symbol))
            }),
        _ => false,
    }
}

fn splice_ability_supported(value: &Value) -> bool {
    value_kind(value) == Some("splice")
        && card_filter_supported(&value["onto"])
        && matches!(
            value_kind(&value["cost"]),
            Some("payMana" | "payLife" | "sacrificePermanent" | "discardCard" | "tap")
        )
        && cost_supported(&value["cost"])
}

fn splice_ability(card: &CardDefinition) -> Option<&Value> {
    card.printed_rules()
        .iter()
        .filter(|rule| value_kind(rule) == Some("keywordAbility"))
        .find_map(|rule| splice_ability_supported(&rule["ability"]).then(|| &rule["ability"]))
}

fn replace_rule_decision_ids(value: &mut Value, replacements: &BTreeMap<String, String>) {
    match value {
        Value::String(current) => {
            if let Some(replacement) = replacements.get(current) {
                *current = replacement.clone();
            }
        }
        Value::Array(values) => {
            for value in values {
                replace_rule_decision_ids(value, replacements);
            }
        }
        Value::Object(values) => {
            for value in values.values_mut() {
                replace_rule_decision_ids(value, replacements);
            }
        }
        Value::Null | Value::Bool(_) | Value::Number(_) => {}
    }
}

fn scoped_splice_spell_rules(card: &CardInstance) -> Vec<Value> {
    let mut rules = card
        .definition
        .printed_rules()
        .iter()
        .filter(|rule| value_kind(rule) == Some("spellAbility"))
        .cloned()
        .collect::<Vec<_>>();
    let replacements = rules
        .iter()
        .flat_map(|rule| {
            rule["declaration"]["decisions"]
                .as_array()
                .into_iter()
                .flatten()
        })
        .filter_map(|decision| decision["id"].as_str())
        .map(|id| (id.to_string(), format!("splice:{}:{id}", card.instance_id)))
        .collect::<BTreeMap<_, _>>();
    for rule in &mut rules {
        replace_rule_decision_ids(rule, &replacements);
    }
    rules
}

fn kicker_costs(value: &Value) -> Vec<&Value> {
    if let Some(costs) = value["costs"].as_array() {
        costs.iter().collect()
    } else if value.get("cost").is_some() {
        vec![&value["cost"]]
    } else {
        Vec::new()
    }
}

fn kicker_cost_decision_id(cost: &Value) -> Option<String> {
    let cost_key = match value_kind(cost) {
        Some("payMana") => cost["manaCost"].as_str()?.to_string(),
        _ => serde_json::to_string(cost).ok()?,
    };
    Some(format!("kickerPaid:{cost_key}"))
}

fn paid_hand_keyword_supported(value: &Value, expected_kind: &str) -> bool {
    value_kind(value) == Some(expected_kind) && cost_supported(&value["cost"])
}

fn typecycling_ability_supported(value: &Value) -> bool {
    value_kind(value) == Some("typecycling")
        && cost_supported(&value["cost"])
        && value["activationZone"].as_str() == Some("hand")
        && value["costs"]
            .as_array()
            .is_some_and(|costs| costs.len() == 1 && costs.iter().all(cost_supported))
        && card_filter_supported(&value["where"])
        && value["effects"]
            .as_array()
            .is_some_and(|effects| !effects.is_empty() && effects.iter().all(effect_supported))
}

fn equip_ability_supported(value: &Value) -> bool {
    value_kind(value) == Some("equip")
        && value["costs"]
            .as_array()
            .is_some_and(|costs| !costs.is_empty() && costs.iter().all(cost_supported))
        && value.get("where").is_none_or(card_filter_supported)
        && value
            .get("targetCounterCostReduction")
            .is_none_or(|reduction| {
                reduction["counter"].is_string()
                    && integer_value(&reduction["amountPerCounter"])
                        .is_some_and(|amount| amount > 0)
            })
}

fn offspring_ability_supported(value: &Value) -> bool {
    value_kind(value) == Some("offspring")
        && value_kind(&value["cost"]) == Some("payMana")
        && value["cost"]["manaCost"]
            .as_str()
            .is_some_and(|cost| parse_mana_requirement(cost).is_some())
        && !value["repeatable"].as_bool().unwrap_or(false)
        && value_kind(&value["trigger"]["event"]) == Some("enterBattlefield")
        && value_kind(&value["trigger"]["event"]["object"]) == Some("self")
        && value_kind(&value["trigger"]["condition"]) == Some("offspringCostWasPaid")
        && value["trigger"]["effects"]
            .as_array()
            .is_some_and(|effects| !effects.is_empty() && effects.iter().all(effect_supported))
}

fn gift_ability_supported(value: &Value) -> bool {
    (value_kind(value) == Some("giftCard") && value["optional"].as_bool() == Some(true))
        || (value_kind(value) == Some("gift")
            && value["optional"].as_bool() == Some(true)
            && value["effects"]
                .as_array()
                .is_some_and(|effects| !effects.is_empty() && effects.iter().all(effect_supported)))
}

fn sacrifice_creature_alternative_cost_supported(value: &Value) -> bool {
    value_kind(value) == Some("sacrificeCreatureAlternativeCost")
        && card_filter_supported(&value["where"])
}

fn alternative_cost_supported(value: &Value) -> bool {
    value_kind(value) == Some("alternativeCost")
        && value.get("mode").is_none_or(Value::is_string)
        && value.get("condition").is_none_or(condition_supported)
        && value["costs"].as_array().is_some_and(|costs| {
            costs.iter().all(|cost| match value_kind(cost) {
                Some("payMana" | "payLife") => cost_supported(cost),
                Some("exileCard") => {
                    value_kind(&cost["zone"]) == Some("hand")
                        && player_reference_supported(&cost["zone"]["player"])
                        && card_filter_supported(&cost["where"])
                }
                Some("returnPermanentToOwnersHand") => card_filter_supported(&cost["where"]),
                _ => false,
            })
        })
}

