    fn enqueue_token_created_triggers(&mut self, controller_id: &str, token: &CardInstance) {
        let sources = self
            .state
            .players
            .iter()
            .filter(|player| !player.has_lost)
            .flat_map(|player| player.battlefield.iter().cloned())
            .collect::<Vec<_>>();
        let decisions = BTreeMap::from([(
            "triggeringPermanentId".to_string(),
            Value::String(token.instance_id.clone()),
        )]);
        for source in sources {
            if source.controller != controller_id {
                continue;
            }
            let rules = self
                .effective_rules(&source)
                .iter()
                .filter(|rule| {
                    triggered_rule_supported(rule)
                        && self.battlefield_observer_rule_active(&source, rule)
                        && triggered_event_variants(&rule["event"])
                            .iter()
                            .any(|event| {
                                matches!(
                                    value_kind(event),
                                    Some("tokenCreated" | "tokenCreatedOrSacrificed")
                                ) && event.get("where").is_none_or(|where_filter| {
                                    self.permanent_state_matches(token, where_filter)
                                })
                            })
                })
                .cloned()
                .collect::<Vec<_>>();
            for rule in rules {
                self.put_triggered_ability_on_stack_with_decisions(
                    &source,
                    rule,
                    decisions.clone(),
                );
                if self.check_quantity_failure().is_err() {
                    return;
                }
            }
        }
    }

    fn enqueue_mana_ability_activated_triggers(
        &mut self,
        mana_source: &CardInstance,
        produced_mana: &[String],
    ) {
        let trigger_sources = self
            .state
            .players
            .iter()
            .filter(|player| !player.has_lost)
            .flat_map(|player| player.battlefield.iter().cloned())
            .collect::<Vec<_>>();
        let decisions = BTreeMap::from([
            (
                "triggeringPermanentId".to_string(),
                Value::String(mana_source.instance_id.clone()),
            ),
            (
                "triggeringPermanentController".to_string(),
                Value::String(mana_source.controller.clone()),
            ),
            (
                "triggeringPlayerId".to_string(),
                Value::String(mana_source.controller.clone()),
            ),
            ("manaProduced".to_string(), json!(produced_mana)),
        ]);
        for trigger_source in trigger_sources {
            let rules = self
                .effective_rules(&trigger_source)
                .iter()
                .filter(|rule| {
                    triggered_rule_supported(rule)
                        && self.rule_active_for_source(&trigger_source, rule)
                        && triggered_event_variants(&rule["event"])
                            .iter()
                            .any(|event| match value_kind(event) {
                                Some("manaAbilityActivated") => {
                                    trigger_source.instance_id == mana_source.instance_id
                                }
                                Some("controlledPermanentManaAbilityActivated") => {
                                    (event["anyPlayer"].as_bool() == Some(true)
                                        || trigger_source.controller == mana_source.controller)
                                        && matches_card_filter(
                                            &mana_source.definition,
                                            &event["where"],
                                        )
                                }
                                Some("abilityActivated") => {
                                    trigger_source.controller == mana_source.controller
                                        && matches_card_filter(
                                            &mana_source.definition,
                                            &event["where"],
                                        )
                                }
                                _ => false,
                            })
                })
                .cloned()
                .collect::<Vec<_>>();
            for rule in rules {
                self.put_triggered_ability_on_stack_with_decisions(
                    &trigger_source,
                    rule,
                    decisions.clone(),
                );
                if self.check_quantity_failure().is_err() {
                    return;
                }
            }
        }
    }

    fn enqueue_card_discarded_triggers(&mut self, discarding_player_id: &str) {
        let discarded_id = self
            .state
            .events
            .iter()
            .rev()
            .find(|event| {
                event.kind == "cardDiscarded"
                    && event.player_id.as_deref() == Some(discarding_player_id)
            })
            .and_then(|event| event.card_instance_id.clone());
        let discarded_card = discarded_id
            .as_deref()
            .and_then(|instance_id| self.card_after_player_action(instance_id));
        let sources = self
            .state
            .players
            .iter()
            .filter(|player| !player.has_lost)
            .flat_map(|player| player.battlefield.iter().cloned())
            .collect::<Vec<_>>();
        for source in sources {
            let rules = self
                .effective_rules(&source)
                .iter()
                .filter(|rule| {
                    triggered_rule_supported(rule)
                        && self.rule_active_for_source(&source, rule)
                        && triggered_event_variants(&rule["event"])
                            .iter()
                            .any(|event| {
                                (value_kind(event) == Some("playerDiscardedCard")
                                    && self.player_card_action_matches(
                                        event,
                                        &source,
                                        discarding_player_id,
                                        discarded_card.as_ref(),
                                    ))
                                    || (value_kind(event) == Some("opponentDiscardedCard")
                                        && source.controller != discarding_player_id)
                            })
                })
                .cloned()
                .collect::<Vec<_>>();
            for rule in rules {
                let mut decisions = BTreeMap::from([(
                    "triggeringPlayerId".to_string(),
                    Value::String(discarding_player_id.to_string()),
                )]);
                if let Some(instance_id) = &discarded_id {
                    decisions.insert(
                        "discardedCardInstanceId".to_string(),
                        Value::String(instance_id.clone()),
                    );
                }
                self.put_triggered_ability_on_stack_with_decisions(&source, rule, decisions);
                if self.check_quantity_failure().is_err() {
                    return;
                }
            }
        }
        let discarded = self
            .state
            .events
            .iter()
            .rev()
            .find(|event| {
                event.kind == "cardDiscarded"
                    && event.player_id.as_deref() == Some(discarding_player_id)
            })
            .and_then(|event| event.card_instance_id.as_deref())
            .and_then(|instance_id| {
                self.player_index(discarding_player_id)
                    .ok()
                    .and_then(|player_index| {
                        self.state.players[player_index]
                            .graveyard
                            .iter()
                            .find(|card| card.instance_id == instance_id)
                            .cloned()
                    })
            });
        if let Some(discarded) = discarded {
            let self_discard_rules = self
                .effective_rules(&discarded)
                .iter()
                .filter(|rule| {
                    triggered_rule_supported(rule)
                        && triggered_event_variants(&rule["event"])
                            .iter()
                            .any(|event| value_kind(event) == Some("selfDiscarded"))
                })
                .cloned()
                .collect::<Vec<_>>();
            for rule in self_discard_rules {
                self.put_triggered_ability_on_stack_with_decisions(
                    &discarded,
                    rule,
                    BTreeMap::new(),
                );
                if self.check_quantity_failure().is_err() {
                    return;
                }
            }
            self.enqueue_cards_entered_graveyard_triggers_from(
                discarding_player_id,
                std::slice::from_ref(&discarded),
                "hand",
            );
        } else {
            self.enqueue_opponent_card_entered_graveyard_triggers(discarding_player_id, &[]);
        }
    }

    fn enqueue_opponent_card_entered_graveyard_triggers(
        &mut self,
        player_id: &str,
        cards: &[CardInstance],
    ) {
        let sources = self
            .state
            .players
            .iter()
            .filter(|player| !player.has_lost)
            .flat_map(|player| player.battlefield.iter())
            .filter(|source| source.controller != player_id)
            .cloned()
            .collect::<Vec<_>>();
        let mut triggers = Vec::new();
        for source in sources {
            for rule in self.effective_rules(&source).iter() {
                if !triggered_rule_supported(rule) {
                    continue;
                }
                let events = triggered_event_variants(&rule["event"])
                    .into_iter()
                    .filter(|event| value_kind(event) == Some("opponentCardEnteredGraveyard"))
                    .collect::<Vec<_>>();
                if events.is_empty() {
                    continue;
                }
                if cards.is_empty() {
                    if events.iter().any(|event| event.get("where").is_none()) {
                        triggers.push((source.clone(), rule.clone(), None));
                    }
                    continue;
                }
                for card in cards {
                    if events.iter().any(|event| {
                        event
                            .get("where")
                            .is_none_or(|filter| matches_card_filter(&card.definition, filter))
                    }) {
                        triggers.push((
                            source.clone(),
                            rule.clone(),
                            Some(card.instance_id.clone()),
                        ));
                    }
                }
            }
        }
        for (source, rule, triggering_card_id) in triggers {
            let mut decisions = BTreeMap::from([(
                "triggeringPlayerId".to_string(),
                Value::String(player_id.to_string()),
            )]);
            if let Some(card_id) = triggering_card_id {
                decisions.insert(
                    "triggeringCardIds".to_string(),
                    Value::Array(vec![Value::String(card_id)]),
                );
            }
            self.put_triggered_ability_on_stack_with_decisions(&source, rule, decisions);
            if self.check_quantity_failure().is_err() {
                return;
            }
        }
    }

    fn enqueue_cards_entered_graveyard_triggers(
        &mut self,
        player_id: &str,
        cards: &[CardInstance],
    ) {
        self.enqueue_cards_entered_graveyard_triggers_with_record(player_id, cards, true, None);
    }

    /// Cards entering a graveyard from a known zone (CR 400.1): the arrival
    /// records carry their origin for `from your library`-style patterns.
    fn enqueue_cards_entered_graveyard_triggers_from(
        &mut self,
        player_id: &str,
        cards: &[CardInstance],
        from: &'static str,
    ) {
        self.enqueue_cards_entered_graveyard_triggers_with_record(
            player_id,
            cards,
            true,
            Some(from),
        );
    }

    fn record_cards_entered_graveyard_event(&mut self, player_id: &str, cards: &[CardInstance]) {
        if cards.is_empty() {
            return;
        }
        self.record_event(
            "cardsEnteredGraveyard",
            Some(player_id.to_string()),
            None,
            event_history::graveyard_arrival_detail(cards),
        );
    }

    fn enqueue_recorded_cards_entered_graveyard_triggers(
        &mut self,
        player_id: &str,
        cards: &[CardInstance],
    ) {
        // Recorded sacrifice batches: the cards came from the battlefield.
        self.enqueue_cards_entered_graveyard_triggers_with_record(
            player_id,
            cards,
            false,
            Some("battlefield"),
        );
    }

    fn enqueue_cards_entered_graveyard_triggers_with_record(
        &mut self,
        player_id: &str,
        cards: &[CardInstance],
        record_event: bool,
        from: Option<&'static str>,
    ) {
        if cards.is_empty() {
            return;
        }
        let mut triggers = self
            .state
            .players
            .iter()
            .filter(|player| !player.has_lost)
            .flat_map(|player| player.battlefield.iter().cloned())
            .filter(|source| source.controller == player_id)
            .flat_map(|source| {
                self.effective_rules(&source)
                    .iter()
                    .filter(|rule| {
                        triggered_rule_supported(rule)
                            && self.rule_active_for_source(&source, rule)
                            && triggered_event_variants(&rule["event"])
                                .iter()
                                .any(|event| {
                                    value_kind(event) == Some("cardsEnteredGraveyard")
                                        && cards.iter().any(|card| {
                                            matches_card_filter(&card.definition, &event["where"])
                                        })
                                })
                    })
                    .cloned()
                    .map(|rule| (source.clone(), rule))
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();
        triggers.extend(cards.iter().flat_map(|source| {
            // The card's own `put into a graveyard from anywhere` abilities.
            let arrival = zone_change_events::ZoneChangeRecord {
                object: source,
                from,
                to: "graveyard",
                reason: None,
            };
            self.effective_rules(&source)
                .iter()
                .filter(|rule| {
                    triggered_rule_supported(rule)
                        && self.rule_matches_zone_change(
                            rule,
                            zone_change_events::ZoneChangeGroup::GraveyardArrival,
                            &arrival,
                            source,
                        )
                })
                .cloned()
                .map(|rule| (source.clone(), rule))
                .collect::<Vec<_>>()
        }));
        // Battlefield observers of cards arriving in a graveyard (generic
        // move pattern): per card, or once per simultaneous event.
        let arrival_observers = self
            .state
            .players
            .iter()
            .filter(|player| !player.has_lost)
            .flat_map(|player| player.battlefield.iter())
            .flat_map(|observer| {
                self.effective_rules(&observer)
                    .iter()
                    .filter(|rule| {
                        triggered_rule_supported(rule)
                            && self.rule_active_for_source(observer, rule)
                    })
                    .filter_map(|rule| {
                        let matching = cards
                            .iter()
                            .filter(|card| {
                                self.rule_matches_zone_change(
                                    rule,
                                    zone_change_events::ZoneChangeGroup::GraveyardArrival,
                                    &zone_change_events::ZoneChangeRecord {
                                        object: card,
                                        from,
                                        to: "graveyard",
                                        reason: None,
                                    },
                                    observer,
                                )
                            })
                            .map(|card| Value::String(card.instance_id.clone()))
                            .collect::<Vec<_>>();
                        (!matching.is_empty()).then(|| (observer.clone(), rule.clone(), matching))
                    })
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();
        let card_ids = cards
            .iter()
            .map(|card| card.instance_id.clone())
            .collect::<Vec<_>>();
        if record_event {
            self.record_cards_entered_graveyard_event(player_id, cards);
        }
        for (observer, rule, matching) in arrival_observers {
            let occurrences = if triggered_event_variants(&rule["event"])
                .into_iter()
                .any(event_batch::event_is_aggregated)
            {
                if self.aggregated_trigger_already_claimed(&observer.instance_id, &rule) {
                    continue;
                }
                vec![matching]
            } else {
                matching.into_iter().map(|id| vec![id]).collect()
            };
            for ids in occurrences {
                self.put_triggered_ability_on_stack_with_decisions(
                    &observer,
                    rule.clone(),
                    BTreeMap::from([("triggeringCardIds".to_string(), Value::Array(ids))]),
                );
                if self.check_quantity_failure().is_err() {
                    return;
                }
            }
        }
        for (source, rule) in triggers {
            self.put_triggered_ability_on_stack_with_decisions(
                &source,
                rule,
                BTreeMap::from([(
                    "triggeringCardIds".to_string(),
                    Value::Array(card_ids.iter().cloned().map(Value::String).collect()),
                )]),
            );
            if self.check_quantity_failure().is_err() {
                return;
            }
        }
        self.enqueue_opponent_card_entered_graveyard_triggers(player_id, cards);
    }

    fn enqueue_cards_left_graveyard_triggers(&mut self, player_id: &str, card_ids: &[String]) {
        if card_ids.is_empty() {
            return;
        }
        let sources = self
            .state
            .players
            .iter()
            .filter(|player| !player.has_lost)
            .flat_map(|player| player.battlefield.iter().cloned())
            .collect::<Vec<_>>();
        for source in sources {
            if source.controller != player_id {
                continue;
            }
            let mut triggers = Vec::new();
            for rule in self.effective_rules(&source).iter() {
                if !triggered_rule_supported(rule) || !self.rule_active_for_source(&source, rule) {
                    continue;
                }
                let Some((aggregation, matching_card_ids)) =
                    triggered_event_variants(&rule["event"])
                        .iter()
                        .find_map(|event| {
                            if value_kind(event) != Some("cardsLeftGraveyard") {
                                return None;
                            }
                            let matching_card_ids = card_ids
                                .iter()
                                .filter(|instance_id| {
                                    self.permanent_position(instance_id)
                                        .map(|(player_index, card_index)| {
                                            &self.state.players[player_index].battlefield
                                                [card_index]
                                        })
                                        .or_else(|| self.card_outside_battlefield(instance_id))
                                        .is_some_and(|card| {
                                            event.get("where").is_none_or(|filter| {
                                                matches_card_filter(&card.definition, filter)
                                            })
                                        })
                                })
                                .cloned()
                                .collect::<Vec<_>>();
                            (!matching_card_ids.is_empty()).then(|| {
                                (
                                    event
                                        .get("aggregation")
                                        .and_then(Value::as_str)
                                        .unwrap_or("oneOrMore"),
                                    matching_card_ids,
                                )
                            })
                        })
                else {
                    continue;
                };
                match aggregation {
                    "perCard" => triggers.extend(
                        matching_card_ids
                            .into_iter()
                            .map(|card_id| (rule.clone(), vec![card_id])),
                    ),
                    // Missing aggregation preserves the historical batch semantics.
                    "oneOrMore" => triggers.push((rule.clone(), matching_card_ids)),
                    _ => continue,
                }
            }
            for (rule, triggering_card_ids) in triggers {
                self.put_triggered_ability_on_stack_with_decisions(
                    &source,
                    rule,
                    BTreeMap::from([(
                        "triggeringCardIds".to_string(),
                        Value::Array(triggering_card_ids.into_iter().map(Value::String).collect()),
                    )]),
                );
                if self.check_quantity_failure().is_err() {
                    return;
                }
            }
        }
    }

    fn enqueue_dungeon_completed_triggers(&mut self, player_id: &str, dungeon_id: &str) {
        let triggers = self
            .state
            .players
            .iter()
            .filter(|player| !player.has_lost)
            .flat_map(|player| player.battlefield.iter().cloned())
            .filter(|source| source.controller == player_id)
            .flat_map(|source| {
                self.effective_rules(&source)
                    .iter()
                    .filter(|rule| {
                        triggered_rule_supported(rule)
                            && self.rule_active_for_source(&source, rule)
                            && triggered_event_variants(&rule["event"])
                                .iter()
                                .any(|event| value_kind(event) == Some("dungeonCompleted"))
                    })
                    .cloned()
                    .map(|rule| (source.clone(), rule))
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();
        for (source, rule) in triggers {
            self.put_triggered_ability_on_stack_with_decisions(
                &source,
                rule,
                BTreeMap::from([(
                    "completedDungeonId".to_string(),
                    Value::String(dungeon_id.to_string()),
                )]),
            );
            if self.check_quantity_failure().is_err() {
                return;
            }
        }
    }

    fn restore_departure_linked_copies(&mut self, source_id: &str) {
        let linked_copy_restorations = self
            .state
            .rule_modifiers
            .iter()
            .filter(|modifier| {
                value_kind(modifier) == Some("copyWhileSourceOnBattlefield")
                    && modifier["sourceCardInstanceId"].as_str() == Some(source_id)
            })
            .cloned()
            .collect::<Vec<_>>();
        for restoration in &linked_copy_restorations {
            let Some(target_id) = restoration["targetCardInstanceId"].as_str() else {
                continue;
            };
            let Some((player_index, card_index)) = self.permanent_position(target_id) else {
                continue;
            };
            let Ok(original_definition) =
                serde_json::from_value::<CardDefinition>(restoration["originalDefinition"].clone())
            else {
                continue;
            };
            let original_printed_definition = serde_json::from_value::<Option<CardDefinition>>(
                restoration["originalPrintedDefinition"].clone(),
            )
            .unwrap_or(None);
            let restored = &mut self.state.players[player_index].battlefield[card_index];
            restored.definition = original_definition;
            restored.printed_definition = original_printed_definition;
        }
        self.state.rule_modifiers.retain(|modifier| {
            value_kind(modifier) != Some("copyWhileSourceOnBattlefield")
                || modifier["sourceCardInstanceId"].as_str() != Some(source_id)
                    && modifier["targetCardInstanceId"].as_str() != Some(source_id)
        });
    }

    fn enqueue_permanent_left_triggers_with_sources(
        &mut self,
        left: &CardInstance,
        destination: &str,
        captured: &[battlefield_departure::DepartureTriggerSource],
        captured_power: Option<i32>,
    ) {
        self.restore_departure_linked_copies(&left.instance_id);
        let sources = captured;
        let departure_power = captured_power.unwrap_or_else(|| self.current_power(left));
        let decisions = BTreeMap::from([
            (
                "triggeringPermanentId".to_string(),
                Value::String(left.instance_id.clone()),
            ),
            (
                "triggeringPermanentController".to_string(),
                Value::String(left.controller.clone()),
            ),
            (
                "triggeringPermanentPower".to_string(),
                Value::from(departure_power),
            ),
            (
                "triggeringPermanentWasAttacking".to_string(),
                Value::Bool(left.flags.get("attacking").copied().unwrap_or(false)),
            ),
            (
                "leftBattlefieldDestination".to_string(),
                Value::String(destination.to_string()),
            ),
        ]);
        if let Err(error) = self.enqueue_delayed_zone_change_triggers(left, destination, &decisions)
        {
            self.defer_quantity_failure(error);
            return;
        }
        // One typed record of the zone-change family, matched by the sources
        // captured before the departure (look-back, CR 603.10a).
        let departure_record = zone_change_events::ZoneChangeRecord {
            object: left,
            from: Some("battlefield"),
            to: destination,
            reason: None,
        };
        for observer in sources {
            let source = &observer.source;
            let rules = observer
                .rules
                .iter()
                .filter(|rule| {
                    triggered_rule_supported(rule)
                        && rule.get("condition").is_none_or(|condition| {
                            self.condition_value_with_source(
                                condition,
                                &source.controller,
                                &BTreeMap::new(),
                                Some(&source),
                            )
                        })
                        && self.rule_matches_zone_change(
                            rule,
                            zone_change_events::ZoneChangeGroup::Departure,
                            &departure_record,
                            source,
                        )
                })
                .cloned()
                .collect::<Vec<_>>();
            for rule in rules {
                // `one or more` departures: once per simultaneous event.
                if self.aggregated_trigger_already_claimed(&source.instance_id, &rule) {
                    continue;
                }
                self.put_triggered_ability_on_stack_with_multiplicity(
                    &source,
                    rule,
                    decisions.clone(),
                    Some(&observer.multiplicity),
                    trigger_multiplicity::CapturedOccurrence::Departure,
                );
                if self.check_quantity_failure().is_err() {
                    return;
                }
            }
        }
        self.queue_linked_exile_return(left);
        let linked_token_ids = self
            .state
            .rule_modifiers
            .iter()
            .filter(|modifier| {
                value_kind(modifier) == Some("exileTokenWhenSourceLeaves")
                    && modifier["sourceCardInstanceId"].as_str() == Some(left.instance_id.as_str())
            })
            .filter_map(|modifier| modifier["tokenId"].as_str().map(ToOwned::to_owned))
            .collect::<Vec<_>>();
        if !linked_token_ids.is_empty() {
            self.state.rule_modifiers.retain(|modifier| {
                value_kind(modifier) != Some("exileTokenWhenSourceLeaves")
                    || modifier["sourceCardInstanceId"].as_str() != Some(left.instance_id.as_str())
            });
            self.put_triggered_ability_on_stack_with_origin(
                left,
                json!({
                    "kind": "triggeredAbility",
                    "source": { "kind": "self" },
                    "effects": [{ "kind": "exileLinkedTokens" }],
                }),
                BTreeMap::from([(
                    "linkedTokenIds".to_string(),
                    Value::Array(linked_token_ids.into_iter().map(Value::String).collect()),
                )]),
                trigger_multiplicity::TriggerOrigin::Delayed,
            );
            if self.check_quantity_failure().is_err() {
                return;
            }
        }
        let linked_cards = self
            .state
            .rule_modifiers
            .iter()
            .filter(|modifier| {
                value_kind(modifier) == Some("returnExiledCardWhenTokenLeaves")
                    && modifier["tokenId"].as_str() == Some(left.instance_id.as_str())
            })
            .filter_map(|modifier| modifier["cardInstanceId"].as_str().map(ToOwned::to_owned))
            .collect::<Vec<_>>();
        self.state.rule_modifiers.retain(|modifier| {
            value_kind(modifier) != Some("returnExiledCardWhenTokenLeaves")
                || modifier["tokenId"].as_str() != Some(left.instance_id.as_str())
        });
        for instance_id in linked_cards {
            self.put_triggered_ability_on_stack_with_origin(
                left,
                json!({
                    "kind": "triggeredAbility",
                    "source": { "kind": "self" },
                    "effects": [{ "kind": "returnLinkedExiledCardToHand" }],
                }),
                BTreeMap::from([("linkedExiledCardId".to_string(), Value::String(instance_id))]),
                trigger_multiplicity::TriggerOrigin::Unproven,
            );
            if self.check_quantity_failure().is_err() {
                return;
            }
        }
        self.state.rule_modifiers.retain(|modifier| {
            value_kind(modifier) != Some("usedPersistentMode")
                || modifier["sourceCardInstanceId"].as_str() != Some(left.instance_id.as_str())
        });
    }

    fn enqueue_damage_to_opponent_triggers(
        &mut self,
        source_controller: &str,
        damaged_player_id: &str,
        amount: i32,
        source_id: &str,
        combat: bool,
    ) {
        self.enqueue_player_damage_observers(
            source_controller,
            source_id,
            combat,
            &[player_damage_batch::PlayerDamageRecord {
                player_id: damaged_player_id.into(),
                amount,
                infect: false,
            }],
            None,
        );
    }

    fn enqueue_declared_attacker_triggers(&mut self, attacker_ids: &[String]) {
        let mut triggers = Vec::new();
        // One typed record per declared attacker (event_model).
        let attack_records = self.attack_records(attacker_ids);
        let attacking_controllers = attacker_ids
            .iter()
            .filter_map(|attacker_id| self.permanent_position(attacker_id))
            .map(|(player_index, card_index)| {
                self.state.players[player_index].battlefield[card_index]
                    .controller
                    .clone()
            })
            .collect::<BTreeSet<_>>();
        let opponent_attack_triggers = self
            .state
            .rule_modifiers
            .iter()
            .filter(|modifier| value_kind(modifier) == Some("delayedOpponentAttackTrigger"))
            .cloned()
            .collect::<Vec<_>>();
        for modifier in opponent_attack_triggers {
            let controller_id = modifier["controllerId"].as_str().unwrap_or_default();
            let matching_attackers = self
                .state
                .combat
                .attackers
                .iter()
                .filter(|assignment| attacker_ids.contains(&assignment.attacker_id))
                .filter(|assignment| assignment.defending_player_id != controller_id)
                .map(|assignment| Value::String(assignment.attacker_id.clone()))
                .collect::<Vec<_>>();
            if matching_attackers.is_empty() {
                continue;
            }
            let Some(source) = modifier
                .get("sourceCard")
                .cloned()
                .and_then(|source| serde_json::from_value::<CardInstance>(source).ok())
            else {
                continue;
            };
            self.put_triggered_ability_on_stack_with_origin(
                &source,
                json!({
                    "kind": "triggeredAbility",
                    "source": { "kind": "self" },
                    "effects": modifier["effects"],
                }),
                BTreeMap::from([(
                    "triggeringAttackerIds".to_string(),
                    Value::Array(matching_attackers),
                )]),
                trigger_multiplicity::TriggerOrigin::Delayed,
            );
            if self.check_quantity_failure().is_err() {
                return;
            }
            if let Some(last) = self.state.stack.last_mut() {
                last.controller = controller_id.to_string();
            }
        }
        let protected_delayed_triggers = self
            .state
            .rule_modifiers
            .iter()
            .filter(|modifier| {
                value_kind(modifier) == Some("delayedTriggeredAbility")
                    && matches!(
                        value_kind(&modifier["event"]),
                        Some("permanentAttacks" | "permanentAttacksProtectedPlayerOrPlaneswalker")
                    )
            })
            .cloned()
            .collect::<Vec<_>>();
        for modifier in protected_delayed_triggers {
            let Some(source) = modifier
                .get("sourceCard")
                .cloned()
                .and_then(|source| serde_json::from_value::<CardInstance>(source).ok())
            else {
                continue;
            };
            let controller_id = modifier["controllerId"]
                .as_str()
                .unwrap_or(source.controller.as_str())
                .to_string();
            let matching_attackers = self
                .state
                .combat
                .attackers
                .iter()
                .filter(|assignment| attacker_ids.contains(&assignment.attacker_id))
                .filter(|assignment| {
                    if value_kind(&modifier["event"]) == Some("permanentAttacks") {
                        let Some((player_index, card_index)) =
                            self.permanent_position(&assignment.attacker_id)
                        else {
                            return false;
                        };
                        let attacker = &self.state.players[player_index].battlefield[card_index];
                        self.permanent_matches_effective_filter(
                            attacker,
                            &modifier["event"]["attacker"],
                        ) && self.attack_defender_matches_predicate(
                            &modifier["event"]["defender"],
                            &assignment.defender,
                        )
                    } else {
                        modifier["event"]["protectedPlayerId"].as_str().is_some_and(
                            |protected_player_id| {
                                assignment.defending_player_id == protected_player_id
                            },
                        )
                    }
                })
                .map(|assignment| assignment.attacker_id.clone())
                .collect::<Vec<_>>();
            for attacker_id in matching_attackers {
                self.put_triggered_ability_on_stack_with_origin(
                    &source,
                    json!({
                        "kind": "triggeredAbility",
                        "source": { "kind": "self" },
                        "effects": modifier["effects"],
                    }),
                    BTreeMap::from([(
                        "triggeringPermanentId".to_string(),
                        Value::String(attacker_id),
                    )]),
                    trigger_multiplicity::TriggerOrigin::Delayed,
                );
                if self.check_quantity_failure().is_err() {
                    return;
                }
                if let Some(last) = self.state.stack.last_mut() {
                    last.controller = controller_id.clone();
                }
            }
        }
        let delayed_triggers = self
            .state
            .rule_modifiers
            .iter()
            .filter(|modifier| {
                value_kind(modifier) == Some("delayedAttackTrigger")
                    && modifier["playerId"]
                        .as_str()
                        .is_some_and(|player_id| attacking_controllers.contains(player_id))
            })
            .filter_map(|modifier| {
                let source = modifier
                    .get("sourceCard")
                    .cloned()
                    .and_then(|source| serde_json::from_value::<CardInstance>(source).ok())
                    .or_else(|| {
                        modifier["sourceCardInstanceId"]
                            .as_str()
                            .and_then(|source_id| self.permanent_position(source_id))
                            .map(|(player_index, card_index)| {
                                self.state.players[player_index].battlefield[card_index].clone()
                            })
                    })?;
                let mut rule = json!({
                    "kind": "triggeredAbility",
                    "source": { "kind": "self" },
                    "event": {
                        "kind": "declaredAttackers",
                        "player": modifier["playerId"],
                    },
                    "effects": modifier["effects"],
                });
                if let Some(declaration) = modifier.get("declaration") {
                    rule["declaration"] = declaration.clone();
                }
                Some((source, rule, trigger_multiplicity::TriggerOrigin::Delayed))
            })
            .collect::<Vec<_>>();
        triggers.extend(delayed_triggers);
        for attacker_id in attacker_ids {
            let Some((player_index, card_index)) = self.permanent_position(attacker_id) else {
                continue;
            };
            let source = self.state.players[player_index].battlefield[card_index].clone();
            if self.ring_bearer_level(&source) >= 2 {
                triggers.push((
                    source.clone(),
                    json!({
                        "kind": "triggeredAbility",
                        "source": { "kind": "self" },
                        "event": { "kind": "declaredAttacker", "object": { "kind": "self" } },
                        "effects": [
                            {
                                "kind": "drawCards",
                                "player": { "kind": "controllerOf", "object": { "kind": "self" } },
                                "count": { "kind": "integer", "value": 1 },
                            },
                            {
                                "kind": "discardCards",
                                "player": { "kind": "controllerOf", "object": { "kind": "self" } },
                                "count": { "kind": "integer", "value": 1 },
                            },
                        ],
                    }),
                    trigger_multiplicity::TriggerOrigin::Emblem,
                ));
            }
            if let Some(quantity) = self
                .effective_rules(&source)
                .iter()
                .filter(|rule| {
                    rule["temporaryUntilTurn"]
                        .as_u64()
                        .is_none_or(|turn| turn >= u64::from(self.state.turn_number))
                })
                .find_map(|rule| {
                    let abilities = match value_kind(rule) {
                        Some("keywordAbility") => vec![&rule["ability"]],
                        Some("keywordAbilityGroup") => {
                            rule["abilities"].as_array()?.iter().collect()
                        }
                        _ => return None,
                    };
                    abilities.into_iter().find_map(|ability| {
                        (value_kind(ability) == Some("annihilator"))
                            .then(|| integer_value(&ability["quantity"]))
                            .flatten()
                    })
                })
            {
                triggers.push((
                    source.clone(),
                    json!({
                        "kind": "triggeredAbility",
                        "source": { "kind": "self" },
                        "event": {
                            "kind": "declaredAttacker",
                            "object": { "kind": "self" },
                        },
                        "effects": [{
                            "kind": "sacrificePermanents",
                            "player": { "kind": "triggeringPlayer" },
                            "where": Value::Null,
                            "count": { "kind": "integer", "value": quantity },
                        }],
                    }),
                    trigger_multiplicity::TriggerOrigin::ObjectAbility,
                ));
            }
            let record = attack_records
                .iter()
                .find(|record| record.attacker == *attacker_id);
            for rule in self.effective_rules(&source).iter().filter(|rule| {
                triggered_rule_supported(rule)
                    && record.is_some_and(|record| {
                        self.rule_matches_combat_record(
                            rule,
                            event_model::PublicationGroup::AttackSource,
                            record,
                            &source,
                        )
                    })
                    && rule.get("condition").is_none_or(|condition| {
                        self.condition_value_with_source(
                            condition,
                            &source.controller,
                            &BTreeMap::new(),
                            Some(&source),
                        )
                    })
            }) {
                triggers.push((
                    source.clone(),
                    rule.clone(),
                    trigger_multiplicity::TriggerOrigin::ObjectAbility,
                ));
            }
        }
        let battlefield_sources = self
            .state
            .players
            .iter()
            .filter(|player| !player.has_lost)
            .flat_map(|player| player.battlefield.iter().cloned())
            .collect::<Vec<_>>();
        for source in &battlefield_sources {
            let rules = self
                .effective_rules(&source)
                .iter()
                .filter(|rule| triggered_rule_supported(rule))
                .filter(|rule| {
                    event_model::rule_combat_patterns(rule)
                        .iter()
                        .any(|pattern| {
                            pattern.group == event_model::PublicationGroup::AttackControlled
                        })
                })
                .cloned()
                .collect::<Vec<_>>();
            for rule in rules {
                let matching_attackers = attack_records
                    .iter()
                    .filter(|record| {
                        self.rule_matches_combat_record(
                            &rule,
                            event_model::PublicationGroup::AttackControlled,
                            record,
                            source,
                        )
                    })
                    .filter_map(|record| {
                        self.combat_attacker_instance(&record.attacker)
                            .map(|attacker| (attacker, record.defending_player.clone()))
                    })
                    .collect::<Vec<_>>();
                // A generic pattern names the defending player (CR 506.2);
                // the historical kind keeps the attacker's controller.
                let generic = event_model::rule_combat_patterns(&rule)
                    .iter()
                    .any(|pattern| {
                        pattern.generic
                            && pattern.group == event_model::PublicationGroup::AttackControlled
                    });
                for (attacker, defending_player) in matching_attackers {
                    self.put_triggered_ability_on_stack_with_decisions(
                        source,
                        rule.clone(),
                        BTreeMap::from([
                            (
                                "triggeringPermanentId".to_string(),
                                Value::String(attacker.instance_id),
                            ),
                            (
                                "triggeringPlayerId".to_string(),
                                Value::String(if generic {
                                    defending_player
                                } else {
                                    attacker.controller
                                }),
                            ),
                        ]),
                    );
                    if self.check_quantity_failure().is_err() {
                        return;
                    }
                }
            }
        }
        if let [attacker_id] = attacker_ids {
            let attacker_controller =
                self.permanent_position(attacker_id)
                    .map(|(player_index, card_index)| {
                        self.state.players[player_index].battlefield[card_index]
                            .controller
                            .clone()
                    });
            if let Some(attacker_controller) = attacker_controller {
                let exalted_sources = battlefield_sources
                    .iter()
                    .filter(|source| {
                        source.controller == attacker_controller
                            && self.permanent_has_keyword(source, "exalted")
                    })
                    .cloned()
                    .collect::<Vec<_>>();
                for source in exalted_sources {
                    self.put_triggered_ability_on_stack_with_decisions(
                        &source,
                        json!({
                            "kind": "triggeredAbility",
                            "source": { "kind": "self" },
                            "event": {
                                "kind": "declaredAttacker",
                                "object": { "kind": "self" },
                            },
                            "effects": [{
                                "kind": "modifyPowerToughness",
                                "object": { "kind": "triggeringPermanent" },
                                "power": { "kind": "integer", "value": 1 },
                                "toughness": { "kind": "integer", "value": 1 },
                                "duration": { "kind": "untilEndOfCurrentTurn" },
                            }],
                        }),
                        BTreeMap::from([(
                            "triggeringPermanentId".to_string(),
                            Value::String(attacker_id.clone()),
                        )]),
                    );
                    if self.check_quantity_failure().is_err() {
                        return;
                    }
                }
            }
        }
        for source in battlefield_sources {
            for rule in self.effective_rules(&source).iter().filter(|rule| {
                triggered_rule_supported(rule)
                    && (attack_records.iter().any(|record| {
                        self.rule_matches_combat_record(
                            rule,
                            event_model::PublicationGroup::AttackAttached,
                            record,
                            &source,
                        )
                    }) || triggered_event_variants(&rule["event"])
                        .iter()
                        .any(|event| match value_kind(event) {
                            Some("attackDeclaredWithSourceOrCommander") => {
                                attacker_ids.contains(&source.instance_id)
                                    || attacker_ids.iter().any(|attacker_id| {
                                        self.permanent_position(attacker_id).is_some_and(
                                            |(player_index, card_index)| {
                                                let attacker = &self.state.players[player_index]
                                                    .battlefield[card_index];
                                                attacker.controller == source.controller
                                                    && is_commander_definition(&attacker.definition)
                                            },
                                        )
                                    })
                            }
                            Some("controlledCreaturesAttacked") => {
                                let controlled_attackers = attacker_ids
                                    .iter()
                                    .filter(|attacker_id| {
                                        self.permanent_position(attacker_id).is_some_and(
                                            |(player_index, card_index)| {
                                                let permanent = &self.state.players[player_index]
                                                    .battlefield[card_index];
                                                permanent.controller == source.controller
                                                    && event.get("where").is_none_or(
                                                        |where_filter| {
                                                            self.permanent_matches_effective_filter(
                                                                permanent,
                                                                where_filter,
                                                            )
                                                        },
                                                    )
                                            },
                                        )
                                    })
                                    .collect::<Vec<_>>();
                                let count = controlled_attackers.len();
                                let total_power = controlled_attackers
                                    .iter()
                                    .filter_map(|attacker_id| {
                                        self.permanent_position(attacker_id).map(
                                            |(player_index, card_index)| {
                                                self.current_power(
                                                    &self.state.players[player_index].battlefield
                                                        [card_index],
                                                )
                                            },
                                        )
                                    })
                                    .sum::<i32>();
                                count
                                    >= integer_value(&event["minimum"]).unwrap_or(1).max(1) as usize
                                    && integer_value(&event["maximum"])
                                        .is_none_or(|maximum| count <= maximum.max(0) as usize)
                                    && (event["sourceMustAttack"].as_bool() != Some(true)
                                        || attacker_ids.contains(&source.instance_id))
                                    && integer_value(&event["totalPowerAtLeast"])
                                        .is_none_or(|minimum| total_power >= minimum)
                                    && self.member_event_condition_holds(event, &source)
                            }
                            _ => false,
                        }))
            }) {
                if !triggers
                    .iter()
                    .any(|(candidate_source, candidate_rule, candidate_origin)| {
                        *candidate_origin == trigger_multiplicity::TriggerOrigin::ObjectAbility
                            && candidate_source.instance_id == source.instance_id
                            && candidate_rule == rule
                    })
                {
                    triggers.push((
                        source.clone(),
                        rule.clone(),
                        trigger_multiplicity::TriggerOrigin::ObjectAbility,
                    ));
                }
            }
        }
        for (source, rule, origin) in triggers {
            let triggering_attacker = attacker_ids
                .iter()
                .find(|attacker_id| **attacker_id == source.instance_id)
                .or_else(|| {
                    source
                        .attached_to
                        .as_ref()
                        .filter(|attached_to| attacker_ids.contains(attached_to))
                })
                .or_else(|| attacker_ids.first())
                .cloned();
            let decisions = triggering_attacker
                .map(|attacker_id| {
                    let mut decisions = BTreeMap::from([(
                        "triggeringPermanentId".to_string(),
                        Value::String(attacker_id.clone()),
                    )]);
                    if let Some(defending_player_id) = self
                        .state
                        .combat
                        .attackers
                        .iter()
                        .find(|assignment| assignment.attacker_id == attacker_id)
                        .map(|assignment| assignment.defending_player_id.clone())
                    {
                        decisions.insert(
                            "triggeringPlayerId".to_string(),
                            Value::String(defending_player_id),
                        );
                    }
                    decisions
                })
                .unwrap_or_default();
            self.put_triggered_ability_on_stack_with_origin(&source, rule, decisions, origin);
            if self.check_quantity_failure().is_err() {
                return;
            }
        }
    }

    fn enqueue_controlled_combat_damage_draw_triggers(&mut self, source_id: &str, amount: i32) {
        let Some((source_player, source_index)) = self.permanent_position(source_id) else {
            return;
        };
        let damage_source = self.state.players[source_player].battlefield[source_index].clone();
        let modifiers = self
            .state
            .rule_modifiers
            .iter()
            .filter(|modifier| {
                value_kind(modifier) == Some("controlledCombatDamageDrawUntilEndOfTurn")
                    && modifier["playerId"].as_str() == Some(damage_source.controller.as_str())
                    && modifier["permanentId"].as_str().is_none_or(|permanent_id| {
                        permanent_id == damage_source.instance_id.as_str()
                    })
                    && modifier["cardName"].as_str().is_none_or(|name| {
                        name.eq_ignore_ascii_case(&damage_source.definition.name)
                    })
                    && modifier["expiresAfterTurn"].as_u64()
                        == Some(u64::from(self.state.turn_number))
            })
            .filter_map(|modifier| {
                let count = integer_value(&modifier["count"]).filter(|count| *count > 0)?;
                Some((
                    serde_json::from_value::<CardInstance>(modifier["sourceCard"].clone()).ok()?,
                    if modifier["useDamageAmount"].as_bool() == Some(true) {
                        amount.max(0)
                    } else {
                        count
                    },
                ))
            })
            .collect::<Vec<_>>();
        for (source, count) in modifiers {
            self.put_triggered_ability_on_stack_with_origin(
                &source,
                json!({
                    "kind": "triggeredAbility",
                    "source": { "kind": "self" },
                    "effects": [{
                        "kind": "drawCards",
                        "player": { "kind": "controllerOf", "object": { "kind": "self" } },
                        "count": { "kind": "integer", "value": count },
                    }],
                }),
                BTreeMap::from([(
                    "triggeringPermanentId".to_string(),
                    Value::String(source_id.to_string()),
                )]),
                trigger_multiplicity::TriggerOrigin::Unproven,
            );
            if self.check_quantity_failure().is_err() {
                return;
            }
        }
    }

    fn enqueue_combat_damage_to_player_triggers(
        &mut self,
        source_id: &str,
        player_id: &str,
        amount: i32,
    ) {
        let Some((source_player, source_index)) = self.permanent_position(source_id) else {
            return;
        };
        let damage_source = self.state.players[source_player].battlefield[source_index].clone();
        let sources = self
            .state
            .players
            .iter()
            .filter(|player| !player.has_lost)
            .flat_map(|player| player.battlefield.iter().cloned())
            .collect::<Vec<_>>();
        let decisions = BTreeMap::from([
            (
                "triggeringPlayerId".to_string(),
                Value::String(player_id.to_string()),
            ),
            (
                "triggeringPermanentId".to_string(),
                Value::String(source_id.to_string()),
            ),
            ("damageAmount".to_string(), Value::from(amount)),
        ]);
        if self.ring_bearer_level(&damage_source) >= 4 {
            self.put_triggered_ability_on_stack_with_origin(
                &damage_source,
                json!({
                    "kind": "triggeredAbility",
                    "source": { "kind": "self" },
                    "event": { "kind": "combatDamageToPlayer", "source": { "kind": "self" } },
                    "effects": [{
                        "kind": "loseLife",
                        "player": {
                            "kind": "opponentsOf",
                            "player": { "kind": "abilityController" },
                        },
                        "amount": { "kind": "integer", "value": 3 },
                    }],
                }),
                decisions.clone(),
                trigger_multiplicity::TriggerOrigin::Emblem,
            );
            if self.check_quantity_failure().is_err() {
                return;
            }
        }
        let delayed = self
            .state
            .rule_modifiers
            .iter()
            .filter(|modifier| {
                value_kind(modifier) == Some("delayedCombatDamageTrigger")
                    && modifier["permanentId"].as_str() == Some(source_id)
                    && modifier["expiresAfterCombatTurn"].as_u64()
                        == Some(u64::from(self.state.turn_number))
            })
            .filter_map(|modifier| {
                let source =
                    serde_json::from_value::<CardInstance>(modifier["sourceCard"].clone()).ok()?;
                Some((source, modifier["effects"].clone()))
            })
            .collect::<Vec<_>>();
        for (source, effects) in delayed {
            self.put_triggered_ability_on_stack_with_origin(
                &source,
                json!({ "kind": "triggeredAbility", "source": { "kind": "self" }, "effects": effects }),
                decisions.clone(), trigger_multiplicity::TriggerOrigin::Delayed,
            );
            if self.check_quantity_failure().is_err() {
                return;
            }
        }
        self.state.rule_modifiers.retain(|modifier| {
            !(value_kind(modifier) == Some("delayedCombatDamageTrigger")
                && modifier["permanentId"].as_str() == Some(source_id)
                && modifier["expiresAfterCombatTurn"].as_u64()
                    == Some(u64::from(self.state.turn_number)))
        });
        // One typed record of the damage family (damage_events).
        let record = damage_events::DamageEventRecord {
            source: source_id.to_string(),
            source_controller: Some(damage_source.controller.clone()),
            recipient: damage_events::DamageRecipientRecord::Player(player_id.to_string()),
            amount,
            combat: true,
            batch: None,
        };
        for source in sources {
            let rules = self
                .effective_rules(&source)
                .iter()
                .filter(|rule| {
                    triggered_rule_supported(rule)
                        && (self
                            .rule_matches_damage_record(
                                rule,
                                damage_events::DamageGroup::CombatToPlayer,
                                &record,
                                &source,
                            )
                            .is_some()
                            || triggered_event_variants(&rule["event"])
                                .into_iter()
                                .any(|event| match value_kind(event) {
                                    Some("controlledCreaturesCombatDamageToPlayer") => {
                                        source.controller == damage_source.controller
                                            && event.get("where").is_none_or(|where_filter| {
                                                self.permanent_matches_effective_filter(
                                                    &damage_source,
                                                    where_filter,
                                                )
                                            })
                                    }
                                    Some("combatDamageReceived") => {
                                        source.controller == player_id
                                            && event.get("where").is_none_or(|where_filter| {
                                                self.permanent_matches_effective_filter(
                                                    &damage_source,
                                                    where_filter,
                                                )
                                            })
                                    }
                                    _ => false,
                                }))
                })
                .cloned()
                .collect::<Vec<_>>();
            for rule in rules {
                let received_damage_trigger = triggered_event_variants(&rule["event"])
                    .iter()
                    .any(|event| value_kind(event) == Some("combatDamageReceived"));
                if received_damage_trigger {
                    if let Some(pending) = self.state.stack.iter_mut().find(|object| {
                        object.card.instance_id == source.instance_id
                            && object.ability_rule.as_ref() == Some(&rule)
                            && object.decisions["triggeringPlayerId"].as_str() == Some(player_id)
                    }) {
                        let mut source_ids = pending.decisions["combatDamageSourceIds"]
                            .as_array()
                            .cloned()
                            .unwrap_or_default();
                        if !source_ids.iter().any(|id| id.as_str() == Some(source_id)) {
                            source_ids.push(Value::String(source_id.to_string()));
                        }
                        pending.decisions.insert(
                            "combatDamageSourceIds".to_string(),
                            Value::Array(source_ids),
                        );
                    } else {
                        let mut received_decisions = decisions.clone();
                        received_decisions
                            .insert("combatDamageSourceIds".to_string(), json!([source_id]));
                        self.put_triggered_ability_on_stack_with_decisions(
                            &source,
                            rule,
                            received_decisions,
                        );
                        if self.check_quantity_failure().is_err() {
                            return;
                        }
                    }
                    continue;
                }
                let grouped_trigger_already_pending = triggered_event_variants(&rule["event"])
                    .iter()
                    .any(|event| {
                        value_kind(event) == Some("controlledCreaturesCombatDamageToPlayer")
                    })
                    && self.state.stack.iter().any(|object| {
                        object.card.instance_id == source.instance_id
                            && object.ability_rule.as_ref() == Some(&rule)
                            && object.decisions["triggeringPlayerId"].as_str() == Some(player_id)
                    });
                if !grouped_trigger_already_pending {
                    self.put_triggered_ability_on_stack_with_decisions(
                        &source,
                        rule,
                        decisions.clone(),
                    );
                    if self.check_quantity_failure().is_err() {
                        return;
                    }
                }
            }
        }
        let defender_is_monarch = self.state.rule_modifiers.iter().any(|modifier| {
            value_kind(modifier) == Some("monarch")
                && modifier["playerId"].as_str() == Some(player_id)
        });
        if amount > 0 && defender_is_monarch && damage_source.controller != player_id {
            self.become_monarch(&damage_source.controller);
        }
    }

    fn enqueue_spell_cast_triggers(
        &mut self,
        casting_player_id: &str,
        spell: &CardDefinition,
        cast_decisions: &BTreeMap<String, Value>,
    ) {
        let mut triggers = Vec::<(CardInstance, Value, trigger_multiplicity::TriggerOrigin)>::new();
        let cast_targets = self
            .state
            .stack
            .iter()
            .rev()
            .find(|object| {
                object.controller == casting_player_id && object.card.definition.id == spell.id
            })
            .map(|object| object.targets.clone())
            .unwrap_or_default();
        let spell_owner = self
            .state
            .stack
            .iter()
            .rev()
            .find(|object| {
                object.controller == casting_player_id && object.card.definition.id == spell.id
            })
            .map(|object| object.card.owner.clone());
        let cast_record = cast_events::CastEventRecord {
            caster: casting_player_id,
            owner: spell_owner.as_deref(),
            spell,
            decisions: cast_decisions,
            targets: &cast_targets,
        };
        for player in self.state.players.iter().filter(|player| !player.has_lost) {
            for source in &player.battlefield {
                let has_prowess = self.permanent_has_keyword(source, "prowess");
                if has_prowess && source.controller == casting_player_id && !is_creature(spell) {
                    triggers.push((
                        source.clone(),
                        json!({
                            "kind": "triggeredAbility",
                            "source": { "kind": "self" },
                            "event": {
                                "kind": "spellCast",
                                "player": {
                                    "kind": "controllerOf",
                                    "object": { "kind": "abilitySource" }
                                },
                                "where": {
                                    "kind": "not",
                                    "operand": {
                                        "kind": "cardTypeContains",
                                        "value": "Creature"
                                    }
                                }
                            },
                            "effects": [{
                                "kind": "modifyPowerToughness",
                                "object": { "kind": "abilitySource" },
                                "power": 1,
                                "toughness": 1,
                                "duration": { "kind": "untilEndOfCurrentTurn" }
                            }]
                        }),
                        trigger_multiplicity::TriggerOrigin::ObjectAbility,
                    ));
                }
                for rule in self.effective_rules(&source).iter() {
                    let is_prowess = value_kind(rule) == Some("prowess")
                        || (value_kind(rule) == Some("keywordAbility")
                            && value_kind(&rule["ability"]) == Some("prowess"));
                    if is_prowess {
                        continue;
                    }
                    let matches_spell_event = triggered_event_variants(&rule["event"])
                        .into_iter()
                        .any(|event| match value_kind(event) {
                            // One cast record, one matcher (cast_events).
                            Some("spellCast") => self.spell_cast_matches(
                                event,
                                &cast_record,
                                source,
                                cast_events::CastSubject::AnySpell,
                            ),
                            Some("spellCastOrdinal") => {
                                source.controller == casting_player_id
                                    && integer_value(&event["ordinal"]).is_some_and(|ordinal| {
                                        self.state
                                            .events
                                            .iter()
                                            .filter(|event| {
                                                event.turn_number == self.state.turn_number
                                                    && event.kind == "spellCast"
                                                    && event.player_id.as_deref()
                                                        == Some(casting_player_id)
                                            })
                                            .count()
                                            == ordinal.max(0) as usize
                                    })
                            }
                            Some("dilemmaFaced") => {
                                source.controller == casting_player_id
                                    && cast_decisions
                                        .get("chosenModes")
                                        .and_then(Value::as_array)
                                        .is_some_and(|modes| !modes.is_empty())
                            }
                            Some("spellCastTargetingControlledCreature") => {
                                source.controller == casting_player_id
                                    && cast_targets.values().any(|target| match target {
                                        TargetRef::Permanent { instance_id } => self
                                            .permanent_position(instance_id)
                                            .is_some_and(|(player_index, card_index)| {
                                                let permanent = &self.state.players[player_index]
                                                    .battlefield[card_index];
                                                permanent.controller == source.controller
                                                    && self.permanent_is_creature(permanent)
                                            }),
                                        _ => false,
                                    })
                            }
                            Some("spellCastTargetingOpponentOrCreature") => {
                                source.controller == casting_player_id
                                    && cast_targets.values().any(|target| match target {
                                        TargetRef::Player { player_id } => {
                                            player_id != &source.controller
                                        }
                                        TargetRef::Permanent { instance_id } => self
                                            .permanent_position(instance_id)
                                            .is_some_and(|(player_index, card_index)| {
                                                let permanent = &self.state.players[player_index]
                                                    .battlefield[card_index];
                                                permanent.controller != source.controller
                                                    && self.permanent_is_creature(permanent)
                                            }),
                                        TargetRef::Card { .. } | TargetRef::StackObject { .. } => {
                                            false
                                        }
                                    })
                            }
                            _ => false,
                        });
                    if triggered_rule_supported(rule) && matches_spell_event {
                        triggers.push((
                            source.clone(),
                            rule.clone(),
                            trigger_multiplicity::TriggerOrigin::ObjectAbility,
                        ));
                    }
                }
            }
        }
        if let Some(source) = self
            .state
            .stack
            .iter()
            .rev()
            .find(|object| object.card.definition.id == spell.id)
            .map(|object| object.card.clone())
        {
            // `When you cast this spell`: the spell observes its own cast.
            for rule in self.effective_rules(&source).iter().filter(|rule| {
                triggered_rule_supported(rule)
                    && triggered_event_variants(&rule["event"])
                        .iter()
                        .any(|event| {
                            self.spell_cast_matches(
                                event,
                                &cast_record,
                                &source,
                                cast_events::CastSubject::SourceSpell,
                            )
                        })
            }) {
                triggers.push((
                    source.clone(),
                    rule.clone(),
                    trigger_multiplicity::TriggerOrigin::ObjectAbility,
                ));
            }
        }
        for player in self.state.players.iter().filter(|player| !player.has_lost) {
            for source in player
                .exile
                .iter()
                .filter(|card| card.flags.get("suspended").copied().unwrap_or(false))
            {
                for rule in self.effective_rules(&source).iter().filter(|rule| {
                    triggered_rule_supported(rule)
                        && triggered_event_variants(&rule["event"])
                            .iter()
                            .any(|event| {
                                value_kind(event) == Some("spellCast")
                                    && event["opponentOfSourceController"].as_bool() == Some(true)
                                    && source.controller != casting_player_id
                                    && matches_card_filter(spell, &event["where"])
                            })
                }) {
                    triggers.push((
                        source.clone(),
                        rule.clone(),
                        trigger_multiplicity::TriggerOrigin::ObjectAbility,
                    ));
                }
            }
        }
        for modifier in self.state.rule_modifiers.iter().filter(|modifier| {
            value_kind(modifier) == Some("emblemTriggeredAbility")
                && modifier["playerId"].as_str() == Some(casting_player_id)
        }) {
            let ability = &modifier["ability"];
            let matches_spell = triggered_event_variants(&ability["event"])
                .iter()
                .any(|event| {
                    value_kind(event) == Some("spellCast")
                        && matches_card_filter(spell, &event["where"])
                });
            if matches_spell
                && let Ok(mut source) =
                    serde_json::from_value::<CardInstance>(modifier["sourceCard"].clone())
            {
                source.controller = casting_player_id.to_string();
                triggers.push((
                    source,
                    ability.clone(),
                    trigger_multiplicity::TriggerOrigin::Emblem,
                ));
            }
        }
        let mut consumed_delayed = Vec::new();
        for (index, modifier) in self.state.rule_modifiers.iter().enumerate() {
            if value_kind(modifier) == Some("delayedSpellCastTrigger")
                && modifier["playerId"].as_str() == Some(casting_player_id)
                && modifier["expiresAfterTurn"].as_u64() == Some(u64::from(self.state.turn_number))
                && matches_card_filter(spell, &modifier["where"])
                && let Ok(source) =
                    serde_json::from_value::<CardInstance>(modifier["sourceCard"].clone())
            {
                triggers.push((
                    source,
                    json!({
                        "kind": "triggeredAbility",
                        "source": { "kind": "self" },
                        "effects": modifier["effects"].clone(),
                    }),
                    trigger_multiplicity::TriggerOrigin::Delayed,
                ));
                consumed_delayed.push(index);
            }
        }
        for index in consumed_delayed.into_iter().rev() {
            self.state.rule_modifiers.remove(index);
        }
        let mut trigger_decisions = BTreeMap::from([
            (
                "triggeringPlayerId".to_string(),
                Value::String(casting_player_id.to_string()),
            ),
            (
                "triggeringSpellManaValue".to_string(),
                Value::from(mana_value_with_decisions(spell, cast_decisions)),
            ),
            (
                "triggeringSpellManaSpent".to_string(),
                Value::from(mana_spent_from_cast_decisions(cast_decisions)),
            ),
            (
                "triggeringSpellManaSpentBySymbol".to_string(),
                mana_payment::triggering_spell_mana_spent_record(cast_decisions),
            ),
            (
                "triggeringSpellTypeLine".to_string(),
                Value::String(spell.type_line.clone()),
            ),
            (
                "triggeringSpellManaCost".to_string(),
                Value::String(spell.mana_cost.clone()),
            ),
            (
                "triggeringSpellXValue".to_string(),
                cast_decisions
                    .get("xValue")
                    .cloned()
                    .unwrap_or(Value::from(0)),
            ),
            (
                "triggeringSpellPower".to_string(),
                Value::from(parse_stat(&spell.power)),
            ),
        ]);
        if let Some(assist_player_id) = cast_decisions.get("assistPlayerId").cloned() {
            trigger_decisions.insert("assistPlayerId".to_string(), assist_player_id);
        }
        let mana_source_definitions = cast_decisions
            .get("manaPayment")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(|payment| payment["sourceId"].as_str())
            .filter_map(|instance_id| {
                self.permanent_position(instance_id)
                    .map(|(player_index, card_index)| {
                        self.state.players[player_index].battlefield[card_index]
                            .definition
                            .clone()
                    })
                    .or_else(|| {
                        self.card_outside_battlefield(instance_id)
                            .map(|card| card.definition.clone())
                    })
            })
            .map(|definition| json!(definition))
            .collect::<Vec<_>>();
        trigger_decisions.insert(
            "triggeringSpellManaSourceDefinitions".to_string(),
            Value::Array(mana_source_definitions),
        );
        if let Some(stack_id) = self
            .state
            .stack
            .iter()
            .rev()
            .find(|object| object.card.definition.id == spell.id)
            .map(|object| object.id.clone())
        {
            trigger_decisions.insert("triggeringStackId".to_string(), Value::String(stack_id));
        }
        if let Some(stack_id) = trigger_decisions
            .get("triggeringStackId")
            .and_then(Value::as_str)
            && self.state.rule_modifiers.iter().any(|modifier| {
                value_kind(modifier) == Some("copyControllerSpells")
                    && modifier["playerId"].as_str() == Some(casting_player_id)
                    && modifier["expiresAfterTurn"].as_u64()
                        == Some(u64::from(self.state.turn_number))
            })
        {
            self.copy_stack_object(stack_id);
        }
        for (source, rule, origin) in triggers {
            self.put_triggered_ability_on_stack_with_origin(
                &source,
                rule,
                trigger_decisions.clone(),
                origin,
            );
            if self.check_quantity_failure().is_err() {
                return;
            }
        }
    }

    fn enqueue_conjured_triggers(&mut self, conjuring_player_id: &str) {
        self.enqueue_player_event_triggers("cardConjured", conjuring_player_id, None);
    }

    fn enqueue_player_event_triggers(
        &mut self,
        event_kind: &str,
        event_player_id: &str,
        event_object_id: Option<&str>,
    ) {
        let triggers = self
            .state
            .players
            .iter()
            .filter(|player| !player.has_lost)
            .flat_map(|player| player.battlefield.iter())
            .filter(|source| source.controller == event_player_id)
            .flat_map(|source| {
                self.effective_rules(&source)
                    .iter()
                    .filter(|rule| {
                        triggered_rule_supported(rule)
                            && triggered_event_variants(&rule["event"])
                                .iter()
                                .any(|event| {
                                    value_kind(event) == Some(event_kind)
                                        && !(event["excludeSource"].as_bool().unwrap_or(false)
                                            && event_object_id == Some(source.instance_id.as_str()))
                                })
                    })
                    .cloned()
                    .map(|rule| (source.clone(), rule))
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();
        for (source, rule) in triggers {
            self.put_triggered_ability_on_stack(&source, rule);
            if self.check_quantity_failure().is_err() {
                return;
            }
        }
    }

    fn mark_bending_performed(&mut self, player_id: &str, form: &str, source_id: Option<String>) {
        let already_marked = self.state.rule_modifiers.iter().any(|modifier| {
            value_kind(modifier) == Some("bendingPerformedThisTurn")
                && modifier["playerId"].as_str() == Some(player_id)
                && modifier["form"].as_str() == Some(form)
                && modifier["expiresAfterTurn"].as_u64() == Some(u64::from(self.state.turn_number))
        });
        if !already_marked {
            self.state.rule_modifiers.push(json!({
                "kind": "bendingPerformedThisTurn",
                "playerId": player_id,
                "form": form,
                "expiresAfterTurn": self.state.turn_number,
            }));
        }
        self.record_event(
            "bendingPerformed",
            Some(player_id.to_string()),
            source_id,
            json!({ "form": form }),
        );

        let triggers = self
            .state
            .players
            .iter()
            .filter(|player| !player.has_lost)
            .flat_map(|player| player.battlefield.iter())
            .filter(|source| source.controller == player_id)
            .flat_map(|source| {
                source
                    .definition
                    .printed_rules()
                    .iter()
                    .filter(|rule| {
                        triggered_rule_supported(rule)
                            && triggered_event_variants(&rule["event"])
                                .iter()
                                .any(|event| {
                                    value_kind(event) == Some("bendingPerformed")
                                        && event["forms"].as_array().is_some_and(|forms| {
                                            forms.iter().any(|value| value.as_str() == Some(form))
                                        })
                                })
                    })
                    .cloned()
                    .map(|rule| (source.clone(), rule))
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();
        for (source, rule) in triggers {
            self.put_triggered_ability_on_stack_with_decisions(
                &source,
                rule,
                BTreeMap::from([("bendingForm".to_string(), Value::String(form.to_string()))]),
            );
            if self.check_quantity_failure().is_err() {
                return;
            }
        }
    }

    fn enqueue_state_triggers(&mut self) {
        let sources = self
            .state
            .players
            .iter()
            .filter(|player| !player.has_lost)
            .flat_map(|player| player.battlefield.iter().cloned())
            .collect::<Vec<_>>();
        let mut triggers = Vec::new();
        for source in sources {
            for rule in self.effective_rules(&source).iter().filter(|rule| {
                triggered_rule_supported(rule)
                    && value_kind(&rule["event"]) == Some("stateConditionMet")
                    && self.condition_value_with_source(
                        &rule["event"]["condition"],
                        &source.controller,
                        &BTreeMap::new(),
                        Some(&source),
                    )
            }) {
                let already_pending = self.state.stack.iter().any(|object| {
                    object.ability_kind.as_deref() == Some("triggeredAbility")
                        && object.card.instance_id == source.instance_id
                        && object.ability_rule.as_ref() == Some(rule)
                });
                if !already_pending {
                    triggers.push((source.clone(), rule.clone()));
                }
            }
        }
        for (source, rule) in triggers {
            self.put_triggered_ability_on_stack(&source, rule);
            if self.check_quantity_failure().is_err() {
                return;
            }
        }
    }

    fn enqueue_step_triggers(&mut self, step: &str) {
        if step == "upkeep" {
            self.open_echo_upkeep_window();
        }
        let active_player_id = self.state.players[self.state.active_player].id.clone();
        let mut sources = self
            .state
            .players
            .iter()
            .flat_map(|player| player.battlefield.iter())
            .cloned()
            .map(|source| (source, "battlefield"))
            .collect::<Vec<_>>();
        sources.extend(
            self.state
                .players
                .iter()
                .flat_map(|player| player.command_zone.iter())
                .filter(|source| {
                    source.definition.printed_rules().iter().any(|rule| {
                        rule["triggerZone"].as_str() == Some("commandZoneOrBattlefield")
                            && triggered_rule_supported(rule)
                    })
                })
                .cloned()
                .map(|source| (source, "commandZone")),
        );
        // Triggered abilities that function in exile (CR 113.6k), printed or
        // keyword-expanded (for example Suspend, CR 702.62a).
        sources.extend(
            self.state
                .players
                .iter()
                .flat_map(|player| player.exile.iter())
                .filter(|source| {
                    source
                        .definition
                        .printed_rules()
                        .iter()
                        .cloned()
                        .chain(suspend_keyword::keyword_triggered_rules(source))
                        .any(|rule| {
                            suspend_keyword::rule_trigger_zone(&rule) == "exile"
                                && triggered_rule_supported(&rule)
                        })
                })
                .cloned()
                .map(|source| (source, "exile")),
        );
        if step == "upkeep" && self.state.turn_number == 1 {
            sources.extend(
                self.state
                    .players
                    .iter()
                    .flat_map(|player| player.hand.iter())
                    .filter(|source| {
                        source.definition.printed_rules().iter().any(|rule| {
                            rule["triggerZone"].as_str() == Some("hand")
                                && triggered_rule_supported(rule)
                        })
                    })
                    .cloned()
                    .map(|source| (source, "hand")),
            );
        }
        for (source, source_zone) in sources {
            // Effective layer: a permanent's functioning printed rules plus
            // granted triggered abilities; other zones keep printed rules.
            let mut candidate_rules = self
                .effective_rules(&source)
                .iter()
                .cloned()
                .collect::<Vec<_>>();
            if source_zone == "exile" {
                candidate_rules.extend(suspend_keyword::keyword_triggered_rules(&source));
            }
            // CR 109.5: "you" for an object outside the battlefield and stack
            // is its owner.
            let source_player = if source_zone == "exile" {
                source.owner.as_str()
            } else {
                source.controller.as_str()
            };
            let rules = candidate_rules
                .into_iter()
                .filter(|rule| {
                    triggered_rule_supported(rule)
                        && zone_of_function::trigger_zone_of_function(rule)
                            .functions_in(source_zone)
                        && rule.get("condition").is_none_or(|condition| {
                            self.condition_value_with_source(
                                condition,
                                &source.controller,
                                &BTreeMap::new(),
                                Some(&source),
                            )
                        })
                        && triggered_event_variants(&rule["event"])
                            .iter()
                            .any(|event| {
                                value_kind(event) == Some("stepBegan")
                                    && event["step"].as_str() == Some(step)
                                    && (event["firstOnly"].as_bool() != Some(true)
                                        || self.state.turn_number == 1)
                                    && event["mainPhaseOrdinal"].as_u64().is_none_or(|ordinal| {
                                        main_phase_ordinal_of_step(step) == Some(ordinal)
                                    })
                                    && match value_kind(&event["player"]) {
                                        Some("eachPlayer") => true,
                                        Some("opponentsOf") => {
                                            source.controller != active_player_id
                                        }
                                        Some("controllerOfAttachedPermanent") => source
                                            .attached_to
                                            .as_deref()
                                            .is_some_and(|attached_id| {
                                                self.permanent_position(attached_id).is_some_and(
                                                    |(player_index, card_index)| {
                                                        self.state.players[player_index].battlefield
                                                            [card_index]
                                                            .controller
                                                            == active_player_id
                                                    },
                                                )
                                            }),
                                        _ => source_player == active_player_id,
                                    }
                            })
                        && (source_zone != "battlefield"
                            || self.rule_active_for_source(&source, rule))
                })
                .collect::<Vec<_>>();
            for rule in rules {
                // The active player is the player whose step began: the
                // event-bound `that player` of a step trigger (CR 603.2).
                self.put_triggered_ability_on_stack_with_decisions(
                    &source,
                    rule,
                    BTreeMap::from([(
                        "triggeringPlayerId".to_string(),
                        Value::String(active_player_id.clone()),
                    )]),
                );
                if self.check_quantity_failure().is_err() {
                    return;
                }
            }
            self.enqueue_training_clock_for_source(&source, source_zone, step, &active_player_id);
            if step == "endStep"
                && source_zone == "battlefield"
                && source.controller == active_player_id
                && source
                    .flags
                    .get("impendingCostPaid")
                    .copied()
                    .unwrap_or(false)
                && source.counters.get("time").copied().unwrap_or(0) > 0
                && impending_ability(&source.definition).is_some()
            {
                self.put_triggered_ability_on_stack(
                    &source,
                    json!({
                        "kind": "triggeredAbility",
                        "source": { "kind": "self" },
                        "effects": [{
                            "kind": "removeCounters",
                            "permanent": { "kind": "self" },
                            "counter": "time",
                            "count": { "kind": "integer", "value": 1 },
                        }],
                    }),
                );
                if self.check_quantity_failure().is_err() {
                    return;
                }
            }
        }
        self.fire_delayed_step_triggers(step);
    }

    /// Puts every delayed trigger waiting for `step` on the stack (CR 603.7);
    /// returns how many were waiting.
    fn fire_delayed_step_triggers(&mut self, step: &str) -> usize {
        let delayed_step_triggers = self
            .state
            .rule_modifiers
            .iter()
            .filter(|modifier| {
                value_kind(modifier) == Some("delayedStepTrigger")
                    && modifier["step"].as_str() == Some(step)
                    && modifier["turnPlayerId"].as_str().is_none_or(|player_id| {
                        self.state
                            .players
                            .get(self.state.active_player)
                            .is_some_and(|active| active.id == player_id)
                    })
            })
            .cloned()
            .collect::<Vec<_>>();
        for modifier in &delayed_step_triggers {
            let Ok(mut source) =
                serde_json::from_value::<CardInstance>(modifier["sourceCard"].clone())
            else {
                continue;
            };
            if let Some(controller_id) = modifier["controllerId"].as_str() {
                source.controller = controller_id.to_string();
            }
            let mut decisions = modifier["trackedObjectId"]
                .as_str()
                .map(|instance_id| {
                    BTreeMap::from([(
                        "triggeringPermanentId".to_string(),
                        Value::String(instance_id.to_string()),
                    )])
                })
                .unwrap_or_default();
            if let Some(captured) = modifier["capturedBindings"].as_object() {
                decisions.extend(
                    captured
                        .iter()
                        .map(|(binding_id, value)| (binding_id.clone(), value.clone())),
                );
            }
            self.put_triggered_ability_on_stack_with_origin(
                &source,
                json!({
                    "kind": "triggeredAbility",
                    "source": { "kind": "self" },
                    "effects": modifier["effects"].clone(),
                }),
                decisions,
                trigger_multiplicity::TriggerOrigin::Delayed,
            );
            if self.check_quantity_failure().is_err() {
                return delayed_step_triggers.len();
            }
        }
        self.state.rule_modifiers.retain(|modifier| {
            !delayed_step_triggers
                .iter()
                .any(|consumed| consumed == modifier)
        });
        delayed_step_triggers.len()
    }

    fn apply_priority_action_inner<P: DecisionProvider>(
        &mut self,
        action: &LegalAction,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        let player_index = self.player_index(&action.player_id)?;
        match action.kind {
            ActionKind::PlayLand => {
                let instance_id = action
                    .card_instance_id
                    .as_deref()
                    .ok_or_else(|| EngineError::new("land action has no source card"))?;
                let source_zone = action
                    .decisions
                    .get("castSourceZone")
                    .and_then(Value::as_str)
                    .unwrap_or("hand");
                if self
                    .battlefield_entry_admission_for_id(instance_id, source_zone)
                    .is_prohibited()
                {
                    return Err(EngineError::new(
                        "the land card cannot enter the battlefield from its source zone",
                    ));
                }
                let land_graveyard_destination =
                    self.prepare_card_graveyard_destination(instance_id)?;
                let (mut card, movement_source) =
                    self.take_action_source_card(player_index, action)?;
                card_zone_transition::reset_movement_card(&mut card, &movement_source)?;
                if let Some(face_index) = action
                    .decisions
                    .get("splitFaceIndex")
                    .and_then(Value::as_u64)
                    .and_then(|value| usize::try_from(value).ok())
                    && !apply_split_face(&mut card, face_index)
                {
                    return Err(EngineError::new("modal land face is no longer available"));
                }
                card.controller = action.player_id.clone();
                let used_after_play = i32::try_from(
                    self.state
                        .events
                        .iter()
                        .filter(|event| {
                            event.turn_number == self.state.turn_number
                                && event.kind == "landPlayed"
                                && event.player_id.as_deref() == Some(action.player_id.as_str())
                        })
                        .count(),
                )
                .unwrap_or(i32::MAX)
                .saturating_add(1);
                self.state.players[player_index].land_plays_remaining = 1_i32
                    .saturating_add(self.additional_land_play_count(&action.player_id))
                    .saturating_sub(used_after_play)
                    .max(0);
                self.apply_enter_replacements(&mut card, provider)?;
                if card.flags.remove("enterGraveyardInstead").unwrap_or(false) {
                    let card_id = card.instance_id.clone();
                    let destination = if self.put_owned_card_into_prepared_graveyard(
                        player_index,
                        card_zone_transition::OwnedMovementCard {
                            source: movement_source.clone(),
                            card,
                        },
                        land_graveyard_destination,
                    )? {
                        "graveyard"
                    } else {
                        "exile"
                    };
                    self.record_event(
                        "landPlayed",
                        Some(action.player_id.clone()),
                        Some(card_id.clone()),
                        json!({ "enteredBattlefield": false }),
                    );
                    self.record_event(
                        "permanentEntryReplaced",
                        Some(action.player_id.clone()),
                        Some(card_id),
                        json!({ "destination": destination }),
                    );
                    return Ok(());
                }
                card.summoning_sick = true;
                let card_id = card.instance_id.clone();
                self.commit_card_zone_transition(
                    &mut card,
                    &movement_source,
                    &card_zone_transition::ObjectZone::Battlefield,
                    card_zone_transition::ObjectTransitionReason::Move,
                )?;
                let trigger_source = card.clone();
                self.state.players[player_index].battlefield.push(card);
                if matches!(
                    movement_source.zone,
                    card_zone_transition::ObjectZone::Graveyard(_)
                ) {
                    self.enqueue_cards_left_graveyard_triggers(
                        &movement_source.storage_player_id,
                        &[card_id.clone()],
                    );
                }
                self.record_event(
                    "landPlayed",
                    Some(action.player_id.clone()),
                    Some(card_id.clone()),
                    json!({
                        "fromZone": action.decisions["castSourceZone"]
                            .as_str()
                            .unwrap_or("hand"),
                    }),
                );
                self.enqueue_player_event_triggers("landPlayed", &action.player_id, Some(&card_id));
                if action.decisions["castSourceZone"].as_str() == Some("exile") {
                    self.enqueue_player_event_triggers(
                        "landPlayedFromExile",
                        &action.player_id,
                        Some(&card_id),
                    );
                }
                self.ensure_prepared_spell_copy(&card_id)?;
                self.enqueue_enter_battlefield_triggers(&trigger_source);
                self.check_life_totals();
            }
            ActionKind::CastSpell => {
                let consumes_single_cast_permission = action
                    .card_instance_id
                    .as_deref()
                    .is_some_and(|instance_id| {
                        self.state.permissions.iter().any(|permission| {
                            value_kind(permission) == Some("singleCastThenProhibitPermission")
                                && permission["playerId"].as_str()
                                    == Some(action.player_id.as_str())
                                && permission["cardInstanceId"].as_str() == Some(instance_id)
                                && permission["expiresAfterTurn"]
                                    .as_u64()
                                    .is_none_or(|turn| turn >= u64::from(self.state.turn_number))
                        })
                    });
                let cast_from_command_zone = action
                    .decisions
                    .get("castSourceZone")
                    .and_then(Value::as_str)
                    == Some("commandZone");
                let prepared_source_id = action
                    .decisions
                    .get("preparedSourceInstanceId")
                    .and_then(Value::as_str)
                    .map(ToOwned::to_owned);
                if let Some(source_id) = prepared_source_id.as_deref() {
                    let Some((controller_index, card_index)) = self.permanent_position(source_id)
                    else {
                        return Err(EngineError::new(
                            "prepared spell source is no longer on the battlefield",
                        ));
                    };
                    let source = &self.state.players[controller_index].battlefield[card_index];
                    if source.controller != action.player_id
                        || !source.flags.get("prepared").copied().unwrap_or(false)
                    {
                        return Err(EngineError::new(
                            "prepared spell source is not prepared for this player",
                        ));
                    }
                }
                let source_definition = action
                    .card_instance_id
                    .as_deref()
                    .and_then(|instance_id| self.card_outside_battlefield(instance_id))
                    .map(|card| card.definition.clone())
                    .ok_or_else(|| EngineError::new("spell source is no longer available"))?;
                let source_definition =
                    adventure::casting_definition(&action.decisions, source_definition)?;
                let cast_source_zone = action
                    .decisions
                    .get("castSourceZone")
                    .and_then(Value::as_str)
                    .unwrap_or("hand");
                if self.spell_cast_from_zone_prohibited(
                    &action.player_id,
                    cast_source_zone,
                    &source_definition,
                ) {
                    return Err(EngineError::new(
                        "spell casting from its declared source zone is prohibited",
                    ));
                }
                let delve_maximum = self.checked_delve_payment_maximum(
                    action,
                    &source_definition,
                    action
                        .card_instance_id
                        .as_deref()
                        .and_then(|id| self.card_outside_battlefield(id)),
                )?;
                if action
                    .decisions
                    .get("useAlternativePlayerCounterCost")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    let card_instance_id = action
                        .card_instance_id
                        .as_deref()
                        .ok_or_else(|| EngineError::new("counter-paid cast has no source card"))?;
                    let counter = action
                        .decisions
                        .get("alternativePlayerCounter")
                        .and_then(Value::as_str)
                        .ok_or_else(|| EngineError::new("counter-paid cast has no counter type"))?;
                    let permission = self.state.permissions.iter().find(|permission| {
                        value_kind(permission)
                            == Some("resolutionPlayerCounterAlternativePermission")
                            && permission["cardInstanceId"].as_str() == Some(card_instance_id)
                            && permission["playerId"].as_str() == Some(action.player_id.as_str())
                            && permission["counter"].as_str() == Some(counter)
                    });
                    if permission.is_none() {
                        return Err(EngineError::new(
                            "the player-counter alternative cast is no longer permitted",
                        ));
                    }
                    let required = mana_value(&source_definition).max(0);
                    let available = self.state.players[player_index]
                        .counters
                        .get(counter)
                        .copied()
                        .unwrap_or(0);
                    if available < required {
                        return Err(EngineError::new(
                            "the player no longer has enough counters for the alternative cost",
                        ));
                    }
                    *self.state.players[player_index]
                        .counters
                        .entry(counter.to_string())
                        .or_default() -= required;
                    self.record_event(
                        "playerCountersPaid",
                        Some(action.player_id.clone()),
                        action.card_instance_id.clone(),
                        json!({ "counter": counter, "count": required, "reason": "castingCost" }),
                    );
                }
                let splice_receiving_definition = if action
                    .decisions
                    .get("fused")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    fused_split_definition(&source_definition).ok_or_else(|| {
                        EngineError::new("split card can no longer receive fused splice effects")
                    })?
                } else if let Some(face_index) = action
                    .decisions
                    .get("splitFaceIndex")
                    .and_then(Value::as_u64)
                    .and_then(|value| usize::try_from(value).ok())
                {
                    split_face_definitions(&source_definition)
                        .get(face_index)
                        .cloned()
                        .ok_or_else(|| {
                            EngineError::new("split card face can no longer receive splice effects")
                        })?
                } else {
                    source_definition.clone()
                };
                let spliced_spell_rules =
                    self.validate_splice_selection(action, &splice_receiving_definition)?;
                self.validate_escape_selection(action, &source_definition)?;
                self.validate_impending_cast(action, &source_definition)?;
                self.validate_improvise_payment(action, &source_definition)?;
                self.validate_convoke_payment(action, &source_definition)?;
                self.validate_teamwork_payment(action, &source_definition)?;
                let mut tapped_sources = self.apply_payment(player_index, action)?;
                tapped_sources.extend(self.apply_teamwork_costs(action, &source_definition)?);
                let life_payment = action
                    .decisions
                    .get("castingLifePayment")
                    .and_then(integer_value)
                    .unwrap_or(0)
                    .max(0);
                if self.state.players[player_index].life < life_payment {
                    return Err(EngineError::new(
                        "the player can no longer pay the spell's additional life cost",
                    ));
                }
                if life_payment > 0 {
                    self.state.players[player_index].life -= life_payment;
                    self.record_event(
                        "lifePaid",
                        Some(action.player_id.clone()),
                        action.card_instance_id.clone(),
                        json!({ "amount": life_payment, "reason": "castingCost" }),
                    );
                }
                if let Some(discard_id) = action
                    .decisions
                    .get("graveyardCastDiscard")
                    .and_then(Value::as_str)
                {
                    if action
                        .decisions
                        .get("castSourceZone")
                        .and_then(Value::as_str)
                        != Some("graveyard")
                        || !graveyard_discard_cast_ability(&source_definition)
                    {
                        return Err(EngineError::new(
                            "graveyard discard casting permission is no longer valid",
                        ));
                    }
                    let discard_index = self.state.players[player_index]
                        .hand
                        .iter()
                        .position(|card| card.instance_id == discard_id)
                        .ok_or_else(|| EngineError::new("additional discard card left the hand"))?;
                    let (discarded, graveyard_destination) =
                        self.take_zone_card_for_graveyard(player_index, "hand", discard_index)?;
                    let discarded_id = discarded.instance_id.clone();
                    self.put_owned_card_into_prepared_graveyard(
                        player_index,
                        discarded,
                        graveyard_destination,
                    )?;
                    self.record_event(
                        "cardDiscarded",
                        Some(action.player_id.clone()),
                        Some(discarded_id),
                        json!({ "reason": "castingCost" }),
                    );
                }
                let (mut card, movement_source) =
                    self.take_action_source_card(player_index, action)?;
                let card_was_conjured = card.flags.get("conjured").copied().unwrap_or(false);
                if action
                    .decisions
                    .get("usePrototype")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    card.definition.mana_cost = action.decisions["prototypeManaCost"]
                        .as_str()
                        .unwrap_or_default()
                        .to_string();
                    card.definition.power = action.decisions["prototypePower"]
                        .as_i64()
                        .map(|value| value.to_string());
                    card.definition.toughness = action.decisions["prototypeToughness"]
                        .as_i64()
                        .map(|value| value.to_string());
                    card.flags.insert("prototyped".to_string(), true);
                }
                if action
                    .decisions
                    .get("castFaceDown")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    card.definition = face_down_creature_definition(
                        card.printed_definition.as_ref().unwrap_or(&card.definition),
                    );
                    card.flags.insert("faceDown".to_string(), true);
                }
                if action
                    .decisions
                    .get("useForetell")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    card.flags.remove("foretoldFaceDown");
                }
                if action
                    .decisions
                    .get("castFromSuspend")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    card.flags.remove("suspended");
                    if is_creature(&card.definition) {
                        card.flags.insert("suspendedCastHaste".to_string(), true);
                    }
                }
                if action
                    .decisions
                    .get("castSourceZone")
                    .and_then(Value::as_str)
                    .unwrap_or("hand")
                    == "hand"
                    && has_keyword(&card.definition, "rebound")
                {
                    card.flags.insert("reboundEligible".to_string(), true);
                }
                if let Some(face_index) = action
                    .decisions
                    .get("splitFaceIndex")
                    .and_then(Value::as_u64)
                    .and_then(|value| usize::try_from(value).ok())
                    && !apply_split_face(&mut card, face_index)
                {
                    return Err(EngineError::new("split card face is no longer available"));
                }
                // CR 716.3b: on the stack, only the Adventure's characteristics.
                card.definition =
                    adventure::casting_definition(&action.decisions, card.definition.clone())?;
                if action
                    .decisions
                    .get("fused")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    card.definition = fused_split_definition(
                        card.printed_definition.as_ref().unwrap_or(&card.definition),
                    )
                    .ok_or_else(|| EngineError::new("split card can no longer be fused"))?;
                }
                card.definition
                    .printed_rules_mut()
                    .extend(spliced_spell_rules);
                if let Some(source_id) = prepared_source_id.as_deref() {
                    self.set_permanent_prepared(source_id, false)?;
                }
                card.flags.insert("wasCast".to_string(), true);
                card.flags.insert(
                    "wasCastFromHand".to_string(),
                    casting_cost::CastingMode::of(&action.decisions).from_zone == "hand",
                );
                let next_creature_modifier = is_creature(&card.definition)
                    .then(|| {
                        self.state
                            .rule_modifiers
                            .iter()
                            .position(|modifier| {
                                value_kind(modifier) == Some("nextCreatureSpellModifier")
                                    && modifier["playerId"].as_str()
                                        == Some(action.player_id.as_str())
                            })
                            .map(|index| self.state.rule_modifiers.remove(index))
                    })
                    .flatten();
                if next_creature_modifier.as_ref().is_some_and(|modifier| {
                    modifier["enteringCounter"].as_str() == Some("+1/+1")
                        && integer_value(&modifier["enteringCounterCount"]) == Some(1)
                }) {
                    card.flags
                        .insert("additionalEnteringPlusOneCounter".to_string(), true);
                }
                // The first matching one-shot modifier is consumed by this
                // cast even when the spell already can't be countered.
                let one_shot_operations =
                    self.consume_one_shot_spell_cast_modifier(&action.player_id, &card.definition);
                let one_shot_cant_be_countered =
                    next_creature_modifier.as_ref().is_some_and(|modifier| {
                        modifier["cantBeCountered"].as_bool() == Some(true)
                    }) || one_shot_modifier::operations_set_stack_modifier(
                        &one_shot_operations,
                        "cantBeCountered",
                    ) || action
                        .decisions
                        .get("manaPayment")
                        .and_then(Value::as_array)
                        .is_some_and(|payments| {
                            payments.iter().any(|payment| {
                                value_kind(payment) == Some("manaPaymentMetadata")
                                    && payment["cantBeCountered"].as_bool() == Some(true)
                            })
                        });
                self.stack_sequence += 1;
                let stack_id = format!("stack:{}", self.stack_sequence);
                let card_id = card.instance_id.clone();
                let spell_definition = card.definition.clone();
                let storm_copy_count = if has_keyword(&spell_definition, "storm") {
                    self.state
                        .events
                        .iter()
                        .filter(|event| {
                            event.turn_number == self.state.turn_number
                                && event.kind == "spellCast"
                                && event.player_id.as_deref() == Some(action.player_id.as_str())
                        })
                        .count()
                } else {
                    0
                };
                let has_gravestorm = has_keyword(&spell_definition, "gravestorm");
                let spell_mana_value =
                    mana_value_with_decisions(&spell_definition, &action.decisions);
                let granted_cascade_count = self
                    .battlefield_static_modifiers()
                    .iter()
                    .filter(|(source, modifier)| {
                        source.controller == action.player_id
                            && value_kind(modifier) == Some("grantCascadeToSpells")
                            && integer_value(&modifier["minimumManaValue"])
                                .is_some_and(|minimum| spell_mana_value >= minimum)
                    })
                    .count();
                let cascade_count = keyword_count(&spell_definition, "cascade")
                    .saturating_add(granted_cascade_count);
                let replicate_counts = self
                    .replicate_costs(&spell_definition, &action.player_id)
                    .into_iter()
                    .enumerate()
                    .filter_map(|(instance_index, _)| {
                        action
                            .decisions
                            .get(&replicate_decision_id(instance_index))
                            .and_then(Value::as_u64)
                            .filter(|count| *count > 0)
                            .map(|count| (instance_index, count))
                    })
                    .collect::<Vec<_>>();
                let mut cost_target_ids = self.casting_sacrifice_cost_targets(
                    &spell_definition,
                    &action.player_id,
                    &action.decisions,
                );
                cost_target_ids.extend(self.casting_discard_cost_targets(
                    &spell_definition,
                    &action.player_id,
                    &action.decisions,
                ));
                cost_target_ids.extend(
                    self.casting_put_counter_costs(
                        &spell_definition,
                        &action.player_id,
                        &action.decisions,
                    )
                    .into_iter()
                    .map(|(target_id, _)| target_id),
                );
                cost_target_ids.extend(Self::escalate_cost_target_ids(
                    &spell_definition,
                    &action.decisions,
                ));
                cost_target_ids.extend(self.splice_cost_target_ids(action));
                if action
                    .decisions
                    .get("useFlashback")
                    .and_then(Value::as_bool)
                    == Some(true)
                {
                    if let Some(cost) = action
                        .decisions
                        .get("effectiveFlashbackCost")
                        .or_else(|| flashback_cost(&spell_definition))
                    {
                        if value_kind(cost) == Some("compositeCost") {
                            for (index, part) in
                                cost["costs"].as_array().into_iter().flatten().enumerate()
                            {
                                if matches!(
                                    value_kind(part),
                                    Some("sacrificePermanent" | "discardCard" | "putCounters")
                                ) {
                                    cost_target_ids.push(format!("flashbackCost{index}"));
                                }
                            }
                        } else if matches!(
                            value_kind(cost),
                            Some("sacrificePermanent" | "discardCard")
                        ) {
                            cost_target_ids.push("flashbackCost".to_string());
                        }
                    }
                }
                let sacrificed_mana_values = cost_target_ids
                    .iter()
                    .filter_map(|target_id| action.targets.get(target_id))
                    .filter_map(|target| match target {
                        TargetRef::Permanent { instance_id } => self
                            .permanent_position(instance_id)
                            .map(|(player_index, card_index)| {
                                mana_value(
                                    &self.state.players[player_index].battlefield[card_index]
                                        .definition,
                                )
                            }),
                        _ => None,
                    })
                    .collect::<Vec<_>>();
                let mut stack_decisions = action.decisions.clone();
                if let Some(value) = sacrificed_mana_values.first() {
                    stack_decisions.insert(
                        "sacrificedPermanentManaValue".to_string(),
                        Value::from(*value),
                    );
                }
                // CR 608.2h: a spell reading the permanent sacrificed for its
                // additional cost uses that permanent's last known values.
                for (binding, value) in self.casting_sacrifice_cost_bindings(
                    &spell_definition,
                    &action.player_id,
                    &action.decisions,
                    &action.targets,
                ) {
                    stack_decisions.insert(binding, Value::from(value));
                }
                let stack_targets: BTreeMap<String, TargetRef> = action
                    .targets
                    .iter()
                    .filter(|(target_id, _)| !cost_target_ids.contains(target_id))
                    .map(|(target_id, target)| (target_id.clone(), target.clone()))
                    .collect();
                self.commit_card_zone_transition(
                    &mut card,
                    &movement_source,
                    &card_zone_transition::ObjectZone::Stack,
                    card_zone_transition::ObjectTransitionReason::Move,
                )?;
                self.state.stack.push(StackObject {
                    id: stack_id.clone(),
                    controller: action.player_id.clone(),
                    cant_be_countered: spell_cant_be_countered(&card.definition)
                        || one_shot_cant_be_countered
                        || self.temporary_controlled_spells_cant_be_countered(&action.player_id),
                    exile_on_leave_stack: action
                        .decisions
                        .get("exileOnLeaveStack")
                        .and_then(Value::as_bool)
                        .unwrap_or(false),
                    ability_kind: None,
                    ability_rule: None,
                    card,
                    decisions: stack_decisions,
                    targets: stack_targets.clone(),
                });
                if matches!(
                    movement_source.zone,
                    card_zone_transition::ObjectZone::Graveyard(_)
                ) {
                    self.enqueue_cards_left_graveyard_triggers(
                        &movement_source.storage_player_id,
                        &[card_id.clone()],
                    );
                }
                if cast_from_command_zone {
                    if let Some(commander) = self
                        .state
                        .commanders
                        .iter_mut()
                        .find(|commander| commander.card_instance_id == card_id)
                    {
                        commander.casts_from_command_zone =
                            commander.casts_from_command_zone.saturating_add(1);
                    }
                    self.commander_last_zones
                        .insert(card_id.clone(), "stack".to_string());
                }
                self.apply_casting_sacrifice_costs(action, &spell_definition)?;
                self.apply_casting_discard_costs(action, &spell_definition)?;
                self.apply_casting_exile_costs(action, &spell_definition)?;
                self.apply_casting_put_counter_costs(action, &spell_definition, provider)?;
                self.apply_escalate_costs_with_provider(action, &spell_definition, provider)?;
                self.apply_delve_cost(action, &spell_definition, delve_maximum)?;
                self.apply_flashback_cost(action, &spell_definition, provider)?;
                self.apply_escape_costs(action, &spell_definition)?;
                self.apply_splice_costs(action, provider)?;
                self.apply_alternative_sacrifice_cost(action, &spell_definition)?;
                self.apply_nonmana_alternative_cost(action, &spell_definition)?;
                let optional_sacrifice_count = self.apply_optional_casting_sacrifices(action)?;
                self.apply_casting_land_sacrifices(action)?;
                let conspire_count = self.apply_conspire_costs(action, &spell_definition)?;
                let gravestorm_copy_count = if has_gravestorm {
                    self.state
                        .events
                        .iter()
                        .filter(|event| {
                            event.turn_number == self.state.turn_number
                                && event.kind == "permanentDied"
                        })
                        .count()
                } else {
                    0
                };
                for source in tapped_sources {
                    self.enqueue_permanent_tapped_triggers(&source);
                }
                self.drain_linked_exile_returns(provider)?;
                self.record_event(
                    "spellCast",
                    Some(action.player_id.clone()),
                    Some(card_id),
                    json!({
                        "manaValue": mana_value_with_decisions(&spell_definition, &action.decisions),
                        "manaCost": spell_definition.mana_cost.clone(),
                        "colors": card_color_symbols(&spell_definition),
                        "objectKind": "spell",
                        "stackId": stack_id,
                        "decisions": action.decisions,
                        "targets": action.targets,
                        "typeLine": spell_definition.type_line,
                        "cardName": spell_definition.name,
                        "fromZone": action.decisions
                            .get("castSourceZone")
                            .and_then(Value::as_str)
                            .unwrap_or("hand"),
                    }),
                );
                if consumes_single_cast_permission {
                    self.state.rule_modifiers.push(json!({
                        "kind": "prohibitAdditionalSpells",
                        "playerId": action.player_id,
                        "expiresAfterTurn": self.state.turn_number,
                    }));
                }
                if self.casting_waterbend_amount(&spell_definition, &action.decisions) > 0 {
                    self.mark_bending_performed(
                        &action.player_id,
                        "waterbend",
                        Some(stack_id.clone()),
                    );
                }
                if optional_sacrifice_count > 0
                    && let Some(source) = self
                        .state
                        .stack
                        .iter()
                        .find(|object| object.id == stack_id)
                        .map(|object| object.card.clone())
                {
                    self.put_spell_copy_trigger_on_stack(
                        &source,
                        &stack_id,
                        optional_sacrifice_count,
                        false,
                        BTreeMap::from([
                            (
                                "originalStackId".to_string(),
                                Value::String(stack_id.clone()),
                            ),
                            (
                                "sacrificeCount".to_string(),
                                Value::from(optional_sacrifice_count),
                            ),
                        ]),
                        trigger_multiplicity::TriggerOrigin::Unproven,
                    );
                }
                if conspire_count > 0
                    && let Some(source) = self
                        .state
                        .stack
                        .iter()
                        .find(|object| object.id == stack_id)
                        .map(|object| object.card.clone())
                {
                    for conspire_index in 0..conspire_count {
                        self.put_spell_copy_trigger_on_stack(
                            &source,
                            &stack_id,
                            1,
                            true,
                            BTreeMap::from([(
                                "originalStackId".to_string(),
                                Value::String(stack_id.clone()),
                            )]),
                            trigger_multiplicity::TriggerOrigin::ObjectAbility,
                        );
                        self.record_event(
                            "conspireTriggered",
                            Some(action.player_id.clone()),
                            Some(source.instance_id.clone()),
                            json!({ "instance": conspire_index + 1, "stackId": stack_id }),
                        );
                    }
                }
                if !replicate_counts.is_empty()
                    && let Some(source) = self
                        .state
                        .stack
                        .iter()
                        .find(|object| object.id == stack_id)
                        .map(|object| object.card.clone())
                {
                    for (instance_index, copy_count) in replicate_counts {
                        self.put_spell_copy_trigger_on_stack(
                            &source,
                            &stack_id,
                            usize::try_from(copy_count).map_err(|_| {
                                EngineError::new("copy count exceeds platform capacity")
                            })?,
                            true,
                            BTreeMap::from([
                                (
                                    "originalStackId".to_string(),
                                    Value::String(stack_id.clone()),
                                ),
                                ("copyCount".to_string(), Value::from(copy_count)),
                            ]),
                            trigger_multiplicity::TriggerOrigin::ObjectAbility,
                        );
                        self.record_event(
                            "replicateTriggered",
                            Some(action.player_id.clone()),
                            Some(source.instance_id.clone()),
                            json!({
                                "copyCount": copy_count,
                                "instance": instance_index + 1,
                                "stackId": stack_id,
                            }),
                        );
                    }
                }
                if storm_copy_count > 0
                    && let Some(source) = self
                        .state
                        .stack
                        .iter()
                        .find(|object| object.id == stack_id)
                        .map(|object| object.card.clone())
                {
                    self.put_spell_copy_trigger_on_stack(
                        &source,
                        &stack_id,
                        storm_copy_count,
                        true,
                        BTreeMap::from([
                            (
                                "originalStackId".to_string(),
                                Value::String(stack_id.clone()),
                            ),
                            ("copyCount".to_string(), Value::from(storm_copy_count)),
                        ]),
                        trigger_multiplicity::TriggerOrigin::ObjectAbility,
                    );
                    self.record_event(
                        "stormTriggered",
                        Some(action.player_id.clone()),
                        Some(source.instance_id.clone()),
                        json!({
                            "copyCount": storm_copy_count,
                            "stackId": stack_id,
                        }),
                    );
                }
                if gravestorm_copy_count > 0
                    && let Some(source) = self
                        .state
                        .stack
                        .iter()
                        .find(|object| object.id == stack_id)
                        .map(|object| object.card.clone())
                {
                    self.put_spell_copy_trigger_on_stack(
                        &source,
                        &stack_id,
                        gravestorm_copy_count,
                        true,
                        BTreeMap::from([
                            (
                                "originalStackId".to_string(),
                                Value::String(stack_id.clone()),
                            ),
                            ("copyCount".to_string(), Value::from(gravestorm_copy_count)),
                        ]),
                        trigger_multiplicity::TriggerOrigin::ObjectAbility,
                    );
                    self.record_event(
                        "gravestormTriggered",
                        Some(action.player_id.clone()),
                        Some(source.instance_id.clone()),
                        json!({
                            "copyCount": gravestorm_copy_count,
                            "stackId": stack_id,
                        }),
                    );
                }
                if cascade_count > 0
                    && let Some(source) = self
                        .state
                        .stack
                        .iter()
                        .find(|object| object.id == stack_id)
                        .map(|object| object.card.clone())
                {
                    for instance_index in 0..cascade_count {
                        self.put_triggered_ability_on_stack(
                            &source,
                            keyword_programs::cascade_trigger_rule(spell_mana_value),
                        );
                        self.check_quantity_failure()?;
                        self.record_event(
                            "cascadeTriggered",
                            Some(action.player_id.clone()),
                            Some(source.instance_id.clone()),
                            json!({ "stackId": stack_id, "instanceIndex": instance_index }),
                        );
                    }
                }
                if type_line_contains(&spell_definition.type_line, "Lesson")
                    && let Some(modifier_index) =
                        self.state.rule_modifiers.iter().position(|modifier| {
                            value_kind(modifier) == Some("copyNextLessonThisTurn")
                                && modifier["playerId"].as_str() == Some(action.player_id.as_str())
                        })
                {
                    let modifier = self.state.rule_modifiers.remove(modifier_index);
                    let source = modifier["sourceCardInstanceId"]
                        .as_str()
                        .and_then(|source_id| self.permanent_position(source_id))
                        .map(|(player_index, card_index)| {
                            self.state.players[player_index].battlefield[card_index].clone()
                        })
                        .or_else(|| {
                            self.state
                                .stack
                                .iter()
                                .find(|object| object.id == stack_id)
                                .map(|object| object.card.clone())
                        });
                    if let Some(source) = source {
                        self.put_spell_copy_trigger_on_stack(
                            &source,
                            &stack_id,
                            1,
                            true,
                            BTreeMap::from([(
                                "originalStackId".to_string(),
                                Value::String(stack_id.clone()),
                            )]),
                            trigger_multiplicity::TriggerOrigin::Unproven,
                        );
                    }
                }
                if action
                    .decisions
                    .get("dragonSmileZeroCost")
                    .and_then(Value::as_bool)
                    == Some(true)
                {
                    self.record_event(
                        "dragonSmileZeroCast",
                        Some(action.player_id.clone()),
                        action.card_instance_id.clone(),
                        json!({ "sourceZone": "exile" }),
                    );
                }
                self.enqueue_spell_cast_triggers(&action.player_id, &spell_definition, &{
                    let mut decisions = action.decisions.clone();
                    decisions.insert("conjured".to_string(), Value::Bool(card_was_conjured));
                    decisions
                });
                self.enqueue_targeting_triggers(&stack_id, &stack_targets)?;
                self.check_state_based_actions_with_provider(Some(provider))?;
            }
            ActionKind::ActivateAbility => {
                if action
                    .decisions
                    .get("companionToHand")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    if player_index != self.state.active_player
                        || !matches!(
                            self.state.step,
                            GameStep::PrecombatMain | GameStep::PostcombatMain
                        )
                        || !self.state.stack.is_empty()
                        || self.state.events.iter().any(|event| {
                            event.kind == "companionMovedToHand"
                                && event.player_id.as_deref() == Some(action.player_id.as_str())
                        })
                    {
                        return Err(EngineError::new(
                            "a companion can only be put into hand once at sorcery timing",
                        ));
                    }
                    let instance_id = action
                        .card_instance_id
                        .as_deref()
                        .ok_or_else(|| EngineError::new("companion action has no source card"))?;
                    let card_index = self.state.players[player_index]
                        .sideboard
                        .iter()
                        .position(|card| {
                            card.instance_id == instance_id
                                && card
                                    .flags
                                    .get("companionEligible")
                                    .copied()
                                    .unwrap_or(false)
                                && companion_ability(&card.definition).is_some()
                        })
                        .ok_or_else(|| {
                            EngineError::new("companion is not eligible or available")
                        })?;
                    let companion_cost = companion_ability(
                        &self.state.players[player_index].sideboard[card_index].definition,
                    )
                    .and_then(|ability| ability["acquisitionCost"]["manaCost"].as_str())
                    .unwrap_or_default()
                    .to_string();
                    let tapped_sources = self.apply_payment(player_index, action)?;
                    let mut card = self.state.players[player_index]
                        .sideboard
                        .remove(card_index);
                    card.flags.remove("companionEligible");
                    self.admit_new_card_carrier(&mut card)?;
                    self.state.players[player_index].hand.push(card);
                    for source in tapped_sources {
                        self.enqueue_permanent_tapped_triggers(&source);
                    }
                    self.record_event(
                        "companionMovedToHand",
                        Some(action.player_id.clone()),
                        Some(instance_id.to_string()),
                        json!({ "cost": companion_cost, "timing": "sorcery" }),
                    );
                    return Ok(());
                }
                if action
                    .decisions
                    .get("lifeForMana")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    let life = action.decisions["lifePaid"]
                        .as_i64()
                        .and_then(|value| i32::try_from(value).ok())
                        .unwrap_or(1)
                        .max(1);
                    if self.state.players[player_index].life < life {
                        return Err(EngineError::new("player cannot pay life for mana"));
                    }
                    let symbol = action.decisions["manaProduced"]
                        .as_array()
                        .and_then(|values| values.first())
                        .and_then(Value::as_str)
                        .unwrap_or("C")
                        .to_string();
                    self.lose_life(&action.player_id, life, "lifeForManaPermission")?;
                    self.drain_linked_exile_returns(provider)?;
                    self.state.players[player_index]
                        .mana_pool
                        .push(FloatingMana {
                            symbol: symbol.clone(),
                            spend_restriction: None,
                        });
                    self.drain_linked_exile_returns(provider)?;
                    self.record_event(
                        "manaAbilityActivated",
                        Some(action.player_id.clone()),
                        None,
                        json!({ "lifePaid": life, "mana": [symbol] }),
                    );
                    return Ok(());
                }
                if action
                    .decisions
                    .get("foretell")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    let instance_id = action
                        .card_instance_id
                        .as_deref()
                        .ok_or_else(|| EngineError::new("foretell has no source card"))?;
                    let card_index = self.hand_position(player_index, instance_id)?;
                    let source = self.state.players[player_index].hand[card_index].clone();
                    let rule_index = action
                        .decisions
                        .get("abilityRuleIndex")
                        .and_then(Value::as_u64)
                        .and_then(|value| usize::try_from(value).ok())
                        .ok_or_else(|| EngineError::new("foretell has no rule index"))?;
                    let foretell_cost = source
                        .definition
                        .printed_rules()
                        .get(rule_index)
                        .filter(|rule| {
                            value_kind(rule) == Some("keywordAbility")
                                && foretell_ability_supported(&rule["ability"])
                        })
                        .and_then(|rule| rule["ability"]["cost"]["manaCost"].as_str())
                        .map(ToOwned::to_owned)
                        .ok_or_else(|| EngineError::new("foretell rule is not executable"))?;
                    if player_index != self.state.active_player {
                        return Err(EngineError::new(
                            "foretell can only be taken during your turn",
                        ));
                    }
                    let tapped_sources = self.apply_payment(player_index, action)?;
                    let mut card =
                        self.take_zone_card_for_movement(player_index, "hand", card_index)?;
                    card.flags.insert("foretoldFaceDown".to_string(), true);
                    self.put_owned_card_into_exile(player_index, card)?;
                    self.state.permissions.push(json!({
                        "kind": "foretoldCardPermission",
                        "playerId": action.player_id,
                        "cardInstanceId": instance_id,
                        "foretellManaCost": foretell_cost,
                        "exiledTurn": self.state.turn_number,
                    }));
                    for source in tapped_sources {
                        self.enqueue_permanent_tapped_triggers(&source);
                    }
                    self.record_event(
                        "cardForetold",
                        Some(action.player_id.clone()),
                        Some(instance_id.to_string()),
                        json!({ "faceDown": true }),
                    );
                    self.check_state_based_actions_with_provider(Some(provider))?;
                    return Ok(());
                }
                if action
                    .decisions
                    .get("suspend")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    let instance_id = action
                        .card_instance_id
                        .as_deref()
                        .ok_or_else(|| EngineError::new("suspend has no source card"))?;
                    let card_index = self.hand_position(player_index, instance_id)?;
                    let source = self.state.players[player_index].hand[card_index].clone();
                    let rule_index = action
                        .decisions
                        .get("abilityRuleIndex")
                        .and_then(Value::as_u64)
                        .and_then(|value| usize::try_from(value).ok())
                        .ok_or_else(|| EngineError::new("suspend has no rule index"))?;
                    let time_counters = source
                        .definition
                        .printed_rules()
                        .get(rule_index)
                        .filter(|rule| {
                            value_kind(rule) == Some("keywordAbility")
                                && suspend_ability_supported(&rule["ability"])
                        })
                        .and_then(|rule| integer_value(&rule["ability"]["timeCounters"]))
                        .ok_or_else(|| EngineError::new("suspend rule is not executable"))?;
                    let tapped_sources = self.apply_payment(player_index, action)?;
                    let mut card =
                        self.take_zone_card_for_movement(player_index, "hand", card_index)?;
                    card.flags.insert("suspended".to_string(), true);
                    card.counters.insert("time".to_string(), time_counters);
                    self.put_owned_card_into_exile(player_index, card)?;
                    for source in tapped_sources {
                        self.enqueue_permanent_tapped_triggers(&source);
                    }
                    self.record_event(
                        "cardSuspended",
                        Some(action.player_id.clone()),
                        Some(instance_id.to_string()),
                        json!({ "timeCounters": time_counters }),
                    );
                    self.check_state_based_actions_with_provider(Some(provider))?;
                    return Ok(());
                }
                if action
                    .decisions
                    .get("plot")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    let instance_id = action
                        .card_instance_id
                        .as_deref()
                        .ok_or_else(|| EngineError::new("plot has no source card"))?;
                    let card_index = self.hand_position(player_index, instance_id)?;
                    let source = self.state.players[player_index].hand[card_index].clone();
                    let rule_index = action
                        .decisions
                        .get("abilityRuleIndex")
                        .and_then(Value::as_u64)
                        .and_then(|value| usize::try_from(value).ok())
                        .ok_or_else(|| EngineError::new("plot has no rule index"))?;
                    if !source
                        .definition
                        .printed_rules()
                        .get(rule_index)
                        .is_some_and(|rule| {
                            value_kind(rule) == Some("keywordAbility")
                                && plot_ability_supported(&rule["ability"])
                        })
                    {
                        return Err(EngineError::new("plot rule is not executable"));
                    }
                    if player_index != self.state.active_player
                        || !matches!(
                            self.state.step,
                            GameStep::PrecombatMain | GameStep::PostcombatMain
                        )
                        || !self.state.stack.is_empty()
                    {
                        return Err(EngineError::new("plot can only be taken as a sorcery"));
                    }
                    let tapped_sources = self.apply_payment(player_index, action)?;
                    let card =
                        self.take_zone_card_for_movement(player_index, "hand", card_index)?;
                    self.put_owned_card_into_exile(player_index, card)?;
                    let permission = json!({
                        "kind": "plottedCardPermission",
                        "playerId": action.player_id,
                        "cardInstanceId": instance_id,
                        "plottedTurn": self.state.turn_number,
                    });
                    self.state.permissions.push(permission);
                    for source in tapped_sources {
                        self.enqueue_permanent_tapped_triggers(&source);
                    }
                    self.record_event(
                        "cardPlotted",
                        Some(action.player_id.clone()),
                        Some(instance_id.to_string()),
                        json!({ "from": "hand", "to": "exile" }),
                    );
                    self.enqueue_card_plotted_triggers(&source);
                    self.check_state_based_actions_with_provider(Some(provider))?;
                    return Ok(());
                }
                if let Some(door_index) = action
                    .decisions
                    .get("roomUnlockDoor")
                    .and_then(Value::as_u64)
                    .and_then(|index| usize::try_from(index).ok())
                {
                    let instance_id = action
                        .card_instance_id
                        .as_deref()
                        .ok_or_else(|| EngineError::new("room unlock has no source"))?;
                    let Some((source_player, source_index)) = self.permanent_position(instance_id)
                    else {
                        return Err(EngineError::new("room is no longer on the battlefield"));
                    };
                    let source = &self.state.players[source_player].battlefield[source_index];
                    if source.controller != action.player_id
                        || !is_room_definition(&source.definition)
                        || source
                            .flags
                            .get(&format!("roomDoor{door_index}Unlocked"))
                            .copied()
                            .unwrap_or(false)
                    {
                        return Err(EngineError::new(
                            "the selected room door cannot be unlocked",
                        ));
                    }
                    let tapped_sources = self.apply_payment(player_index, action)?;
                    let Some((source_player, source_index)) = self.permanent_position(instance_id)
                    else {
                        return Err(EngineError::new(
                            "room left the battlefield while paying to unlock it",
                        ));
                    };
                    self.state.players[source_player].battlefield[source_index]
                        .flags
                        .insert(format!("roomDoor{door_index}Unlocked"), true);
                    let source =
                        self.state.players[source_player].battlefield[source_index].clone();
                    for tapped_source in tapped_sources {
                        self.enqueue_permanent_tapped_triggers(&tapped_source);
                    }
                    self.record_event(
                        "doorUnlocked",
                        Some(action.player_id.clone()),
                        Some(instance_id.to_string()),
                        json!({ "doorIndex": door_index }),
                    );
                    self.enqueue_door_unlocked_triggers(&source, door_index);
                    self.check_state_based_actions_with_provider(Some(provider))?;
                    return Ok(());
                }
                if action
                    .decisions
                    .get("offBattlefieldActivation")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    let instance_id = action
                        .card_instance_id
                        .as_deref()
                        .ok_or_else(|| EngineError::new("activation has no source"))?;
                    let zone_name = action
                        .decisions
                        .get("activationSourceZone")
                        .and_then(Value::as_str)
                        .ok_or_else(|| EngineError::new("activation has no source zone"))?;
                    let source = match zone_name {
                        "hand" => self.state.players[player_index]
                            .hand
                            .iter()
                            .find(|card| card.instance_id == instance_id),
                        "graveyard" => self.state.players[player_index]
                            .graveyard
                            .iter()
                            .find(|card| card.instance_id == instance_id),
                        _ => None,
                    }
                    .cloned()
                    .ok_or_else(|| {
                        EngineError::new("activation source is no longer in its declared zone")
                    })?;
                    let rule_index = action
                        .decisions
                        .get("abilityRuleIndex")
                        .and_then(Value::as_u64)
                        .and_then(|value| usize::try_from(value).ok())
                        .ok_or_else(|| EngineError::new("activation has no rule index"))?;
                    let rule = source
                        .definition
                        .printed_rules()
                        .get(rule_index)
                        .filter(|rule| {
                            (activated_rule_supported(rule) || mana_rule_supported(rule))
                                && activated_rule_usable_from_zone(rule, zone_name)
                        })
                        .cloned()
                        .ok_or_else(|| {
                            EngineError::new("off-battlefield activation is not executable")
                        })?;
                    let prepared_cost_payment =
                        self.prepare_activated_cost_payment(action, &rule)?;
                    return self.with_activated_cost_rollback(&prepared_cost_payment, |engine| {
                        let cost_stack_start = engine.state.stack.len();
                        if mana_rule_supported(&rule) {
                            engine.apply_activated_discard_costs(action, &rule)?;
                            engine.apply_activated_exile_source_costs(action, &rule)?;
                            let tapped_sources = engine.apply_payment(player_index, action)?;
                            engine.pay_activated_counter_costs(action, &rule, provider)?;
                            let pending_cost_triggers =
                                engine.state.stack.split_off(cost_stack_start);
                            let committed_cost_payment =
                                engine.commit_activated_cost_payment(&prepared_cost_payment)?;
                            let mana_symbols = action
                                .decisions
                                .get("offBattlefieldManaProduced")
                                .and_then(Value::as_array)
                                .into_iter()
                                .flatten()
                                .filter_map(Value::as_str)
                                .map(ToOwned::to_owned)
                                .collect::<Vec<_>>();
                            let spend_restriction = action
                                .decisions
                                .get("offBattlefieldManaSpendRestriction")
                                .cloned();
                            for symbol in &mana_symbols {
                                engine.drain_linked_exile_returns(provider)?;
                                engine.state.players[player_index]
                                    .mana_pool
                                    .push(FloatingMana {
                                        symbol: symbol.clone(),
                                        spend_restriction: spend_restriction.clone(),
                                    });
                            }
                            engine.state.stack.extend(pending_cost_triggers);
                            engine.publish_activated_cost_payment(committed_cost_payment);
                            engine.drain_linked_exile_returns(provider)?;
                            engine.record_event(
                                "manaAbilityActivated",
                                Some(action.player_id.clone()),
                                Some(source.instance_id.clone()),
                                json!({
                                    "mana": mana_symbols,
                                    "sourceZone": zone_name,
                                    "spendRestriction": spend_restriction,
                                }),
                            );
                            engine.enqueue_mana_ability_activated_triggers(&source, &mana_symbols);
                            for tapped_source in tapped_sources {
                                engine.enqueue_permanent_tapped_triggers(&tapped_source);
                            }
                            engine.check_state_based_actions_with_provider(Some(provider))?;
                            return Ok(());
                        }
                        // Activation costs may be paid in any order. Move an
                        // off-battlefield source out of its declared zone before
                        // activating mana sources so a nested mana activation or
                        // trigger cannot invalidate the source halfway through
                        // paying Channel-style costs.
                        engine.apply_activated_discard_costs(action, &rule)?;
                        engine.apply_activated_exile_source_costs(action, &rule)?;
                        engine.apply_activated_return_costs(action, &rule)?;
                        engine.apply_activated_move_costs(action, &rule)?;
                        let tapped_sources = engine.apply_payment(player_index, action)?;
                        engine.pay_activated_counter_costs(action, &rule, provider)?;
                        let pending_cost_triggers = engine.state.stack.split_off(cost_stack_start);
                        let committed_cost_payment =
                            engine.commit_activated_cost_payment(&prepared_cost_payment)?;
                        engine.stack_sequence += 1;
                        let stack_id = format!("stack:{}", engine.stack_sequence);
                        let stack_targets = Self::activated_effect_targets(&rule, &action.targets);
                        engine.state.stack.push(StackObject {
                            id: stack_id.clone(),
                            controller: action.player_id.clone(),
                            card: source.clone(),
                            cant_be_countered: false,
                            exile_on_leave_stack: false,
                            ability_kind: Some("activatedAbility".to_string()),
                            ability_rule: Some(rule.clone()),
                            decisions: action.decisions.clone(),
                            targets: stack_targets.clone(),
                        });
                        engine.state.stack.extend(pending_cost_triggers);
                        engine.publish_activated_cost_payment(committed_cost_payment);
                        for source in tapped_sources {
                            engine.enqueue_permanent_tapped_triggers(&source);
                        }
                        engine.drain_linked_exile_returns(provider)?;
                        engine.record_event(
                            "activatedAbilityPutOnStack",
                            Some(action.player_id.clone()),
                            Some(source.instance_id.clone()),
                            json!({
                                "cardName": source.definition.name,
                                "objectKind": "activatedAbility",
                                "sourceZone": zone_name,
                                "stackId": stack_id,
                            }),
                        );
                        engine.enqueue_nonmana_ability_activated_triggers(
                            &action.player_id,
                            &stack_id,
                        );
                        engine.enqueue_targeting_triggers(&stack_id, &stack_targets)?;
                        return Ok(());
                    });
                }
                if action
                    .decisions
                    .get("splinterTwin")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    let instance_id = action
                        .card_instance_id
                        .as_deref()
                        .ok_or_else(|| EngineError::new("Splinter Twin action has no source"))?;
                    let Some((controller_index, card_index)) = self.permanent_position(instance_id)
                    else {
                        return Err(EngineError::new(
                            "Splinter Twin source is not on the battlefield",
                        ));
                    };
                    let source =
                        self.state.players[controller_index].battlefield[card_index].clone();
                    if source.controller != action.player_id
                        || source.tapped
                        || source.summoning_sick
                    {
                        return Err(EngineError::new("illegal Splinter Twin activation"));
                    }
                    let Some(tapped_source) = self.tap_permanent(instance_id)? else {
                        return Err(EngineError::new("Splinter Twin source could not be tapped"));
                    };
                    self.stack_sequence += 1;
                    let stack_id = format!("stack:{}", self.stack_sequence);
                    self.state.stack.push(StackObject {
                        id: stack_id.clone(),
                        controller: action.player_id.clone(),
                        card: source.clone(),
                        cant_be_countered: false,
                        exile_on_leave_stack: false,
                        ability_kind: Some("activatedAbility".to_string()),
                        ability_rule: Some(json!({
                            "kind": "activatedAbility",
                            "source": { "kind": "self" },
                            "costs": [{ "kind": "tap", "object": { "kind": "self" } }],
                            "effects": [{
                                "kind": "createTokens",
                                "quantity": { "kind": "integer", "value": 1 },
                                "token": {
                                    "kind": "copyOf",
                                    "object": { "kind": "abilitySource" },
                                    "except": [{ "kind": "grantKeyword", "keyword": "haste" }],
                                },
                                "exileAtNextEndStep": true,
                            }],
                        })),
                        decisions: action.decisions.clone(),
                        targets: BTreeMap::new(),
                    });
                    self.enqueue_permanent_tapped_triggers(&tapped_source);
                    self.drain_linked_exile_returns(provider)?;
                    self.record_event(
                        "activatedAbilityPutOnStack",
                        Some(action.player_id.clone()),
                        Some(source.instance_id.clone()),
                        json!({
                            "cardName": source.definition.name,
                            "objectKind": "activatedAbility",
                            "stackId": stack_id,
                        }),
                    );
                    self.enqueue_nonmana_ability_activated_triggers(&action.player_id, &stack_id);
                    return Ok(());
                }
                if action
                    .decisions
                    .get("turnFaceUp")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    let instance_id = action
                        .card_instance_id
                        .as_deref()
                        .ok_or_else(|| EngineError::new("turn-face-up action has no source"))?;
                    let Some((controller_index, card_index)) = self.permanent_position(instance_id)
                    else {
                        return Err(EngineError::new(
                            "face-down creature is not on the battlefield",
                        ));
                    };
                    if self.state.players[controller_index].battlefield[card_index].controller
                        != action.player_id
                        || self.state.players[controller_index].battlefield[card_index]
                            .flags
                            .get("faceDown")
                            != Some(&true)
                    {
                        return Err(EngineError::new("illegal turn-face-up action"));
                    }
                    let tapped_sources = self.apply_payment(player_index, action)?;
                    let turned_face_up = {
                        let permanent =
                            &mut self.state.players[controller_index].battlefield[card_index];
                        let printed = permanent.printed_definition.clone().ok_or_else(|| {
                            EngineError::new("face-down creature has no front face")
                        })?;
                        let megamorph = morph_ability(&printed).is_some_and(|ability| {
                            ability["putCounterWhenTurnedFaceUp"].as_bool() == Some(true)
                        });
                        permanent.definition = printed;
                        permanent.flags.remove("faceDown");
                        if megamorph {
                            *permanent.counters.entry("+1/+1".to_string()).or_default() += 1;
                        }
                        permanent.clone()
                    };
                    for source in tapped_sources {
                        self.enqueue_permanent_tapped_triggers(&source);
                    }
                    self.record_event(
                        "permanentTurnedFaceUp",
                        Some(action.player_id.clone()),
                        Some(instance_id.to_string()),
                        json!({}),
                    );
                    self.enqueue_turned_face_up_triggers(&turned_face_up);
                    self.check_state_based_actions_with_provider(Some(provider))?;
                    return Ok(());
                }
                if action
                    .decisions
                    .get("cycling")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    let instance_id = action
                        .card_instance_id
                        .as_deref()
                        .ok_or_else(|| EngineError::new("cycling has no source card"))?;
                    let card_index = self.hand_position(player_index, instance_id)?;
                    let source = self.state.players[player_index].hand[card_index].clone();
                    let rule_index = action
                        .decisions
                        .get("abilityRuleIndex")
                        .and_then(Value::as_u64)
                        .and_then(|value| usize::try_from(value).ok())
                        .ok_or_else(|| EngineError::new("cycling has no rule index"))?;
                    let ability = source
                        .definition
                        .printed_rules()
                        .get(rule_index)
                        .filter(|rule| {
                            value_kind(rule) == Some("keywordAbility")
                                && cycling_ability_supported(&rule["ability"])
                        })
                        .map(|rule| rule["ability"].clone())
                        .ok_or_else(|| EngineError::new("cycling rule is not executable"))?;
                    let tapped_sources = self.apply_payment(player_index, action)?;
                    let (card, graveyard_destination) =
                        self.take_zone_card_for_graveyard(player_index, "hand", card_index)?;
                    self.put_owned_card_into_prepared_graveyard(
                        player_index,
                        card,
                        graveyard_destination,
                    )?;
                    self.stack_sequence += 1;
                    let stack_id = format!("stack:{}", self.stack_sequence);
                    self.state.stack.push(StackObject {
                        id: stack_id.clone(),
                        controller: action.player_id.clone(),
                        card: source.clone(),
                        cant_be_countered: false,
                        exile_on_leave_stack: false,
                        ability_kind: Some("activatedAbility".to_string()),
                        ability_rule: Some(json!({
                            "kind": "activatedAbility",
                            "source": { "kind": "self" },
                            "effects": ability["effects"].clone(),
                        })),
                        decisions: action.decisions.clone(),
                        targets: BTreeMap::new(),
                    });
                    for source in tapped_sources {
                        self.enqueue_permanent_tapped_triggers(&source);
                    }
                    self.record_event(
                        "cardCycled",
                        Some(action.player_id.clone()),
                        Some(source.instance_id.clone()),
                        json!({
                            "cardName": source.definition.name,
                            "objectKind": "activatedAbility",
                            "stackId": stack_id,
                        }),
                    );
                    for rule in source
                        .definition
                        .printed_rules()
                        .iter()
                        .filter(|rule| {
                            triggered_rule_supported(rule)
                                && value_kind(&rule["event"]) == Some("sourceCycled")
                        })
                        .cloned()
                        .collect::<Vec<_>>()
                    {
                        self.put_triggered_ability_on_stack_with_decisions(
                            &source,
                            rule,
                            action.decisions.clone(),
                        );
                        self.check_quantity_failure()?;
                    }
                    self.publish_cycling_card_actions(&action.player_id, &source);
                    self.check_quantity_failure()?;
                    self.check_state_based_actions_with_provider(Some(provider))?;
                    return Ok(());
                }
                let typed_cycling_kind =
                    ["basicLandcycling", "typecycling"]
                        .into_iter()
                        .find(|kind| {
                            action
                                .decisions
                                .get(*kind)
                                .and_then(Value::as_bool)
                                .unwrap_or(false)
                        });
                if let Some(typed_cycling_kind) = typed_cycling_kind {
                    let instance_id = action
                        .card_instance_id
                        .as_deref()
                        .ok_or_else(|| EngineError::new("typed cycling has no source"))?;
                    let card_index = self.hand_position(player_index, instance_id)?;
                    let source = self.state.players[player_index].hand[card_index].clone();
                    let rule_index = action
                        .decisions
                        .get("abilityRuleIndex")
                        .and_then(Value::as_u64)
                        .and_then(|value| usize::try_from(value).ok())
                        .ok_or_else(|| EngineError::new("typed cycling has no rule index"))?;
                    let ability = source
                        .definition
                        .printed_rules()
                        .get(rule_index)
                        .filter(|rule| {
                            value_kind(rule) == Some("keywordAbility")
                                && if typed_cycling_kind == "basicLandcycling" {
                                    paid_hand_keyword_supported(
                                        &rule["ability"],
                                        "basicLandcycling",
                                    )
                                } else {
                                    typecycling_ability_supported(&rule["ability"])
                                }
                        })
                        .map(|rule| rule["ability"].clone())
                        .ok_or_else(|| EngineError::new("typed cycling rule is not executable"))?;
                    let tapped_sources = self.apply_payment(player_index, action)?;
                    let (card, graveyard_destination) =
                        self.take_zone_card_for_graveyard(player_index, "hand", card_index)?;
                    self.put_owned_card_into_prepared_graveyard(
                        player_index,
                        card,
                        graveyard_destination,
                    )?;
                    self.stack_sequence += 1;
                    let stack_id = format!("stack:{}", self.stack_sequence);
                    self.state.stack.push(StackObject {
                        id: stack_id.clone(),
                        controller: action.player_id.clone(),
                        card: source.clone(),
                        cant_be_countered: false,
                        exile_on_leave_stack: false,
                        ability_kind: Some("activatedAbility".to_string()),
                        ability_rule: Some(json!({
                            "kind": "activatedAbility",
                            "source": { "kind": "self" },
                            "costs": [{ "kind": "payMana", "manaCost": "{0}" }],
                            "effects": ability["effects"].clone(),
                        })),
                        decisions: action.decisions.clone(),
                        targets: BTreeMap::new(),
                    });
                    for source in tapped_sources {
                        self.enqueue_permanent_tapped_triggers(&source);
                    }
                    self.record_event(
                        "cardTypecycled",
                        Some(action.player_id.clone()),
                        Some(source.instance_id.clone()),
                        json!({
                            "cardName": source.definition.name,
                            "objectKind": "activatedAbility",
                            "stackId": stack_id,
                        }),
                    );
                    self.publish_cycling_card_actions(&action.player_id, &source);
                    self.check_quantity_failure()?;
                    self.check_state_based_actions_with_provider(Some(provider))?;
                    return Ok(());
                }
                if action
                    .decisions
                    .get("equip")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    let instance_id = action
                        .card_instance_id
                        .as_deref()
                        .ok_or_else(|| EngineError::new("equip has no source"))?;
                    let rule_index = action
                        .decisions
                        .get("abilityRuleIndex")
                        .and_then(Value::as_u64)
                        .and_then(|value| usize::try_from(value).ok())
                        .ok_or_else(|| EngineError::new("equip has no rule index"))?;
                    let Some((controller_index, card_index)) = self.permanent_position(instance_id)
                    else {
                        return Err(EngineError::new("equipment is not on the battlefield"));
                    };
                    if self.state.players[controller_index].battlefield[card_index].controller
                        != action.player_id
                    {
                        return Err(EngineError::new("player does not control equipment"));
                    }
                    let source =
                        self.state.players[controller_index].battlefield[card_index].clone();
                    let ability = source
                        .definition
                        .printed_rules()
                        .get(rule_index)
                        .filter(|rule| {
                            value_kind(rule) == Some("keywordAbility")
                                && equip_ability_supported(&rule["ability"])
                        })
                        .map(|rule| rule["ability"].clone())
                        .ok_or_else(|| EngineError::new("equip rule is not executable"))?;
                    let tapped_sources = self.apply_payment(player_index, action)?;
                    if let Some(sacrifice_id) = action
                        .decisions
                        .get("equipSacrifice")
                        .and_then(Value::as_str)
                    {
                        let cost = &ability["costs"][0];
                        let Some((sacrifice_player, sacrifice_index)) =
                            self.permanent_position(sacrifice_id)
                        else {
                            return Err(EngineError::new(
                                "equip sacrifice is no longer on the battlefield",
                            ));
                        };
                        let sacrifice =
                            &self.state.players[sacrifice_player].battlefield[sacrifice_index];
                        if sacrifice.controller != action.player_id
                            || !self.permanent_state_matches(sacrifice, &cost["where"])
                        {
                            return Err(EngineError::new("illegal equip sacrifice"));
                        }
                        self.move_permanent_to_graveyard(sacrifice_id, "sacrificed")?;
                    }
                    self.stack_sequence += 1;
                    let stack_id = format!("stack:{}", self.stack_sequence);
                    let equip_rule = json!({
                        "kind": "activatedAbility",
                        "source": { "kind": "self" },
                        "costs": [{ "kind": "payMana", "manaCost": "{0}" }],
                        "effects": [{
                            "kind": "attachPermanent",
                            "attachment": { "kind": "abilitySource" },
                            "to": { "kind": "chosenTarget", "id": "equipTarget" },
                        }],
                    });
                    self.state.stack.push(StackObject {
                        id: stack_id.clone(),
                        controller: action.player_id.clone(),
                        card: source.clone(),
                        cant_be_countered: false,
                        exile_on_leave_stack: false,
                        ability_kind: Some("activatedAbility".to_string()),
                        ability_rule: Some(equip_rule),
                        decisions: action.decisions.clone(),
                        targets: action.targets.clone(),
                    });
                    for source in tapped_sources {
                        self.enqueue_permanent_tapped_triggers(&source);
                    }
                    self.record_event(
                        "equipAbilityPutOnStack",
                        Some(action.player_id.clone()),
                        Some(source.instance_id.clone()),
                        json!({
                            "cardName": source.definition.name,
                            "objectKind": "activatedAbility",
                            "stackId": stack_id,
                        }),
                    );
                    self.check_state_based_actions_with_provider(Some(provider))?;
                    return Ok(());
                }
                if action
                    .decisions
                    .get("manaAbility")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    self.apply_mana_ability_action(player_index, action, provider)?;
                    self.check_state_based_actions_with_provider(Some(provider))?;
                    return Ok(());
                }
                let instance_id = action
                    .card_instance_id
                    .as_deref()
                    .ok_or_else(|| EngineError::new("activated ability has no source"))?;
                let rule_index = action
                    .decisions
                    .get("abilityRuleIndex")
                    .and_then(Value::as_u64)
                    .and_then(|value| usize::try_from(value).ok())
                    .ok_or_else(|| EngineError::new("activated ability has no rule index"))?;
                let Some((controller_index, card_index)) = self.permanent_position(instance_id)
                else {
                    return Err(EngineError::new(
                        "activated ability source is not on the battlefield",
                    ));
                };
                if self.state.players[controller_index].battlefield[card_index].controller
                    != action.player_id
                {
                    return Err(EngineError::new(
                        "player does not control activated ability source",
                    ));
                }
                let source = self.state.players[controller_index].battlefield[card_index].clone();
                let rule = if let Some(granted_rule) = action.decisions.get("grantedAbilityRule") {
                    if !activated_rule_supported(granted_rule)
                        || !self
                            .granted_activated_abilities(&source)
                            .iter()
                            .any(|current| current == granted_rule)
                    {
                        return Err(EngineError::new(
                            "granted activated ability is no longer available",
                        ));
                    }
                    granted_rule.clone()
                } else {
                    source
                        .definition
                        .printed_rules()
                        .get(rule_index)
                        .filter(|rule| activated_rule_supported(rule))
                        .cloned()
                        .ok_or_else(|| {
                            EngineError::new("activated ability rule is not executable")
                        })?
                };
                if !activated_rule_usable_from_zone(&rule, "battlefield") {
                    return Err(EngineError::new(
                        "activated ability cannot be activated from the battlefield",
                    ));
                }
                let cost_trigger_start = self.state.stack.len();
                let prepared_cost_payment = self.prepare_activated_cost_payment(action, &rule)?;
                let mut tapped_sources = self.apply_payment(player_index, action)?;
                let activation_limit = &rule["activationLimit"];
                if let Some(prefix) = activation_limit_use_prefix(activation_limit, rule_index) {
                    let use_count = activation_limit_use_count(
                        &self.state.players[controller_index].battlefield[card_index],
                        activation_limit,
                        rule_index,
                    );
                    self.state.players[controller_index].battlefield[card_index]
                        .flags
                        .insert(format!("{prefix}{}", use_count + 1), true);
                } else if let Some(flag) =
                    activation_limit_flag(activation_limit, self.state.turn_number, rule_index)
                {
                    self.state.players[controller_index].battlefield[card_index]
                        .flags
                        .insert(flag, true);
                }
                if action
                    .decisions
                    .get("tapSource")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
                {
                    if let Some(source) = self.tap_permanent(instance_id)? {
                        tapped_sources.push(source);
                    }
                }
                let loyalty_change = action
                    .decisions
                    .get("loyaltyChange")
                    .and_then(Value::as_i64)
                    .and_then(|value| i32::try_from(value).ok())
                    .unwrap_or(0);
                if loyalty_change > 0 {
                    self.pay_counter_placement_cost(
                        instance_id,
                        "loyalty",
                        loyalty_change,
                        &action.player_id,
                        provider,
                    )?;
                } else if loyalty_change < 0 {
                    let current = self.state.players[controller_index].battlefield[card_index]
                        .counters
                        .get("loyalty")
                        .copied()
                        .unwrap_or(0);
                    if current.saturating_add(loyalty_change) < 0 {
                        return Err(EngineError::new(
                            "player cannot pay activated ability loyalty cost",
                        ));
                    }
                    self.remove_counters_from_permanent(
                        instance_id,
                        "loyalty",
                        loyalty_change.saturating_neg(),
                        "cost",
                    );
                }
                self.pay_activated_counter_costs(action, &rule, provider)?;

                for cost in rule["costs"]
                    .as_array()
                    .into_iter()
                    .flatten()
                    .filter(|cost| value_kind(cost) == Some("removeCounters"))
                {
                    let counter = Self::remove_counter_cost_name(cost, &action.decisions)
                        .ok_or_else(|| {
                            EngineError::new("activated ability counter cost has no choice")
                        })?;
                    let count =
                        cost_payment::activated_cost_count(&cost["count"], &action.decisions)
                            .ok_or_else(|| {
                                EngineError::new("activated ability counter cost has no count")
                            })?;
                    let available = self.state.players[controller_index].battlefield[card_index]
                        .counters
                        .get(&counter)
                        .copied()
                        .unwrap_or(0);
                    if available < count {
                        return Err(EngineError::new(
                            "activated ability counter cost cannot be paid",
                        ));
                    }
                    self.state.players[controller_index].battlefield[card_index]
                        .counters
                        .insert(counter, available - count);
                }
                if rule["costs"]
                    .as_array()
                    .into_iter()
                    .flatten()
                    .any(|cost| value_kind(cost) == Some("removeCountersFromControlledPermanents"))
                {
                    let payments = action.decisions["activatedCounterRemoval"]
                        .as_array()
                        .ok_or_else(|| {
                            EngineError::new("activated counter-removal cost is missing")
                        })?
                        .clone();
                    let distribution_cost = rule["costs"]
                        .as_array()
                        .into_iter()
                        .flatten()
                        .find(|cost| {
                            value_kind(cost) == Some("removeCountersFromControlledPermanents")
                        })
                        .cloned()
                        .unwrap_or(Value::Null);
                    let required = integer_value(&distribution_cost["count"]).unwrap_or(0);
                    let total = payments
                        .iter()
                        .filter_map(|payment| integer_value(&payment["count"]))
                        .sum::<i32>();
                    if total != required {
                        return Err(EngineError::new(
                            "activated counter-removal count is invalid",
                        ));
                    }
                    for payment in &payments {
                        let instance_id = payment["cardInstanceId"].as_str().ok_or_else(|| {
                            EngineError::new("counter-removal permanent is missing")
                        })?;
                        let counter = payment["counter"].as_str().unwrap_or_default();
                        let count = integer_value(&payment["count"]).unwrap_or(0);
                        let Some((payment_player, payment_index)) =
                            self.permanent_position(instance_id)
                        else {
                            return Err(EngineError::new("counter-removal permanent left play"));
                        };
                        let candidate =
                            &mut self.state.players[payment_player].battlefield[payment_index];
                        if candidate.controller != action.player_id
                            || candidate.counters.get(counter).copied().unwrap_or(0) < count
                            || distribution_cost["counter"]
                                .as_str()
                                .is_some_and(|named| named != counter)
                            || (value_kind(&distribution_cost["permanent"]) == Some("self")
                                && action.card_instance_id.as_deref() != Some(instance_id))
                        {
                            return Err(EngineError::new(
                                "activated counter-removal cost cannot be paid",
                            ));
                        }
                        *candidate.counters.entry(counter.to_string()).or_default() -= count;
                    }
                }
                if let Some(minimum) = rule["costs"]
                    .as_array()
                    .into_iter()
                    .flatten()
                    .find(|cost| value_kind(cost) == Some("exileHistoricManaValue"))
                    .and_then(|cost| integer_value(&cost["minimum"]))
                {
                    let selected = action.decisions["historicExileCost"]
                        .as_array()
                        .into_iter()
                        .flatten()
                        .filter_map(Value::as_str)
                        .map(ToOwned::to_owned)
                        .collect::<Vec<_>>();
                    let total = selected
                        .iter()
                        .filter_map(|instance_id| {
                            self.state.players[player_index]
                                .graveyard
                                .iter()
                                .find(|card| card.instance_id == *instance_id)
                        })
                        .filter(|card| {
                            matches_card_filter(&card.definition, &json!({ "kind": "historic" }))
                        })
                        .map(|card| mana_value(&card.definition))
                        .sum::<i32>();
                    if total < minimum || selected.is_empty() {
                        return Err(EngineError::new(
                            "historic exile activation cost is no longer payable",
                        ));
                    }
                    for instance_id in selected {
                        let Some(card_index) = self.state.players[player_index]
                            .graveyard
                            .iter()
                            .position(|card| card.instance_id == instance_id)
                        else {
                            return Err(EngineError::new(
                                "historic exile cost card left the graveyard",
                            ));
                        };
                        let card = self.take_zone_card_for_movement(
                            player_index,
                            "graveyard",
                            card_index,
                        )?;
                        self.put_owned_card_into_exile(player_index, card)?;
                    }
                }
                self.apply_activated_move_costs(action, &rule)?;
                for cost in rule["costs"]
                    .as_array()
                    .into_iter()
                    .flatten()
                    .filter(|cost| value_kind(cost) == Some("exileGraveyardCard"))
                {
                    let target_id = cost["card"]["id"]
                        .as_str()
                        .ok_or_else(|| EngineError::new("graveyard exile cost has no target"))?;
                    let instance_id = action
                        .targets
                        .get(target_id)
                        .and_then(|target| match target {
                            TargetRef::Card { instance_id } => Some(instance_id.clone()),
                            _ => None,
                        })
                        .ok_or_else(|| {
                            EngineError::new("graveyard exile cost target is missing")
                        })?;
                    let card_index = self.state.players[player_index]
                        .graveyard
                        .iter()
                        .position(|card| card.instance_id == instance_id)
                        .ok_or_else(|| {
                            EngineError::new("graveyard exile cost card left the graveyard")
                        })?;
                    let card =
                        self.take_zone_card_for_movement(player_index, "graveyard", card_index)?;
                    self.put_owned_card_into_exile(player_index, card)?;
                    self.enqueue_cards_left_graveyard_triggers(
                        &action.player_id,
                        std::slice::from_ref(&instance_id),
                    );
                }
                for cost in rule["costs"]
                    .as_array()
                    .into_iter()
                    .flatten()
                    .filter(|cost| value_kind(cost) == Some("exileTopMatchingGraveyardCard"))
                {
                    let card_index = self.state.players[player_index]
                        .graveyard
                        .iter()
                        .rposition(|card| matches_card_filter(&card.definition, &cost["where"]))
                        .ok_or_else(|| {
                            EngineError::new(
                                "top matching graveyard-card cost is no longer payable",
                            )
                        })?;
                    let card =
                        self.take_zone_card_for_movement(player_index, "graveyard", card_index)?;
                    let instance_id = card.instance_id.clone();
                    self.put_owned_card_into_exile(player_index, card)?;
                    self.enqueue_cards_left_graveyard_triggers(
                        &action.player_id,
                        std::slice::from_ref(&instance_id),
                    );
                }
                self.stack_sequence += 1;
                let stack_id = format!("stack:{}", self.stack_sequence);
                let mut stack_decisions = action.decisions.clone();
                for stored in source
                    .definition
                    .printed_rules()
                    .iter()
                    .filter(|rule| value_kind(rule) == Some("storedDecisionValue"))
                {
                    if let (Some(decision_id), Some(value)) =
                        (stored["decisionId"].as_str(), stored.get("value"))
                    {
                        stack_decisions
                            .entry(decision_id.to_string())
                            .or_insert_with(|| value.clone());
                    }
                }
                for cost in rule["costs"]
                    .as_array()
                    .into_iter()
                    .flatten()
                    .filter(|cost| {
                        value_kind(cost) == Some("tap")
                            && value_kind(&cost["object"]) == Some("chosenTarget")
                    })
                {
                    let target_id = cost["object"]["id"]
                        .as_str()
                        .ok_or_else(|| EngineError::new("tap cost has no target id"))?;
                    let instance_id = action
                        .targets
                        .get(target_id)
                        .and_then(|target| match target {
                            TargetRef::Permanent { instance_id } => Some(instance_id.clone()),
                            _ => None,
                        })
                        .ok_or_else(|| EngineError::new("tap cost permanent is missing"))?;
                    let Some((target_player, target_index)) = self.permanent_position(&instance_id)
                    else {
                        return Err(EngineError::new(
                            "tap cost permanent is no longer on the battlefield",
                        ));
                    };
                    let target = &self.state.players[target_player].battlefield[target_index];
                    if target.controller != action.player_id || target.tapped {
                        return Err(EngineError::new(
                            "activated ability tap cost cannot be paid",
                        ));
                    }
                    if let Some(binding) = cost["bindPowerAs"].as_str() {
                        stack_decisions
                            .insert(binding.to_string(), Value::from(self.current_power(target)));
                    }
                    stack_decisions.insert(
                        format!("{target_id}InstanceId"),
                        Value::String(instance_id.clone()),
                    );
                    if let Some(tapped_source) = self.tap_permanent(&instance_id)? {
                        tapped_sources.push(tapped_source);
                    }
                }
                for cost in rule["costs"]
                    .as_array()
                    .into_iter()
                    .flatten()
                    .filter(|cost| value_kind(cost) == Some("sacrificePermanent"))
                {
                    let power_binding = cost["bindPowerAs"].as_str();
                    let toughness_binding = cost["bindToughnessAs"].as_str();
                    if power_binding.is_none() && toughness_binding.is_none() {
                        continue;
                    }
                    let Some(target_id) = cost["permanent"]["id"].as_str() else {
                        continue;
                    };
                    let Some(TargetRef::Permanent { instance_id }) = action.targets.get(target_id)
                    else {
                        continue;
                    };
                    if let Some((target_player, target_index)) =
                        self.permanent_position(instance_id)
                    {
                        let permanent =
                            &self.state.players[target_player].battlefield[target_index];
                        if let Some(binding) = power_binding {
                            stack_decisions.insert(
                                binding.to_string(),
                                Value::from(self.current_power(permanent)),
                            );
                        }
                        if let Some(binding) = toughness_binding {
                            stack_decisions.insert(
                                binding.to_string(),
                                Value::from(self.current_toughness(permanent)),
                            );
                        }
                    }
                }
                let stack_targets = Self::activated_effect_targets(&rule, &action.targets);
                let pending_activation = StackObject {
                    id: stack_id.clone(),
                    controller: action.player_id.clone(),
                    card: source.clone(),
                    cant_be_countered: false,
                    exile_on_leave_stack: false,
                    ability_kind: Some("activatedAbility".to_string()),
                    ability_rule: Some(rule.clone()),
                    decisions: stack_decisions,
                    targets: stack_targets.clone(),
                };
                let (committed_cost_payment, pending_activation) = self
                    .with_pending_activation_source(pending_activation, |engine| {
                        engine.commit_activated_cost_payment(&prepared_cost_payment)
                    })?;
                let pending_counter_cost_triggers = self.state.stack.split_off(cost_trigger_start);
                self.state.stack.push(pending_activation);
                self.apply_activated_exile_source_costs(action, &rule)?;
                self.apply_activated_exile_object_costs(action, &rule)?;
                self.apply_activated_discard_costs(action, &rule)?;
                self.apply_activated_return_costs(action, &rule)?;
                self.state.stack.extend(pending_counter_cost_triggers);
                self.publish_activated_cost_payment(committed_cost_payment);
                for source in tapped_sources {
                    self.enqueue_permanent_tapped_triggers(&source);
                }
                self.drain_linked_exile_returns(provider)?;
                self.record_event(
                    "activatedAbilityPutOnStack",
                    Some(action.player_id.clone()),
                    Some(source.instance_id.clone()),
                    json!({
                        "cardName": source.definition.name,
                        "objectKind": "activatedAbility",
                        "stackId": stack_id,
                        "loyalty": rule["costs"].as_array().is_some_and(|costs| {
                            costs.iter().any(|cost| value_kind(cost) == Some("payLoyalty"))
                        }),
                    }),
                );
                self.enqueue_nonmana_ability_activated_triggers(&action.player_id, &stack_id);
                if rule["costs"].as_array().is_some_and(|costs| {
                    costs
                        .iter()
                        .any(|cost| value_kind(cost) == Some("payWaterbend"))
                }) {
                    self.mark_bending_performed(
                        &action.player_id,
                        "waterbend",
                        Some(source.instance_id.clone()),
                    );
                }
                self.enqueue_targeting_triggers(&stack_id, &stack_targets)?;
                self.check_state_based_actions_with_provider(Some(provider))?;
            }
            _ => {
                return Err(EngineError::new(
                    "non-priority action passed to priority action executor",
                ));
            }
        }
        Ok(())
    }

    fn run_priority_window<P: DecisionProvider>(
        &mut self,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        let mut shortcut_provider = LoopShortcutDecisionProvider::new(provider);
        self.run_priority_window_with_shortcuts(&mut shortcut_provider)
    }

    fn run_priority_window_with_shortcuts<P: DecisionProvider>(
        &mut self,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        self.check_quantity_failure()?;
        let started = Instant::now();
        let mut priority_player = self.first_live_player_from(self.state.active_player);
        let mut consecutive_passes = 0;
        let mut nonpass_action_taken = false;
        let mut action_occurrences = BTreeMap::<String, usize>::new();
        let mut repeated_states = BTreeMap::<u64, usize>::new();
        let mut actions_chosen_by_state = BTreeMap::<(u64, String), BTreeSet<String>>::new();
        let mut loop_resource_history =
            BTreeMap::<(String, String), Vec<LoopResourceSnapshot>>::new();
        let mut loop_iteration_allowances = BTreeMap::<(String, String), usize>::new();
        let mut automatic_resolution_states = BTreeSet::<u64>::new();
        for action_number in 0..MAX_PRIORITY_ACTIONS {
            self.check_quantity_failure()?;
            if provider.is_cancelled() {
                return Err(EngineError::new("game session cancelled"));
            }
            if action_number > 0
                && action_number % 64 == 0
                && started.elapsed() >= Duration::from_secs(2)
            {
                eprintln!(
                    "[engine-loop] priority elapsedMs={} turn={} step={:?} action={} player={} passes={} stack={} events={}",
                    started.elapsed().as_millis(),
                    self.state.turn_number,
                    self.state.step,
                    action_number,
                    self.state.players[priority_player].id,
                    consecutive_passes,
                    self.state.stack.len(),
                    self.state.events.len(),
                );
            }
            if self.state.outcome.is_some() {
                return Ok(());
            }
            self.resolve_commander_zone_choices(provider)?;
            self.commit_pending_triggered_targets(provider)?;
            self.state.priority_player = Some(priority_player);
            let options = self.try_legal_priority_actions(priority_player)?;
            let player_id = self.state.players[priority_player].id.clone();
            let requires_explicit_pass = provider.requests_explicit_priority_pass(&player_id);
            let has_non_mana_action = options.iter().any(|action| {
                action.kind != ActionKind::PassPriority
                    && !action
                        .decisions
                        .get("manaAbility")
                        .and_then(Value::as_bool)
                        .unwrap_or(false)
            });
            let has_mana_action = options.iter().any(|action| {
                action
                    .decisions
                    .get("manaAbility")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
            });
            let should_prompt = has_non_mana_action
                || (requires_explicit_pass && (has_mana_action || nonpass_action_taken));
            let action = if !should_prompt {
                options
                    .iter()
                    .find(|action| action.kind == ActionKind::PassPriority)
                    .cloned()
                    .ok_or_else(|| EngineError::new("priority window has no pass action"))?
            } else {
                let request = EngineDecisionRequest {
                    id: format!(
                        "priority:{}:{}:{action_number}",
                        self.state.turn_number, priority_player
                    ),
                    kind: DecisionKind::Priority,
                    player_id: player_id.clone(),
                    source_card: None,
                    source_card_instance_id: None,
                    choice: None,
                    options,
                };
                if request.options.len() > 1 {
                    self.branching_decision_sequence
                        .set(self.branching_decision_sequence.get().saturating_add(1));
                }
                self.check_quantity_failure()?;
                let option_index = provider.choose(&self.state, &request)?;
                let selected = request.options.get(option_index).cloned().ok_or_else(|| {
                    EngineError::new(format!(
                        "decision provider selected invalid option {option_index} for {}",
                        request.id
                    ))
                })?;
                let fingerprint = self.priority_state_fingerprint();
                let loop_key = (fingerprint, player_id.clone());
                let seen = actions_chosen_by_state
                    .get(&loop_key)
                    .cloned()
                    .unwrap_or_default();
                let repetition_key = (player_id.clone(), selected.id.clone());
                let resource_snapshot = self.loop_resource_snapshot();
                let prior_action_occurrence = loop_resource_history.get(&repetition_key);
                let state_is_equal_or_greater = prior_action_occurrence.is_some_and(|history| {
                    history
                        .iter()
                        .any(|earlier| resource_snapshot.dominates(earlier))
                });
                let bounded_progress_loop = !state_is_equal_or_greater
                    && prior_action_occurrence.is_some()
                    && self.priority_action_has_renewable_cost(&selected);
                loop_resource_history
                    .entry(repetition_key.clone())
                    .or_default()
                    .push(resource_snapshot);
                // CR 732 applies when the sequence can return to a functionally
                // equivalent state, or to one that retains every previously
                // available resource. We also allow a bounded shortcut when the
                // repeated action itself has a renewable cost: its useful effects
                // may still change life totals, hands, or libraries. Every chosen
                // iteration is executed normally, so those finite effects can end
                // the sequence without being incorrectly treated as unbounded.
                let repeated_action = seen.contains(&selected.id)
                    || state_is_equal_or_greater
                    || bounded_progress_loop;
                let loop_kind = if bounded_progress_loop {
                    "boundedProgressLoop"
                } else {
                    "optionalStateLoop"
                };
                let repetition_allowed = if !repeated_action {
                    true
                } else if let Some(remaining) = loop_iteration_allowances.get_mut(&repetition_key) {
                    if *remaining == 0 {
                        false
                    } else {
                        *remaining -= 1;
                        true
                    }
                } else {
                    let repeat_count = self.choose_number(
                        provider,
                        format!(
                            "loop-iterations:{}:{}:{action_number}",
                            self.state.turn_number, priority_player
                        ),
                        player_id.clone(),
                        "loopIterations".to_string(),
                        0,
                        MAX_OPTIONAL_LOOP_ITERATIONS,
                        if bounded_progress_loop {
                            "Choose how many additional times to repeat this action".to_string()
                        } else {
                            "Choose how many additional times to repeat this non-depleting action"
                                .to_string()
                        },
                        selected.card_instance_id.clone(),
                    )?;
                    loop_iteration_allowances.insert(
                        repetition_key.clone(),
                        usize::try_from(repeat_count.saturating_sub(1)).unwrap_or(0),
                    );
                    self.record_event(
                        "loopIterationCountChosen",
                        Some(player_id.clone()),
                        selected.card_instance_id.clone(),
                        json!({
                            "actionId": selected.id,
                            "iterations": repeat_count,
                            "loopKind": loop_kind,
                            "stateNonDepleting": !bounded_progress_loop,
                            "iterationsAreExecuted": true,
                        }),
                    );
                    if repeat_count > 0 {
                        provider.begin_loop_shortcut(
                            &player_id,
                            &selected.id,
                            usize::try_from(repeat_count).unwrap_or(0),
                        );
                    }
                    repeat_count > 0
                };
                if repetition_allowed {
                    provider.begin_loop_iteration(&player_id, &selected.id);
                }
                let selected = if !repetition_allowed {
                    let mut alternatives = request
                        .options
                        .iter()
                        .filter(|candidate| {
                            candidate.kind != ActionKind::PassPriority
                                && candidate.id != selected.id
                                && !seen.contains(&candidate.id)
                        })
                        .cloned()
                        .collect::<Vec<_>>();
                    alternatives.shuffle(&mut self.rng);
                    let replacement = alternatives.into_iter().next().or_else(|| {
                        request
                            .options
                            .iter()
                            .find(|candidate| candidate.kind == ActionKind::PassPriority)
                            .cloned()
                    });
                    if let Some(replacement) = replacement {
                        self.record_event(
                            "decisionLoopAvoided",
                            Some(player_id.clone()),
                            selected.card_instance_id.clone(),
                            json!({
                                "decisionKind": "priority",
                                "repeatedActionId": selected.id,
                                "replacementActionId": replacement.id,
                                "loopKind": loop_kind,
                            }),
                        );
                        replacement
                    } else {
                        selected
                    }
                } else {
                    selected
                };
                actions_chosen_by_state
                    .entry(loop_key)
                    .or_default()
                    .insert(selected.id.clone());
                selected
            };

            if action.kind == ActionKind::PassPriority {
                consecutive_passes += 1;
                self.record_event("priorityPassed", Some(action.player_id), None, json!({}));
                if consecutive_passes == self.live_player_count() {
                    if self.state.stack.is_empty() {
                        self.state.priority_player = None;
                        return Ok(());
                    }
                    let branching_before = self.branching_decision_sequence.get();
                    automatic_resolution_states.insert(self.loop_state_fingerprint());
                    self.resolve_top_stack(provider)?;
                    if self.branching_decision_sequence.get() != branching_before {
                        automatic_resolution_states.clear();
                    } else if !automatic_resolution_states.insert(self.loop_state_fingerprint()) {
                        self.end_game_as_draw(GameEndReason::MandatoryLoop);
                        return Ok(());
                    }
                    consecutive_passes = 0;
                    priority_player = self.first_live_player_from(self.state.active_player);
                } else {
                    priority_player = self.next_live_player_index(priority_player);
                }
                continue;
            }

            self.apply_checked_priority_action(&action, provider)?;
            automatic_resolution_states.clear();
            let action_count = action_occurrences.entry(action.id.clone()).or_default();
            *action_count += 1;
            if *action_count >= 2 {
                let fingerprint = self.priority_state_fingerprint();
                let occurrences = repeated_states.entry(fingerprint).or_default();
                *occurrences += 1;
                if *occurrences >= MAX_REPEATED_PRIORITY_STATES {
                    self.record_event(
                        "priorityLoopTerminated",
                        Some(action.player_id.clone()),
                        action.card_instance_id.clone(),
                        json!({
                            "actionId": action.id,
                            "reason": "repeatedState",
                        }),
                    );
                    consecutive_passes = 1;
                    priority_player = self.next_live_player_index(priority_player);
                    continue;
                }
            }
            consecutive_passes = 0;
            nonpass_action_taken = true;
            priority_player = self.first_live_player_from(priority_player);
        }
        self.force_end_turn = true;
        self.state.priority_player = None;
        self.record_event(
            "decisionLoopTurnEndRequested",
            self.state
                .players
                .get(priority_player)
                .map(|player| player.id.clone()),
            None,
            json!({
                "elapsedMs": started.elapsed().as_millis(),
                "reason": "priorityActionSafetyLimit",
            }),
        );
        Ok(())
    }

    fn priority_state_fingerprint(&self) -> u64 {
        self.state_fingerprint(true)
    }

    fn loop_state_fingerprint(&self) -> u64 {
        self.state_fingerprint(false)
    }

    fn priority_action_has_renewable_cost(&self, action: &LegalAction) -> bool {
        if action.kind != ActionKind::CastSpell
            || action
                .decisions
                .get("castSourceZone")
                .and_then(Value::as_str)
                != Some("hand")
            || !action.payment_sources.is_empty()
            || action
                .decisions
                .get("manaPayment")
                .and_then(Value::as_array)
                .is_some_and(|payments| !payments.is_empty())
            || action
                .decisions
                .get("manaPoolPayment")
                .and_then(Value::as_array)
                .is_some_and(|payments| !payments.is_empty())
            || action
                .decisions
                .get("castingLifePayment")
                .and_then(Value::as_i64)
                .is_some_and(|amount| amount > 0)
            || action
                .decisions
                .get("useAlternativePlayerCounterCost")
                .and_then(Value::as_bool)
                .unwrap_or(false)
            || action.decisions.contains_key("staticCastingSacrifice")
            || action.decisions.contains_key("staticCastingCounterRemoval")
            || action
                .decisions
                .get("delveCards")
                .and_then(Value::as_array)
                .is_some_and(|cards| !cards.is_empty())
            || action
                .decisions
                .get("historicExileCost")
                .and_then(Value::as_array)
                .is_some_and(|cards| !cards.is_empty())
        {
            return false;
        }

        let Some(card) = action
            .card_instance_id
            .as_deref()
            .and_then(|instance_id| self.card_outside_battlefield(instance_id))
            .map(|card| &card.definition)
        else {
            return false;
        };

        self.casting_sacrifice_cost_targets(card, &action.player_id, &action.decisions)
            .is_empty()
            && self
                .casting_discard_cost_targets(card, &action.player_id, &action.decisions)
                .is_empty()
            && self
                .casting_put_counter_costs(card, &action.player_id, &action.decisions)
                .is_empty()
            && Self::escalate_cost_target_ids(card, &action.decisions).is_empty()
            && self.splice_cost_target_ids(action).is_empty()
    }

    fn loop_resource_snapshot(&self) -> LoopResourceSnapshot {
        fn add_resource(resources: &mut BTreeMap<String, i64>, key: String, amount: i64) {
            *resources.entry(key).or_default() += amount;
        }

        fn card_group_key(zone: &str, card: &CardInstance) -> String {
            // Equivalent objects are grouped by characteristics and status. A
            // per-object incarnation marker is identity, not a resource, so
            // it must not make otherwise identical loop states distinct.
            let flags = card
                .flags
                .iter()
                .filter(|(flag, _)| !flag.starts_with(zone_change_triggers::TRACKED_ZONE_PREFIX))
                .collect::<BTreeMap<_, _>>();
            format!(
                "{zone}|{}|{}|{}|{}|{}|{}",
                card.definition.id,
                card.definition.name,
                card.definition.type_line,
                card.owner,
                card.controller,
                serde_json::to_string(&flags).unwrap_or_default(),
            )
        }

        let mut context = DefaultHasher::new();
        self.state.turn_number.hash(&mut context);
        self.state.active_player.hash(&mut context);
        format!("{:?}", self.state.status).hash(&mut context);
        format!("{:?}", self.state.step).hash(&mut context);
        serde_json::to_string(&self.state.combat)
            .unwrap_or_default()
            .hash(&mut context);
        serde_json::to_string(&self.state.permissions)
            .unwrap_or_default()
            .hash(&mut context);
        serde_json::to_string(&self.state.rule_modifiers)
            .unwrap_or_default()
            .hash(&mut context);
        serde_json::to_string(&self.state.outcome)
            .unwrap_or_default()
            .hash(&mut context);

        let mut resources = BTreeMap::new();
        for player in &self.state.players {
            player.id.hash(&mut context);
            player.has_lost.hash(&mut context);
            player.max_hand_size.hash(&mut context);
            player
                .library
                .iter()
                .map(|card| card.definition.id.as_str())
                .collect::<Vec<_>>()
                .hash(&mut context);

            resources.insert(format!("player|{}|life", player.id), i64::from(player.life));
            resources.insert(
                format!("player|{}|landPlays", player.id),
                i64::from(player.land_plays_remaining),
            );
            for (counter, count) in &player.counters {
                resources.insert(
                    format!("player|{}|counter|{counter}", player.id),
                    i64::from(*count),
                );
            }
            for mana in &player.mana_pool {
                add_resource(
                    &mut resources,
                    format!(
                        "player|{}|mana|{}|{}",
                        player.id,
                        mana.symbol,
                        mana.spend_restriction
                            .as_ref()
                            .map(Value::to_string)
                            .unwrap_or_default(),
                    ),
                    1,
                );
            }
            for damage in &player.commander_damage {
                resources.insert(
                    format!(
                        "player|{}|commanderDamage|{}|{}",
                        player.id, damage.commander_id, damage.owner_id
                    ),
                    -i64::from(damage.amount),
                );
            }
            for (zone_name, zone) in [
                ("library", &player.library),
                ("hand", &player.hand),
                ("graveyard", &player.graveyard),
                ("exile", &player.exile),
                ("sideboard", &player.sideboard),
                ("command", &player.command_zone),
            ] {
                for card in zone {
                    add_resource(
                        &mut resources,
                        card_group_key(&format!("player|{}|{zone_name}", player.id), card),
                        1,
                    );
                }
            }
            for card in &player.battlefield {
                let base = format!(
                    "{}|tapped:{}|sick:{}|attached:{}|protected:{}",
                    card_group_key(&format!("player|{}|battlefield", player.id), card),
                    card.tapped,
                    card.summoning_sick,
                    card.attached_to.is_some(),
                    card.battle_protector.is_some(),
                );
                add_resource(&mut resources, format!("{base}|count"), 1);
                add_resource(
                    &mut resources,
                    format!("{base}|damageCapacity"),
                    -i64::from(card.damage_marked),
                );
                add_resource(
                    &mut resources,
                    format!("{base}|powerModifier"),
                    i64::from(card.power_modifier),
                );
                add_resource(
                    &mut resources,
                    format!("{base}|toughnessModifier"),
                    i64::from(card.toughness_modifier),
                );
                for (counter, count) in &card.counters {
                    add_resource(
                        &mut resources,
                        format!("{base}|counter|{counter}"),
                        i64::from(*count),
                    );
                }
            }
        }
        for commander in &self.state.commanders {
            commander.card_instance_id.hash(&mut context);
            commander.owner_id.hash(&mut context);
            resources.insert(
                format!("commander|{}|castCapacity", commander.card_instance_id),
                -i64::from(commander.casts_from_command_zone),
            );
        }
        for object in &self.state.stack {
            add_resource(
                &mut resources,
                format!(
                    "stack|{}|{}|{}|{}|{}",
                    object.controller,
                    object.card.definition.id,
                    object.ability_kind.as_deref().unwrap_or_default(),
                    object
                        .ability_rule
                        .as_ref()
                        .map(Value::to_string)
                        .unwrap_or_default(),
                    serde_json::to_string(&object.decisions).unwrap_or_default(),
                ),
                1,
            );
        }

        LoopResourceSnapshot {
            context_fingerprint: context.finish(),
            resources,
        }
    }

    fn state_fingerprint(&self, include_stack_ids: bool) -> u64 {
        let mut hasher = DefaultHasher::new();
        self.state.turn_number.hash(&mut hasher);
        self.state.active_player.hash(&mut hasher);
        format!("{:?}", self.state.status).hash(&mut hasher);
        format!("{:?}", self.state.step).hash(&mut hasher);
        for player in &self.state.players {
            player.id.hash(&mut hasher);
            player.life.hash(&mut hasher);
            player.has_lost.hash(&mut hasher);
            player.land_plays_remaining.hash(&mut hasher);
            player.max_hand_size.hash(&mut hasher);
            for zone in [
                &player.library,
                &player.hand,
                &player.graveyard,
                &player.exile,
                &player.sideboard,
                &player.command_zone,
            ] {
                zone.len().hash(&mut hasher);
                for card in zone {
                    card.instance_id.hash(&mut hasher);
                    card.flags.iter().for_each(|entry| entry.hash(&mut hasher));
                }
            }
            for card in &player.battlefield {
                card.instance_id.hash(&mut hasher);
                card.controller.hash(&mut hasher);
                card.tapped.hash(&mut hasher);
                card.summoning_sick.hash(&mut hasher);
                card.damage_marked.hash(&mut hasher);
                card.power_modifier.hash(&mut hasher);
                card.toughness_modifier.hash(&mut hasher);
                card.counters
                    .iter()
                    .for_each(|entry| entry.hash(&mut hasher));
                card.flags.iter().for_each(|entry| entry.hash(&mut hasher));
                card.battle_protector.hash(&mut hasher);
                card.attached_to.hash(&mut hasher);
                card.definition.name.hash(&mut hasher);
                card.definition.type_line.hash(&mut hasher);
                card.definition.power.hash(&mut hasher);
                card.definition.toughness.hash(&mut hasher);
            }
            for damage in &player.commander_damage {
                damage.commander_id.hash(&mut hasher);
                damage.owner_id.hash(&mut hasher);
                damage.controller_id.hash(&mut hasher);
                damage.amount.hash(&mut hasher);
            }
            for mana in &player.mana_pool {
                mana.symbol.hash(&mut hasher);
                mana.spend_restriction
                    .as_ref()
                    .map(Value::to_string)
                    .hash(&mut hasher);
            }
            player
                .counters
                .iter()
                .for_each(|entry| entry.hash(&mut hasher));
        }
        for commander in &self.state.commanders {
            commander.card_instance_id.hash(&mut hasher);
            commander.owner_id.hash(&mut hasher);
            commander.casts_from_command_zone.hash(&mut hasher);
        }
        for object in &self.state.stack {
            if include_stack_ids {
                object.id.hash(&mut hasher);
            }
            object.controller.hash(&mut hasher);
            object.card.instance_id.hash(&mut hasher);
            object.cant_be_countered.hash(&mut hasher);
            object.exile_on_leave_stack.hash(&mut hasher);
            object.ability_kind.hash(&mut hasher);
            object
                .ability_rule
                .as_ref()
                .map(Value::to_string)
                .hash(&mut hasher);
            object
                .decisions
                .iter()
                .for_each(|(key, value)| (key, value.to_string()).hash(&mut hasher));
            format!("{:?}", object.targets).hash(&mut hasher);
        }
        format!("{:?}", self.state.combat).hash(&mut hasher);
        serde_json::to_string(&self.state.permissions)
            .unwrap_or_default()
            .hash(&mut hasher);
        serde_json::to_string(&self.state.rule_modifiers)
            .unwrap_or_default()
            .hash(&mut hasher);
        serde_json::to_string(&self.state.outcome)
            .unwrap_or_default()
            .hash(&mut hasher);
        hasher.finish()
    }

    fn end_game_as_draw(&mut self, reason: GameEndReason) {
        if self.state.outcome.is_some() {
            return;
        }
        self.record_event("gameDraw", None, None, json!({ "reason": reason }));
        self.state.status = GameStatus::Completed;
        self.state.priority_player = None;
        self.state.outcome = Some(GameOutcome {
            winner: None,
            losers: Vec::new(),
            reason,
            turn_number: self.state.turn_number,
        });
    }

    fn ensure_prepared_spell_copy(&mut self, source_id: &str) -> Result<(), EngineError> {
        let Some((controller_index, card_index)) = self.permanent_position(source_id) else {
            return Ok(());
        };
        let source = self.state.players[controller_index].battlefield[card_index].clone();
        if !source.flags.get("prepared").copied().unwrap_or(false)
            || source.flags.get("phasedOut").copied().unwrap_or(false)
            || self.state.permissions.iter().any(|permission| {
                value_kind(permission) == Some("preparedSpellPermission")
                    && permission["sourceCardInstanceId"].as_str() == Some(source_id)
            })
        {
            return Ok(());
        }
        let Some(spell_definition) = prepared_spell_definition(&source.definition) else {
            return Ok(());
        };
        self.copy_sequence += 1;
        let copy_id = format!(
            "copy:prepared:{}:{}",
            source.instance_id, self.copy_sequence
        );
        let mut flags = BTreeMap::new();
        flags.insert("isSpellCopy".to_string(), true);
        let mut copy = CardInstance {
            instance_id: copy_id.clone(),
            definition: spell_definition,
            printed_definition: None,
            owner: source.controller.clone(),
            controller: source.controller.clone(),
            tapped: false,
            summoning_sick: false,
            damage_marked: 0,
            power_modifier: 0,
            toughness_modifier: 0,
            counters: BTreeMap::new(),
            flags,
            battle_protector: None,
            attached_to: None,
        };
        self.admit_new_card_carrier(&mut copy)?;
        self.state.players[controller_index].exile.push(copy);
        let permission = json!({
            "kind": "preparedSpellPermission",
            "action": "cast",
            "cardInstanceId": copy_id,
            "normalCostsApply": true,
            "normalTimingApplies": true,
            "playerId": source.controller,
            "sourceCardInstanceId": source.instance_id,
        });
        self.state.permissions.push(permission.clone());
        self.record_event(
            "preparedSpellCopyCreated",
            Some(source.controller),
            Some(copy_id),
            permission,
        );
        Ok(())
    }

    fn phase_out_permanent(&mut self, instance_id: &str) {
        let Some((player_index, card_index)) = self.permanent_position(instance_id) else {
            return;
        };
        if self.state.players[player_index].battlefield[card_index]
            .flags
            .get("phasedOut")
            .copied()
            .unwrap_or(false)
        {
            return;
        }
        self.remove_prepared_spell_copy(instance_id);
        let controller = self.state.players[player_index].battlefield[card_index]
            .controller
            .clone();
        self.state.players[player_index].battlefield[card_index]
            .flags
            .insert("phasedOut".to_string(), true);
        self.record_event(
            "permanentPhasedOut",
            Some(controller),
            Some(instance_id.to_string()),
            json!({}),
        );
    }

    fn remove_prepared_spell_copy(&mut self, source_id: &str) {
        let copy_ids = self
            .state
            .permissions
            .iter()
            .filter(|permission| {
                value_kind(permission) == Some("preparedSpellPermission")
                    && permission["sourceCardInstanceId"].as_str() == Some(source_id)
            })
            .filter_map(|permission| permission["cardInstanceId"].as_str().map(ToOwned::to_owned))
            .collect::<BTreeSet<_>>();
        self.state.permissions.retain(|permission| {
            value_kind(permission) != Some("preparedSpellPermission")
                || permission["sourceCardInstanceId"].as_str() != Some(source_id)
        });
        let mut removed = Vec::new();
        for player in &mut self.state.players {
            let mut card_index = 0;
            while card_index < player.exile.len() {
                if copy_ids.contains(&player.exile[card_index].instance_id) {
                    let copy = player.exile.remove(card_index);
                    removed.push((player.id.clone(), copy.controller, copy.instance_id));
                } else {
                    card_index += 1;
                }
            }
        }
        for (owner, controller, copy_id) in removed {
            self.record_event(
                "spellCopyCeasedToExist",
                Some(owner),
                Some(copy_id),
                json!({
                    "lastKnownController": controller,
                    "sourceCardInstanceId": source_id,
                    "zone": "exile",
                }),
            );
        }
    }

    fn set_permanent_prepared(
        &mut self,
        source_id: &str,
        prepared: bool,
    ) -> Result<(), EngineError> {
        let Some((controller_index, card_index)) = self.permanent_position(source_id) else {
            return Ok(());
        };
        let was_prepared = self.state.players[controller_index].battlefield[card_index]
            .flags
            .get("prepared")
            .copied()
            .unwrap_or(false);
        if was_prepared == prepared {
            return Ok(());
        }
        let controller = self.state.players[controller_index].battlefield[card_index]
            .controller
            .clone();
        self.state.players[controller_index].battlefield[card_index]
            .flags
            .insert("prepared".to_string(), prepared);
        if prepared {
            self.ensure_prepared_spell_copy(source_id)?;
        } else {
            self.remove_prepared_spell_copy(source_id);
        }
        self.record_event(
            if prepared {
                "permanentPrepared"
            } else {
                "permanentUnprepared"
            },
            Some(controller),
            Some(source_id.to_string()),
            json!({}),
        );
        Ok(())
    }

    fn apply_replacement_operations(
        &mut self,
        card: &mut CardInstance,
        operations: &Value,
        decisions: &BTreeMap<String, Value>,
    ) -> Result<(), EngineError> {
        for operation in operations.as_array().into_iter().flatten() {
            match value_kind(operation) {
                Some("setEnteringState") => {
                    card.tapped = operation["tapped"].as_bool().unwrap_or(false);
                }
                Some("setEnteringFlag") => {
                    if let Some(flag) = operation["flag"].as_str() {
                        card.flags.insert(flag.to_string(), true);
                    }
                }
                Some("setBasicLandType") => {
                    let decision_id = operation["decisionId"].as_str().unwrap_or("basicLandType");
                    let chosen_type = decisions
                        .get(decision_id)
                        .and_then(Value::as_str)
                        .ok_or_else(|| EngineError::new("basic land type choice is missing"))?;
                    let card_types = card
                        .definition
                        .type_line
                        .split(" - ")
                        .next()
                        .unwrap_or("Land");
                    card.definition.type_line = format!("{card_types} - {chosen_type}");
                }
                Some("setPrepared") => {
                    card.flags.insert(
                        "prepared".to_string(),
                        operation["value"].as_bool().unwrap_or(true),
                    );
                }
                Some("putEnteringCounters") => {
                    let counter = operation["counter"]
                        .as_str()
                        .unwrap_or_default()
                        .to_string();
                    let count = integer_value(&operation["count"])
                        .or_else(|| {
                            (value_kind(&operation["count"]) == Some("decisionResult"))
                                .then(|| {
                                    operation["count"]["decisionId"]
                                        .as_str()
                                        .and_then(|decision_id| decisions.get(decision_id))
                                        .and_then(Value::as_i64)
                                        .and_then(|value| i32::try_from(value).ok())
                                })
                                .flatten()
                        })
                        .or_else(|| {
                            self.numeric_expression_with_source_and_decisions(
                                &operation["count"],
                                &card.controller,
                                Some(card),
                                decisions,
                            )
                        })
                        .unwrap_or(0)
                        .max(0);
                    let count = count;
                    if !counter.is_empty() && count > 0 {
                        *card.counters.entry(counter).or_default() += count;
                    }
                }
                Some("storeDecision") => {
                    let decision_id = operation["decisionId"]
                        .as_str()
                        .unwrap_or("chosenCreatureType");
                    let chosen_value = decisions
                        .get(decision_id)
                        .and_then(|value| {
                            value.as_str().or_else(|| {
                                value
                                    .as_array()
                                    .and_then(|values| values.first())
                                    .and_then(Value::as_str)
                            })
                        })
                        .ok_or_else(|| EngineError::new("stored replacement choice is missing"))?
                        .to_string();
                    card.definition.printed_rules_mut().retain(|rule| {
                        value_kind(rule) != Some("storedDecisionValue")
                            || rule["decisionId"].as_str() != Some(decision_id)
                    });
                    card.definition.printed_rules_mut().push(json!({
                        "kind": "storedDecisionValue",
                        "decisionId": decision_id,
                        "value": chosen_value,
                    }));
                    let gains_chosen_subtype =
                        card.definition.printed_rules().iter().any(|rule| {
                            value_kind(rule) == Some("staticAbility")
                                && rule["modifiers"].as_array().into_iter().flatten().any(
                                    |modifier| value_kind(modifier) == Some("addChosenSubtype"),
                                )
                        });
                    if gains_chosen_subtype
                        && !type_line_contains(&card.definition.type_line, &chosen_value)
                    {
                        if card.definition.type_line.contains(" - ") {
                            card.definition.type_line =
                                format!("{} {chosen_value}", card.definition.type_line);
                        } else {
                            card.definition.type_line =
                                format!("{} - {chosen_value}", card.definition.type_line);
                        }
                    }
                }
                Some("discardChosenCardOrReplaceEntry") => {
                    let decision_id = operation["decisionId"].as_str().unwrap_or("entryDiscard");
                    let selected = decisions
                        .get(decision_id)
                        .and_then(Value::as_array)
                        .and_then(|cards| cards.first())
                        .and_then(Value::as_str)
                        .map(ToOwned::to_owned);
                    if let Some(instance_id) = selected {
                        let player_index = self.player_index(&card.controller)?;
                        if let Some(card_index) = self.state.players[player_index]
                            .hand
                            .iter()
                            .position(|candidate| candidate.instance_id == instance_id)
                        {
                            let (discarded, graveyard_destination) = self
                                .take_zone_card_for_graveyard(player_index, "hand", card_index)?;
                            self.put_owned_card_into_prepared_graveyard(
                                player_index,
                                discarded,
                                graveyard_destination,
                            )?;
                            self.record_event(
                                "cardDiscarded",
                                Some(card.controller.clone()),
                                Some(instance_id),
                                json!({ "reason": "entryReplacement" }),
                            );
                            self.enqueue_card_discarded_triggers(&card.controller);
                        } else {
                            card.flags.insert("enterGraveyardInstead".to_string(), true);
                        }
                    } else {
                        card.flags.insert("enterGraveyardInstead".to_string(), true);
                    }
                }
                Some("putEnteringCountersForChosenType") => {
                    let decision_id = operation["decisionId"]
                        .as_str()
                        .unwrap_or("chosenCreatureType");
                    let chosen_type = decisions
                        .get(decision_id)
                        .and_then(Value::as_str)
                        .unwrap_or_default();
                    let count = self
                        .state
                        .players
                        .iter()
                        .flat_map(|player| player.battlefield.iter())
                        .filter(|permanent| {
                            permanent.controller == card.controller
                                && self.permanent_is_creature(permanent)
                                && (self.permanent_has_changeling(permanent)
                                    || type_line_contains(
                                        &permanent.definition.type_line,
                                        chosen_type,
                                    ))
                        })
                        .count() as i32;
                    let counter = operation["counter"].as_str().unwrap_or("fellowship");
                    let count = count;
                    if count > 0 {
                        *card.counters.entry(counter.to_string()).or_default() += count;
                    }
                }
                Some("applyRiotChoice") => {
                    let decision_id = operation["decisionId"].as_str().unwrap_or("riotChoice");
                    self.apply_riot_entry_choice(card, decisions.get(decision_id))?;
                }
                Some("copyEnteringGraveyardCard") => {
                    let decision_id = operation["decisionId"]
                        .as_str()
                        .unwrap_or("graveyardEntryCopy");
                    let Some(instance_id) = decisions
                        .get(decision_id)
                        .and_then(Value::as_array)
                        .and_then(|values| values.first())
                        .and_then(Value::as_str)
                        .map(ToOwned::to_owned)
                    else {
                        continue;
                    };
                    let Some((graveyard_index, card_index)) = self
                        .state
                        .players
                        .iter()
                        .enumerate()
                        .find_map(|(player_index, player)| {
                            player
                                .graveyard
                                .iter()
                                .position(|candidate| candidate.instance_id == instance_id)
                                .map(|card_index| (player_index, card_index))
                        })
                    else {
                        continue;
                    };
                    let copied_card =
                        self.state.players[graveyard_index].graveyard[card_index].clone();
                    card.printed_definition = Some(card.definition.clone());
                    card.definition = Self::copiable_values(&copied_card);
                    card.definition.name = operation["name"]
                        .as_str()
                        .unwrap_or(&card.definition.name)
                        .to_string();
                    if operation.get("basePower").is_some()
                        || operation.get("baseToughness").is_some()
                    {
                        Self::remove_copied_power_toughness_definitions(&mut card.definition);
                    }
                    card.definition.power =
                        integer_value(&operation["basePower"]).map(|value| value.to_string());
                    card.definition.toughness =
                        integer_value(&operation["baseToughness"]).map(|value| value.to_string());
                    let added_types = operation["addTypes"]
                        .as_array()
                        .into_iter()
                        .flatten()
                        .filter_map(Value::as_str)
                        .filter(|card_type| {
                            !type_line_contains(&card.definition.type_line, card_type)
                        })
                        .collect::<Vec<_>>();
                    if !added_types.is_empty() {
                        let separator = if card.definition.type_line.contains(" - ") {
                            " "
                        } else {
                            " - "
                        };
                        card.definition.type_line = format!(
                            "{}{separator}{}",
                            card.definition.type_line,
                            added_types.join(" ")
                        );
                    }
                    if operation["exileChosenCard"].as_bool() == Some(true) {
                        let graveyard_owner_id = self.state.players[graveyard_index].id.clone();
                        let mut exiled = self.take_zone_card_for_movement(
                            graveyard_index,
                            "graveyard",
                            card_index,
                        )?;
                        exiled.flags.remove("faceDown");
                        let owner_id = exiled.owner.clone();
                        let owner_index = self.player_index(&owner_id)?;
                        self.put_owned_card_into_exile(owner_index, exiled)?;
                        self.enqueue_cards_left_graveyard_triggers(
                            &graveyard_owner_id,
                            std::slice::from_ref(&instance_id),
                        );
                        self.record_event(
                            "cardExiled",
                            Some(card.controller.clone()),
                            Some(instance_id),
                            json!({ "reason": "entryCopyReflexiveTrigger" }),
                        );
                    }
                }
                Some("copyEnteringPermanent") => {
                    let decision_id = operation["decisionId"].as_str().unwrap_or("entryCopy");
                    let Some(instance_id) = decisions
                        .get(decision_id)
                        .and_then(Value::as_array)
                        .and_then(|values| values.first())
                        .and_then(Value::as_str)
                    else {
                        continue;
                    };
                    let Some((player_index, card_index)) = self.permanent_position(instance_id)
                    else {
                        continue;
                    };
                    let copied = self.state.players[player_index].battlefield[card_index].clone();
                    card.printed_definition = Some(card.definition.clone());
                    card.definition = Self::copiable_values(&copied);
                    if operation["removeLegendary"].as_bool() == Some(true) {
                        card.definition.type_line = card
                            .definition
                            .type_line
                            .strip_prefix("Legendary ")
                            .unwrap_or(&card.definition.type_line)
                            .to_string();
                    }
                    if operation["copyCounters"].as_bool() == Some(true) {
                        for (counter, amount) in copied.counters {
                            *card.counters.entry(counter).or_default() += amount;
                        }
                    }
                    for keyword in operation["grantKeywords"]
                        .as_array()
                        .into_iter()
                        .flatten()
                        .filter_map(Value::as_str)
                    {
                        card.definition.printed_rules_mut().push(json!({
                            "kind": "keywordAbility",
                            "source": { "kind": "self" },
                            "ability": { "kind": keyword },
                        }));
                    }
                    card.tapped = operation["tapped"].as_bool().unwrap_or(false);
                }
                Some("copyEnteringEquipment") => {
                    if let Some(definition) = self
                        .state
                        .players
                        .iter()
                        .flat_map(|player| player.battlefield.iter())
                        .find(|permanent| {
                            permanent.instance_id != card.instance_id
                                && type_line_contains(&permanent.definition.type_line, "Equipment")
                        })
                        .map(Self::copiable_values)
                    {
                        card.printed_definition = Some(card.definition.clone());
                        card.definition = definition;
                        card.definition.is_token = false;
                        card.flags.insert("copiedEquipment".to_string(), true);
                    }
                }
                Some("conditional") => {
                    let branch = if self.condition_value(
                        &operation["condition"],
                        &card.controller,
                        decisions,
                    ) {
                        &operation["then"]
                    } else {
                        &operation["else"]
                    };
                    self.apply_replacement_operations(card, branch, decisions)?;
                }
                _ => {
                    return Err(EngineError::new(format!(
                        "unsupported replacement operation reached execution: {}",
                        value_kind(operation).unwrap_or("missingKind")
                    )));
                }
            }
        }
        Ok(())
    }

    fn apply_enter_replacements<P: DecisionProvider>(
        &mut self,
        card: &mut CardInstance,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        self.apply_enter_replacements_with_decisions(card, provider, &BTreeMap::new())
    }

    fn apply_outer_enter_replacements_with_decisions<P: DecisionProvider>(
        &mut self,
        card: &mut CardInstance,
        provider: &mut P,
        initial_decisions: &BTreeMap<String, Value>,
    ) -> Result<(), EngineError> {
        let prepared_initial_decisions = nominal_choices::prepare_entry_creature_type_bindings(
            &card.definition,
            initial_decisions,
        )?;
        let initial_decisions = prepared_initial_decisions.as_ref();
        let entering_counter_modifiers = self
            .battlefield_static_modifiers()
            .into_iter()
            .filter(|(source, modifier)| {
                value_kind(modifier) == Some("addEnteringCounters")
                    && matches_card_filter(&card.definition, &modifier["objects"]["where"])
                    && self.event_player_reference_matches(
                        &modifier["objects"]["controller"],
                        source,
                        &card.controller,
                    )
                    && (!modifier["objects"]["excludeSource"]
                        .as_bool()
                        .unwrap_or(false)
                        || source.instance_id != card.instance_id)
            })
            .map(|(source, modifier)| (source.clone(), modifier.clone()))
            .collect::<Vec<_>>();
        for (source, modifier) in entering_counter_modifiers {
            let counter = modifier["counter"].as_str().unwrap_or_default();
            let count = self
                .numeric_expression_with_source_and_decisions(
                    &modifier["count"],
                    &source.controller,
                    Some(&source),
                    initial_decisions,
                )
                .unwrap_or(0)
                .max(0);
            let count = count;
            if !counter.is_empty() && count > 0 {
                *card.counters.entry(counter.to_string()).or_default() += count;
            }
        }
        let venser_counter_count = self
            .battlefield_static_modifiers()
            .iter()
            .filter(|(source, modifier)| {
                value_kind(modifier) == Some("venserAdditionalEnteringCounters")
                    && source.controller == card.controller
                    && is_creature(&card.definition)
                    && !card.definition.is_token
                    && !card.flags.get("wasCastFromHand").copied().unwrap_or(false)
            })
            .filter_map(|(_, modifier)| integer_value(&modifier["count"]))
            .sum::<i32>();
        let venser_counter_count = venser_counter_count;
        if venser_counter_count > 0 {
            *card.counters.entry("+1/+1".to_string()).or_default() += venser_counter_count;
        }
        if self
            .battlefield_static_modifiers()
            .iter()
            .any(|(source, modifier)| {
                value_kind(modifier) == Some("permanentsEnterTapped")
                    && matches_card_filter(&card.definition, &modifier["objects"]["where"])
                    && self.event_player_reference_matches(
                        &modifier["objects"]["controller"],
                        source,
                        &card.controller,
                    )
            })
        {
            card.tapped = true;
        }
        if is_land(&card.definition)
            && !card.definition.type_line.starts_with("Basic ")
            && self
                .battlefield_static_modifiers()
                .iter()
                .any(|(_, modifier)| value_kind(modifier) == Some("nonbasicLandsEnterTapped"))
        {
            card.tapped = true;
        }
        let replacement_rules = card
            .definition
            .printed_rules()
            .iter()
            .filter(|rule| replacement_rule_supported(rule))
            .cloned()
            .collect::<Vec<_>>();
        for rule in replacement_rules {
            let mut decisions = initial_decisions.clone();
            for decision in rule["decisions"].as_array().into_iter().flatten() {
                let decision_id = decision["id"].as_str().unwrap_or("replacementChoice");
                if decisions.contains_key(decision_id) {
                    continue;
                }
                if value_kind(decision) == Some("chooseBehold") {
                    let player_index = self.player_index(&card.controller)?;
                    let candidates = self.state.players[player_index]
                        .battlefield
                        .iter()
                        .chain(self.state.players[player_index].hand.iter())
                        .filter(|candidate| {
                            matches_card_filter(&candidate.definition, &decision["where"])
                        })
                        .map(|candidate| candidate.instance_id.clone())
                        .collect::<Vec<_>>();
                    let options = std::iter::once(None)
                        .chain(candidates.into_iter().map(Some))
                        .enumerate()
                        .map(|(index, instance_id)| LegalAction {
                            id: format!("choose:{decision_id}:{index}"),
                            kind: if instance_id.is_some() {
                                ActionKind::ChooseResolution
                            } else {
                                ActionKind::DeclinePayment
                            },
                            player_id: card.controller.clone(),
                            label: instance_id
                                .as_ref()
                                .map(|id| format!("Behold {}", self.card_name_for_instance(id)))
                                .unwrap_or_else(|| "Decline to behold".to_string()),
                            card_instance_id: instance_id.clone(),
                            payment_sources: Vec::new(),
                            decisions: BTreeMap::from([(
                                decision_id.to_string(),
                                Value::Array(instance_id.into_iter().map(Value::String).collect()),
                            )]),
                            targets: BTreeMap::new(),
                            target_order: Vec::new(),
                            attacker_id: None,
                            blocker_id: None,
                        })
                        .collect::<Vec<_>>();
                    let choice = self.choose_action(
                        provider,
                        EngineDecisionRequest {
                            id: format!("replacement:{}:{decision_id}", card.instance_id),
                            kind: DecisionKind::ReplacementChoice,
                            player_id: card.controller.clone(),
                            source_card: Some(card.clone()),
                            source_card_instance_id: Some(card.instance_id.clone()),
                            choice: None,
                            options,
                        },
                    )?;
                    let selected = choice
                        .decisions
                        .get(decision_id)
                        .and_then(Value::as_array)
                        .cloned()
                        .unwrap_or_default();
                    decisions.insert(decision_id.to_string(), Value::Array(selected));
                    continue;
                }
                if matches!(
                    value_kind(decision),
                    Some("chooseCardForReplacement" | "chooseRevealCard")
                ) {
                    let reveal = value_kind(decision) == Some("chooseRevealCard");
                    let player_index = self.player_index(&card.controller)?;
                    let candidates = self.state.players[player_index]
                        .hand
                        .iter()
                        .filter(|candidate| {
                            matches_card_filter(&candidate.definition, &decision["where"])
                        })
                        .map(|candidate| candidate.instance_id.clone())
                        .collect::<Vec<_>>();
                    let mut selections = vec![Vec::new()];
                    selections.extend(candidates.into_iter().map(|instance_id| vec![instance_id]));
                    let options = selections
                        .into_iter()
                        .enumerate()
                        .map(|(index, selection)| LegalAction {
                            id: format!("choose:{decision_id}:{index}"),
                            kind: if selection.is_empty() {
                                ActionKind::DeclinePayment
                            } else {
                                ActionKind::ChooseResolution
                            },
                            player_id: card.controller.clone(),
                            label: selection
                                .first()
                                .map(|instance_id| {
                                    format!(
                                        "{} {}",
                                        if reveal { "Reveal" } else { "Discard" },
                                        self.card_name_for_instance(instance_id)
                                    )
                                })
                                .unwrap_or_else(|| {
                                    if reveal {
                                        "Do not reveal a card".to_string()
                                    } else {
                                        "Decline discard".to_string()
                                    }
                                }),
                            card_instance_id: selection.first().cloned(),
                            payment_sources: Vec::new(),
                            decisions: BTreeMap::from([(
                                decision_id.to_string(),
                                Value::Array(selection.into_iter().map(Value::String).collect()),
                            )]),
                            targets: BTreeMap::new(),
                            target_order: Vec::new(),
                            attacker_id: None,
                            blocker_id: None,
                        })
                        .collect::<Vec<_>>();
                    let choice = self.choose_action(
                        provider,
                        EngineDecisionRequest {
                            id: format!("replacement:{}:{decision_id}", card.instance_id),
                            kind: DecisionKind::ReplacementChoice,
                            player_id: card.controller.clone(),
                            source_card: Some(card.clone()),
                            source_card_instance_id: Some(card.instance_id.clone()),
                            choice: None,
                            options,
                        },
                    )?;
                    decisions.insert(
                        decision_id.to_string(),
                        choice
                            .decisions
                            .get(decision_id)
                            .cloned()
                            .unwrap_or_else(|| Value::Array(Vec::new())),
                    );
                    continue;
                }
                if value_kind(decision) == Some("chooseUntappedLands") {
                    let player_index = self.player_index(&card.controller)?;
                    let candidates = self.state.players[player_index]
                        .battlefield
                        .iter()
                        .filter(|permanent| is_land(&permanent.definition) && !permanent.tapped)
                        .map(|permanent| permanent.instance_id.clone())
                        .collect::<Vec<_>>();
                    let minimum = integer_value(&decision["minimum"]).unwrap_or(0).max(0) as usize;
                    let maximum = integer_value(&decision["maximum"]).unwrap_or(0).max(0) as usize;
                    let mut selections = Vec::new();
                    for count in (minimum..=maximum.min(candidates.len())).rev() {
                        selections.extend(Self::resolution_selections(
                            &candidates,
                            count,
                            MAX_DECLARATION_OPTIONS.saturating_sub(selections.len()),
                        ));
                    }
                    let options = selections
                        .into_iter()
                        .enumerate()
                        .map(|(index, selection)| LegalAction {
                            id: format!("choose:{decision_id}:{index}"),
                            kind: ActionKind::ChooseResolution,
                            player_id: card.controller.clone(),
                            label: if selection.is_empty() {
                                "Do not sacrifice lands".to_string()
                            } else {
                                format!("Sacrifice {} untapped lands", selection.len())
                            },
                            card_instance_id: Some(card.instance_id.clone()),
                            payment_sources: Vec::new(),
                            decisions: BTreeMap::from([(
                                decision_id.to_string(),
                                Value::Array(selection.into_iter().map(Value::String).collect()),
                            )]),
                            targets: BTreeMap::new(),
                            target_order: Vec::new(),
                            attacker_id: None,
                            blocker_id: None,
                        })
                        .collect::<Vec<_>>();
                    let choice = self.choose_action(
                        provider,
                        EngineDecisionRequest {
                            id: format!("replacement:{}:{decision_id}", card.instance_id),
                            kind: DecisionKind::ReplacementChoice,
                            player_id: card.controller.clone(),
                            source_card: Some(card.clone()),
                            source_card_instance_id: Some(card.instance_id.clone()),
                            choice: None,
                            options,
                        },
                    )?;
                    decisions.insert(
                        decision_id.to_string(),
                        choice
                            .decisions
                            .get(decision_id)
                            .cloned()
                            .unwrap_or_else(|| Value::Array(Vec::new())),
                    );
                    continue;
                }
                if matches!(
                    value_kind(decision),
                    Some("chooseBattlefieldCreature" | "chooseBattlefieldPermanent")
                ) {
                    let candidates = self
                        .state
                        .players
                        .iter()
                        .flat_map(|player| player.battlefield.iter())
                        .filter(|permanent| {
                            (!decision["controlledByEnteringController"]
                                .as_bool()
                                .unwrap_or(false)
                                || permanent.controller == card.controller)
                                && (value_kind(decision) == Some("chooseBattlefieldCreature")
                                    && self.permanent_is_creature(permanent)
                                    || value_kind(decision) == Some("chooseBattlefieldPermanent")
                                        && self
                                            .permanent_state_matches(permanent, &decision["where"]))
                        })
                        .map(|permanent| permanent.instance_id.clone())
                        .collect::<Vec<_>>();
                    let mut selections = candidates
                        .iter()
                        .cloned()
                        .map(|instance_id| vec![instance_id])
                        .collect::<Vec<_>>();
                    if decision["optional"].as_bool().unwrap_or(false) {
                        selections.insert(0, Vec::new());
                    }
                    let options = selections
                        .into_iter()
                        .enumerate()
                        .map(|(index, selection)| LegalAction {
                            id: format!("choose:{decision_id}:{index}"),
                            kind: ActionKind::ChooseResolution,
                            player_id: card.controller.clone(),
                            label: selection
                                .first()
                                .and_then(|instance_id| {
                                    self.permanent_position(instance_id).map(
                                        |(player_index, card_index)| {
                                            format!(
                                                "Copy {}",
                                                self.state.players[player_index].battlefield
                                                    [card_index]
                                                    .definition
                                                    .name
                                            )
                                        },
                                    )
                                })
                                .unwrap_or_else(|| "Do not copy a permanent".to_string()),
                            card_instance_id: Some(card.instance_id.clone()),
                            payment_sources: Vec::new(),
                            decisions: BTreeMap::from([(
                                decision_id.to_string(),
                                Value::Array(selection.into_iter().map(Value::String).collect()),
                            )]),
                            targets: BTreeMap::new(),
                            target_order: Vec::new(),
                            attacker_id: None,
                            blocker_id: None,
                        })
                        .collect::<Vec<_>>();
                    let choice = self.choose_action(
                        provider,
                        EngineDecisionRequest {
                            id: format!("replacement:{}:{decision_id}", card.instance_id),
                            kind: DecisionKind::ReplacementChoice,
                            player_id: card.controller.clone(),
                            source_card: Some(card.clone()),
                            source_card_instance_id: Some(card.instance_id.clone()),
                            choice: None,
                            options,
                        },
                    )?;
                    decisions.insert(
                        decision_id.to_string(),
                        choice
                            .decisions
                            .get(decision_id)
                            .cloned()
                            .unwrap_or_else(|| Value::Array(Vec::new())),
                    );
                    continue;
                }
                if value_kind(decision) == Some("chooseGraveyardCard") {
                    let candidates = self
                        .state
                        .players
                        .iter()
                        .flat_map(|player| player.graveyard.iter())
                        .filter(|candidate| {
                            matches_card_filter(&candidate.definition, &decision["where"])
                        })
                        .map(|candidate| candidate.instance_id.clone())
                        .collect::<Vec<_>>();
                    let mut selections = candidates
                        .iter()
                        .cloned()
                        .map(|instance_id| vec![instance_id])
                        .collect::<Vec<_>>();
                    if decision["optional"].as_bool().unwrap_or(false) {
                        selections.insert(0, Vec::new());
                    }
                    let options = selections
                        .into_iter()
                        .enumerate()
                        .map(|(index, selection)| LegalAction {
                            id: format!("choose:{decision_id}:{index}"),
                            kind: ActionKind::ChooseResolution,
                            player_id: card.controller.clone(),
                            label: selection
                                .first()
                                .and_then(|instance_id| self.card_outside_battlefield(instance_id))
                                .map(|candidate| format!("Copy {}", candidate.definition.name))
                                .unwrap_or_else(|| "Do not copy a graveyard card".to_string()),
                            card_instance_id: Some(card.instance_id.clone()),
                            payment_sources: Vec::new(),
                            decisions: BTreeMap::from([(
                                decision_id.to_string(),
                                Value::Array(selection.into_iter().map(Value::String).collect()),
                            )]),
                            targets: BTreeMap::new(),
                            target_order: Vec::new(),
                            attacker_id: None,
                            blocker_id: None,
                        })
                        .collect::<Vec<_>>();
                    let choice = self.choose_action(
                        provider,
                        EngineDecisionRequest {
                            id: format!("replacement:{}:{decision_id}", card.instance_id),
                            kind: DecisionKind::ReplacementChoice,
                            player_id: card.controller.clone(),
                            source_card: Some(card.clone()),
                            source_card_instance_id: Some(card.instance_id.clone()),
                            choice: None,
                            options,
                        },
                    )?;
                    decisions.insert(
                        decision_id.to_string(),
                        choice
                            .decisions
                            .get(decision_id)
                            .cloned()
                            .unwrap_or_else(|| Value::Array(Vec::new())),
                    );
                    continue;
                }
                // CR 614.1c `you may have`: whether the optional
                // replacement applies; the rule's condition reads it.
                if value_kind(decision) == Some("chooseWhether") {
                    let options = [true, false]
                        .into_iter()
                        .map(|applies| LegalAction {
                            id: format!("choose:{decision_id}:{applies}"),
                            kind: ActionKind::ChooseResolution,
                            player_id: card.controller.clone(),
                            label: if applies { "Apply" } else { "Decline" }.to_string(),
                            card_instance_id: Some(card.instance_id.clone()),
                            payment_sources: Vec::new(),
                            decisions: BTreeMap::from([(
                                decision_id.to_string(),
                                Value::Bool(applies),
                            )]),
                            targets: BTreeMap::new(),
                            target_order: Vec::new(),
                            attacker_id: None,
                            blocker_id: None,
                        })
                        .collect::<Vec<_>>();
                    let choice = self.choose_action(
                        provider,
                        EngineDecisionRequest {
                            id: format!("replacement:{}:{decision_id}", card.instance_id),
                            kind: DecisionKind::ReplacementChoice,
                            player_id: card.controller.clone(),
                            source_card: Some(card.clone()),
                            source_card_instance_id: Some(card.instance_id.clone()),
                            choice: None,
                            options,
                        },
                    )?;
                    let applies = choice
                        .decisions
                        .get(decision_id)
                        .and_then(Value::as_bool)
                        .ok_or_else(|| {
                            EngineError::new("optional replacement choice is missing")
                        })?;
                    decisions.insert(decision_id.to_string(), Value::Bool(applies));
                    continue;
                }
                if value_kind(decision) == Some("chooseOption") {
                    let options = decision["options"]
                        .as_array()
                        .into_iter()
                        .flatten()
                        .filter_map(Value::as_str)
                        .map(|option| LegalAction {
                            id: format!("choose:{decision_id}:{}", option.to_ascii_lowercase()),
                            kind: ActionKind::ChooseResolution,
                            player_id: card.controller.clone(),
                            label: format!("Choose {option}"),
                            card_instance_id: Some(card.instance_id.clone()),
                            payment_sources: Vec::new(),
                            decisions: BTreeMap::from([(
                                decision_id.to_string(),
                                Value::String(option.to_string()),
                            )]),
                            targets: BTreeMap::new(),
                            target_order: Vec::new(),
                            attacker_id: None,
                            blocker_id: None,
                        })
                        .collect::<Vec<_>>();
                    let choice = self.choose_action(
                        provider,
                        EngineDecisionRequest {
                            id: format!("replacement:{}:{decision_id}", card.instance_id),
                            kind: DecisionKind::ReplacementChoice,
                            player_id: card.controller.clone(),
                            source_card: Some(card.clone()),
                            source_card_instance_id: Some(card.instance_id.clone()),
                            choice: None,
                            options,
                        },
                    )?;
                    let selected =
                        choice.decisions.get(decision_id).cloned().ok_or_else(|| {
                            EngineError::new("replacement option choice is missing")
                        })?;
                    decisions.insert(decision_id.to_string(), selected);
                    continue;
                }
                if value_kind(decision) == Some("chooseColor") {
                    let options = decision["options"]
                        .as_array()
                        .into_iter()
                        .flatten()
                        .filter_map(Value::as_str)
                        .map(|color| LegalAction {
                            id: format!("choose:{decision_id}:{}", color.to_ascii_lowercase()),
                            kind: ActionKind::ChooseResolution,
                            player_id: card.controller.clone(),
                            label: format!("Choose {color}"),
                            card_instance_id: Some(card.instance_id.clone()),
                            payment_sources: Vec::new(),
                            decisions: BTreeMap::from([(
                                decision_id.to_string(),
                                Value::String(color.to_string()),
                            )]),
                            targets: BTreeMap::new(),
                            target_order: Vec::new(),
                            attacker_id: None,
                            blocker_id: None,
                        })
                        .collect::<Vec<_>>();
                    let choice = self.choose_action(
                        provider,
                        EngineDecisionRequest {
                            id: format!("replacement:{}:{decision_id}", card.instance_id),
                            kind: DecisionKind::ReplacementChoice,
                            player_id: card.controller.clone(),
                            source_card: Some(card.clone()),
                            source_card_instance_id: Some(card.instance_id.clone()),
                            choice: None,
                            options,
                        },
                    )?;
                    let chosen_color = choice
                        .decisions
                        .get(decision_id)
                        .cloned()
                        .ok_or_else(|| EngineError::new("color choice is missing"))?;
                    decisions.insert(decision_id.to_string(), chosen_color);
                    continue;
                }
                if value_kind(decision) == Some("chooseBasicLandType") {
                    let options = decision["options"]
                        .as_array()
                        .into_iter()
                        .flatten()
                        .filter_map(Value::as_str)
                        .map(|land_type| LegalAction {
                            id: format!("choose:{decision_id}:{}", land_type.to_ascii_lowercase()),
                            kind: ActionKind::ChooseResolution,
                            player_id: card.controller.clone(),
                            label: format!("Choose {land_type}"),
                            card_instance_id: Some(card.instance_id.clone()),
                            payment_sources: Vec::new(),
                            decisions: BTreeMap::from([(
                                decision_id.to_string(),
                                Value::String(land_type.to_string()),
                            )]),
                            targets: BTreeMap::new(),
                            target_order: Vec::new(),
                            attacker_id: None,
                            blocker_id: None,
                        })
                        .collect::<Vec<_>>();
                    let choice = self.choose_action(
                        provider,
                        EngineDecisionRequest {
                            id: format!("replacement:{}:{decision_id}", card.instance_id),
                            kind: DecisionKind::ReplacementChoice,
                            player_id: card.controller.clone(),
                            source_card: Some(card.clone()),
                            source_card_instance_id: Some(card.instance_id.clone()),
                            choice: None,
                            options,
                        },
                    )?;
                    let chosen_type = choice
                        .decisions
                        .get(decision_id)
                        .cloned()
                        .ok_or_else(|| EngineError::new("basic land type choice is missing"))?;
                    decisions.insert(decision_id.to_string(), chosen_type);
                    continue;
                }
                if value_kind(decision) == Some("chooseCardName") {
                    if decision["lookAtOpponentHand"].as_bool() == Some(true)
                        && let Some(opponent_id) = self
                            .state
                            .players
                            .iter()
                            .find(|player| player.id != card.controller && !player.has_lost)
                            .map(|player| player.id.clone())
                    {
                        self.remember_looked_at_hand(&opponent_id, &card.controller);
                    }
                    let suggestions = self.visible_card_name_suggestions(
                        &card.controller,
                        &decision["where"],
                        &card.definition.name,
                    );
                    let options = suggestions
                        .iter()
                        .enumerate()
                        .map(|(index, name)| LegalAction {
                            id: format!("choose:{decision_id}:name:{index}"),
                            kind: ActionKind::ChooseResolution,
                            player_id: card.controller.clone(),
                            label: format!("Choose {name}"),
                            card_instance_id: Some(card.instance_id.clone()),
                            payment_sources: Vec::new(),
                            decisions: BTreeMap::from([(
                                decision_id.to_string(),
                                Value::Array(vec![Value::String(name.clone())]),
                            )]),
                            targets: BTreeMap::new(),
                            target_order: Vec::new(),
                            attacker_id: None,
                            blocker_id: None,
                        })
                        .collect::<Vec<_>>();
                    let request = EngineDecisionRequest {
                        id: format!("replacement:{}:{decision_id}", card.instance_id),
                        kind: DecisionKind::ReplacementChoice,
                        player_id: card.controller.clone(),
                        source_card: Some(card.clone()),
                        source_card_instance_id: Some(card.instance_id.clone()),
                        choice: Some(DecisionChoice::CardNameSelection {
                            decision_id: decision_id.to_string(),
                            suggestions,
                            prompt: "Choose a card name.".to_string(),
                        }),
                        options,
                    };
                    self.check_quantity_failure()?;
                    let chosen_name = provider.choose_card_name(&self.state, &request)?;
                    let chosen_name = chosen_name.trim();
                    if chosen_name.is_empty()
                        || chosen_name.chars().count() > 256
                        || chosen_name.chars().any(char::is_control)
                    {
                        return Err(EngineError::new(
                            "card name must contain 1 to 256 printable characters",
                        ));
                    }
                    decisions.insert(
                        decision_id.to_string(),
                        Value::String(chosen_name.to_string()),
                    );
                    continue;
                }
                if value_kind(decision) == Some("chooseCardType") {
                    let options = decision["options"]
                        .as_array()
                        .into_iter()
                        .flatten()
                        .filter_map(Value::as_str)
                        .map(|card_type| LegalAction {
                            id: format!("choose:{decision_id}:{}", card_type.to_ascii_lowercase()),
                            kind: ActionKind::ChooseResolution,
                            player_id: card.controller.clone(),
                            label: format!("Choose {card_type}"),
                            card_instance_id: Some(card.instance_id.clone()),
                            payment_sources: Vec::new(),
                            decisions: BTreeMap::from([(
                                decision_id.to_string(),
                                Value::String(card_type.to_string()),
                            )]),
                            targets: BTreeMap::new(),
                            target_order: Vec::new(),
                            attacker_id: None,
                            blocker_id: None,
                        })
                        .collect::<Vec<_>>();
                    let choice = self.choose_action(
                        provider,
                        EngineDecisionRequest {
                            id: format!("replacement:{}:{decision_id}", card.instance_id),
                            kind: DecisionKind::ReplacementChoice,
                            player_id: card.controller.clone(),
                            source_card: Some(card.clone()),
                            source_card_instance_id: Some(card.instance_id.clone()),
                            choice: None,
                            options,
                        },
                    )?;
                    let chosen_type = choice
                        .decisions
                        .get(decision_id)
                        .cloned()
                        .ok_or_else(|| EngineError::new("card type choice is missing"))?;
                    decisions.insert(decision_id.to_string(), chosen_type);
                    continue;
                }
                if value_kind(decision) == Some("chooseOpponentHand") {
                    let opponents = self
                        .state
                        .players
                        .iter()
                        .filter(|player| player.id != card.controller && !player.has_lost)
                        .map(|player| player.id.clone())
                        .collect::<Vec<_>>();
                    let options = opponents
                        .iter()
                        .map(|opponent_id| LegalAction {
                            id: format!("choose:{decision_id}:{opponent_id}"),
                            kind: ActionKind::ChooseResolution,
                            player_id: card.controller.clone(),
                            label: format!("Look at {opponent_id}'s hand"),
                            card_instance_id: Some(card.instance_id.clone()),
                            payment_sources: Vec::new(),
                            decisions: BTreeMap::from([(
                                decision_id.to_string(),
                                Value::String(opponent_id.clone()),
                            )]),
                            targets: BTreeMap::new(),
                            target_order: Vec::new(),
                            attacker_id: None,
                            blocker_id: None,
                        })
                        .collect::<Vec<_>>();
                    let choice = self.choose_action(
                        provider,
                        EngineDecisionRequest {
                            id: format!("replacement:{}:{decision_id}", card.instance_id),
                            kind: DecisionKind::ReplacementChoice,
                            player_id: card.controller.clone(),
                            source_card: Some(card.clone()),
                            source_card_instance_id: Some(card.instance_id.clone()),
                            choice: None,
                            options,
                        },
                    )?;
                    if let Some(opponent_id) =
                        choice.decisions.get(decision_id).and_then(Value::as_str)
                    {
                        self.remember_looked_at_hand(opponent_id, &card.controller);
                        decisions.insert(
                            decision_id.to_string(),
                            Value::String(opponent_id.to_string()),
                        );
                    }
                    continue;
                }
                if value_kind(decision) == Some("chooseCreatureType") {
                    let creature_types =
                        nominal_choices::creature_type_options(decision.get("options"))?;
                    let options = creature_types
                        .into_iter()
                        .map(|creature_type| LegalAction {
                            id: format!(
                                "choose:{decision_id}:{}",
                                creature_type.to_ascii_lowercase()
                            ),
                            kind: ActionKind::ChooseResolution,
                            player_id: card.controller.clone(),
                            label: format!("Choose {creature_type}"),
                            card_instance_id: Some(card.instance_id.clone()),
                            payment_sources: Vec::new(),
                            decisions: BTreeMap::from([(
                                decision_id.to_string(),
                                Value::String(creature_type),
                            )]),
                            targets: BTreeMap::new(),
                            target_order: Vec::new(),
                            attacker_id: None,
                            blocker_id: None,
                        })
                        .collect::<Vec<_>>();
                    let choice = self.choose_action(
                        provider,
                        EngineDecisionRequest {
                            id: format!("replacement:{}:{decision_id}", card.instance_id),
                            kind: DecisionKind::ReplacementChoice,
                            player_id: card.controller.clone(),
                            source_card: Some(card.clone()),
                            source_card_instance_id: Some(card.instance_id.clone()),
                            choice: None,
                            options,
                        },
                    )?;
                    let chosen_type = choice
                        .decisions
                        .get(decision_id)
                        .cloned()
                        .ok_or_else(|| EngineError::new("creature type choice is missing"))?;
                    decisions.insert(decision_id.to_string(), chosen_type);
                    continue;
                }
                if value_kind(decision) != Some("chooseWhetherToPay") {
                    continue;
                }
                let amount = integer_value(&decision["cost"]["amount"]).unwrap_or(0);
                let controller_index = self.player_index(&card.controller)?;
                let can_pay = self.state.players[controller_index].life >= amount;
                let mut options = vec![LegalAction {
                    id: format!("decline:{decision_id}"),
                    kind: ActionKind::DeclinePayment,
                    player_id: card.controller.clone(),
                    label: "Decline payment".to_string(),
                    card_instance_id: Some(card.instance_id.clone()),
                    payment_sources: Vec::new(),
                    decisions: BTreeMap::new(),
                    targets: BTreeMap::new(),
                    target_order: Vec::new(),
                    attacker_id: None,
                    blocker_id: None,
                }];
                if can_pay {
                    options.push(LegalAction {
                        id: format!("pay:{decision_id}"),
                        kind: ActionKind::PayLife,
                        player_id: card.controller.clone(),
                        label: format!("Pay {amount} life"),
                        card_instance_id: Some(card.instance_id.clone()),
                        payment_sources: Vec::new(),
                        decisions: BTreeMap::new(),
                        targets: BTreeMap::new(),
                        target_order: Vec::new(),
                        attacker_id: None,
                        blocker_id: None,
                    });
                }
                let choice = self.choose_action(
                    provider,
                    EngineDecisionRequest {
                        id: format!("replacement:{}:{decision_id}", card.instance_id),
                        kind: DecisionKind::ReplacementChoice,
                        player_id: card.controller.clone(),
                        source_card: Some(card.clone()),
                        source_card_instance_id: Some(card.instance_id.clone()),
                        choice: None,
                        options,
                    },
                )?;
                let paid = choice.kind == ActionKind::PayLife;
                if paid {
                    self.state.players[controller_index].life -= amount;
                    self.record_event(
                        "lifePaid",
                        Some(card.controller.clone()),
                        Some(card.instance_id.clone()),
                        json!({ "amount": amount }),
                    );
                }
                decisions.insert(decision_id.to_string(), Value::Bool(paid));
            }
            if rule.get("condition").is_some()
                && !self
                    .checked_entry_condition_with_source(
                        &rule["condition"],
                        &card.controller,
                        &decisions,
                        card,
                    )
                    .map_err(permanent_presence_query::PresenceQueryError::into_engine_error)?
            {
                continue;
            }
            self.apply_replacement_operations(card, &rule["replacement"], &decisions)?;
        }
        // Granted entry abilities are evaluated after intrinsic copy/type
        // replacements have established the object that would enter.
        self.apply_granted_riot_entry_choices(card, provider)?;
        // CR 702.44a-b: only resolution of a cast permanent supplies its
        // mana-payment decisions. Reanimation and other non-stack entries
        // supply none. X is deliberately not used: repeated colors count once,
        // C not at all. CR 702.44d: each instance works separately.
        let sunburst_instances = card
            .definition
            .printed_rules()
            .iter()
            .filter(|rule| {
                value_kind(rule) == Some("keywordAbility")
                    && value_kind(&rule["ability"]) == Some("sunburst")
            })
            .count();
        if sunburst_instances > 0 {
            let colors = mana_colors_spent_from_cast_decisions(initial_decisions);
            let counter = if has_card_type(&card.definition, "Creature") {
                "+1/+1"
            } else {
                "charge"
            };
            for _ in 0..sunburst_instances {
                if colors > 0 {
                    *card.counters.entry(counter.to_string()).or_default() += colors;
                }
            }
        }
        let graft_counters = card
            .definition
            .printed_rules()
            .iter()
            .filter(|rule| value_kind(rule) == Some("keywordAbility"))
            .filter(|rule| value_kind(&rule["ability"]) == Some("graft"))
            .filter_map(|rule| integer_value(&rule["ability"]["count"]))
            .sum::<i32>();
        if graft_counters > 0 {
            let count = graft_counters;
            *card.counters.entry("+1/+1".to_string()).or_default() += count;
        }
        let has_read_ahead = card.definition.printed_rules().iter().any(|rule| {
            value_kind(rule) == Some("keywordAbility")
                && value_kind(&rule["ability"]) == Some("readAhead")
        });
        let mut read_ahead_chapter = None;
        if has_read_ahead
            && !card.counters.contains_key("lore")
            && let Some(final_chapter) = saga_final_chapter(&card.definition)
        {
            let options = (1..=final_chapter)
                .map(|chapter| LegalAction {
                    id: format!("readAhead:{}:{chapter}", card.instance_id),
                    kind: ActionKind::ChooseResolution,
                    player_id: card.controller.clone(),
                    label: format!("Start on chapter {chapter}"),
                    card_instance_id: Some(card.instance_id.clone()),
                    payment_sources: Vec::new(),
                    decisions: BTreeMap::from([(
                        "readAheadChapter".to_string(),
                        Value::from(chapter),
                    )]),
                    targets: BTreeMap::new(),
                    target_order: Vec::new(),
                    attacker_id: None,
                    blocker_id: None,
                })
                .collect::<Vec<_>>();
            let choice = self.choose_action(
                provider,
                EngineDecisionRequest {
                    id: format!("readAhead:{}", card.instance_id),
                    kind: DecisionKind::ReplacementChoice,
                    player_id: card.controller.clone(),
                    source_card: Some(card.clone()),
                    source_card_instance_id: Some(card.instance_id.clone()),
                    choice: None,
                    options,
                },
            )?;
            let chapter = choice
                .decisions
                .get("readAheadChapter")
                .and_then(Value::as_i64)
                .and_then(|value| i32::try_from(value).ok())
                .filter(|value| (1..=final_chapter).contains(value))
                .ok_or_else(|| EngineError::new("invalid Read ahead chapter choice"))?;
            read_ahead_chapter = Some(chapter);
        }
        if type_line_contains(&card.definition.type_line, "Saga")
            && !card.counters.contains_key("lore")
        {
            self.mark_saga_entry_lore_pending(card, read_ahead_chapter);
        }
        if has_card_type(&card.definition, "Planeswalker")
            && !card.counters.contains_key("loyalty")
            && let Some(starting_loyalty) = card
                .definition
                .printed_rules()
                .iter()
                .filter_map(|rule| integer_value(&rule["startingLoyalty"]))
                .max()
        {
            card.counters
                .insert("loyalty".to_string(), starting_loyalty);
        }
        if card.definition.printed_rules().iter().any(|rule| {
            value_kind(rule) == Some("triggeredAbility")
                && value_kind(&rule["condition"]) == Some("sourceNeedsEcho")
        }) {
            card.flags.insert(ECHO_DUE_FLAG.to_string(), true);
        }
        if self
            .battlefield_static_modifiers()
            .iter()
            .any(|(source, modifier)| {
                value_kind(modifier) == Some("controlledPermanentsEnterUntapped")
                    && matches_card_filter(&card.definition, &modifier["where"])
                    && self.event_player_reference_matches(
                        &modifier["player"],
                        source,
                        &card.controller,
                    )
            })
        {
            card.tapped = false;
        }
        Ok(())
    }

    fn resolve_top_stack_quantity_inner<P: DecisionProvider>(
        &mut self,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        self.commit_pending_triggered_targets(provider)?;
        if self.state.stack.is_empty() {
            return Ok(());
        }
        if let Some(top) = self.state.stack.last() {
            self.validate_resolution_target_authentication(top)?;
        }
        let stack_object = self
            .pop_stack_object_with_lki()
            .ok_or_else(|| EngineError::new("resolving stack object disappeared"))?;
        let context = self.target_numeric_context(&stack_object);
        // A keyword ability that names its action publishes it once it has
        // resolved (CR 702.110b), from the actions recorded meanwhile.
        let first_event = self.state.events.len();
        let resolved = stack_object
            .ability_rule
            .as_ref()
            .is_some_and(keyword_actions::rule_names_keyword_action)
            .then(|| stack_object.clone());
        self.with_target_numeric_context(context, |engine| {
            engine.resolve_prepared_stack_object_body(stack_object, provider)
        })?;
        if let Some(resolved) = resolved {
            self.publish_keyword_named_actions(&resolved, first_event);
        }
        Ok(())
    }

    fn resolve_prepared_stack_object_body<P: DecisionProvider>(
        &mut self,
        stack_object: StackObject,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        let movement_source = if card_zone_transition::stack_requires_checkpoint(&stack_object) {
            Some(self.detached_spell_movement_source(&stack_object)?)
        } else {
            None
        };
        let stack_id = stack_object.id.clone();
        self.record_event(
            "stackObjectStartedResolving",
            Some(stack_object.controller.clone()),
            Some(stack_object.card.instance_id.clone()),
            json!({
                "objectKind": stack_object.ability_kind.as_deref().unwrap_or("spell"),
                "stackId": stack_id,
            }),
        );
        let has_targets = !stack_object.targets.is_empty();
        let has_legal_target = stack_object.targets.iter().any(|(target_id, target)| {
            self.target_is_legal_for_stack_object(target_id, target, &stack_object)
        });
        if has_targets && !has_legal_target {
            if !stack_object_is_spell(&stack_object) {
                self.record_event(
                    "abilityFizzled",
                    Some(stack_object.controller),
                    Some(stack_object.card.instance_id),
                    json!({ "stackId": stack_object.id }),
                );
                self.check_state_based_actions_with_provider(Some(provider))?;
                return Ok(());
            }
            let controller = stack_object.controller.clone();
            let exile_on_leave_stack = stack_object.exile_on_leave_stack;
            let owner_index = self.player_index(&stack_object.card.owner)?;
            let mut card = stack_object.card;
            let card_id = card.instance_id.clone();
            let spell_copy = is_spell_copy(&card);
            // CR 608.2b: this spell doesn't resolve, so Rebound's resolution
            // replacement (CR 702.88a) never applies.
            card.flags.remove("reboundEligible");
            if let Some(source) = &movement_source {
                card_zone_transition::reset_movement_card(&mut card, source)?;
            } else {
                reset_after_leaving_battlefield(&mut card);
            }
            let destination = if spell_copy {
                "ceasesToExist"
            } else if exile_on_leave_stack {
                let destination_zone = card_zone_transition::ObjectZone::Exile;
                if let Some(source) = &movement_source {
                    self.commit_card_zone_transition(
                        &mut card,
                        source,
                        &destination_zone,
                        card_zone_transition::ObjectTransitionReason::Move,
                    )?;
                }
                self.state.players[owner_index].exile.push(card);
                "exile"
            } else if self.put_known_source_card_into_graveyard(
                owner_index,
                card,
                movement_source.as_ref().ok_or_else(|| {
                    EngineError::new("physical spell destination requires source identity")
                })?,
            )? {
                "graveyard"
            } else {
                "exile"
            };
            self.record_event(
                "spellFizzled",
                Some(controller.clone()),
                Some(card_id.clone()),
                json!({ "destination": destination, "stackId": stack_id }),
            );
            if spell_copy {
                self.record_event(
                    "spellCopyCeasedToExist",
                    Some(controller),
                    Some(card_id),
                    json!({ "zone": "stack" }),
                );
            }
            return Ok(());
        }

        if let Some(rule) = stack_object.ability_rule.clone() {
            let resolved_final_saga_chapter = stack_object.ability_kind.as_deref()
                == Some("triggeredAbility")
                && saga_chapter_rule_is_final(&stack_object.card.definition, &rule);
            let mut bindings = BTreeMap::new();
            let mut decisions = stack_object.decisions.clone();
            // CR 603.4: the intervening `if` is rechecked on resolution by
            // the same stack-context evaluator as on publication.
            let condition_met = rule.get("condition").is_none_or(|condition| {
                self.runtime_condition_value(condition, &stack_object, &bindings, &decisions)
            });
            if condition_met && !self.resolve_training_clock(&stack_object, &rule)? {
                self.execute_effects(
                    &rule["effects"],
                    &stack_object,
                    &mut bindings,
                    &mut decisions,
                    provider,
                )?;
            }
            let ability_kind = stack_object.ability_kind.as_deref().unwrap_or("ability");
            self.record_event(
                &format!("{ability_kind}Resolved"),
                Some(stack_object.controller.clone()),
                Some(stack_object.card.instance_id.clone()),
                json!({ "conditionMet": condition_met, "stackId": stack_object.id }),
            );
            if condition_met && resolved_final_saga_chapter {
                self.record_event(
                    "sagaFinalChapterAbilityResolved",
                    Some(stack_object.controller.clone()),
                    Some(stack_object.card.instance_id.clone()),
                    json!({ "stackId": stack_object.id }),
                );
                self.enqueue_saga_final_chapter_resolved_triggers(&stack_object.card);
            }
            self.check_state_based_actions_with_provider(Some(provider))?;
            return Ok(());
        }

        if is_land(&stack_object.card.definition) {
            return Err(EngineError::new("a land was illegally placed on the stack"));
        }
        if is_permanent(&stack_object.card.definition) || is_creature(&stack_object.card.definition)
        {
            let controller_index = self.player_index(&stack_object.controller)?;
            let room_door = stack_object
                .decisions
                .get("roomDoor")
                .and_then(Value::as_u64)
                .and_then(|index| usize::try_from(index).ok());
            let mut card = stack_object.card;
            let permanent_spell_copy = is_spell_copy(&card);
            card.controller = stack_object.controller.clone();
            card.summoning_sick = true;
            if let Some(from_zone) = stack_object
                .decisions
                .get("castSourceZone")
                .and_then(Value::as_str)
            {
                card.flags.insert(format!("enteredFrom:{from_zone}"), true);
            }
            if permanent_spell_copy {
                card.owner = stack_object.controller.clone();
                card.definition.is_token = true;
                if card.definition.printed_rules().iter().any(|rule| {
                    rule["modifiers"].as_array().is_some_and(|modifiers| {
                        modifiers.iter().any(|modifier| {
                            value_kind(modifier) == Some("removeLegendaryFromTokenCopy")
                        })
                    })
                }) {
                    card.definition.type_line = card
                        .definition
                        .type_line
                        .strip_prefix("Legendary ")
                        .unwrap_or(&card.definition.type_line)
                        .to_string();
                }
                card.flags.remove("isSpellCopy");
                card.flags.insert("isTokenCopy".to_string(), true);
            }
            for (decision_id, paid) in &stack_object.decisions {
                if decision_id.starts_with("offspringPaid:") && paid.as_bool() == Some(true) {
                    card.flags.insert(decision_id.clone(), true);
                }
            }
            // The casting mode's follow-ups mark how the spell was cast.
            for flag in casting_cost::CastingMode::of(&stack_object.decisions).follow_up_flags() {
                card.flags.insert(flag, true);
            }
            mana_payment::record_mana_spent_flags(&mut card.flags, &stack_object.decisions);
            let was_warped = stack_object
                .decisions
                .get("useWarp")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            if was_warped {
                card.flags.insert("warped".to_string(), true);
            }
            let was_blitzed = stack_object
                .decisions
                .get("useBlitz")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            if was_blitzed {
                card.flags.insert("blitzed".to_string(), true);
            }
            let was_dashed = stack_object
                .decisions
                .get("useDash")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            if was_dashed {
                card.flags.insert("dashed".to_string(), true);
            }
            let impending_time_counters = stack_object
                .decisions
                .get("useImpending")
                .and_then(Value::as_bool)
                .filter(|paid| *paid)
                .and_then(|_| impending_ability(&card.definition))
                .and_then(|ability| integer_value(&ability["timeCounters"]));
            if impending_time_counters.is_some() {
                card.flags.insert("impendingCostPaid".to_string(), true);
            }
            if has_card_type(&card.definition, "battle") && card.battle_protector.is_none() {
                let live_opponents = self
                    .state
                    .players
                    .iter()
                    .filter(|player| !player.has_lost && player.id != stack_object.controller)
                    .map(|player| player.id.clone())
                    .collect::<Vec<_>>();
                if live_opponents.len() == 1 {
                    card.battle_protector = live_opponents.into_iter().next();
                }
            }
            if is_room_definition(&card.definition)
                && let Some(door_index) = room_door
            {
                card.flags
                    .insert(format!("roomDoor{door_index}Unlocked"), true);
            }
            if card.definition.printed_rules().iter().any(|rule| {
                value_kind(rule) == Some("keywordAbility")
                    && value_kind(&rule["ability"]) == Some("enchant")
            }) || stack_object
                .decisions
                .get("useBestow")
                .and_then(Value::as_bool)
                == Some(true)
            {
                card.attached_to = stack_object
                    .targets
                    .get("enchantTarget")
                    .and_then(|target| match target {
                        TargetRef::Permanent { instance_id } | TargetRef::Card { instance_id } => {
                            Some(instance_id.clone())
                        }
                        _ => None,
                    });
            }
            if stack_object
                .decisions
                .get("useBestow")
                .and_then(Value::as_bool)
                == Some(true)
            {
                let original_type_line = card.definition.type_line.clone();
                card.flags.insert("bestowedAura".to_string(), true);
                card.definition.type_line = "Enchantment - Aura".to_string();
                card.definition.printed_rules_mut().push(json!({
                    "kind": "bestowOriginalTypeLine",
                    "value": original_type_line,
                }));
            }
            if let Some(time_counters) = impending_time_counters {
                *card.counters.entry("time".to_string()).or_default() += time_counters;
            }
            self.apply_enter_replacements_with_decisions(
                &mut card,
                provider,
                &stack_object.decisions,
            )?;
            if card.flags.remove("enterGraveyardInstead").unwrap_or(false) {
                let card_id = card.instance_id.clone();
                let owner_id = card.owner.clone();
                let owner_index = self.player_index(&owner_id)?;
                if let Some(source) = &movement_source {
                    card_zone_transition::reset_movement_card(&mut card, source)?;
                } else {
                    reset_after_leaving_battlefield(&mut card);
                }
                let entered_graveyard = self.put_known_source_card_into_graveyard(
                    owner_index,
                    card.clone(),
                    movement_source.as_ref().ok_or_else(|| {
                        EngineError::new("physical spell destination requires source identity")
                    })?,
                )?;
                let destination = if entered_graveyard {
                    "graveyard"
                } else {
                    "exile"
                };
                self.record_event(
                    "permanentEntryReplaced",
                    Some(stack_object.controller.clone()),
                    Some(card_id.clone()),
                    json!({ "destination": destination, "stackId": stack_id }),
                );
                self.record_event(
                    "spellResolved",
                    Some(stack_object.controller),
                    Some(card_id),
                    json!({ "destination": destination, "stackId": stack_id }),
                );
                if entered_graveyard {
                    self.enqueue_cards_entered_graveyard_triggers_from(&owner_id, &[card], "stack");
                }
                self.check_state_based_actions_with_provider(Some(provider))?;
                return Ok(());
            }
            let card_id = card.instance_id.clone();
            if let Some(source) = &movement_source {
                self.commit_card_zone_transition(
                    &mut card,
                    source,
                    &card_zone_transition::ObjectZone::Battlefield,
                    card_zone_transition::ObjectTransitionReason::Move,
                )?;
            } else {
                self.prepare_battlefield_entry_identity(&mut card);
            }
            let trigger_source = card.clone();
            self.state.players[controller_index].battlefield.push(card);
            self.apply_stored_copy_aura(&card_id);
            if let Some(x_value) = stack_object.decisions.get("xValue").and_then(Value::as_i64) {
                self.state.rule_modifiers.push(json!({
                    "kind": "permanentCastXValue",
                    "cardInstanceId": card_id,
                    "value": x_value,
                }));
            }
            if was_warped {
                self.state.rule_modifiers.push(json!({
                    "kind": "warpExileAtEndStep",
                    "cardInstanceId": card_id,
                    "notBeforeTurn": self.state.turn_number,
                }));
            }
            if was_blitzed {
                self.state.rule_modifiers.push(json!({
                    "kind": "sacrificeAtEndStep",
                    "cardInstanceId": card_id,
                    "notBeforeTurn": self.state.turn_number,
                }));
            }
            if was_dashed {
                self.state.rule_modifiers.push(json!({
                    "kind": "returnToHandAtEndStep",
                    "cardInstanceId": card_id,
                    "notBeforeTurn": self.state.turn_number,
                }));
            }
            self.record_event(
                "permanentResolved",
                Some(stack_object.controller.clone()),
                Some(card_id.clone()),
                json!({ "stackId": stack_id }),
            );
            if permanent_spell_copy {
                self.record_event(
                    "permanentSpellCopyBecameToken",
                    Some(stack_object.controller.clone()),
                    Some(card_id.clone()),
                    json!({ "stackId": stack_id }),
                );
            }
            self.ensure_prepared_spell_copy(&card_id)?;
            self.enqueue_enter_battlefield_triggers(&trigger_source);
            if let Some(door_index) = room_door {
                self.record_event(
                    "doorUnlocked",
                    Some(trigger_source.controller.clone()),
                    Some(card_id),
                    json!({ "doorIndex": door_index, "onEntry": true }),
                );
                self.enqueue_door_unlocked_triggers(&trigger_source, door_index);
            }
        } else {
            let mut bindings = BTreeMap::new();
            let mut resolution_decisions = stack_object.decisions.clone();
            let promised_gift = stack_object
                .card
                .definition
                .printed_rules()
                .iter()
                .find(|rule| {
                    value_kind(rule) == Some("keywordAbility")
                        && gift_ability_supported(&rule["ability"])
                })
                .map(|rule| rule["ability"].clone());
            if let Some(gift) = promised_gift
                && let Some(recipient_id) = stack_object
                    .decisions
                    .get("giftRecipient")
                    .and_then(Value::as_str)
                    .map(ToOwned::to_owned)
            {
                bindings.insert(
                    "giftRecipient".to_string(),
                    RuntimeBinding::Player(recipient_id.clone()),
                );
                if value_kind(&gift) == Some("giftCard") {
                    self.draw_cards_without_state_check(&recipient_id, 1)?;
                } else {
                    self.execute_effects(
                        &gift["effects"],
                        &stack_object,
                        &mut bindings,
                        &mut resolution_decisions,
                        provider,
                    )?;
                }
                self.record_event(
                    "giftPromised",
                    Some(stack_object.controller.clone()),
                    Some(stack_object.card.instance_id.clone()),
                    json!({ "recipientId": recipient_id }),
                );
            }
            for rule in stack_object
                .card
                .definition
                .printed_rules()
                .iter()
                .filter(|rule| value_kind(rule) == Some("spellAbility"))
                .cloned()
                .collect::<Vec<_>>()
            {
                self.execute_effects(
                    &rule["effects"],
                    &stack_object,
                    &mut bindings,
                    &mut resolution_decisions,
                    provider,
                )?;
                if self.state.outcome.is_some() {
                    break;
                }
            }
            if stack_object
                .decisions
                .get("awakened")
                .and_then(Value::as_bool)
                == Some(true)
                && let Some(TargetRef::Permanent { instance_id }) =
                    stack_object.targets.get("awakenLand")
                && let Some((player_index, card_index)) = self.permanent_position(instance_id)
            {
                let counter_count = stack_object
                    .card
                    .definition
                    .printed_rules()
                    .iter()
                    .find(|rule| {
                        value_kind(rule) == Some("keywordAbility")
                            && awaken_ability_supported(&rule["ability"])
                    })
                    .and_then(|rule| integer_value(&rule["ability"]["count"]))
                    .unwrap_or(0);
                let permanent = &mut self.state.players[player_index].battlefield[card_index];
                if !has_card_type(&permanent.definition, "Creature") {
                    permanent.definition.type_line = if let Some((types, subtypes)) =
                        split_type_line(&permanent.definition.type_line)
                    {
                        format!("{types} Creature - {subtypes}")
                    } else {
                        format!("{} Creature", permanent.definition.type_line)
                    };
                }
                if !type_line_contains(&permanent.definition.type_line, "Elemental") {
                    if permanent.definition.type_line.contains(" - ") {
                        permanent.definition.type_line =
                            format!("{} Elemental", permanent.definition.type_line);
                    } else {
                        permanent.definition.type_line =
                            format!("{} - Elemental", permanent.definition.type_line);
                    }
                }
                permanent.definition.power = Some("0".to_string());
                permanent.definition.toughness = Some("0".to_string());
                if !permanent_printed_has_keyword(permanent, "haste") {
                    permanent.definition.printed_rules_mut().push(json!({
                        "kind": "keywordAbility",
                        "source": { "kind": "self" },
                        "ability": { "kind": "haste" },
                    }));
                }
                self.place_counters(
                    instance_id,
                    "+1/+1",
                    counter_count,
                    QuantityOrigin::Effect,
                    None,
                    provider,
                )?;
            }
            let controller = stack_object.controller.clone();
            let paradigm_name = paradigm_spell_name(&stack_object.card.definition);
            if let Some(spell_name) = paradigm_name.as_deref() {
                self.establish_paradigm(&stack_object, spell_name);
            }
            let effect_exiles_resolving_spell = self.state.rule_modifiers.iter().any(|modifier| {
                value_kind(modifier) == Some("exileResolvingSpell")
                    && modifier["cardInstanceId"].as_str()
                        == Some(stack_object.card.instance_id.as_str())
            });
            let resolving_spell_exile_counter = self
                .state
                .rule_modifiers
                .iter()
                .find(|modifier| {
                    value_kind(modifier) == Some("exileResolvingSpell")
                        && modifier["cardInstanceId"].as_str()
                            == Some(stack_object.card.instance_id.as_str())
                })
                .and_then(|modifier| modifier["addCounter"].as_str())
                .map(ToOwned::to_owned);
            self.state.rule_modifiers.retain(|modifier| {
                value_kind(modifier) != Some("exileResolvingSpell")
                    || modifier["cardInstanceId"].as_str()
                        != Some(stack_object.card.instance_id.as_str())
            });
            // CR 702.88a: a hand-cast spell with rebound is exiled instead of
            // being put into its owner's graveyard as it resolves.
            let rebound = stack_object
                .card
                .flags
                .get("reboundEligible")
                .copied()
                .unwrap_or(false)
                && !is_spell_copy(&stack_object.card);
            let exile_on_leave_stack = stack_object.exile_on_leave_stack
                || rebound
                || effect_exiles_resolving_spell
                || paradigm_name.is_some()
                || spell_exiles_after_resolution(&stack_object.card.definition)
                || spell_suspend_after_resolution(&stack_object.card.definition).is_some();
            let adventure_after_resolution = spell_is_adventure(&stack_object.card.definition);
            let suspend_after_resolution =
                spell_suspend_after_resolution(&stack_object.card.definition);
            let shuffle_into_library =
                spell_shuffles_into_library_after_resolution(&stack_object.card.definition);
            let library_position_from_top = resolution_decisions
                .get("resolutionLibraryPositionFromTop")
                .and_then(Value::as_u64)
                .and_then(|value| usize::try_from(value).ok())
                .filter(|position| *position > 0);
            let owner_index = self.player_index(&stack_object.card.owner)?;
            let mut card = stack_object.card;
            let card_id = card.instance_id.clone();
            let spell_copy = is_spell_copy(&card);
            let buyback_paid = stack_object
                .decisions
                .get("buybackMode")
                .and_then(Value::as_array)
                .is_some_and(|modes| modes.iter().any(|mode| mode.as_str() == Some("buyback")))
                || stack_object
                    .decisions
                    .get("buybackMode")
                    .and_then(Value::as_str)
                    == Some("buyback");
            if let Some(source) = &movement_source {
                card_zone_transition::reset_movement_card(&mut card, source)?;
            } else {
                reset_after_leaving_battlefield(&mut card);
            }
            if let Some(time_counters) = suspend_after_resolution {
                card.flags.insert("suspended".to_string(), true);
                card.counters.insert("time".to_string(), time_counters);
            }
            card.flags.remove("reboundEligible");
            let destination = if spell_copy {
                "ceasesToExist"
            } else if exile_on_leave_stack {
                if let Some(counter) = resolving_spell_exile_counter {
                    *card.counters.entry(counter).or_default() += 1;
                }
                let destination_zone = card_zone_transition::ObjectZone::Exile;
                if let Some(source) = &movement_source {
                    self.commit_card_zone_transition(
                        &mut card,
                        source,
                        &destination_zone,
                        card_zone_transition::ObjectTransitionReason::Move,
                    )?;
                }
                if rebound {
                    self.install_rebound_upkeep_trigger(&card, &controller);
                }
                // CR 716.3d: bound to this exile incarnation (CR 400.7).
                let adventure_permission = adventure_after_resolution
                    .then(|| adventure::adventure_cast_permission(&card, &controller));
                self.state.players[owner_index].exile.push(card);
                self.state.permissions.extend(adventure_permission);
                "exile"
            } else if shuffle_into_library {
                let destination_zone =
                    card_zone_transition::ObjectZone::Library(card.owner.clone());
                if let Some(source) = &movement_source {
                    self.commit_card_zone_transition(
                        &mut card,
                        source,
                        &destination_zone,
                        card_zone_transition::ObjectTransitionReason::Move,
                    )?;
                }
                self.state.players[owner_index].library.push(card);
                self.state.players[owner_index]
                    .library
                    .shuffle(&mut self.rng);
                "library"
            } else if let Some(position) = library_position_from_top {
                let library_len = self.state.players[owner_index].library.len();
                let insert_index = library_len.saturating_sub(position.saturating_sub(1));
                let destination_zone =
                    card_zone_transition::ObjectZone::Library(card.owner.clone());
                if let Some(source) = &movement_source {
                    self.commit_card_zone_transition(
                        &mut card,
                        source,
                        &destination_zone,
                        card_zone_transition::ObjectTransitionReason::Move,
                    )?;
                }
                self.state.players[owner_index]
                    .library
                    .insert(insert_index, card);
                "library"
            } else if buyback_paid {
                let destination_zone = card_zone_transition::ObjectZone::Hand(card.owner.clone());
                if let Some(source) = &movement_source {
                    self.commit_card_zone_transition(
                        &mut card,
                        source,
                        &destination_zone,
                        card_zone_transition::ObjectTransitionReason::Move,
                    )?;
                }
                self.state.players[owner_index].hand.push(card);
                "hand"
            } else if self.put_known_source_card_into_graveyard(
                owner_index,
                card,
                movement_source.as_ref().ok_or_else(|| {
                    EngineError::new("physical spell destination requires source identity")
                })?,
            )? {
                "graveyard"
            } else {
                "exile"
            };
            self.record_event(
                "spellResolved",
                Some(controller.clone()),
                Some(card_id.clone()),
                json!({ "destination": destination, "stackId": stack_id }),
            );
            if spell_copy {
                self.record_event(
                    "spellCopyCeasedToExist",
                    Some(controller),
                    Some(card_id),
                    json!({ "zone": "stack" }),
                );
            }
        }
        self.check_state_based_actions_with_provider(Some(provider))?;
        Ok(())
    }

    fn resolve_target(
        &self,
        reference: &Value,
        stack_object: &StackObject,
        bindings: &BTreeMap<String, RuntimeBinding>,
    ) -> Option<TargetRef> {
        match value_kind(reference) {
            Some("boundObject" | "singleBoundObject") => reference["binding"]
                .as_str()
                .and_then(|id| match bindings.get(id) {
                    Some(RuntimeBinding::Objects(objects)) => objects.first().cloned(),
                    Some(_) => None,
                    // A delayed trigger finds the object it captured when it
                    // was created, only while it is that object (CR 603.7c,
                    // 400.7); no other resolution reads its decisions.
                    None => self.captured_bound_object(stack_object, id),
                })
                .map(|instance_id| {
                    if self.permanent_position(&instance_id).is_some() {
                        TargetRef::Permanent {
                            instance_id: instance_id.clone(),
                        }
                    } else {
                        TargetRef::Card {
                            instance_id: instance_id.clone(),
                        }
                    }
                }),
            Some("chosenTarget" | "chosenObject") => reference["id"]
                .as_str()
                .and_then(|id| stack_object.targets.get(id))
                .cloned(),
            Some("boundValue") => reference["id"]
                .as_str()
                .and_then(|id| bindings.get(id))
                .and_then(|binding| match binding {
                    RuntimeBinding::Target(target) => Some(target.clone()),
                    RuntimeBinding::Player(player_id) => Some(TargetRef::Player {
                        player_id: player_id.clone(),
                    }),
                    RuntimeBinding::Integer(_) | RuntimeBinding::Objects(_) => None,
                }),
            // The record's permanent, while it is the incarnation the event
            // saw (CR 400.7).
            Some("triggeringPermanent") => self.event_object_target(stack_object),
            Some("blockingPermanent") => stack_object
                .decisions
                .get("blockingPermanentId")
                .and_then(Value::as_str)
                .map(|instance_id| TargetRef::Permanent {
                    instance_id: instance_id.to_string(),
                }),
            // The other combatant of the triggering block record, while it is
            // still the same object (CR 400.7).
            Some("combatCounterpart") => self.combat_counterpart_target(stack_object),
            // The entering permanent, while it is the incarnation the entry
            // event observed (CR 400.7).
            Some("observedEventObject") => self
                .resolve_observed_event_permanent(reference, stack_object)
                .ok()
                .flatten()
                .map(|instance_id| TargetRef::Permanent { instance_id }),
            Some("triggeringStackObject") => stack_object
                .decisions
                .get("triggeringStackId")
                .and_then(Value::as_str)
                .map(|stack_id| TargetRef::StackObject {
                    stack_id: stack_id.to_string(),
                }),
            Some("attachedPermanent") if value_kind(&reference["attachment"]) == Some("self") => {
                stack_object
                    .card
                    .attached_to
                    .as_ref()
                    .map(|instance_id| TargetRef::Permanent {
                        instance_id: instance_id.clone(),
                    })
            }
            Some("cardExiledWithSource") => self
                .state
                .rule_modifiers
                .iter()
                .find(|modifier| {
                    value_kind(modifier) == Some("exiledWithSource")
                        && modifier["sourceCardInstanceId"].as_str()
                            == Some(stack_object.card.instance_id.as_str())
                })
                .and_then(|modifier| modifier["cardInstanceId"].as_str())
                .map(|instance_id| TargetRef::Card {
                    instance_id: instance_id.to_string(),
                }),
            _ => None,
        }
    }

    fn event_player_reference_matches(
        &self,
        reference: &Value,
        source: &CardInstance,
        player_id: &str,
    ) -> bool {
        match value_kind(reference) {
            Some("abilityController") => source.controller == player_id,
            Some("controllerOf")
                if matches!(
                    value_kind(&reference["object"]),
                    Some("self" | "abilitySource")
                ) =>
            {
                source.controller == player_id
            }
            Some("opponentsOf") => {
                !self.event_player_reference_matches(&reference["player"], source, player_id)
            }
            Some("eachPlayer") => true,
            Some("controllerOfAttachedPermanent") => source
                .attached_to
                .as_deref()
                .and_then(|instance_id| self.permanent_position(instance_id))
                .is_some_and(|(player_index, card_index)| {
                    self.state.players[player_index].battlefield[card_index].controller == player_id
                }),
            _ => false,
        }
    }

    fn resolve_player(
        &self,
        reference: &Value,
        stack_object: &StackObject,
        bindings: &BTreeMap<String, RuntimeBinding>,
    ) -> Option<String> {
        match value_kind(reference) {
            Some("controllerOfObject") => {
                self.resolved_object_controller(&reference["object"], stack_object, bindings)
            }
            Some("abilityController") => Some(stack_object.controller.clone()),
            Some("controllerOf") => {
                if matches!(
                    value_kind(&reference["object"]),
                    Some("self" | "abilitySource")
                ) {
                    return Some(stack_object.controller.clone());
                }
                if matches!(
                    value_kind(&reference["object"]),
                    Some("triggeringPermanent" | "observedEventObject")
                ) {
                    return self.event_object_player(
                        object_relation_lki::ObjectPlayerRelation::Controller,
                        &reference["object"],
                        stack_object,
                    );
                }
                // The spell the cast record binds: its controller while it is
                // on the stack, else its caster (CR 110.2).
                if value_kind(&reference["object"]) == Some("triggeringStackObject")
                    && self
                        .resolve_target(&reference["object"], stack_object, bindings)
                        .is_some_and(|target| match target {
                            TargetRef::StackObject { stack_id } => {
                                !self.state.stack.iter().any(|object| object.id == stack_id)
                            }
                            _ => false,
                        })
                {
                    return stack_object
                        .decisions
                        .get("triggeringPlayerId")
                        .and_then(Value::as_str)
                        .map(str::to_string);
                }
                let departed = || {
                    self.departed_target_player(
                        object_relation_lki::ObjectPlayerRelation::Controller,
                        &reference["object"],
                        stack_object,
                    )
                };
                match self.resolve_target(&reference["object"], stack_object, bindings)? {
                    TargetRef::Player { player_id } => Some(player_id),
                    TargetRef::Permanent { instance_id } => departed().or_else(|| {
                        let (player_index, card_index) = self.permanent_position(&instance_id)?;
                        Some(
                            self.state.players[player_index].battlefield[card_index]
                                .controller
                                .clone(),
                        )
                    }),
                    TargetRef::Card { instance_id } => self
                        .card_outside_battlefield(&instance_id)
                        .map(|card| card.owner.clone()),
                    TargetRef::StackObject { stack_id } => self
                        .state
                        .stack
                        .iter()
                        .find(|object| object.id == stack_id)
                        .map(|object| object.controller.clone())
                        .or_else(departed),
                }
            }
            Some("ownerOf") => {
                if matches!(
                    value_kind(&reference["object"]),
                    Some("self" | "abilitySource")
                ) {
                    return Some(stack_object.card.owner.clone());
                }
                if matches!(
                    value_kind(&reference["object"]),
                    Some("triggeringPermanent" | "observedEventObject")
                ) {
                    return self.event_object_player(
                        object_relation_lki::ObjectPlayerRelation::Owner,
                        &reference["object"],
                        stack_object,
                    );
                }
                let departed = || {
                    self.departed_target_player(
                        object_relation_lki::ObjectPlayerRelation::Owner,
                        &reference["object"],
                        stack_object,
                    )
                };
                match self.resolve_target(&reference["object"], stack_object, bindings)? {
                    TargetRef::Player { player_id } => Some(player_id),
                    TargetRef::Permanent { instance_id } => departed().or_else(|| {
                        let (player_index, card_index) = self.permanent_position(&instance_id)?;
                        Some(
                            self.state.players[player_index].battlefield[card_index]
                                .owner
                                .clone(),
                        )
                    }),
                    TargetRef::Card { instance_id } => self
                        .card_outside_battlefield(&instance_id)
                        .map(|card| card.owner.clone()),
                    TargetRef::StackObject { stack_id } => self
                        .state
                        .stack
                        .iter()
                        .find(|object| object.id == stack_id)
                        .map(|object| object.card.owner.clone())
                        .or_else(departed),
                }
            }
            Some("chosenTarget" | "chosenObject") => {
                match self.resolve_target(reference, stack_object, bindings)? {
                    TargetRef::Player { player_id } => Some(player_id),
                    TargetRef::Permanent { instance_id } => {
                        let (player_index, card_index) = self.permanent_position(&instance_id)?;
                        Some(
                            self.state.players[player_index].battlefield[card_index]
                                .controller
                                .clone(),
                        )
                    }
                    TargetRef::Card { instance_id } => self
                        .card_outside_battlefield(&instance_id)
                        .map(|card| card.owner.clone()),
                    TargetRef::StackObject { stack_id } => self
                        .state
                        .stack
                        .iter()
                        .find(|object| object.id == stack_id)
                        .map(|object| object.controller.clone()),
                }
            }
            Some("boundValue") => reference["id"].as_str().and_then(|id| {
                bindings
                    .get(id)
                    .and_then(|binding| match binding {
                        RuntimeBinding::Player(player_id) => Some(player_id.clone()),
                        RuntimeBinding::Target(TargetRef::Player { player_id }) => {
                            Some(player_id.clone())
                        }
                        RuntimeBinding::Target(TargetRef::Permanent { instance_id }) => {
                            let (player_index, card_index) =
                                self.permanent_position(instance_id)?;
                            Some(
                                self.state.players[player_index].battlefield[card_index]
                                    .controller
                                    .clone(),
                            )
                        }
                        RuntimeBinding::Target(TargetRef::Card { instance_id }) => self
                            .card_outside_battlefield(instance_id)
                            .map(|card| card.owner.clone()),
                        RuntimeBinding::Target(TargetRef::StackObject { stack_id }) => self
                            .state
                            .stack
                            .iter()
                            .find(|object| object.id == *stack_id)
                            .map(|object| object.controller.clone()),
                        RuntimeBinding::Integer(_) | RuntimeBinding::Objects(_) => None,
                    })
                    .or_else(|| {
                        stack_object
                            .decisions
                            .get(id)
                            .and_then(Value::as_str)
                            .map(ToOwned::to_owned)
                    })
            }),
            Some("triggeringPlayer") => stack_object
                .decisions
                .get("triggeringPlayerId")
                .and_then(Value::as_str)
                .map(ToOwned::to_owned),
            Some("controllerOfAttachedPermanent") => stack_object
                .card
                .attached_to
                .as_deref()
                .and_then(|instance_id| self.permanent_position(instance_id))
                .map(|(player_index, card_index)| {
                    self.state.players[player_index].battlefield[card_index]
                        .controller
                        .clone()
                }),
            _ => None,
        }
    }

    fn materialize_attack_defender_predicate(
        &self,
        predicate: &Value,
        stack_object: &StackObject,
        bindings: &BTreeMap<String, RuntimeBinding>,
    ) -> Option<Value> {
        match value_kind(predicate) {
            Some("player") => Some(json!({
                "kind": "player",
                "playerId": self.resolve_player(&predicate["player"], stack_object, bindings)?,
            })),
            Some("permanent") => Some(json!({
                "kind": "permanent",
                "controllerId": self.resolve_player(
                    &predicate["controller"],
                    stack_object,
                    bindings,
                )?,
                "where": predicate["where"].clone(),
            })),
            Some("union") => Some(json!({
                "kind": "union",
                "operands": predicate["operands"]
                    .as_array()?
                    .iter()
                    .map(|operand| {
                        self.materialize_attack_defender_predicate(
                            operand,
                            stack_object,
                            bindings,
                        )
                    })
                    .collect::<Option<Vec<_>>>()?,
            })),
            _ => None,
        }
    }

    fn resolve_players(
        &self,
        reference: &Value,
        stack_object: &StackObject,
        bindings: &BTreeMap<String, RuntimeBinding>,
    ) -> Vec<String> {
        match value_kind(reference) {
            Some("eachPlayer" | "randomPlayer") => self
                .state
                .players
                .iter()
                .filter(|player| !player.has_lost)
                .map(|player| player.id.clone())
                .collect(),
            // `players except X` is the same complement as `opponents of X`
            // in the shared population grammar (player_query).
            Some("opponentsOf" | "playersExcept" | "randomOpponentOf") => {
                let Some(reference_player) =
                    self.resolve_player(&reference["player"], stack_object, bindings)
                else {
                    return Vec::new();
                };
                self.state
                    .players
                    .iter()
                    .filter(|player| !player.has_lost && player.id != reference_player)
                    .map(|player| player.id.clone())
                    .collect()
            }
            _ => self
                .resolve_player(reference, stack_object, bindings)
                .into_iter()
                .collect(),
        }
    }

    fn source_cast_x_value(
        &self,
        source_instance_id: &str,
        decisions: &BTreeMap<String, Value>,
    ) -> Option<i32> {
        decisions
            .get("xValue")
            .and_then(Value::as_i64)
            .and_then(|value| i32::try_from(value).ok())
            .or_else(|| {
                self.state
                    .rule_modifiers
                    .iter()
                    .find(|modifier| {
                        value_kind(modifier) == Some("permanentCastXValue")
                            && modifier["cardInstanceId"].as_str() == Some(source_instance_id)
                    })
                    .and_then(|modifier| modifier["value"].as_i64())
                    .and_then(|value| i32::try_from(value).ok())
            })
            .map(|value| value.max(0))
    }

    fn runtime_numeric_expression(
        &self,
        expression: &Value,
        stack_object: &StackObject,
        bindings: &BTreeMap<String, RuntimeBinding>,
        decisions: &BTreeMap<String, Value>,
    ) -> Option<i32> {
        if let Some(value) = integer_value(expression) {
            return Some(value);
        }
        // An event object: live while it is the same incarnation, else its
        // last known characteristics (CR 400.7, 608.2h).
        if matches!(
            value_kind(&expression["object"]),
            Some("triggeringPermanent" | "observedEventObject")
        ) && let Some(value) = self.event_object_numeric(expression, stack_object)
        {
            return value;
        }
        if value_kind(&expression["object"]) == Some("chosenTarget")
            && let Some(target_id) = expression["object"]["id"].as_str()
            && matches!(
                stack_object.targets.get(target_id),
                Some(TargetRef::Permanent { .. })
            )
        {
            let property = match value_kind(expression) {
                Some("manaValueOf") => Some(object_lki::TargetNumericProperty::ManaValue),
                Some("powerOf") => Some(object_lki::TargetNumericProperty::Power),
                Some("toughnessOf") => Some(object_lki::TargetNumericProperty::Toughness),
                _ => None,
            };
            if let Some(property) = property {
                return self
                    .read_chosen_target_numeric(property, stack_object, target_id)
                    .ok();
            }
        }
        match value_kind(expression) {
            Some("countTurnsTaken") => {
                let player_id =
                    self.resolve_player(&expression["player"], stack_object, bindings)?;
                Some(count_turns_taken(&self.state.events, &player_id))
            }
            Some("countManaSymbolsInTriggeringSpell") => {
                let required_symbol = expression["symbol"].as_str()?;
                let mana_cost = decisions["triggeringSpellManaCost"].as_str()?;
                Some(
                    parse_mana_symbols(mana_cost)
                        .iter()
                        .filter(|symbol| symbol.split('/').any(|part| part == required_symbol))
                        .count() as i32,
                )
            }
            Some("countAttackingCreatures") => {
                let player_id =
                    self.resolve_player(&expression["player"], stack_object, bindings)?;
                Some(
                    self.state
                        .combat
                        .attackers
                        .iter()
                        .filter(|assignment| {
                            self.permanent_position(&assignment.attacker_id)
                                .is_some_and(|(player_index, card_index)| {
                                    let permanent =
                                        &self.state.players[player_index].battlefield[card_index];
                                    permanent.controller == player_id
                                        && self.permanent_is_creature(permanent)
                                })
                        })
                        .count() as i32,
                )
            }
            Some("negate") => self
                .runtime_numeric_expression(
                    &expression["operand"],
                    stack_object,
                    bindings,
                    decisions,
                )
                .map(|value| value.saturating_neg()),
            Some("countDistinctPowers" | "countDistinctColors") => {
                let player_id =
                    self.resolve_player(&expression["player"], stack_object, bindings)?;
                let player_index = self.player_index(&player_id).ok()?;
                if value_kind(expression) == Some("countDistinctPowers") {
                    Some(
                        self.state.players[player_index]
                            .battlefield
                            .iter()
                            .filter(|permanent| {
                                self.permanent_state_matches(permanent, &expression["where"])
                            })
                            .filter(|permanent| {
                                !expression["excludeSource"].as_bool().unwrap_or(false)
                                    || permanent.instance_id != stack_object.card.instance_id
                            })
                            .map(|permanent| self.current_power(permanent))
                            .collect::<BTreeSet<_>>()
                            .len() as i32,
                    )
                } else {
                    Some(
                        self.state.players[player_index]
                            .battlefield
                            .iter()
                            .filter(|permanent| {
                                self.permanent_state_matches(permanent, &expression["where"])
                            })
                            .filter(|permanent| {
                                !expression["excludeSource"].as_bool().unwrap_or(false)
                                    || permanent.instance_id != stack_object.card.instance_id
                            })
                            .flat_map(|permanent| card_color_symbols(&permanent.definition))
                            .collect::<BTreeSet<_>>()
                            .len() as i32,
                    )
                }
            }
            Some("countEvents" | "countEventsThisTurn" | "countEventsPreviousTurn") => {
                self.runtime_event_history_count(expression, stack_object, bindings)
            }
            Some("sumEventValuesThisTurn") => {
                let player_id =
                    self.resolve_player(&expression["player"], stack_object, bindings)?;
                let event_kind = expression["eventKind"].as_str()?;
                let detail_field = expression["detailField"].as_str()?;
                Some(
                    self.state
                        .events
                        .iter()
                        .filter(|event| event.turn_number == self.state.turn_number)
                        .filter(|event| event.kind == event_kind)
                        .filter(|event| event.player_id.as_deref() == Some(player_id.as_str()))
                        .filter(|event| {
                            expression["excludeSource"].as_bool() != Some(true)
                                || event.card_instance_id.as_deref()
                                    != Some(stack_object.card.instance_id.as_str())
                        })
                        .filter_map(|event| event.detail[detail_field].as_i64())
                        .filter_map(|value| i32::try_from(value).ok())
                        .fold(0_i32, i32::saturating_add),
                )
            }
            Some("add" | "subtract") => self
                .runtime_numeric_expression(&expression["left"], stack_object, bindings, decisions)
                .zip(self.runtime_numeric_expression(
                    &expression["right"],
                    stack_object,
                    bindings,
                    decisions,
                ))
                .map(|(left, right)| {
                    if value_kind(expression) == Some("add") {
                        left.saturating_add(right)
                    } else {
                        left.saturating_sub(right)
                    }
                }),
            Some("absoluteDifference") => self
                .runtime_numeric_expression(&expression["left"], stack_object, bindings, decisions)
                .zip(self.runtime_numeric_expression(
                    &expression["right"],
                    stack_object,
                    bindings,
                    decisions,
                ))
                .map(|(left, right)| left.abs_diff(right).min(i32::MAX as u32) as i32),
            Some("powerDifferenceOfChosenObjects") => {
                let decision_id = expression["decisionId"].as_str()?;
                let mut powers = stack_object
                    .targets
                    .iter()
                    .filter(|(target_id, _)| {
                        target_id.as_str() == decision_id
                            || target_id.starts_with(&format!("{decision_id}:"))
                    })
                    .filter_map(|(_, target)| match target {
                        TargetRef::Permanent { instance_id } => self
                            .permanent_position(instance_id)
                            .map(|(player_index, card_index)| {
                                self.current_power(
                                    &self.state.players[player_index].battlefield[card_index],
                                )
                            }),
                        _ => None,
                    });
                let first = powers.next()?;
                let second = powers.next()?;
                Some(first.abs_diff(second).min(i32::MAX as u32) as i32)
            }
            Some("countBoundObjects") => {
                bindings
                    .get(expression["binding"].as_str()?)
                    .and_then(|binding| match binding {
                        RuntimeBinding::Objects(objects) => i32::try_from(objects.len()).ok(),
                        RuntimeBinding::Target(_) => Some(1),
                        _ => None,
                    })
            }
            Some("multiply") => self
                .runtime_numeric_expression(
                    expression.get("left").unwrap_or(&expression["value"]),
                    stack_object,
                    bindings,
                    decisions,
                )
                .zip(self.runtime_numeric_expression(
                    expression.get("right").unwrap_or(&expression["factor"]),
                    stack_object,
                    bindings,
                    decisions,
                ))
                .map(|(value, factor)| value.saturating_mul(factor)),
            Some("divide") => self
                .runtime_numeric_expression(&expression["left"], stack_object, bindings, decisions)
                .zip(self.runtime_numeric_expression(
                    &expression["right"],
                    stack_object,
                    bindings,
                    decisions,
                ))
                .and_then(|(left, right)| divide_integer(left, right, &expression["round"])),
            Some("countPermanents")
                if rule_contains_kind(&expression["where"], "chosenCreatureType") =>
            {
                let player_id = expression
                    .get("player")
                    .and_then(|player| self.resolve_player(player, stack_object, bindings))
                    .unwrap_or_else(|| stack_object.controller.clone());
                let player_index = self.player_index(&player_id).ok()?;
                let count = i32::try_from(
                    self.state.players[player_index]
                        .battlefield
                        .iter()
                        .filter(|card| {
                            matches_card_filter_with_decisions(
                                &card.definition,
                                &expression["where"],
                                decisions,
                            )
                        })
                        .count(),
                )
                .ok()?;
                if expression["excludeSource"].as_bool() == Some(true) {
                    self.exclude_current_source_from_count(
                        count,
                        Some(&stack_object.card),
                        source_lki::source_has_departed(stack_object),
                        |current, current_player| {
                            current_player == player_id
                                && matches_card_filter_with_decisions(
                                    &current.definition,
                                    &expression["where"],
                                    decisions,
                                )
                        },
                    )
                } else {
                    Some(count)
                }
            }
            Some(
                "countPermanents"
                | "countPermanentsControlledByOpponents"
                | "greatestSharedCreatureTypeCount"
                | "countCards"
                | "countDistinctCardTypes"
                | "countDistinctPermanentNames"
                | "domainCount"
                | "countPlayerCounters"
                | "greatestPower"
                | "greatestToughness"
                | "greatestManaValue"
                | "greatestOpponentPermanentCount"
                | "sumManaValues"
                | "manaPoolSize"
                | "manaPoolSymbolCount",
            ) => {
                let player_id = expression
                    .get("player")
                    .or_else(|| expression.get("zone").and_then(|zone| zone.get("player")))
                    .and_then(|player| self.resolve_player(player, stack_object, bindings))
                    .unwrap_or_else(|| stack_object.controller.clone());
                if value_kind(expression) == Some("countPermanentsControlledByOpponents") {
                    return Some(
                        self.state
                            .players
                            .iter()
                            .filter(|player| !player.has_lost && player.id != player_id)
                            .flat_map(|player| player.battlefield.iter())
                            .filter(|card| {
                                matches_card_filter(&card.definition, &expression["where"])
                            })
                            .count() as i32,
                    );
                }
                let value = self.numeric_expression(expression, &player_id)?;
                if value_kind(expression) == Some("countPermanents")
                    && expression["excludeSource"].as_bool() == Some(true)
                {
                    self.exclude_current_source_from_count(
                        value,
                        Some(&stack_object.card),
                        source_lki::source_has_departed(stack_object),
                        |current, current_player| {
                            let player_in_scope =
                                if expression["allPlayers"].as_bool() == Some(true) {
                                    self.player_index(current_player)
                                        .ok()
                                        .is_some_and(|index| !self.state.players[index].has_lost)
                                } else {
                                    current_player == player_id
                                };
                            let ownership_matches = match expression["ownership"].as_str() {
                                Some("owned") => current.owner == player_id,
                                Some("notOwned") => current.owner != player_id,
                                _ => true,
                            };
                            player_in_scope
                                && ownership_matches
                                && self.permanent_state_matches(current, &expression["where"])
                        },
                    )
                } else {
                    Some(value)
                }
            }
            Some("countPlaneswalkerTypes") => {
                let player_id = self
                    .resolve_player(&expression["player"], stack_object, bindings)
                    .unwrap_or_else(|| stack_object.controller.clone());
                let player_index = self.player_index(&player_id).ok()?;
                let types = self.state.players[player_index]
                    .battlefield
                    .iter()
                    .filter(|card| has_card_type(&card.definition, "Planeswalker"))
                    .flat_map(|card| {
                        card.definition
                            .type_line
                            .split_once(" - ")
                            .map(|(_, subtypes)| {
                                subtypes
                                    .split_whitespace()
                                    .map(str::to_string)
                                    .collect::<Vec<_>>()
                            })
                            .unwrap_or_default()
                    })
                    .collect::<BTreeSet<_>>();
                i32::try_from(types.len()).ok()
            }
            Some("triggeringPermanentCounterCount") => {
                stack_object.decisions["triggeringPermanentCounterCount"]
                    .as_i64()
                    .and_then(|value| i32::try_from(value).ok())
            }
            Some("deadPermanentPower") => stack_object.decisions["deadPermanentPower"]
                .as_i64()
                .and_then(|value| i32::try_from(value).ok()),
            Some("countOpponents" | "countOpponentsAttackedThisCombat") => {
                self.numeric_expression(expression, &stack_object.controller)
            }
            // CR 700.5: the devotion of the player the expression names.
            Some("devotion") => {
                let player = self.resolve_player(&expression["player"], stack_object, bindings)?;
                self.numeric_expression(expression, &player)
            }
            Some("sourceCastXValue") => {
                self.source_cast_x_value(&stack_object.card.instance_id, decisions)
            }
            Some("countOpponentsWithPermanent") => {
                let controller = expression
                    .get("player")
                    .and_then(|player| self.resolve_player(player, stack_object, bindings))
                    .unwrap_or_else(|| stack_object.controller.clone());
                Some(
                    self.state
                        .players
                        .iter()
                        .filter(|player| !player.has_lost && player.id != controller)
                        .filter(|player| {
                            player.battlefield.iter().any(|permanent| {
                                self.permanent_matches_effective_filter(
                                    permanent,
                                    &expression["where"],
                                )
                            })
                        })
                        .count() as i32,
                )
            }
            Some("countPlayers") => i32::try_from(
                self.state
                    .players
                    .iter()
                    .filter(|player| !player.has_lost)
                    .count(),
            )
            .ok(),
            Some("minimumHandSize" | "greatestHandSize" | "greatestOpponentHandSize") => {
                self.numeric_expression(expression, &stack_object.controller)
            }
            Some("lifeGainedThisTurn" | "lifeLostThisTurn" | "countPlayerZonesByCardCount") => {
                self.numeric_expression(expression, &stack_object.controller)
            }
            Some("lifeTotal") => {
                let player_id = expression
                    .get("player")
                    .and_then(|player| self.resolve_player(player, stack_object, bindings))
                    .unwrap_or_else(|| stack_object.controller.clone());
                self.numeric_expression(
                    &json!({
                        "kind": "lifeTotal",
                        "player": { "kind": "controller" },
                    }),
                    &player_id,
                )
            }
            Some("countCounters") => {
                let instance_id = match value_kind(&expression["object"]) {
                    Some("self" | "abilitySource") => stack_object.card.instance_id.clone(),
                    _ => self
                        .resolve_target(&expression["object"], stack_object, bindings)
                        .and_then(|target| match target {
                            TargetRef::Permanent { instance_id } => Some(instance_id),
                            _ => None,
                        })?,
                };
                self.permanent_position(&instance_id)
                    .map(|(player_index, card_index)| {
                        let counters =
                            &self.state.players[player_index].battlefield[card_index].counters;
                        expression["counter"].as_str().map_or_else(
                            || counters.values().copied().sum(),
                            |counter| counters.get(counter).copied().unwrap_or(0),
                        )
                    })
                    .or_else(|| {
                        let counters = &stack_object.card.counters;
                        Some(expression["counter"].as_str().map_or_else(
                            || counters.values().copied().sum(),
                            |counter| counters.get(counter).copied().unwrap_or(0),
                        ))
                    })
            }
            Some("countAttachments") => self.numeric_expression_with_source_and_decisions(
                expression,
                &stack_object.controller,
                Some(&stack_object.card),
                decisions,
            ),
            Some("abilitySourceLastKnownPower") => {
                let triggering_source_matches = stack_object.decisions["triggeringPermanentId"]
                    .as_str()
                    == Some(stack_object.card.instance_id.as_str());
                if triggering_source_matches {
                    stack_object.decisions["triggeringPermanentPower"]
                        .as_i64()
                        .and_then(|value| i32::try_from(value).ok())
                } else {
                    self.permanent_position(&stack_object.card.instance_id).map(
                        |(player_index, card_index)| {
                            self.current_power(
                                &self.state.players[player_index].battlefield[card_index],
                            )
                        },
                    )
                }
            }
            Some("powerOf" | "toughnessOf") => match value_kind(&expression["object"]) {
                Some("self" | "abilitySource") => {
                    let live_source = self.permanent_position(&stack_object.card.instance_id).map(
                        |(player_index, card_index)| {
                            &self.state.players[player_index].battlefield[card_index]
                        },
                    );
                    numeric_evaluation::evaluate_source_property(
                        value_kind(expression)?,
                        live_source,
                        stack_object,
                        |source| self.current_power(source),
                        |source| self.current_toughness(source),
                    )
                }
                _ => {
                    let TargetRef::Permanent { instance_id } =
                        self.resolve_target(&expression["object"], stack_object, bindings)?
                    else {
                        return None;
                    };
                    self.permanent_position(&instance_id)
                        .map(|(player_index, card_index)| {
                            let permanent =
                                &self.state.players[player_index].battlefield[card_index];
                            if value_kind(expression) == Some("powerOf") {
                                self.current_power(permanent)
                            } else {
                                self.current_toughness(permanent)
                            }
                        })
                }
            },
            Some("counterCountOf") => {
                let counter = expression["counter"].as_str()?;
                let permanent = match value_kind(&expression["object"]) {
                    Some("self" | "abilitySource") => self
                        .permanent_position(&stack_object.card.instance_id)
                        .map(|(player_index, card_index)| {
                            &self.state.players[player_index].battlefield[card_index]
                        })
                        .or(Some(&stack_object.card)),
                    _ => {
                        let TargetRef::Permanent { instance_id } =
                            self.resolve_target(&expression["object"], stack_object, bindings)?
                        else {
                            return None;
                        };
                        self.permanent_position(&instance_id)
                            .map(|(player_index, card_index)| {
                                &self.state.players[player_index].battlefield[card_index]
                            })
                    }
                }?;
                permanent.counters.get(counter).copied().or(Some(0))
            }
            Some("manaValueOf") => {
                let target = self.resolve_target(&expression["object"], stack_object, bindings)?;
                match target {
                    TargetRef::Permanent { instance_id } => self
                        .permanent_position(&instance_id)
                        .map(|(player_index, card_index)| {
                            mana_value(
                                &self.state.players[player_index].battlefield[card_index]
                                    .definition,
                            )
                        }),
                    TargetRef::Card { instance_id } => self
                        .card_outside_battlefield(&instance_id)
                        .map(|card| mana_value(&card.definition)),
                    TargetRef::StackObject { stack_id } => self
                        .state
                        .stack
                        .iter()
                        .find(|object| object.id == stack_id)
                        .map(|object| mana_value(&object.card.definition)),
                    TargetRef::Player { .. } => None,
                }
            }
            Some("boundValue") => expression["id"]
                .as_str()
                .and_then(|id| bindings.get(id))
                .and_then(|binding| match binding {
                    RuntimeBinding::Integer(value) => Some(*value),
                    RuntimeBinding::Objects(objects) => i32::try_from(objects.len()).ok(),
                    _ => None,
                }),
            Some("decisionResult") => expression["decisionId"]
                .as_str()
                .and_then(|id| decisions.get(id))
                .and_then(Value::as_i64)
                .and_then(|value| i32::try_from(value).ok()),
            Some("triggeringSpellManaValue") => decisions
                .get("triggeringSpellManaValue")
                .and_then(Value::as_i64)
                .and_then(|value| i32::try_from(value).ok()),
            Some("triggeringSpellManaSpent") => decisions
                .get("triggeringSpellManaSpent")
                .and_then(Value::as_i64)
                .and_then(|value| i32::try_from(value).ok()),
            Some("manaSpentToCastSource") => Some(mana_spent_from_cast_decisions(decisions)),
            Some("manaSpentToCast") => self.runtime_mana_spent_to_cast(expression, stack_object),
            Some("opponentExtremum") => self.opponent_extremum(expression, &stack_object.controller),
            Some("colorsOfManaSpentToCastSource") => {
                Some(mana_colors_spent_from_cast_decisions(decisions))
            }
            Some("countDecisionCardsMatching") => {
                let decision_id = expression["decisionId"].as_str()?;
                let count = decisions
                    .get(decision_id)?
                    .as_array()?
                    .iter()
                    .filter_map(Value::as_str)
                    .filter_map(|instance_id| self.card_outside_battlefield(instance_id))
                    .filter(|card| matches_card_filter(&card.definition, &expression["where"]))
                    .count();
                i32::try_from(count).ok()
            }
            Some("countObjects") => self
                .resolve_runtime_object_ids(
                    &expression["objects"],
                    stack_object,
                    bindings,
                    decisions,
                )
                .and_then(|objects| i32::try_from(objects.len()).ok()),
            Some("maximumManaValue") => self
                .resolve_object_ids(&expression["collection"], bindings, decisions)
                .and_then(|objects| {
                    objects
                        .iter()
                        .filter_map(|instance_id| {
                            self.permanent_position(instance_id)
                                .map(|(player_index, card_index)| {
                                    &self.state.players[player_index].battlefield[card_index]
                                })
                                .or_else(|| self.card_outside_battlefield(instance_id))
                                .or_else(|| {
                                    self.state
                                        .stack
                                        .iter()
                                        .find(|object| object.card.instance_id == *instance_id)
                                        .map(|object| &object.card)
                                })
                                .map(|card| mana_value(&card.definition))
                        })
                        .max()
                }),
            Some("minimum" | "maximum") => {
                let values = expression["operands"]
                    .as_array()?
                    .iter()
                    .map(|operand| {
                        self.runtime_numeric_expression(operand, stack_object, bindings, decisions)
                    })
                    .collect::<Option<Vec<_>>>()?;
                if value_kind(expression) == Some("minimum") {
                    values.into_iter().min()
                } else {
                    values.into_iter().max()
                }
            }
            Some("conditionalValue") => {
                let branch = if self.condition_value(
                    &expression["condition"],
                    &stack_object.controller,
                    decisions,
                ) {
                    &expression["ifTrue"]
                } else {
                    &expression["ifFalse"]
                };
                self.runtime_numeric_expression(branch, stack_object, bindings, decisions)
            }
            _ => None,
        }
    }

    fn materialize_runtime_numeric_expressions(
        &self,
        value: &Value,
        stack_object: &StackObject,
        bindings: &BTreeMap<String, RuntimeBinding>,
        decisions: &BTreeMap<String, Value>,
    ) -> Value {
        if value_kind(value).is_some()
            && numeric_expression_supported(value)
            && let Some(result) =
                self.runtime_numeric_expression(value, stack_object, bindings, decisions)
        {
            return json!({ "kind": "integer", "value": result });
        }
        match value {
            Value::Array(values) => Value::Array(
                values
                    .iter()
                    .map(|nested| {
                        self.materialize_runtime_numeric_expressions(
                            nested,
                            stack_object,
                            bindings,
                            decisions,
                        )
                    })
                    .collect(),
            ),
            Value::Object(object) => Value::Object(
                object
                    .iter()
                    .map(|(key, nested)| {
                        (
                            key.clone(),
                            self.materialize_runtime_numeric_expressions(
                                nested,
                                stack_object,
                                bindings,
                                decisions,
                            ),
                        )
                    })
                    .collect(),
            ),
            _ => value.clone(),
        }
    }

    fn value_references_transient_runtime_binding(value: &Value) -> bool {
        if matches!(
            value_kind(value),
            Some(
                "boundObjects"
                    | "boundValue"
                    | "countBoundObjects"
                    | "decisionResult"
                    | "countDecisionCardsMatching"
                    | "triggeringPermanentCounterCount"
                    | "deadPermanentPower"
                    | "countManaSymbolsInTriggeringSpell"
                    | "abilitySourceLastKnownPower"
                    | "triggeringSpellManaValue"
                    | "triggeringSpellManaSpent"
                    | "manaSpentToCastSource"
                    | "colorsOfManaSpentToCastSource"
                    | "sourceCastXValue"
                    | "powerDifferenceOfChosenObjects"
            )
        ) {
            return true;
        }
        match value {
            Value::Array(values) => values
                .iter()
                .any(Self::value_references_transient_runtime_binding),
            Value::Object(values) => values
                .values()
                .any(Self::value_references_transient_runtime_binding),
            _ => false,
        }
    }

    /// Freezes only numeric values backed by transient effect bindings before
    /// a reflexive ability leaves the resolving effect's binding scope. Live
    /// game-state expressions remain in the nested rule and are evaluated by
    /// the intervening-if check both when the trigger is created and resolves.
    fn materialize_reflexive_numeric_expressions(
        &self,
        value: &Value,
        stack_object: &StackObject,
        bindings: &BTreeMap<String, RuntimeBinding>,
        decisions: &BTreeMap<String, Value>,
    ) -> Value {
        if value_kind(value).is_some()
            && numeric_expression_supported(value)
            && Self::value_references_transient_runtime_binding(value)
            && let Some(result) =
                self.runtime_numeric_expression(value, stack_object, bindings, decisions)
        {
            return json!({ "kind": "integer", "value": result });
        }
        match value {
            Value::Array(values) => Value::Array(
                values
                    .iter()
                    .map(|nested| {
                        self.materialize_reflexive_numeric_expressions(
                            nested,
                            stack_object,
                            bindings,
                            decisions,
                        )
                    })
                    .collect(),
            ),
            Value::Object(object) => Value::Object(
                object
                    .iter()
                    .map(|(key, nested)| {
                        (
                            key.clone(),
                            self.materialize_reflexive_numeric_expressions(
                                nested,
                                stack_object,
                                bindings,
                                decisions,
                            ),
                        )
                    })
                    .collect(),
            ),
            _ => value.clone(),
        }
    }

    fn materialize_runtime_object_bindings(
        &self,
        value: &Value,
        bindings: &BTreeMap<String, RuntimeBinding>,
    ) -> Value {
        if value_kind(value) == Some("boundObjects")
            && let Some(binding_id) = value["binding"].as_str()
            && matches!(bindings.get(binding_id), Some(RuntimeBinding::Objects(_)))
        {
            return json!({ "kind": "decisionResult", "decisionId": binding_id });
        }
        match value {
            Value::Array(values) => Value::Array(
                values
                    .iter()
                    .map(|nested| self.materialize_runtime_object_bindings(nested, bindings))
                    .collect(),
            ),
            Value::Object(object) => Value::Object(
                object
                    .iter()
                    .map(|(key, nested)| {
                        (
                            key.clone(),
                            self.materialize_runtime_object_bindings(nested, bindings),
                        )
                    })
                    .collect(),
            ),
            _ => value.clone(),
        }
    }

    fn materialize_runtime_target_bindings(
        &self,
        value: &Value,
        bindings: &BTreeMap<String, RuntimeBinding>,
    ) -> Value {
        if value_kind(value) == Some("boundValue")
            && let Some(binding_id) = value["id"].as_str()
            && matches!(bindings.get(binding_id), Some(RuntimeBinding::Target(_)))
        {
            return json!({ "kind": "chosenTarget", "id": binding_id });
        }
        match value {
            Value::Array(values) => Value::Array(
                values
                    .iter()
                    .map(|nested| self.materialize_runtime_target_bindings(nested, bindings))
                    .collect(),
            ),
            Value::Object(object) => Value::Object(
                object
                    .iter()
                    .map(|(key, nested)| {
                        (
                            key.clone(),
                            self.materialize_runtime_target_bindings(nested, bindings),
                        )
                    })
                    .collect(),
            ),
            _ => value.clone(),
        }
    }

    fn resolve_object_ids(
        &self,
        expression: &Value,
        bindings: &BTreeMap<String, RuntimeBinding>,
        decisions: &BTreeMap<String, Value>,
    ) -> Option<Vec<String>> {
        match value_kind(expression) {
            Some("boundObjects") => expression["binding"]
                .as_str()
                .and_then(|id| bindings.get(id))
                .and_then(|binding| match binding {
                    RuntimeBinding::Objects(objects) => Some(objects.clone()),
                    _ => None,
                }),
            Some("decisionResult") => expression["decisionId"]
                .as_str()
                .and_then(|id| decisions.get(id))
                .and_then(Value::as_array)
                .map(|values| {
                    values
                        .iter()
                        .filter_map(Value::as_str)
                        .map(ToOwned::to_owned)
                        .collect()
                }),
            Some("setDifference") => {
                let left = self.resolve_object_ids(&expression["left"], bindings, decisions)?;
                let right = self
                    .resolve_object_ids(&expression["right"], bindings, decisions)?
                    .into_iter()
                    .collect::<BTreeSet<_>>();
                Some(
                    left.into_iter()
                        .filter(|object| !right.contains(object))
                        .collect(),
                )
            }
            Some("filterObjects") => {
                let mut objects =
                    self.resolve_object_ids(&expression["objects"], bindings, decisions)?;
                objects.retain(|instance_id| {
                    self.card_outside_battlefield(instance_id)
                        .or_else(|| {
                            self.permanent_position(instance_id).map(
                                |(player_index, card_index)| {
                                    &self.state.players[player_index].battlefield[card_index]
                                },
                            )
                        })
                        .is_some_and(|card| {
                            matches_card_filter(&card.definition, &expression["where"])
                        })
                });
                Some(objects)
            }
            _ => None,
        }
    }

    fn runtime_card_filter_matches(
        &self,
        card: &CardDefinition,
        filter: &Value,
        stack_object: &StackObject,
        bindings: &BTreeMap<String, RuntimeBinding>,
        decisions: &BTreeMap<String, Value>,
    ) -> bool {
        self.runtime_object_filter_matches(
            runtime_object_filter::ObjectFilterView::Definition(
                object_predicate::DefinitionView::new(card),
            ),
            filter,
            stack_object,
            bindings,
            decisions,
        )
    }

    /// Historical Option adapter. Checked consumers preserve query errors.
    fn resolve_runtime_object_ids(
        &self,
        expression: &Value,
        stack_object: &StackObject,
        bindings: &BTreeMap<String, RuntimeBinding>,
        decisions: &BTreeMap<String, Value>,
    ) -> Option<Vec<String>> {
        self.resolve_runtime_object_ids_checked(expression, stack_object, bindings, decisions)
            .ok()
    }

    pub(super) fn resolve_runtime_object_ids_atom(
        &self,
        expression: &Value,
        stack_object: &StackObject,
        bindings: &BTreeMap<String, RuntimeBinding>,
        decisions: &BTreeMap<String, Value>,
    ) -> Option<Vec<String>> {
        match value_kind(expression) {
            Some("opponentsOf") => {
                let player_id =
                    self.resolve_player(&expression["player"], stack_object, bindings)?;
                Some(
                    self.state
                        .players
                        .iter()
                        .filter(|player| !player.has_lost && player.id != player_id)
                        .map(|player| player.id.clone())
                        .collect(),
                )
            }
            Some("self" | "abilitySource") => Some(vec![stack_object.card.instance_id.clone()]),
            // The top N cards of a library, top first (CR 401.2). The set is
            // identified when evaluated; a `bind` fixes it for later verbs.
            Some("libraryTopCards") => {
                let player_id =
                    self.resolve_player(&expression["zone"]["player"], stack_object, bindings)?;
                let player_index = self.player_index(&player_id).ok()?;
                let count = self
                    .checked_runtime_numeric_expression(
                        &expression["count"],
                        stack_object,
                        bindings,
                        decisions,
                        "libraryTopCards.count",
                    )
                    .ok()?
                    .max(0) as usize;
                Some(
                    self.state.players[player_index]
                        .library
                        .iter()
                        .rev()
                        .take(count)
                        .map(|card| card.instance_id.clone())
                        .collect(),
                )
            }
            Some("attachedObject") if value_kind(&expression["attachment"]) == Some("self") => {
                stack_object
                    .card
                    .attached_to
                    .as_ref()
                    .map(|instance_id| vec![instance_id.clone()])
            }
            Some("chosenTargets" | "chosenObjects") => {
                let decision_id = expression["id"].as_str()?;
                Some(
                    stack_object
                        .targets
                        .iter()
                        .filter(|(target_id, _)| {
                            target_id.as_str() == decision_id
                                || target_id.starts_with(&format!("{decision_id}:"))
                        })
                        .filter_map(|(_, target)| match target {
                            TargetRef::Permanent { instance_id }
                            | TargetRef::Card { instance_id } => Some(instance_id.clone()),
                            TargetRef::StackObject { stack_id } => Some(stack_id.clone()),
                            TargetRef::Player { .. } => None,
                        })
                        .collect(),
                )
            }
            Some("cardsDrawnThisTurn") => {
                let player_id =
                    self.resolve_player(&expression["player"], stack_object, bindings)?;
                let zone_player_id =
                    self.resolve_player(&expression["zone"]["player"], stack_object, bindings)?;
                if player_id != zone_player_id || value_kind(&expression["zone"]) != Some("hand") {
                    return None;
                }
                let player_index = self.player_index(&player_id).ok()?;
                let cards_in_hand = self.state.players[player_index]
                    .hand
                    .iter()
                    .map(|card| card.instance_id.as_str())
                    .collect::<BTreeSet<_>>();
                let mut drawn = Vec::new();
                for instance_id in self
                    .state
                    .events
                    .iter()
                    .filter(|event| {
                        event.turn_number == self.state.turn_number
                            && event.kind == "cardDrawn"
                            && event.player_id.as_deref() == Some(player_id.as_str())
                    })
                    .filter_map(|event| event.card_instance_id.as_ref())
                {
                    if cards_in_hand.contains(instance_id.as_str()) && !drawn.contains(instance_id)
                    {
                        drawn.push(instance_id.clone());
                    }
                }
                Some(drawn)
            }
            Some("triggeringCard") => Some(self.event_card_ids(stack_object)),
            Some("cardsExiledWithSource") => Some(
                self.state
                    .rule_modifiers
                    .iter()
                    .filter(|modifier| {
                        value_kind(modifier) == Some("exiledWithSource")
                            && modifier["sourceCardInstanceId"].as_str()
                                == Some(stack_object.card.instance_id.as_str())
                    })
                    .filter_map(|modifier| modifier["cardInstanceId"].as_str())
                    .filter(|instance_id| self.card_zone_owner_id(instance_id, "exile").is_some())
                    .map(ToOwned::to_owned)
                    .collect(),
            ),
            _ => None,
        }
    }

    fn resolution_selections(objects: &[String], count: usize, maximum: usize) -> Vec<Vec<String>> {
        fn choose(
            objects: &[String],
            start: usize,
            remaining: usize,
            selected: &mut Vec<String>,
            selections: &mut Vec<Vec<String>>,
            maximum: usize,
        ) {
            if remaining == 0 {
                selections.push(selected.clone());
                return;
            }
            if objects.len().saturating_sub(start) < remaining || selections.len() >= maximum {
                return;
            }
            let last_start = objects.len() - remaining;
            for index in start..=last_start {
                selected.push(objects[index].clone());
                choose(
                    objects,
                    index + 1,
                    remaining - 1,
                    selected,
                    selections,
                    maximum,
                );
                selected.pop();
                if selections.len() >= maximum {
                    return;
                }
            }
        }

        if count > objects.len() {
            return Vec::new();
        }
        let mut selections = Vec::new();
        choose(objects, 0, count, &mut Vec::new(), &mut selections, maximum);
        selections
    }

    fn target_selections(
        targets: &[TargetRef],
        count: usize,
        maximum: usize,
    ) -> Vec<Vec<TargetRef>> {
        fn choose(
            targets: &[TargetRef],
            start: usize,
            remaining: usize,
            selected: &mut Vec<TargetRef>,
            selections: &mut Vec<Vec<TargetRef>>,
            maximum: usize,
        ) {
            if remaining == 0 {
                selections.push(selected.clone());
                return;
            }
            if targets.len().saturating_sub(start) < remaining || selections.len() >= maximum {
                return;
            }
            let last_start = targets.len() - remaining;
            for index in start..=last_start {
                selected.push(targets[index].clone());
                choose(
                    targets,
                    index + 1,
                    remaining - 1,
                    selected,
                    selections,
                    maximum,
                );
                selected.pop();
                if selections.len() >= maximum {
                    return;
                }
            }
        }

        if count > targets.len() || maximum == 0 {
            return Vec::new();
        }
        let mut selections = Vec::new();
        choose(targets, 0, count, &mut Vec::new(), &mut selections, maximum);
        selections
    }

    fn resolution_orders(objects: &[String], maximum: usize) -> Vec<Vec<String>> {
        fn permute(
            remaining: &mut Vec<String>,
            selected: &mut Vec<String>,
            orders: &mut Vec<Vec<String>>,
            maximum: usize,
        ) {
            if remaining.is_empty() {
                orders.push(selected.clone());
                return;
            }
            for index in 0..remaining.len() {
                let object = remaining.remove(index);
                selected.push(object.clone());
                permute(remaining, selected, orders, maximum);
                selected.pop();
                remaining.insert(index, object);
                if orders.len() >= maximum {
                    return;
                }
            }
        }

        let mut orders = Vec::new();
        permute(&mut objects.to_vec(), &mut Vec::new(), &mut orders, maximum);
        orders
    }

    fn make_resolution_decision<P: DecisionProvider>(
        &mut self,
        decision_id: &str,
        player_id: &str,
        source: &StackObject,
        choice: DecisionChoice,
        values: Vec<Vec<String>>,
        decisions: &mut BTreeMap<String, Value>,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        self.check_quantity_failure()?;
        let Some(first) = values.first() else {
            return Err(EngineError::new(format!(
                "resolution decision {decision_id} has no legal values"
            )));
        };
        let observes_another_players_hand = match &choice {
            DecisionChoice::CardSelection {
                candidate_card_instance_ids,
                ..
            } => self.state.players.iter().any(|player| {
                player.id != player_id
                    && player
                        .hand
                        .iter()
                        .any(|card| candidate_card_instance_ids.contains(&card.instance_id))
            }),
            _ => false,
        };
        let selected = if values.len() == 1 && !observes_another_players_hand {
            first.clone()
        } else {
            let is_card_order = matches!(&choice, DecisionChoice::CardOrder { .. });
            let options = values
                .iter()
                .enumerate()
                .map(|(index, value)| {
                    let card_names = if matches!(&choice, DecisionChoice::OptionSelection { .. }) {
                        value.clone()
                    } else {
                        value
                            .iter()
                            .map(|instance_id| self.card_name_for_instance(instance_id))
                            .collect::<Vec<_>>()
                    };
                    let mut option_decisions = BTreeMap::new();
                    option_decisions.insert(
                        decision_id.to_string(),
                        Value::Array(value.iter().cloned().map(Value::String).collect()),
                    );
                    LegalAction {
                        id: format!("resolve:{}:{decision_id}:{index}", source.id),
                        kind: ActionKind::ChooseResolution,
                        player_id: player_id.to_string(),
                        label: if is_card_order {
                            format!("Order cards: {}", card_names.join(" -> "))
                        } else if card_names.is_empty() {
                            "Choose no cards".to_string()
                        } else {
                            format!("Choose {}", card_names.join(", "))
                        },
                        card_instance_id: Some(source.card.instance_id.clone()),
                        payment_sources: Vec::new(),
                        decisions: option_decisions,
                        targets: BTreeMap::new(),
                        target_order: Vec::new(),
                        attacker_id: None,
                        blocker_id: None,
                    }
                })
                .collect();
            let is_card_choice = matches!(
                &choice,
                DecisionChoice::CardSelection { .. } | DecisionChoice::CardOrder { .. }
            );
            let request = EngineDecisionRequest {
                id: format!("resolution:{}:{decision_id}", source.id),
                kind: DecisionKind::ResolutionChoice,
                player_id: player_id.to_string(),
                source_card: Some(source.card.clone()),
                source_card_instance_id: Some(source.card.instance_id.clone()),
                choice: Some(choice),
                options,
            };
            if is_card_choice {
                if request.options.len() > 1 {
                    self.branching_decision_sequence
                        .set(self.branching_decision_sequence.get().saturating_add(1));
                }
                self.check_quantity_failure()?;
                let selected = provider.choose_card_instance_ids(&self.state, &request)?;
                validate_decision_card_instance_ids(&request, &selected)?;
                selected
            } else {
                let choice = self.choose_action(provider, request)?;
                choice
                    .decisions
                    .get(decision_id)
                    .and_then(Value::as_array)
                    .map(|values| {
                        values
                            .iter()
                            .filter_map(Value::as_str)
                            .map(ToOwned::to_owned)
                            .collect()
                    })
                    .ok_or_else(|| {
                        EngineError::new(format!(
                            "resolution decision {decision_id} returned no value"
                        ))
                    })?
            }
        };

        decisions.insert(
            decision_id.to_string(),
            Value::Array(selected.iter().cloned().map(Value::String).collect()),
        );
        self.record_event(
            "resolutionChoiceMade",
            Some(player_id.to_string()),
            Some(source.card.instance_id.clone()),
            json!({
                "decisionId": decision_id,
                "selected": selected,
                "stackId": source.id,
            }),
        );
        Ok(())
    }

    fn visible_card_name_suggestions(
        &self,
        player_id: &str,
        card_filter: &Value,
        fallback_name: &str,
    ) -> Vec<String> {
        let known_hand_card_ids = self
            .state
            .rule_modifiers
            .iter()
            .filter(|modifier| {
                value_kind(modifier) == Some("knownHandCards")
                    && modifier["viewerId"]
                        .as_str()
                        .is_none_or(|viewer_id| viewer_id == player_id)
            })
            .flat_map(|modifier| modifier["cardInstanceIds"].as_array().into_iter().flatten())
            .filter_map(Value::as_str)
            .collect::<BTreeSet<_>>();
        let mut names = self
            .state
            .players
            .iter()
            .flat_map(|player| {
                player
                    .battlefield
                    .iter()
                    .chain(&player.graveyard)
                    .chain(&player.exile)
                    .chain(&player.command_zone)
                    .chain(player.hand.iter().filter(|card| {
                        player.id == player_id
                            || known_hand_card_ids.contains(card.instance_id.as_str())
                    }))
            })
            .chain(self.state.stack.iter().map(|object| &object.card))
            .filter(|card| matches_card_filter(&card.definition, card_filter))
            .map(|card| card.definition.name.clone())
            .collect::<BTreeSet<_>>();
        if !fallback_name.trim().is_empty() {
            names.insert(fallback_name.to_string());
        }
        names.into_iter().collect()
    }

    fn make_card_name_decision<P: DecisionProvider>(
        &mut self,
        decision_id: &str,
        player_id: &str,
        source: &StackObject,
        card_filter: &Value,
        decisions: &mut BTreeMap<String, Value>,
        provider: &mut P,
    ) -> Result<String, EngineError> {
        let suggestions = self.visible_card_name_suggestions(
            player_id,
            card_filter,
            &source.card.definition.name,
        );
        let options = suggestions
            .iter()
            .enumerate()
            .map(|(index, name)| LegalAction {
                id: format!("resolve:{}:{decision_id}:name:{index}", source.id),
                kind: ActionKind::ChooseResolution,
                player_id: player_id.to_string(),
                label: format!("Choose {name}"),
                card_instance_id: Some(source.card.instance_id.clone()),
                payment_sources: Vec::new(),
                decisions: BTreeMap::from([(
                    decision_id.to_string(),
                    Value::Array(vec![Value::String(name.clone())]),
                )]),
                targets: BTreeMap::new(),
                target_order: Vec::new(),
                attacker_id: None,
                blocker_id: None,
            })
            .collect::<Vec<_>>();
        let request = EngineDecisionRequest {
            id: format!("resolution:{}:{decision_id}", source.id),
            kind: DecisionKind::ResolutionChoice,
            player_id: player_id.to_string(),
            source_card: Some(source.card.clone()),
            source_card_instance_id: Some(source.card.instance_id.clone()),
            choice: Some(DecisionChoice::CardNameSelection {
                decision_id: decision_id.to_string(),
                suggestions,
                prompt: "Choose a card name.".to_string(),
            }),
            options,
        };
        self.check_quantity_failure()?;
        let selected = provider.choose_card_name(&self.state, &request)?;
        let selected = selected.trim();
        if selected.is_empty()
            || selected.chars().count() > 256
            || selected.chars().any(char::is_control)
        {
            return Err(EngineError::new(
                "card name must contain 1 to 256 printable characters",
            ));
        }
        let selected = selected.to_string();
        decisions.insert(
            decision_id.to_string(),
            Value::Array(vec![Value::String(selected.clone())]),
        );
        self.record_event(
            "resolutionChoiceMade",
            Some(player_id.to_string()),
            Some(source.card.instance_id.clone()),
            json!({
                "decisionId": decision_id,
                "selected": [selected.clone()],
                "stackId": source.id,
            }),
        );
        Ok(selected)
    }

    fn choose_resolution_target<P: DecisionProvider>(
        &mut self,
        decision_id: &str,
        candidates: &Value,
        source: &StackObject,
        optional: bool,
        provider: &mut P,
    ) -> Result<Option<TargetRef>, EngineError> {
        let mut targets = self
            .target_candidates(&source.controller, candidates)
            .unwrap_or_default();
        if candidates["excludeSource"].as_bool().unwrap_or(false) {
            targets.retain(|target| {
                !matches!(
                    target,
                    TargetRef::Permanent { instance_id }
                        if instance_id == &source.card.instance_id
                )
            });
        }
        let mut options = Vec::new();
        if optional {
            options.push(LegalAction {
                id: format!("resolve:{}:{decision_id}:decline", source.id),
                kind: ActionKind::ChooseResolution,
                player_id: source.controller.clone(),
                label: "Choose no target".to_string(),
                card_instance_id: Some(source.card.instance_id.clone()),
                payment_sources: Vec::new(),
                decisions: BTreeMap::new(),
                targets: BTreeMap::new(),
                target_order: Vec::new(),
                attacker_id: None,
                blocker_id: None,
            });
        }
        options.extend(targets.into_iter().enumerate().map(|(index, target)| {
            let label = match &target {
                TargetRef::Player { player_id } => player_id.clone(),
                TargetRef::Permanent { instance_id } | TargetRef::Card { instance_id } => {
                    self.card_name_for_instance(instance_id)
                }
                TargetRef::StackObject { stack_id } => self
                    .state
                    .stack
                    .iter()
                    .find(|object| object.id == *stack_id)
                    .map(|object| object.card.definition.name.clone())
                    .unwrap_or_else(|| stack_id.clone()),
            };
            LegalAction {
                id: format!("resolve:{}:{decision_id}:{index}", source.id),
                kind: ActionKind::ChooseResolution,
                player_id: source.controller.clone(),
                label: format!("Choose {label}"),
                card_instance_id: Some(source.card.instance_id.clone()),
                payment_sources: Vec::new(),
                decisions: BTreeMap::new(),
                targets: BTreeMap::from([(decision_id.to_string(), target)]),
                target_order: vec![decision_id.to_string()],
                attacker_id: None,
                blocker_id: None,
            }
        }));
        if options.is_empty() {
            return Ok(None);
        }
        if options.len() == 1 {
            return Ok(options[0].targets.get(decision_id).cloned());
        }
        let choice = self.choose_action(
            provider,
            EngineDecisionRequest {
                id: format!("resolution:{}:{decision_id}", source.id),
                kind: DecisionKind::ResolutionChoice,
                player_id: source.controller.clone(),
                source_card: Some(source.card.clone()),
                source_card_instance_id: Some(source.card.instance_id.clone()),
                choice: None,
                options,
            },
        )?;
        Ok(choice.targets.get(decision_id).cloned())
    }

    fn take_card_from_player_zones(
        player: &mut EnginePlayer,
        instance_id: &str,
    ) -> Option<CardInstance> {
        for zone in [
            &mut player.library,
            &mut player.hand,
            &mut player.graveyard,
            &mut player.exile,
            &mut player.sideboard,
            &mut player.command_zone,
        ] {
            if let Some(index) = zone.iter().position(|card| card.instance_id == instance_id) {
                let mut card = zone.remove(index);
                Self::clear_tracked_zone_identity(&mut card);
                return Some(card);
            }
        }
        None
    }

    fn take_card_from_player_named_zone(
        player: &mut EnginePlayer,
        zone_name: &str,
        instance_id: &str,
    ) -> Option<CardInstance> {
        let zone = match zone_name {
            "library" => &mut player.library,
            "hand" => &mut player.hand,
            "graveyard" => &mut player.graveyard,
            "exile" => &mut player.exile,
            _ => return None,
        };
        let index = zone
            .iter()
            .position(|card| card.instance_id == instance_id)?;
        let mut card = zone.remove(index);
        Self::clear_tracked_zone_identity(&mut card);
        Some(card)
    }

    fn move_card_to_exile(
        &mut self,
        instance_id: &str,
        from_zone: &str,
        from_player_id: &str,
        reason: &str,
    ) -> Result<bool, EngineError> {
        let from_player_index = self.player_index(from_player_id)?;
        let source_zone = match from_zone {
            "graveyard" => &mut self.state.players[from_player_index].graveyard,
            "hand" => &mut self.state.players[from_player_index].hand,
            _ => return Ok(false),
        };
        let Some(card_index) = source_zone
            .iter()
            .position(|card| card.instance_id == instance_id)
        else {
            return Ok(false);
        };
        let mut card =
            self.take_zone_card_for_movement(from_player_index, from_zone, card_index)?;
        let owner_id = card.owner.clone();
        let owner_index = self.player_index(&owner_id)?;
        card_zone_transition::reset_owned_movement_card(&mut card)?;
        card.controller = owner_id.clone();
        card.flags.insert("faceDown".to_string(), false);
        self.put_owned_card_into_exile(owner_index, card)?;
        self.record_event(
            "cardExiled",
            Some(from_player_id.to_string()),
            Some(instance_id.to_string()),
            json!({ "from": from_zone, "reason": reason }),
        );
        if from_zone == "graveyard" {
            self.enqueue_cards_left_graveyard_triggers(from_player_id, &[instance_id.to_string()]);
        }
        Ok(true)
    }

    fn execute_effects<P: DecisionProvider>(
        &mut self,
        effects: &Value,
        stack_object: &StackObject,
        bindings: &mut BTreeMap<String, RuntimeBinding>,
        decisions: &mut BTreeMap<String, Value>,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        self.check_quantity_failure()?;
        let Some(effects) = effects.as_array() else {
            return Ok(());
        };
        self.drain_linked_exile_returns(provider)?;
        for (index, effect) in effects.iter().enumerate() {
            self.check_quantity_failure()?;
            let event_count_before = self.state.events.len();
            let libraries_before = self
                .state
                .players
                .iter()
                .map(|player| {
                    (
                        player.id.clone(),
                        player
                            .library
                            .iter()
                            .map(|card| card.instance_id.clone())
                            .collect::<Vec<_>>(),
                    )
                })
                .collect::<Vec<_>>();
            let graveyards_before = if effect_domains::movement_is_owned_by_child_frames(effect) {
                Vec::new()
            } else {
                self.state
                    .players
                    .iter()
                    .map(|player| {
                        (
                            player.id.clone(),
                            player
                                .graveyard
                                .iter()
                                .map(|card| card.instance_id.clone())
                                .collect::<BTreeSet<_>>(),
                        )
                    })
                    .collect::<Vec<_>>()
            };
            self.execute_effect(
                effect,
                effects.get(index + 1),
                stack_object,
                bindings,
                decisions,
                provider,
            )?;
            self.check_quantity_failure()?;
            self.drain_linked_exile_returns(provider)?;
            for (player_id, before) in libraries_before {
                let changed = self
                    .player_index(&player_id)
                    .ok()
                    .is_none_or(|player_index| {
                        self.state.players[player_index]
                            .library
                            .iter()
                            .map(|card| card.instance_id.as_str())
                            .ne(before.iter().map(String::as_str))
                    });
                if changed {
                    self.forget_known_library_cards(&player_id);
                }
            }
            for (player_id, before) in graveyards_before {
                let after = self
                    .player_index(&player_id)
                    .ok()
                    .map(|player_index| {
                        self.state.players[player_index]
                            .graveyard
                            .iter()
                            .map(|card| card.instance_id.clone())
                            .collect::<BTreeSet<_>>()
                    })
                    .unwrap_or_default();
                let left = before.difference(&after).cloned().collect::<Vec<_>>();
                self.enqueue_cards_left_graveyard_triggers(&player_id, &left);
                let already_reported = self.state.events[event_count_before..]
                    .iter()
                    .filter(|event| {
                        event.kind == "cardsEnteredGraveyard"
                            && event.player_id.as_deref() == Some(player_id.as_str())
                    })
                    .flat_map(|event| event.detail["cardIds"].as_array().into_iter().flatten())
                    .filter_map(Value::as_str)
                    .map(ToOwned::to_owned)
                    .collect::<BTreeSet<_>>();
                let entered_ids = after
                    .difference(&before)
                    .filter(|instance_id| !already_reported.contains(*instance_id))
                    .cloned()
                    .collect::<BTreeSet<_>>();
                let entered = self
                    .player_index(&player_id)
                    .ok()
                    .map(|player_index| {
                        self.state.players[player_index]
                            .graveyard
                            .iter()
                            .filter(|card| entered_ids.contains(&card.instance_id))
                            .cloned()
                            .collect::<Vec<_>>()
                    })
                    .unwrap_or_default();
                self.enqueue_cards_entered_graveyard_triggers(&player_id, &entered);
            }
            if self.state.outcome.is_some() {
                break;
            }
        }
        Ok(())
    }

    fn resolution_choice_prompt(
        decision_id: &str,
        next_effect: Option<&Value>,
        is_card_order: bool,
    ) -> String {
        let Some(next_effect) =
            next_effect.filter(|effect| value_kind(effect) == Some("moveCards"))
        else {
            return if is_card_order {
                "Order the remaining cards for this effect.".to_string()
            } else {
                "Choose cards for this effect.".to_string()
            };
        };
        let uses_decision = next_effect["cards"]["decisionId"].as_str() == Some(decision_id)
            || next_effect["order"]["decisionId"].as_str() == Some(decision_id);
        if !uses_decision {
            return if is_card_order {
                "Order the remaining cards for this effect.".to_string()
            } else {
                "Choose cards for this effect.".to_string()
            };
        }

        match (
            value_kind(&next_effect["to"]),
            next_effect["to"]["position"].as_str(),
        ) {
            (Some("library"), Some("bottom")) if is_card_order => {
                "Order the remaining cards for the bottom of the library, bottommost first."
                    .to_string()
            }
            (Some("library"), Some("top")) if is_card_order => {
                "Order the cards for the top of the library, topmost first.".to_string()
            }
            (Some("hand"), _) => "Choose cards to put into hand.".to_string(),
            (Some("battlefield"), _) => "Choose cards to put onto the battlefield.".to_string(),
            (Some("graveyard"), _) => "Choose cards to put into the graveyard.".to_string(),
            (Some("exile"), _) => "Choose cards to exile.".to_string(),
            _ if is_card_order => "Order the remaining cards for this effect.".to_string(),
            _ => "Choose cards for this effect.".to_string(),
        }
    }

    fn exile_from_top_until(
        &mut self,
        effect: &Value,
        stack_object: &StackObject,
        bindings: &mut BTreeMap<String, RuntimeBinding>,
    ) -> Result<(), EngineError> {
        let player_ids = if value_kind(&effect["zone"]["player"]) == Some("opponentsOf") {
            self.state
                .players
                .iter()
                .filter(|player| !player.has_lost && player.id != stack_object.controller)
                .map(|player| player.id.clone())
                .collect::<Vec<_>>()
        } else {
            let Some(player_id) =
                self.resolve_player(&effect["zone"]["player"], stack_object, bindings)
            else {
                return Ok(());
            };
            vec![player_id]
        };
        let threshold = integer_value(&effect["stopWhen"]["right"]).map(|value| value.max(0));
        let stop_where = effect.get("stopWhere");
        let mut exiled_ids = Vec::new();
        let mut stopping_card_id = None;
        for player_id in player_ids {
            let player_index = self.player_index(&player_id)?;
            let mut total_mana_value = 0;
            let mut player_exiled_ids = Vec::new();
            loop {
                if threshold.is_some_and(|threshold| total_mana_value >= threshold) {
                    break;
                }
                let Some(card_index) = self.state.players[player_index]
                    .library
                    .len()
                    .checked_sub(1)
                else {
                    break;
                };
                let card = self.take_zone_card_for_movement(player_index, "library", card_index)?;
                total_mana_value += mana_value(&card.definition);
                let stops = stop_where.is_some_and(|where_filter| {
                    matches_card_filter(&card.definition, where_filter)
                });
                if stops {
                    stopping_card_id = Some(card.instance_id.clone());
                }
                player_exiled_ids.push(card.instance_id.clone());
                exiled_ids.push(card.instance_id.clone());
                self.put_owned_card_into_exile(player_index, card)?;
                if stops {
                    break;
                }
            }
            self.record_event(
                "cardsExiledFromTop",
                Some(player_id),
                Some(stack_object.card.instance_id.clone()),
                json!({
                    "cardIds": player_exiled_ids,
                    "count": player_exiled_ids.len(),
                    "totalManaValue": total_mana_value,
                }),
            );
        }
        if let Some(binding_id) = effect["bind"].as_str() {
            bindings.insert(
                binding_id.to_string(),
                RuntimeBinding::Objects(exiled_ids.clone()),
            );
        }
        if let Some(binding_id) = effect["stopCardBind"].as_str() {
            bindings.insert(
                binding_id.to_string(),
                RuntimeBinding::Objects(stopping_card_id.into_iter().collect()),
            );
        }
        Ok(())
    }

    fn cast_bound_cards_without_paying<P: DecisionProvider>(
        &mut self,
        effect: &Value,
        stack_object: &StackObject,
        bindings: &BTreeMap<String, RuntimeBinding>,
        decisions: &mut BTreeMap<String, Value>,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        let Some(player_id) = self.resolve_player(&effect["player"], stack_object, bindings) else {
            return Ok(());
        };
        let player_index = self.player_index(&player_id)?;
        let object_ids = self
            .resolve_runtime_object_ids(&effect["cards"], stack_object, bindings, decisions)
            .unwrap_or_default()
            .into_iter()
            .collect::<BTreeSet<_>>();
        let source_zone = effect["sourceZone"].as_str().unwrap_or("exile");
        let maximum =
            integer_value(&effect["maximum"]).and_then(|value| usize::try_from(value).ok());
        let alternative_counter = (value_kind(&effect["alternativeCost"])
            == Some("payPlayerCounters"))
        .then(|| effect["alternativeCost"]["counter"].as_str())
        .flatten();
        let mut cast_count = 0;
        loop {
            if maximum.is_some_and(|maximum| cast_count >= maximum) {
                break;
            }
            let cards = match source_zone {
                "hand" => self.state.players[player_index]
                    .hand
                    .iter()
                    .filter(|card| object_ids.contains(&card.instance_id))
                    .cloned()
                    .collect::<Vec<_>>(),
                "graveyard" => self
                    .state
                    .players
                    .iter()
                    .flat_map(|player| player.graveyard.iter())
                    .filter(|card| object_ids.contains(&card.instance_id))
                    .cloned()
                    .collect::<Vec<_>>(),
                "exile" => self
                    .state
                    .players
                    .iter()
                    .flat_map(|player| player.exile.iter())
                    .filter(|card| object_ids.contains(&card.instance_id))
                    .cloned()
                    .collect::<Vec<_>>(),
                _ => return Ok(()),
            };
            if let Some(counter) = alternative_counter {
                let available = self.state.players[player_index]
                    .counters
                    .get(counter)
                    .copied()
                    .unwrap_or(0);
                for card in cards
                    .iter()
                    .filter(|card| mana_value(&card.definition) <= available)
                {
                    if !self.state.permissions.iter().any(|permission| {
                        value_kind(permission)
                            == Some("resolutionPlayerCounterAlternativePermission")
                            && permission["cardInstanceId"].as_str()
                                == Some(card.instance_id.as_str())
                            && permission["playerId"].as_str() == Some(player_id.as_str())
                            && permission["sourceStackId"].as_str()
                                == Some(stack_object.id.as_str())
                    }) {
                        self.state.permissions.push(json!({
                            "kind": "resolutionPlayerCounterAlternativePermission",
                            "cardInstanceId": card.instance_id,
                            "playerId": player_id,
                            "sourceStackId": stack_object.id,
                            "counter": counter,
                        }));
                    }
                }
            }
            let normal_costs_apply = effect["withoutPayingManaCost"].as_bool() == Some(false)
                && alternative_counter.is_none();
            let mut options = self.cast_actions_from_zone(
                player_index,
                &cards,
                "duringResolution",
                source_zone,
                normal_costs_apply,
            )?;
            if let Some(counter) = alternative_counter {
                let available = self.state.players[player_index]
                    .counters
                    .get(counter)
                    .copied()
                    .unwrap_or(0);
                options.retain(|action| {
                    action
                        .card_instance_id
                        .as_deref()
                        .and_then(|instance_id| {
                            cards.iter().find(|card| card.instance_id == instance_id)
                        })
                        .is_some_and(|card| mana_value(&card.definition) <= available)
                });
                for action in &mut options {
                    action.decisions.remove("withoutPayingManaCost");
                    action.decisions.insert(
                        "useAlternativePlayerCounterCost".to_string(),
                        Value::Bool(true),
                    );
                    action.decisions.insert(
                        "alternativePlayerCounter".to_string(),
                        Value::String(counter.to_string()),
                    );
                    if let Some(card) = action.card_instance_id.as_deref().and_then(|instance_id| {
                        cards.iter().find(|card| card.instance_id == instance_id)
                    }) {
                        action.label = format!(
                            "Cast {} by paying {} {} counter(s)",
                            card.definition.name,
                            mana_value(&card.definition),
                            counter
                        );
                    }
                }
            }
            if options.is_empty() {
                break;
            }
            if let Some(provenance) = suspend_keyword::cast_via_decision(&effect["castVia"]) {
                for action in &mut options {
                    action
                        .decisions
                        .insert(provenance.to_string(), Value::Bool(true));
                }
            }
            options.push(LegalAction {
                id: format!("finishCasting:{}", stack_object.id),
                kind: ActionKind::ChooseResolution,
                player_id: player_id.clone(),
                label: "Finish casting spells".to_string(),
                card_instance_id: None,
                payment_sources: Vec::new(),
                decisions: BTreeMap::new(),
                targets: BTreeMap::new(),
                target_order: Vec::new(),
                attacker_id: None,
                blocker_id: None,
            });
            let action = self.choose_action(
                provider,
                EngineDecisionRequest {
                    id: format!("castAnyNumber:{}:{cast_count}", stack_object.id),
                    kind: DecisionKind::ResolutionChoice,
                    player_id: player_id.clone(),
                    source_card: Some(stack_object.card.clone()),
                    source_card_instance_id: Some(stack_object.card.instance_id.clone()),
                    choice: None,
                    options,
                },
            )?;
            if action.kind == ActionKind::ChooseResolution {
                break;
            }
            if action.kind != ActionKind::CastSpell {
                return Err(EngineError::new(
                    "cast-any-number decision returned an invalid action",
                ));
            }
            self.apply_priority_action(&action, provider)?;
            cast_count += 1;
            if self.state.outcome.is_some() {
                break;
            }
        }
        decisions.insert(
            "spellsCastWithoutPaying".to_string(),
            Value::from(cast_count),
        );
        self.state.permissions.retain(|permission| {
            value_kind(permission) != Some("resolutionPlayerCounterAlternativePermission")
                || permission["sourceStackId"].as_str() != Some(stack_object.id.as_str())
        });
        Ok(())
    }

    fn remove_ephemeral_copy_from_exile(
        &mut self,
        player_index: usize,
        copy_id: &str,
        source_id: &str,
    ) {
        let Some(card_index) = self.state.players[player_index]
            .exile
            .iter()
            .position(|card| card.instance_id == copy_id)
        else {
            return;
        };
        self.state.players[player_index].exile.remove(card_index);
        self.record_event(
            "spellCopyCeasedToExist",
            Some(self.state.players[player_index].id.clone()),
            Some(copy_id.to_string()),
            json!({ "sourceCardInstanceId": source_id, "zone": "exile" }),
        );
    }

    fn cast_paradigm_copy<P: DecisionProvider>(
        &mut self,
        stack_object: &StackObject,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        let player_index = self.player_index(&stack_object.controller)?;
        self.copy_sequence += 1;
        let copy_id = format!(
            "copy:paradigm:{}:{}",
            stack_object.controller, self.copy_sequence
        );
        let mut flags = BTreeMap::new();
        flags.insert("isSpellCopy".to_string(), true);
        let mut copy = CardInstance {
            instance_id: copy_id.clone(),
            definition: stack_object.card.definition.clone(),
            printed_definition: None,
            owner: stack_object.controller.clone(),
            controller: stack_object.controller.clone(),
            tapped: false,
            summoning_sick: false,
            damage_marked: 0,
            power_modifier: 0,
            toughness_modifier: 0,
            counters: BTreeMap::new(),
            flags,
            battle_protector: None,
            attached_to: None,
        };
        self.admit_new_card_carrier(&mut copy)?;
        self.state.players[player_index].exile.push(copy.clone());
        self.record_event(
            "paradigmCopyCreated",
            Some(stack_object.controller.clone()),
            Some(copy_id.clone()),
            json!({
                "sourceCardInstanceId": stack_object.card.instance_id,
                "zone": "exile",
            }),
        );

        let mut options = self.cast_without_paying_actions(
            player_index,
            std::slice::from_ref(&copy),
            "paradigm",
        )?;
        if options.is_empty() {
            self.remove_ephemeral_copy_from_exile(
                player_index,
                &copy_id,
                &stack_object.card.instance_id,
            );
            return Ok(());
        }
        options.push(LegalAction {
            id: format!("declineParadigm:{copy_id}"),
            kind: ActionKind::ChooseResolution,
            player_id: stack_object.controller.clone(),
            label: "Do not cast the paradigm copy".to_string(),
            card_instance_id: None,
            payment_sources: Vec::new(),
            decisions: BTreeMap::new(),
            targets: BTreeMap::new(),
            target_order: Vec::new(),
            attacker_id: None,
            blocker_id: None,
        });
        let action = self.choose_action(
            provider,
            EngineDecisionRequest {
                id: format!("paradigmCast:{}", stack_object.id),
                kind: DecisionKind::ResolutionChoice,
                player_id: stack_object.controller.clone(),
                source_card: Some(stack_object.card.clone()),
                source_card_instance_id: Some(stack_object.card.instance_id.clone()),
                choice: None,
                options,
            },
        )?;
        if action.kind == ActionKind::CastSpell {
            self.apply_priority_action(&action, provider)?;
        } else if action.kind == ActionKind::ChooseResolution {
            self.remove_ephemeral_copy_from_exile(
                player_index,
                &copy_id,
                &stack_object.card.instance_id,
            );
        } else {
            return Err(EngineError::new(
                "paradigm decision returned an invalid action",
            ));
        }
        Ok(())
    }

    fn optional_action_is_available(
        &self,
        action: &Value,
        stack_object: &StackObject,
        bindings: &BTreeMap<String, RuntimeBinding>,
    ) -> bool {
        match value_kind(action) {
            Some("exileAbilitySourceFromGraveyard") => self
                .state
                .players
                .iter()
                .flat_map(|player| player.graveyard.iter())
                .any(|card| card.instance_id == stack_object.card.instance_id),
            Some("exileCards") => {
                let Some(count) =
                    integer_value(&action["count"]).and_then(|count| usize::try_from(count).ok())
                else {
                    return false;
                };
                let Some(player_id) =
                    self.resolve_player(&action["from"]["player"], stack_object, bindings)
                else {
                    return false;
                };
                self.player_index(&player_id)
                    .ok()
                    .is_some_and(|player_index| {
                        self.state.players[player_index].graveyard.len() >= count
                    })
            }
            Some("discardCards") => {
                let Some(count) = self
                    .runtime_numeric_expression(
                        &action["count"],
                        stack_object,
                        bindings,
                        &BTreeMap::new(),
                    )
                    .and_then(|count| usize::try_from(count.max(0)).ok())
                else {
                    return false;
                };
                let Some(player_id) =
                    self.resolve_player(&action["player"], stack_object, bindings)
                else {
                    return false;
                };
                self.player_index(&player_id)
                    .ok()
                    .is_some_and(|player_index| {
                        self.state.players[player_index].hand.len() >= count
                    })
            }
            Some("sacrificePermanents") => {
                let Some(count) = integer_value(&action["count"])
                    .and_then(|count| usize::try_from(count.max(0)).ok())
                else {
                    return false;
                };
                let Some(player_id) =
                    self.resolve_player(&action["player"], stack_object, bindings)
                else {
                    return false;
                };
                self.player_index(&player_id)
                    .ok()
                    .is_some_and(|player_index| {
                        self.state.players[player_index]
                            .battlefield
                            .iter()
                            .filter(|card| {
                                !action["excludeSource"].as_bool().unwrap_or(false)
                                    || card.instance_id != stack_object.card.instance_id
                            })
                            .filter(|card| self.permanent_state_matches(card, &action["where"]))
                            .count()
                            >= count
                    })
            }
            _ => true,
        }
    }

    fn execute_optional_action<P: DecisionProvider>(
        &mut self,
        effect: &Value,
        stack_object: &StackObject,
        bindings: &mut BTreeMap<String, RuntimeBinding>,
        decisions: &mut BTreeMap<String, Value>,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        // CR 608.2d: an impossible option can't be chosen, so the instruction
        // is not performed and only an `If you don't` outcome follows.
        if !self.optional_action_is_available(&effect["action"], stack_object, bindings) {
            self.record_event(
                "optionalActionUnavailable",
                Some(stack_object.controller.clone()),
                Some(stack_object.card.instance_id.clone()),
                json!({ "action": effect["action"], "stackId": stack_object.id }),
            );
            if let Some(declined) = effect.get("onDeclined") {
                self.execute_effects(declined, stack_object, bindings, decisions, provider)?;
            }
            return Ok(());
        }
        let Some(player_id) = self.resolve_player(&effect["player"], stack_object, bindings) else {
            return Ok(());
        };
        let decision_id = format!(
            "optionalAction:{}:{}",
            stack_object.id,
            self.state.events.len()
        );
        let choice_key = "performOptionalAction".to_string();
        let options = [
            (false, "Decline the optional action".to_string()),
            (
                true,
                match value_kind(&effect["action"]) {
                    Some("exileCards") => format!(
                        "Exile {} cards from your graveyard",
                        integer_value(&effect["action"]["count"]).unwrap_or(0)
                    ),
                    _ => "Perform the optional action".to_string(),
                },
            ),
        ]
        .into_iter()
        .enumerate()
        .map(|(index, (perform, label))| LegalAction {
            id: format!("{decision_id}:{index}"),
            kind: ActionKind::ChooseResolution,
            player_id: player_id.clone(),
            label,
            card_instance_id: Some(stack_object.card.instance_id.clone()),
            payment_sources: Vec::new(),
            decisions: BTreeMap::from([(choice_key.clone(), Value::Bool(perform))]),
            targets: BTreeMap::new(),
            target_order: Vec::new(),
            attacker_id: None,
            blocker_id: None,
        })
        .collect();
        let choice = self.choose_action(
            provider,
            EngineDecisionRequest {
                id: decision_id,
                kind: DecisionKind::ResolutionChoice,
                player_id: player_id.clone(),
                source_card: Some(stack_object.card.clone()),
                source_card_instance_id: Some(stack_object.card.instance_id.clone()),
                choice: None,
                options,
            },
        )?;
        let chosen = choice
            .decisions
            .get(&choice_key)
            .and_then(Value::as_bool)
            .unwrap_or(false);
        decisions.insert(choice_key, Value::Bool(chosen));
        // CR 608.2c, 603.12: the outcome follows whether the instruction was
        // actually performed, measured by its prepared witness.
        let performed = if chosen {
            let witness = self.prepare_optional_action_witness(
                &effect["action"],
                stack_object,
                bindings,
                decisions,
            );
            let first_event = self.state.events.len();
            self.execute_effects(
                &Value::Array(vec![effect["action"].clone()]),
                stack_object,
                bindings,
                decisions,
                provider,
            )?;
            self.optional_action_was_performed(&witness, first_event)
        } else {
            false
        };
        if performed {
            self.execute_effects(
                &effect["onPerformed"],
                stack_object,
                bindings,
                decisions,
                provider,
            )?;
        } else if let Some(declined) = effect.get("onDeclined") {
            self.execute_effects(declined, stack_object, bindings, decisions, provider)?;
        }
        self.record_event(
            "optionalActionChosen",
            Some(player_id),
            Some(stack_object.card.instance_id.clone()),
            json!({ "chosen": chosen, "performed": performed, "stackId": stack_object.id }),
        );
        Ok(())
    }

    /// Runs a mandatory instruction and, only when its prepared witness shows
    /// it was actually performed (CR 603.12), the dependent outcome effects.
    fn execute_performed_action<P: DecisionProvider>(
        &mut self,
        effect: &Value,
        stack_object: &StackObject,
        bindings: &mut BTreeMap<String, RuntimeBinding>,
        decisions: &mut BTreeMap<String, Value>,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        let witness = self.prepare_optional_action_witness(
            &effect["action"],
            stack_object,
            bindings,
            decisions,
        );
        let first_event = self.state.events.len();
        self.execute_effects(
            &Value::Array(vec![effect["action"].clone()]),
            stack_object,
            bindings,
            decisions,
            provider,
        )?;
        if self.optional_action_was_performed(&witness, first_event) {
            self.execute_effects(
                &effect["onPerformed"],
                stack_object,
                bindings,
                decisions,
                provider,
            )?;
        }
        Ok(())
    }

    fn exile_cards_from_graveyard<P: DecisionProvider>(
        &mut self,
        effect: &Value,
        stack_object: &StackObject,
        bindings: &BTreeMap<String, RuntimeBinding>,
        decisions: &mut BTreeMap<String, Value>,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        let count = integer_value(&effect["count"])
            .and_then(|count| usize::try_from(count).ok())
            .ok_or_else(|| EngineError::new("exile-cards effect has an invalid count"))?;
        let player_id = self
            .resolve_player(&effect["from"]["player"], stack_object, bindings)
            .ok_or_else(|| EngineError::new("exile-cards effect has no player"))?;
        let player_index = self.player_index(&player_id)?;
        let candidates = self.state.players[player_index]
            .graveyard
            .iter()
            .map(|card| card.instance_id.clone())
            .collect::<Vec<_>>();
        let decision_id = format!("exileCards:{}:{}", stack_object.id, self.state.events.len());
        let values = Self::resolution_selections(&candidates, count, 128);
        self.make_resolution_decision(
            &decision_id,
            &player_id,
            stack_object,
            DecisionChoice::CardSelection {
                decision_id: decision_id.clone(),
                candidate_card_instance_ids: candidates,
                minimum: count,
                maximum: count,
                prompt: format!("Choose exactly {count} cards to exile."),
            },
            values,
            decisions,
            provider,
        )?;
        let selected = decisions
            .get(&decision_id)
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(Value::as_str)
            .map(ToOwned::to_owned)
            .collect::<Vec<_>>();
        let mut exiled = Vec::new();
        for instance_id in &selected {
            let Some(card_index) = self.state.players[player_index]
                .graveyard
                .iter()
                .position(|card| card.instance_id == *instance_id)
            else {
                return Err(EngineError::new(
                    "chosen exile card is no longer in the graveyard",
                ));
            };
            exiled.push(self.take_zone_card_for_movement(player_index, "graveyard", card_index)?);
        }
        for card in exiled {
            self.put_owned_card_into_exile(player_index, card)?;
        }
        self.record_event(
            "cardsExiled",
            Some(player_id),
            Some(stack_object.card.instance_id.clone()),
            json!({
                "cardIds": selected,
                "count": selected.len(),
                "from": "graveyard",
                "stackId": stack_object.id,
            }),
        );
        Ok(())
    }

    fn execute_effect<P: DecisionProvider>(
        &mut self,
        effect: &Value,
        next_effect: Option<&Value>,
        stack_object: &StackObject,
        bindings: &mut BTreeMap<String, RuntimeBinding>,
        decisions: &mut BTreeMap<String, Value>,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        let materialized = self.materialize_resolution_choices(effect, decisions);
        let effect = materialized.as_ref();
        // One instruction is one simultaneous event (CR 603.2c).
        let scope = self.begin_event_batch();
        let result = self.execute_effect_in_batch(
            effect,
            next_effect,
            stack_object,
            bindings,
            decisions,
            provider,
        );
        self.end_event_batch(scope);
        result
    }

    fn execute_effect_in_batch<P: DecisionProvider>(
        &mut self,
        effect: &Value,
        next_effect: Option<&Value>,
        stack_object: &StackObject,
        bindings: &mut BTreeMap<String, RuntimeBinding>,
        decisions: &mut BTreeMap<String, Value>,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        if self.execute_performed_effect(
            effect,
            next_effect,
            stack_object,
            bindings,
            decisions,
            provider,
        )? {
            return Ok(());
        }
        if self.execute_player_iteration(effect, stack_object, bindings, decisions, provider)? {
            return Ok(());
        }
        if self.execute_ability_signal_effect(effect, stack_object, bindings)? {
            return Ok(());
        }
        if self.execute_direct_life_effect(effect, stack_object, bindings, decisions)? {
            return Ok(());
        }
        if self.execute_explicit_object_sacrifice(effect, stack_object, bindings, decisions)? {
            return Ok(());
        }
        if self.execute_zone_change_effect(effect, stack_object, bindings, decisions, provider)? {
            return Ok(());
        }

        if self.execute_effect_domain(
            effect,
            next_effect,
            stack_object,
            bindings,
            decisions,
            provider,
        )? {
            return Ok(());
        }
        Err(EngineError::new(format!(
            "unsupported effect reached execution: {}",
            value_kind(effect).unwrap_or("missingKind")
        )))
    }

    fn deal_damage(
        &mut self,
        target: TargetRef,
        amount: i32,
        source: &str,
    ) -> Result<(), EngineError> {
        self.deal_damage_amount(target, amount, source).map(|_| ())
    }

    fn deal_damage_amount(
        &mut self,
        target: TargetRef,
        amount: i32,
        source: &str,
    ) -> Result<i32, EngineError> {
        self.deal_damage_amount_with_kind(target, amount, source, false)
    }

    fn replace_leaving_battlefield_with_exile(
        &mut self,
        instance_id: &str,
        intended_destination: &str,
    ) -> Result<bool, EngineError> {
        let replaces = self.state.rule_modifiers.iter().any(|modifier| {
            value_kind(modifier) == Some("exileIfLeavesBattlefield")
                && modifier["cardInstanceId"].as_str() == Some(instance_id)
        });
        if !replaces {
            return Ok(false);
        }
        self.exile_permanent(instance_id)?;
        self.record_event(
            "zoneChangeReplacedByExile",
            None,
            Some(instance_id.to_string()),
            json!({ "intendedDestination": intended_destination }),
        );
        Ok(true)
    }

    fn move_permanent_to_graveyard_internal(
        &mut self,
        instance_id: &str,
        reason: &str,
    ) -> Result<(), EngineError> {
        if self.permanent_position(instance_id).is_none() {
            return Ok(());
        }
        let trigger_sources = self.capture_death_trigger_source_snapshot();
        self.move_permanent_to_graveyard_internal_with_death_sources(
            instance_id,
            reason,
            &trigger_sources,
        )
    }

    fn move_permanent_to_graveyard_internal_with_death_sources(
        &mut self,
        instance_id: &str,
        reason: &str,
        trigger_sources: &death_trigger_batch::DeathTriggerSourceSnapshot,
    ) -> Result<(), EngineError> {
        if self.permanent_position(instance_id).is_none() {
            return Ok(());
        }
        if reason == "destroyed" {
            let umbra_armor = self
                .state
                .players
                .iter()
                .flat_map(|player| player.battlefield.iter())
                .find(|attachment| {
                    attachment.attached_to.as_deref() == Some(instance_id)
                        && self.permanent_has_keyword(attachment, "umbraArmor")
                })
                .map(|attachment| attachment.instance_id.clone());
            if let Some(umbra_armor) = umbra_armor {
                if let Some((player_index, card_index)) = self.permanent_position(instance_id) {
                    self.state.players[player_index].battlefield[card_index].damage_marked = 0;
                }
                self.move_permanent_to_graveyard(&umbra_armor, "destroyed")?;
                self.record_event(
                    "destructionReplacedByUmbraArmor",
                    None,
                    Some(instance_id.to_string()),
                    json!({ "auraInstanceId": umbra_armor }),
                );
                return Ok(());
            }
        }
        let opponent_death_replacement = self
            .permanent_position(instance_id)
            .map(|(player_index, card_index)| {
                self.state.players[player_index].battlefield[card_index].clone()
            })
            .and_then(|permanent| {
                self.battlefield_static_modifiers()
                    .into_iter()
                    .find(|(source, modifier)| {
                        value_kind(modifier) == Some("exileOpponentCreatureInsteadOfDying")
                            && source.controller != permanent.controller
                            && modifier.get("where").map_or_else(
                                || self.permanent_is_creature(&permanent),
                                |where_filter| {
                                    self.permanent_matches_effective_filter(
                                        &permanent,
                                        where_filter,
                                    )
                                },
                            )
                    })
            });
        if let Some((replacement_source, replacement)) = opponent_death_replacement {
            self.record_event(
                "deathReplacedWithExile",
                None,
                Some(instance_id.to_string()),
                json!({ "reason": reason }),
            );
            self.exile_permanent(instance_id)?;
            if replacement.get("onReplaced").is_some() {
                self.put_triggered_ability_on_stack_with_origin(
                    &replacement_source,
                    replacement["onReplaced"].clone(),
                    BTreeMap::new(),
                    trigger_multiplicity::TriggerOrigin::Unproven,
                );
                self.check_quantity_failure()?;
            }
            return Ok(());
        }
        if matches!(reason, "destroyed" | "lethalDamage") {
            let has_regeneration_shield = self.state.rule_modifiers.iter().any(|modifier| {
                value_kind(modifier) == Some("regenerationShield")
                    && modifier["cardInstanceId"].as_str() == Some(instance_id)
            });
            if has_regeneration_shield {
                self.consume_regeneration_shield(instance_id, reason);
                return Ok(());
            }
        }
        if reason == "destroyed"
            && self
                .permanent_position(instance_id)
                .is_some_and(|(player_index, card_index)| {
                    self.permanent_has_keyword(
                        &self.state.players[player_index].battlefield[card_index],
                        "indestructible",
                    )
                })
        {
            return Ok(());
        }
        if reason == "destroyed"
            && self.remove_counters_from_permanent(instance_id, "shield", 1, "wouldBeDestroyed")
                == 1
        {
            self.record_event(
                "destructionPrevented",
                None,
                Some(instance_id.to_string()),
                json!({ "reason": "shieldCounter" }),
            );
            return Ok(());
        }
        if self.replace_leaving_battlefield_with_exile(instance_id, "graveyard")? {
            return Ok(());
        }
        if let Some(modifier_index) = self.state.rule_modifiers.iter().position(|modifier| {
            (value_kind(modifier) == Some("exileIfWouldDie")
                && modifier["cardInstanceId"].as_str() == Some(instance_id))
                || (value_kind(modifier) == Some("exileIfDiesThisTurn")
                    && modifier["instanceId"].as_str() == Some(instance_id)
                    && modifier["expiresAfterTurn"].as_u64()
                        == Some(u64::from(self.state.turn_number)))
        }) {
            self.state.rule_modifiers.remove(modifier_index);
            self.exile_permanent(instance_id)?;
            self.record_event(
                "deathReplacedByExile",
                None,
                Some(instance_id.to_string()),
                json!({ "reason": reason }),
            );
            return Ok(());
        }
        let died = self.commit_permanent_graveyard_move_with_sources(
            instance_id,
            reason,
            destruction_batch::FrozenGraveyardDestination::EvaluateLive,
            Some(trigger_sources.sources()),
        )?;
        if let Some(died) = died.as_ref() {
            self.publish_committed_death_triggers(died, reason, trigger_sources);
        }
        Ok(())
    }

    fn destroy_permanent_from_stack(
        &mut self,
        instance_id: &str,
        stack_object: &StackObject,
    ) -> Result<(), EngineError> {
        let destroyed = self
            .permanent_position(instance_id)
            .map(|(player_index, card_index)| {
                self.state.players[player_index].battlefield[card_index].clone()
            });
        self.move_permanent_to_graveyard(instance_id, "destroyed")?;
        let Some(destroyed) = destroyed else {
            return Ok(());
        };
        if self.permanent_position(instance_id).is_some() {
            return Ok(());
        }
        self.record_event(
            "permanentDestroyed",
            Some(stack_object.controller.clone()),
            Some(instance_id.to_string()),
            json!({ "destroyedControllerId": destroyed.controller }),
        );
        if destroyed.controller == stack_object.controller {
            return Ok(());
        }
        let sources = self
            .state
            .players
            .iter()
            .flat_map(|player| player.battlefield.iter())
            .filter(|source| source.controller == destroyed.controller)
            .flat_map(|source| {
                source
                    .definition
                    .printed_rules()
                    .iter()
                    .filter(|rule| {
                        triggered_rule_supported(rule)
                            && value_kind(&rule["event"])
                                == Some("opponentDestroyedControlledPermanent")
                            && matches_card_filter(&destroyed.definition, &rule["event"]["where"])
                    })
                    .cloned()
                    .map(|rule| (source.clone(), rule))
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();
        for (source, rule) in sources {
            self.put_triggered_ability_on_stack_with_decisions(
                &source,
                rule,
                BTreeMap::from([(
                    "triggeringPlayerId".to_string(),
                    Value::String(stack_object.controller.clone()),
                )]),
            );
            self.check_quantity_failure()?;
        }
        Ok(())
    }

    fn return_earthbent_card(
        &mut self,
        instance_id: &str,
        source_zone: &str,
    ) -> Result<(), EngineError> {
        let found = self
            .prepare_card_movement_source(instance_id, None)?
            .filter(|source| source.zone.name() == source_zone)
            .map(|source| self.take_prepared_movement_card(source))
            .transpose()?;
        let Some(mut card) = found else {
            return Ok(());
        };
        card_zone_transition::reset_owned_movement_card(&mut card)?;
        let owner_index = self.player_index(&card.owner)?;
        card.controller = card.owner.clone();
        card.tapped = true;
        card.summoning_sick = true;
        self.commit_movement_identity(
            &mut card,
            &card_zone_transition::ObjectZone::Battlefield,
            card_zone_transition::ObjectTransitionReason::Move,
        )?;
        let trigger_source = card.clone();
        self.state.players[owner_index].battlefield.push(card.card);
        self.record_event(
            "earthbentLandReturned",
            Some(trigger_source.controller.clone()),
            Some(instance_id.to_string()),
            json!({ "from": source_zone, "tapped": true }),
        );
        self.enqueue_enter_battlefield_triggers(&trigger_source);
        Ok(())
    }

    fn restore_stored_copy_aura(&mut self, source_id: &str) {
        let restorations = self
            .state
            .rule_modifiers
            .iter()
            .filter(|modifier| {
                value_kind(modifier) == Some("storedCopyAura")
                    && modifier["sourceCardInstanceId"].as_str() == Some(source_id)
            })
            .cloned()
            .collect::<Vec<_>>();
        for restoration in &restorations {
            let Some(target_id) = restoration["targetCardInstanceId"].as_str() else {
                continue;
            };
            let Ok(original_definition) =
                serde_json::from_value::<CardDefinition>(restoration["originalDefinition"].clone())
            else {
                continue;
            };
            if let Some((player_index, card_index)) = self.permanent_position(target_id) {
                self.state.players[player_index].battlefield[card_index].definition =
                    original_definition;
            }
        }
        self.state.rule_modifiers.retain(|modifier| {
            !restorations
                .iter()
                .any(|restoration| restoration == modifier)
        });
    }

    fn apply_stored_copy_aura(&mut self, source_id: &str) {
        self.restore_stored_copy_aura(source_id);
        let Some((source_player, source_index)) = self.permanent_position(source_id) else {
            return;
        };
        let source = self.state.players[source_player].battlefield[source_index].clone();
        let Some(modifier) = source.definition.printed_rules().iter().find_map(|rule| {
            (value_kind(rule) == Some("staticAbility"))
                .then(|| rule["modifiers"].as_array())
                .flatten()
                .and_then(|modifiers| {
                    modifiers.iter().find(|modifier| {
                        value_kind(modifier) == Some("copyAttachedFromStoredCreature")
                    })
                })
        }) else {
            return;
        };
        let decision_id = modifier["decisionId"].as_str().unwrap_or("chosenCreature");
        let Some(chosen_id) = stored_decision_value(&source.definition, decision_id) else {
            return;
        };
        let Some(target_id) = source.attached_to.as_deref() else {
            return;
        };
        let Some((chosen_player, chosen_index)) = self.permanent_position(chosen_id) else {
            return;
        };
        let Some((target_player, target_index)) = self.permanent_position(target_id) else {
            return;
        };
        let chosen_definition = self.state.players[chosen_player].battlefield[chosen_index]
            .definition
            .clone();
        let original_definition = self.state.players[target_player].battlefield[target_index]
            .definition
            .clone();
        let mut copied_definition = chosen_definition;
        copied_definition.is_commander = original_definition.is_commander;
        copied_definition.is_token = original_definition.is_token;
        copied_definition.is_game_piece = original_definition.is_game_piece;
        copied_definition.is_sideboard = original_definition.is_sideboard;
        self.state.players[target_player].battlefield[target_index].definition = copied_definition;
        self.state.rule_modifiers.push(json!({
            "kind": "storedCopyAura",
            "sourceCardInstanceId": source_id,
            "targetCardInstanceId": target_id,
            "originalDefinition": original_definition,
        }));
    }

    /// CR 704.5m / 303.4d: Auras whose enchant restriction (or protection of
    /// the enchanted permanent) no longer permits their attachment. Auras with
    /// a zone-linked enchant ability keep their dedicated entry handling.
    fn illegally_attached_auras(&self) -> Vec<String> {
        self.state
            .players
            .iter()
            .flat_map(|player| player.battlefield.iter())
            .filter(|aura| !aura.flags.get("phasedOut").copied().unwrap_or(false))
            .filter_map(|aura| {
                let enchant_ability = enchant_ability_of(&aura.definition)?;
                if enchant_ability.get("where").is_none() || enchant_ability.get("zone").is_some() {
                    return None;
                }
                let legal = aura.attached_to.as_deref().is_some_and(|attached_id| {
                    let Some((player_index, card_index)) = self.permanent_position(attached_id)
                    else {
                        return false;
                    };
                    let host = &self.state.players[player_index].battlefield[card_index];
                    host.flags.get("phasedOut").copied().unwrap_or(false)
                        || (!self.permanent_is_protected_from_card(host, &aura.definition)
                            && self
                                .selection_candidates_with_decisions(
                                    &aura.controller,
                                    &enchant_candidates_shape(enchant_ability),
                                    &BTreeMap::new(),
                                    false,
                                )
                                .is_some_and(|candidates| {
                                    candidates.contains(&TargetRef::Permanent {
                                        instance_id: attached_id.to_string(),
                                    })
                                }))
                });
                (!legal).then(|| aura.instance_id.clone())
            })
            .collect()
    }

    fn handle_attachment_target_left(&mut self, instance_id: &str) {
        self.restore_stored_copy_aura(instance_id);
        let mut auras = Vec::new();
        for player in &mut self.state.players {
            for attachment in &mut player.battlefield {
                if attachment.attached_to.as_deref() != Some(instance_id) {
                    continue;
                }
                if attachment.flags.remove("bestowedAura").unwrap_or(false) {
                    attachment.attached_to = None;
                    if let Some(original_type_line) = attachment
                        .definition
                        .printed_rules()
                        .iter()
                        .find(|rule| value_kind(rule) == Some("bestowOriginalTypeLine"))
                        .and_then(|rule| rule["value"].as_str())
                        .map(ToOwned::to_owned)
                    {
                        attachment.definition.type_line = original_type_line;
                    }
                    attachment
                        .definition
                        .printed_rules_mut()
                        .retain(|rule| value_kind(rule) != Some("bestowOriginalTypeLine"));
                    continue;
                }
                let is_aura = attachment.definition.printed_rules().iter().any(|rule| {
                    value_kind(rule) == Some("keywordAbility")
                        && value_kind(&rule["ability"]) == Some("enchant")
                });
                if is_aura {
                    auras.push(attachment.instance_id.clone());
                } else {
                    attachment.attached_to = None;
                }
            }
        }
        for aura_id in auras {
            if let Err(error) = self.move_permanent_to_graveyard(&aura_id, "unattachedAura") {
                self.defer_quantity_failure(error);
                return;
            }
        }
    }

    fn exile_permanent(&mut self, instance_id: &str) -> Result<(), EngineError> {
        let Some(movement) = self.install_permanent_exile_move(instance_id)? else {
            return Ok(());
        };
        self.publish_installed_battlefield_departure(&movement, "exiled")
    }

    fn return_permanent_to_hand(&mut self, instance_id: &str) -> Result<(), EngineError> {
        if self.permanent_position(instance_id).is_none() {
            return Ok(());
        }
        if self.replace_leaving_battlefield_with_exile(instance_id, "hand")? {
            return Ok(());
        }
        let observers = self.capture_battlefield_departure_trigger_sources();
        self.remove_prepared_spell_copy(instance_id);
        let Some((controller_index, card_index)) = self.permanent_position(instance_id) else {
            return Ok(());
        };
        let movement_source = self
            .prepare_card_movement_source(instance_id, None)?
            .ok_or_else(|| EngineError::new("battlefield return source identity is missing"))?;
        let target_numeric_departure = self.prepare_target_numeric_departure(instance_id);
        self.capture_pending_source_lki(instance_id);
        let mut card = self.state.players[controller_index]
            .battlefield
            .remove(card_index);
        self.confirm_target_numeric_departure(target_numeric_departure);
        let last_known = card.clone();
        card_zone_transition::reset_movement_card(&mut card, &movement_source)?;
        let owner_index = self.player_index(&card.owner)?;
        let destination = card_zone_transition::ObjectZone::Hand(card.owner.clone());
        self.commit_card_zone_transition(
            &mut card,
            &movement_source,
            &destination,
            card_zone_transition::ObjectTransitionReason::Move,
        )?;
        self.state.players[owner_index].hand.push(card);
        self.record_event(
            "permanentReturned",
            None,
            Some(instance_id.to_string()),
            json!({}),
        );
        self.record_event(
            "permanentLeftBattlefield",
            Some(last_known.controller.clone()),
            Some(instance_id.to_string()),
            json!({
                "destination": "hand",
                "typeLine": last_known.definition.type_line,
            }),
        );
        self.enqueue_permanent_left_triggers_with_sources(&last_known, "hand", &observers, None);
        self.handle_attachment_target_left(instance_id);
        self.refresh_control_effects();
        Ok(())
    }

    fn put_permanent_on_owner_library(
        &mut self,
        instance_id: &str,
        position: &str,
    ) -> Result<(), EngineError> {
        if self.replace_leaving_battlefield_with_exile(instance_id, "library")? {
            return Ok(());
        }
        let observers = self.capture_battlefield_departure_trigger_sources();
        self.remove_prepared_spell_copy(instance_id);
        let Some((controller_index, card_index)) = self.permanent_position(instance_id) else {
            return Ok(());
        };
        let movement_source = self
            .prepare_card_movement_source(instance_id, None)?
            .ok_or_else(|| EngineError::new("battlefield return source identity is missing"))?;
        let target_numeric_departure = self.prepare_target_numeric_departure(instance_id);
        self.capture_pending_source_lki(instance_id);
        let mut card = self.state.players[controller_index]
            .battlefield
            .remove(card_index);
        self.confirm_target_numeric_departure(target_numeric_departure);
        let last_known = card.clone();
        card_zone_transition::reset_movement_card(&mut card, &movement_source)?;
        let owner_index = self.player_index(&card.owner)?;
        let destination = card_zone_transition::ObjectZone::Library(card.owner.clone());
        self.commit_card_zone_transition(
            &mut card,
            &movement_source,
            &destination,
            card_zone_transition::ObjectTransitionReason::Move,
        )?;
        if position == "bottom" {
            self.state.players[owner_index].library.insert(0, card);
        } else if position == "secondFromTop" {
            let insert_at = self.state.players[owner_index]
                .library
                .len()
                .saturating_sub(1);
            self.state.players[owner_index]
                .library
                .insert(insert_at, card);
        } else {
            self.state.players[owner_index].library.push(card);
        }
        self.record_event(
            if position == "bottom" {
                "permanentPutOnLibraryBottom"
            } else {
                "permanentPutOnLibraryTop"
            },
            Some(last_known.controller.clone()),
            Some(instance_id.to_string()),
            json!({ "owner": last_known.owner, "position": position }),
        );
        self.record_event(
            "permanentLeftBattlefield",
            Some(last_known.controller.clone()),
            Some(instance_id.to_string()),
            json!({
                "destination": "library",
                "typeLine": last_known.definition.type_line,
            }),
        );
        self.enqueue_permanent_left_triggers_with_sources(&last_known, "library", &observers, None);
        self.handle_attachment_target_left(instance_id);
        self.refresh_control_effects();
        Ok(())
    }

    fn return_stack_object_to_hand(&mut self, stack_id: &str) -> Result<(), EngineError> {
        let Some(index) = self
            .state
            .stack
            .iter()
            .position(|object| object.id == stack_id)
        else {
            return Ok(());
        };
        if !stack_object_is_spell(&self.state.stack[index]) {
            return Err(EngineError::new(
                "returning a stack ability as a physical card is unsupported",
            ));
        }
        let movement_source =
            if card_zone_transition::stack_requires_checkpoint(&self.state.stack[index]) {
                Some(self.prepare_stack_card_movement_source(index)?)
            } else {
                None
            };
        let stack_object = self.take_stack_object_with_lki(index);
        let card_id = stack_object.card.instance_id.clone();
        let owner_index = self.player_index(&stack_object.card.owner)?;
        let controller = stack_object.controller;
        let mut card = stack_object.card;
        let spell_copy = is_spell_copy(&card);
        if let Some(source) = &movement_source {
            card_zone_transition::reset_movement_card(&mut card, source)?;
        } else {
            reset_after_leaving_battlefield(&mut card);
        }
        let destination = if spell_copy {
            "ceasesToExist"
        } else if stack_object.exile_on_leave_stack {
            let destination = card_zone_transition::ObjectZone::Exile;
            let source = movement_source.as_ref().ok_or_else(|| {
                EngineError::new("physical stack departure lacks source identity")
            })?;
            self.commit_card_zone_transition(
                &mut card,
                source,
                &destination,
                card_zone_transition::ObjectTransitionReason::Move,
            )?;
            self.state.players[owner_index].exile.push(card);
            "exile"
        } else {
            let destination = card_zone_transition::ObjectZone::Hand(card.owner.clone());
            let source = movement_source.as_ref().ok_or_else(|| {
                EngineError::new("physical stack departure lacks source identity")
            })?;
            self.commit_card_zone_transition(
                &mut card,
                source,
                &destination,
                card_zone_transition::ObjectTransitionReason::Move,
            )?;
            self.state.players[owner_index].hand.push(card);
            "hand"
        };
        self.record_event(
            "spellReturned",
            Some(controller.clone()),
            Some(card_id.clone()),
            json!({ "destination": destination, "stackId": stack_id }),
        );
        if spell_copy {
            self.record_event(
                "spellCopyCeasedToExist",
                Some(controller),
                Some(card_id),
                json!({ "zone": "stack" }),
            );
        }
        Ok(())
    }

    fn counter_stack_object(
        &mut self,
        stack_id: &str,
        source: &str,
        source_controller: &str,
        exile_instead: bool,
    ) -> Result<(), EngineError> {
        let Some(index) = self
            .state
            .stack
            .iter()
            .position(|object| object.id == stack_id)
        else {
            return Ok(());
        };
        if self.stack_object_cant_be_countered(&self.state.stack[index]) {
            self.record_event(
                "counterPrevented",
                Some(self.state.stack[index].controller.clone()),
                Some(self.state.stack[index].card.instance_id.clone()),
                json!({ "source": source, "stackId": stack_id }),
            );
            return Ok(());
        }
        let movement_source =
            if card_zone_transition::stack_requires_checkpoint(&self.state.stack[index]) {
                Some(self.prepare_stack_card_movement_source(index)?)
            } else {
                None
            };
        if exile_instead {
            self.state.stack[index].exile_on_leave_stack = true;
        }

        let stack_object = self.take_stack_object_with_lki(index);
        let is_spell = stack_object_is_spell(&stack_object);
        let object_kind = stack_object
            .ability_kind
            .clone()
            .unwrap_or_else(|| "spell".to_string());
        let card_id = stack_object.card.instance_id.clone();
        let controller = stack_object.controller;
        if !is_spell {
            self.record_event(
                "spellCountered",
                Some(controller),
                Some(card_id),
                json!({
                    "destination": "counteredAbility",
                    "objectKind": object_kind,
                    "source": source,
                    "counterSourceControllerId": source_controller,
                    "stackId": stack_id,
                }),
            );
            return Ok(());
        }

        let owner_index = self.player_index(&stack_object.card.owner)?;
        let mut card = stack_object.card;
        let graveyard_owner = card.owner.clone();
        let spell_copy = is_spell_copy(&card);
        if let Some(source) = &movement_source {
            card_zone_transition::reset_movement_card(&mut card, source)?;
        } else {
            reset_after_leaving_battlefield(&mut card);
        }
        let mut graveyard_card = None;
        let destination = if spell_copy {
            "ceasesToExist"
        } else if stack_object.exile_on_leave_stack {
            let destination = card_zone_transition::ObjectZone::Exile;
            let source = movement_source.as_ref().ok_or_else(|| {
                EngineError::new("physical stack departure lacks source identity")
            })?;
            self.commit_card_zone_transition(
                &mut card,
                source,
                &destination,
                card_zone_transition::ObjectTransitionReason::Move,
            )?;
            self.state.players[owner_index].exile.push(card);
            "exile"
        } else {
            if self.put_known_source_card_into_graveyard(
                owner_index,
                card,
                movement_source.as_ref().ok_or_else(|| {
                    EngineError::new("physical stack departure lacks source identity")
                })?,
            )? {
                graveyard_card = Some(
                    self.state.players[owner_index]
                        .graveyard
                        .last()
                        .filter(|card| card.instance_id == card_id)
                        .ok_or_else(|| {
                            EngineError::new("countered spell destination commitment disappeared")
                        })?
                        .clone(),
                );
                "graveyard"
            } else {
                "exile"
            }
        };
        self.record_event(
            "spellCountered",
            Some(controller.clone()),
            Some(card_id.clone()),
            json!({
                "destination": destination,
                "objectKind": object_kind,
                "source": source,
                "counterSourceControllerId": source_controller,
                "stackId": stack_id,
            }),
        );
        if let Some(graveyard_card) = graveyard_card {
            self.enqueue_cards_entered_graveyard_triggers_from(
                &graveyard_owner,
                std::slice::from_ref(&graveyard_card),
                "stack",
            );
        }
        if spell_copy {
            self.record_event(
                "spellCopyCeasedToExist",
                Some(controller),
                Some(card_id),
                json!({ "zone": "stack" }),
            );
        }
        Ok(())
    }

    fn counter_spell(
        &mut self,
        stack_id: &str,
        source: &str,
        source_controller: &str,
        exile_instead: bool,
    ) -> Result<(), EngineError> {
        let is_spell = self
            .state
            .stack
            .iter()
            .find(|object| object.id == stack_id)
            .is_some_and(stack_object_is_spell);
        if !is_spell {
            return Ok(());
        }
        self.counter_stack_object(stack_id, source, source_controller, exile_instead)
    }

    fn choose_resolution_objects<P: DecisionProvider>(
        &mut self,
        stack_object: &StackObject,
        provider: &mut P,
        chooser_id: &str,
        decision_name: &str,
        candidates: Vec<String>,
        minimum: usize,
        maximum: usize,
        prompt: &str,
    ) -> Result<Vec<String>, EngineError> {
        let maximum = maximum.min(candidates.len());
        if minimum > maximum {
            return Ok(Vec::new());
        }
        let cardinalities = (minimum..=maximum).rev().collect::<Vec<_>>();
        let mut values = Vec::new();
        for (cardinality_index, count) in cardinalities.iter().enumerate() {
            let reserved_for_smaller_counts =
                cardinalities.len().saturating_sub(cardinality_index + 1);
            let selection_capacity = 128usize
                .saturating_sub(values.len())
                .saturating_sub(reserved_for_smaller_counts)
                .max(1);
            values.extend(Self::resolution_selections(
                &candidates,
                *count,
                selection_capacity,
            ));
            if values.len() >= 128 {
                break;
            }
        }
        values.sort_by_key(Vec::len);
        values.dedup();
        if values.is_empty() {
            return Ok(Vec::new());
        }
        let decision_id = format!(
            "{decision_name}:{}:{}",
            stack_object.id,
            self.state.events.len()
        );
        let mut decisions = BTreeMap::new();
        self.make_resolution_decision(
            &decision_id,
            chooser_id,
            stack_object,
            DecisionChoice::CardSelection {
                decision_id: decision_id.clone(),
                candidate_card_instance_ids: candidates,
                minimum,
                maximum,
                prompt: prompt.to_string(),
            },
            values,
            &mut decisions,
            provider,
        )?;
        Ok(decisions
            .get(&decision_id)
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(Value::as_str)
            .map(ToOwned::to_owned)
            .collect())
    }

    fn choose_resolution_player<P: DecisionProvider>(
        &mut self,
        stack_object: &StackObject,
        provider: &mut P,
        chooser_id: &str,
        opponents_only: bool,
        optional: bool,
        prompt: &str,
    ) -> Result<Option<String>, EngineError> {
        let candidates = self
            .state
            .players
            .iter()
            .filter(|player| {
                !player.has_lost && (!opponents_only || player.id != stack_object.controller)
            })
            .map(|player| player.id.clone())
            .collect::<Vec<_>>();
        if candidates.is_empty() {
            return Ok(None);
        }
        let decision_id = format!(
            "choosePlayer:{}:{}",
            stack_object.id,
            self.state.events.len()
        );
        let mut values = candidates
            .iter()
            .cloned()
            .map(|candidate| vec![candidate])
            .collect::<Vec<_>>();
        if optional {
            values.insert(0, Vec::new());
        }
        let mut decisions = BTreeMap::new();
        self.make_resolution_decision(
            &decision_id,
            chooser_id,
            stack_object,
            DecisionChoice::OptionSelection {
                decision_id: decision_id.clone(),
                options: candidates,
                prompt: prompt.to_string(),
            },
            values,
            &mut decisions,
            provider,
        )?;
        Ok(decisions
            .get(&decision_id)
            .and_then(Value::as_array)
            .and_then(|values| values.first())
            .and_then(Value::as_str)
            .map(ToOwned::to_owned))
    }

    fn choose_resolution_option<P: DecisionProvider>(
        &mut self,
        stack_object: &StackObject,
        provider: &mut P,
        chooser_id: &str,
        options: Vec<String>,
        prompt: &str,
    ) -> Result<Option<String>, EngineError> {
        if options.is_empty() {
            return Ok(None);
        }
        let decision_id = format!(
            "chooseOption:{}:{}",
            stack_object.id,
            self.state.events.len()
        );
        let values = options
            .iter()
            .cloned()
            .map(|option| vec![option])
            .collect::<Vec<_>>();
        let mut decisions = BTreeMap::new();
        self.make_resolution_decision(
            &decision_id,
            chooser_id,
            stack_object,
            DecisionChoice::OptionSelection {
                decision_id: decision_id.clone(),
                options,
                prompt: prompt.to_string(),
            },
            values,
            &mut decisions,
            provider,
        )?;
        Ok(decisions
            .get(&decision_id)
            .and_then(Value::as_array)
            .and_then(|values| values.first())
            .and_then(Value::as_str)
            .map(ToOwned::to_owned))
    }

    fn choose_creature_type_for_resolution<P: DecisionProvider>(
        &mut self,
        stack_object: &StackObject,
        provider: &mut P,
        chooser_id: &str,
        prompt: &str,
        explicit_options: Option<&Value>,
    ) -> Result<Option<String>, EngineError> {
        let creature_types = nominal_choices::creature_type_options(explicit_options)?;
        self.choose_resolution_option(
            stack_object,
            provider,
            chooser_id,
            creature_types.into_iter().collect(),
            prompt,
        )
    }

    fn confirm_resolution_action<P: DecisionProvider>(
        &mut self,
        stack_object: &StackObject,
        provider: &mut P,
        chooser_id: &str,
        label: &str,
    ) -> Result<bool, EngineError> {
        Ok(self
            .choose_resolution_option(
                stack_object,
                provider,
                chooser_id,
                vec!["Decline".to_string(), label.to_string()],
                label,
            )?
            .as_deref()
            == Some(label))
    }

