    fn transform_permanent(
        &mut self,
        instance_id: &str,
        requested_face_index: Option<usize>,
    ) -> Option<CardInstance> {
        let (player_index, card_index) = self.permanent_position(instance_id)?;
        let card = &mut self.state.players[player_index].battlefield[card_index];
        let current_face_index =
            usize::from(card.flags.get("transformed").copied().unwrap_or(false));
        let face_index = requested_face_index.unwrap_or(1usize.saturating_sub(current_face_index));
        if face_index == current_face_index {
            return None;
        }
        if !apply_card_face(card, face_index) {
            if face_index == 0 {
                card.flags.remove("transformed");
            } else {
                card.flags.insert("transformed".to_string(), true);
            }
        }
        Some(card.clone())
    }

    fn enqueue_permanent_transformed_triggers(&mut self, source: &CardInstance) {
        let rules = self
            .effective_rules(&source)
            .iter()
            .filter(|rule| {
                triggered_rule_supported(rule)
                    && triggered_event_variants(&rule["event"])
                        .iter()
                        .any(|event| value_kind(event) == Some("permanentTransformed"))
            })
            .cloned()
            .collect::<Vec<_>>();
        for rule in rules {
            self.put_triggered_ability_on_stack(source, rule);
            if self.check_quantity_failure().is_err() {
                return;
            }
        }
    }

    fn enqueue_turned_face_up_triggers(&mut self, source: &CardInstance) {
        self.publish_turned_face_up_observers(source);
    }

    fn selected_mode(stack_object: &StackObject, decision_id: &str, mode: &str) -> bool {
        stack_object.decisions[decision_id]
            .as_array()
            .is_some_and(|values| values.iter().any(|value| value.as_str() == Some(mode)))
    }

    fn target_permanent_id(stack_object: &StackObject, target_id: &str) -> Option<String> {
        stack_object
            .targets
            .get(target_id)
            .and_then(|target| match target {
                TargetRef::Permanent { instance_id } => Some(instance_id.clone()),
                _ => None,
            })
    }

    fn change_permanent_controller(
        &mut self,
        instance_id: &str,
        new_controller: &str,
    ) -> Result<Option<String>, EngineError> {
        let Some((current_player_index, card_index)) = self.permanent_position(instance_id) else {
            return Ok(None);
        };
        let original_controller = self.state.players[current_player_index].battlefield[card_index]
            .controller
            .clone();
        if original_controller == new_controller {
            return Ok(Some(original_controller));
        }
        let mut permanent = self.state.players[current_player_index]
            .battlefield
            .remove(card_index);
        permanent.flags.remove("suspendedCastHaste");
        if permanent.definition.printed_rules().iter().any(|rule| {
            value_kind(rule) == Some("triggeredAbility")
                && value_kind(&rule["condition"]) == Some("sourceNeedsEcho")
        }) {
            permanent.flags.insert(ECHO_DUE_FLAG.to_string(), true);
        }
        permanent.controller = new_controller.to_string();
        permanent.summoning_sick = true;
        let new_controller_index = self.player_index(new_controller)?;
        self.state.players[new_controller_index]
            .battlefield
            .push(permanent);
        Ok(Some(original_controller))
    }

    fn stack_target_candidates(
        &self,
        stack_object: &StackObject,
        target_id: &str,
    ) -> Vec<TargetRef> {
        self.retarget_candidates_for_stack_target(stack_object, target_id)
    }

    fn choose_stack_target<P: DecisionProvider>(
        &mut self,
        target_stack_id: &str,
        target_id: &str,
        chooser_id: &str,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        let Some(stack_object) = self
            .state
            .stack
            .iter()
            .find(|object| object.id == target_stack_id)
            .cloned()
        else {
            return Ok(());
        };
        let candidates = self.stack_target_candidates(&stack_object, target_id);
        if candidates.is_empty() {
            return Ok(());
        }
        let labels = candidates
            .iter()
            .map(|target| match target {
                TargetRef::Player { player_id } => format!("player:{player_id}"),
                TargetRef::Permanent { instance_id } => format!("permanent:{instance_id}"),
                TargetRef::Card { instance_id } => format!("card:{instance_id}"),
                TargetRef::StackObject { stack_id } => format!("stack:{stack_id}"),
            })
            .collect::<Vec<_>>();
        let Some(selected) = self.choose_resolution_option(
            &stack_object,
            provider,
            chooser_id,
            labels.clone(),
            "Choose a legal target.",
        )?
        else {
            return Ok(());
        };
        let Some(selected_index) = labels.iter().position(|label| label == &selected) else {
            return Ok(());
        };
        let selected_target = candidates[selected_index].clone();
        let mut recaptured_decisions = stack_object.decisions.clone();
        self.capture_target_incarnation(&mut recaptured_decisions, target_id, &selected_target)?;
        let previous_targets = stack_object.targets.clone();
        let mut current_targets = previous_targets.clone();
        current_targets.insert(target_id.to_string(), selected_target.clone());
        self.validate_target_cost_programs(&stack_object.controller, &current_targets)?;
        if let Some(target_object) = self
            .state
            .stack
            .iter_mut()
            .find(|object| object.id == target_stack_id)
        {
            target_object.decisions = recaptured_decisions;
            target_object
                .targets
                .insert(target_id.to_string(), selected_target.clone());
        }
        let newly_targeted =
            targeting_triggers::newly_targeted_identities(&previous_targets, &current_targets);
        if !newly_targeted.is_empty() {
            self.enqueue_targeting_triggers(target_stack_id, &newly_targeted)?;
        }
        Ok(())
    }

    fn choose_new_targets_for_copy<P: DecisionProvider>(
        &mut self,
        stack_id: &str,
        chooser_id: &str,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        let target_ids = self
            .state
            .stack
            .iter()
            .find(|object| object.id == stack_id)
            .map(|object| object.targets.keys().cloned().collect::<Vec<_>>())
            .unwrap_or_default();
        for target_id in target_ids {
            self.choose_stack_target(stack_id, &target_id, chooser_id, provider)?;
        }
        Ok(())
    }

    fn goad_permanent(&mut self, instance_id: &str, goading_player_id: &str) {
        self.state.rule_modifiers.retain(|modifier| {
            value_kind(modifier) != Some("goaded")
                || modifier["objectId"].as_str() != Some(instance_id)
                || modifier["goadingPlayerId"].as_str() != Some(goading_player_id)
        });
        self.state.rule_modifiers.push(json!({
            "kind": "goaded",
            "objectId": instance_id,
            "goadingPlayerId": goading_player_id,
            "expiresAtTurnOfPlayer": goading_player_id,
            "installedTurn": self.state.turn_number,
        }));
    }

    fn venture_into_dungeon<P: DecisionProvider>(
        &mut self,
        stack_object: &StackObject,
        provider: &mut P,
        player_id: &str,
        entry_procedure: Option<&str>,
    ) -> Result<(), EngineError> {
        // Load outside-game definitions only when needed. Ordinary games must
        // not parse/serialize four unused dungeons in every observation/frame.
        for dungeon in crate::model::builtin_dungeon_definitions().map_err(EngineError::new)? {
            if !self
                .state
                .game_pieces
                .iter()
                .any(|piece| piece.name.eq_ignore_ascii_case(&dungeon.name))
            {
                self.state.game_pieces.push(dungeon.clone());
            }
        }
        let current_position = self.state.rule_modifiers.iter().find_map(|modifier| {
            (value_kind(modifier) == Some("dungeonPosition")
                && modifier["playerId"].as_str() == Some(player_id))
            .then(|| {
                Some((
                    modifier["dungeonId"].as_str()?.to_string(),
                    modifier["room"].as_str()?.to_string(),
                ))
            })
            .flatten()
        });

        let (dungeon, room_name) = if let Some((dungeon_id, current_room)) = current_position {
            let Some(dungeon) = self
                .state
                .game_pieces
                .iter()
                .find(|piece| piece.id == dungeon_id)
                .cloned()
            else {
                return Ok(());
            };
            let next_rooms = dungeon
                .printed_rules()
                .iter()
                .find(|rule| {
                    value_kind(rule) == Some("dungeonRoom")
                        && rule["room"].as_str() == Some(current_room.as_str())
                })
                .and_then(|rule| rule["nextRooms"].as_array())
                .map(|rooms| {
                    rooms
                        .iter()
                        .filter_map(Value::as_str)
                        .map(ToOwned::to_owned)
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            if next_rooms.is_empty() {
                return Ok(());
            }
            let room_name = if next_rooms.len() == 1 {
                next_rooms[0].clone()
            } else {
                self.choose_resolution_option(
                    stack_object,
                    provider,
                    player_id,
                    next_rooms.clone(),
                    "Choose the next Dungeon room.",
                )?
                .unwrap_or_else(|| next_rooms[0].clone())
            };
            (dungeon, room_name)
        } else {
            let dungeons = self
                .state
                .game_pieces
                .iter()
                .filter(|piece| {
                    if !has_card_type(piece, "Dungeon") {
                        return false;
                    }
                    let restriction = piece.printed_rules().iter().find_map(|rule| {
                        (value_kind(rule) == Some("staticAbility"))
                            .then(|| rule["modifiers"].as_array())
                            .flatten()?
                            .iter()
                            .find(|modifier| {
                                value_kind(modifier) == Some("dungeonEntryRestriction")
                            })
                            .and_then(|modifier| modifier["procedure"].as_str())
                    });
                    match entry_procedure {
                        None => restriction.is_none(),
                        Some(procedure) => restriction
                            .is_some_and(|required| required.eq_ignore_ascii_case(procedure)),
                    }
                })
                .cloned()
                .collect::<Vec<_>>();
            if dungeons.is_empty() {
                self.record_event(
                    "dungeonVentureUnavailable",
                    Some(player_id.to_string()),
                    Some(stack_object.card.instance_id.clone()),
                    json!({ "reason": "noDungeonGamePiece" }),
                );
                return Ok(());
            }
            let names = dungeons
                .iter()
                .map(|dungeon| dungeon.name.clone())
                .collect::<Vec<_>>();
            let selected_name = if names.len() == 1 {
                names[0].clone()
            } else {
                self.choose_resolution_option(
                    stack_object,
                    provider,
                    player_id,
                    names.clone(),
                    "Choose a Dungeon to enter.",
                )?
                .unwrap_or_else(|| names[0].clone())
            };
            let dungeon = dungeons
                .into_iter()
                .find(|dungeon| dungeon.name == selected_name)
                .unwrap_or_else(|| self.state.game_pieces[0].clone());
            let Some(room_name) = dungeon.printed_rules().iter().find_map(|rule| {
                (value_kind(rule) == Some("dungeonRoom"))
                    .then(|| rule["room"].as_str().map(ToOwned::to_owned))
                    .flatten()
            }) else {
                return Ok(());
            };
            (dungeon, room_name)
        };

        let Some(room_rule) = dungeon
            .printed_rules()
            .iter()
            .find(|rule| {
                value_kind(rule) == Some("dungeonRoom")
                    && rule["room"].as_str() == Some(room_name.as_str())
            })
            .cloned()
        else {
            return Ok(());
        };
        let completed = room_rule["nextRooms"].as_array().is_none_or(Vec::is_empty);
        self.state.rule_modifiers.retain(|modifier| {
            value_kind(modifier) != Some("dungeonPosition")
                || modifier["playerId"].as_str() != Some(player_id)
        });
        if !completed {
            self.state.rule_modifiers.push(json!({
                "kind": "dungeonPosition",
                "playerId": player_id,
                "dungeonId": dungeon.id,
                "room": room_name,
            }));
        }

        if room_rule["effects"]
            .as_array()
            .is_some_and(|effects| effects.iter().all(effect_supported))
        {
            let mut trigger_rule = json!({
                "kind": "triggeredAbility",
                "source": { "kind": "self" },
                "event": { "kind": "dungeonRoomEntered", "player": { "kind": "abilityController" } },
                "effects": room_rule["effects"],
            });
            if let Some(declaration) = room_rule.get("declaration") {
                trigger_rule["declaration"] = declaration.clone();
            }
            let source = card_instance(player_id, &dungeon, usize::MAX);
            self.put_triggered_ability_on_stack_with_decisions(
                &source,
                trigger_rule,
                BTreeMap::new(),
            );
            self.check_quantity_failure()?;
        } else {
            self.record_event(
                "dungeonRoomEffectUnsupported",
                Some(player_id.to_string()),
                Some(dungeon.id.clone()),
                json!({ "dungeon": dungeon.name, "room": room_name }),
            );
        }
        self.record_event(
            "dungeonRoomEntered",
            Some(player_id.to_string()),
            Some(dungeon.id.clone()),
            json!({ "dungeon": dungeon.name, "room": room_name, "completed": completed }),
        );
        if completed {
            self.enqueue_dungeon_completed_triggers(player_id, &dungeon.id);
        }
        Ok(())
    }

    fn reveal_creatures_to_battlefield<P: DecisionProvider>(
        &mut self,
        player_id: &str,
        count: usize,
        source_id: &str,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        let player_index = self.player_index(player_id)?;
        // Find the reveal prefix without temporarily changing the logical
        // library used by active conditions. The reverse order matches pop().
        let mut reveal_count = 0;
        let mut creature_count = 0;
        for card in self.state.players[player_index].library.iter().rev() {
            if creature_count >= count {
                break;
            }
            reveal_count += 1;
            if has_card_type(&card.definition, "Creature") {
                creature_count += 1;
            }
        }
        let split = self.state.players[player_index].library.len() - reveal_count;
        // Preserve the historical event-ID order (noncreatures, creatures),
        // while revealing without temporarily changing the logical library.
        let selected = &self.state.players[player_index].library[split..];
        let card_ids = selected
            .iter()
            .rev()
            .filter(|card| !has_card_type(&card.definition, "Creature"))
            .chain(
                selected
                    .iter()
                    .rev()
                    .filter(|card| has_card_type(&card.definition, "Creature")),
            )
            .map(|card| card.instance_id.clone())
            .collect::<Vec<_>>();
        let mut movement_sources = card_ids
            .iter()
            .map(|id| {
                self.prepare_card_movement_source(id, None)?
                    .map(|source| (id.clone(), source))
                    .ok_or_else(|| EngineError::new("revealed card source identity is missing"))
            })
            .collect::<Result<BTreeMap<_, _>, EngineError>>()?;
        self.record_event(
            "cardsRevealed",
            Some(player_id.to_string()),
            Some(source_id.to_string()),
            json!({ "cardIds": card_ids }),
        );
        // Entry follows revealing, but precedes removal from the library.
        let entry_policy = self.capture_zone_entry_policy();
        let selected = self.state.players[player_index].library.split_off(split);
        let mut revealed = Vec::new();
        let mut creatures = Vec::new();
        for card in selected.into_iter().rev() {
            if has_card_type(&card.definition, "Creature") {
                creatures.push(card);
            } else {
                revealed.push(card);
            }
        }
        // The reveal still finds/counts these creatures. Prohibited cards
        // remain in the library and take part in the instruction's shuffle;
        // they never produce a departure or battlefield-entry notification.
        let (creatures, prohibited): (Vec<_>, Vec<_>) = creatures.into_iter().partition(|card| {
            !entry_policy
                .admission(&card.definition, "library")
                .is_prohibited()
        });
        revealed.extend(prohibited);
        self.state.players[player_index].library.extend(revealed);
        self.state.players[player_index]
            .library
            .shuffle(&mut self.rng);
        for mut card in creatures {
            card.controller = player_id.to_string();
            card.summoning_sick = true;
            self.apply_enter_replacements(&mut card, provider)?;
            let movement_source = movement_sources
                .remove(&card.instance_id)
                .ok_or_else(|| EngineError::new("revealed entrant source identity is missing"))?;
            self.commit_card_zone_transition(
                &mut card,
                &movement_source,
                &card_zone_transition::ObjectZone::Battlefield,
                card_zone_transition::ObjectTransitionReason::Move,
            )?;
            let trigger_source = card.clone();
            self.state.players[player_index].battlefield.push(card);
            self.enqueue_enter_battlefield_triggers(&trigger_source);
        }
        Ok(())
    }

    fn become_monarch(&mut self, player_id: &str) {
        self.state
            .rule_modifiers
            .retain(|modifier| value_kind(modifier) != Some("monarch"));
        self.state.rule_modifiers.push(json!({
            "kind": "monarch",
            "playerId": player_id,
        }));
        self.record_event(
            "becameMonarch",
            Some(player_id.to_string()),
            None,
            json!({}),
        );
    }

    fn draw_monarch_card<P: DecisionProvider>(
        &mut self,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        let monarch = self.state.rule_modifiers.iter().find_map(|modifier| {
            (value_kind(modifier) == Some("monarch"))
                .then(|| modifier["playerId"].as_str().map(ToOwned::to_owned))
                .flatten()
        });
        if let Some(player_id) = monarch {
            self.draw_cards_with_replacements(&player_id, 1, provider)?;
        }
        Ok(())
    }

    fn process_synthetic_destiny<P: DecisionProvider>(
        &mut self,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        let required = self.state.rule_modifiers.iter().any(|modifier| {
            matches!(value_kind(modifier), Some("syntheticDestinyReturn"))
                && modifier["notBeforeTurn"]
                    .as_u64()
                    .is_none_or(|turn| turn <= u64::from(self.state.turn_number))
        });
        self.with_replacement_checkpoint(required, |engine| {
            engine.process_synthetic_destiny_identity_inner(provider)
        })
    }

    fn process_synthetic_destiny_identity_inner<P: DecisionProvider>(
        &mut self,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        let entries = self
            .state
            .rule_modifiers
            .iter()
            .filter(|modifier| value_kind(modifier) == Some("syntheticDestinyReturn"))
            .filter(|modifier| {
                modifier["notBeforeTurn"]
                    .as_u64()
                    .is_none_or(|turn| turn <= u64::from(self.state.turn_number))
            })
            .filter_map(|modifier| {
                Some((
                    modifier["playerId"].as_str()?.to_string(),
                    modifier["count"].as_u64()? as usize,
                    modifier["sourceCardInstanceId"].as_str()?.to_string(),
                ))
            })
            .collect::<Vec<_>>();
        self.state.rule_modifiers.retain(|modifier| {
            value_kind(modifier) != Some("syntheticDestinyReturn")
                || !entries.iter().any(|(player_id, _, source_id)| {
                    modifier["playerId"].as_str() == Some(player_id.as_str())
                        && modifier["sourceCardInstanceId"].as_str() == Some(source_id.as_str())
                })
        });
        for (player_id, count, source_id) in entries {
            self.reveal_creatures_to_battlefield(&player_id, count, &source_id, provider)?;
        }
        Ok(())
    }

    fn process_end_step_sacrifices<P: DecisionProvider>(
        &mut self,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        // Payment discovery may reject a source context. Snapshot before the
        // scheduler is consumed, so unsupported is never treated as decline.
        let fallible_payment = self.state.rule_modifiers.iter().any(|modifier| {
            matches!(
                value_kind(modifier),
                Some("ashlingPayOrSacrificeAtEndStep" | "sacrificeAtEndStep")
            ) && modifier["notBeforeTurn"]
                .as_u64()
                .is_none_or(|turn| turn <= u64::from(self.state.turn_number))
        });
        self.with_replacement_checkpoint(fallible_payment, |engine| {
            engine.process_end_step_sacrifices_checked_inner(provider)
        })
    }

    fn process_end_step_sacrifices_checked_inner<P: DecisionProvider>(
        &mut self,
        provider: &mut P,
    ) -> Result<(), EngineError> {
        let turn_number = self.state.turn_number;
        let ashling_entries = self
            .state
            .rule_modifiers
            .iter()
            .filter(|modifier| {
                value_kind(modifier) == Some("ashlingPayOrSacrificeAtEndStep")
                    && modifier["notBeforeTurn"]
                        .as_u64()
                        .is_none_or(|turn| turn <= u64::from(turn_number))
            })
            .filter_map(|modifier| {
                Some((
                    modifier["cardInstanceId"].as_str()?.to_string(),
                    modifier["playerId"].as_str()?.to_string(),
                    modifier["manaCost"].as_str()?.to_string(),
                ))
            })
            .collect::<Vec<_>>();
        self.state.rule_modifiers.retain(|modifier| {
            value_kind(modifier) != Some("ashlingPayOrSacrificeAtEndStep")
                || !ashling_entries.iter().any(|(instance_id, _, _)| {
                    modifier["cardInstanceId"].as_str() == Some(instance_id.as_str())
                })
        });
        for (instance_id, player_id, mana_cost) in ashling_entries {
            if self.permanent_position(&instance_id).is_none() {
                continue;
            }
            let player_index = self.player_index(&player_id)?;
            let payment = mana_discovery_session::ManaDiscoverySession::new(self)
                .payment_for_mana_costs(
                    player_index,
                    std::slice::from_ref(&mana_cost),
                    &BTreeSet::new(),
                    None,
                )?;
            let mut options = vec![LegalAction {
                id: format!("ashlingSacrifice:{instance_id}"),
                kind: ActionKind::ChooseResolution,
                player_id: player_id.clone(),
                label: "Sacrifice the Elemental token".to_string(),
                card_instance_id: Some(instance_id.clone()),
                payment_sources: Vec::new(),
                decisions: BTreeMap::new(),
                targets: BTreeMap::new(),
                target_order: Vec::new(),
                attacker_id: None,
                blocker_id: None,
            }];
            if let Some(payment) = payment {
                options.push(LegalAction {
                    id: format!("ashlingPay:{instance_id}"),
                    kind: ActionKind::ChooseResolution,
                    player_id: player_id.clone(),
                    label: format!("Pay {mana_cost}"),
                    card_instance_id: Some(instance_id.clone()),
                    payment_sources: Vec::new(),
                    decisions: BTreeMap::from([(
                        "manaPayment".to_string(),
                        mana_payment_decision(&payment),
                    )]),
                    targets: BTreeMap::new(),
                    target_order: Vec::new(),
                    attacker_id: None,
                    blocker_id: None,
                });
            }
            let choice = self.choose_action(
                provider,
                EngineDecisionRequest {
                    id: format!("ashlingEndStep:{instance_id}"),
                    kind: DecisionKind::ResolutionChoice,
                    player_id: player_id.clone(),
                    source_card: self.permanent_position(&instance_id).map(
                        |(player_index, card_index)| {
                            self.state.players[player_index].battlefield[card_index].clone()
                        },
                    ),
                    source_card_instance_id: Some(instance_id.clone()),
                    choice: None,
                    options,
                },
            )?;
            if choice.id.starts_with("ashlingPay:") {
                let sources = self.apply_payment(player_index, &choice)?;
                for source in sources {
                    self.enqueue_permanent_tapped_triggers(&source);
                }
            } else {
                self.move_permanent_to_graveyard(&instance_id, "sacrificed")?;
            }
        }
        let instance_ids = self
            .state
            .rule_modifiers
            .iter()
            .filter(|modifier| {
                value_kind(modifier) == Some("sacrificeAtEndStep")
                    && modifier["notBeforeTurn"]
                        .as_u64()
                        .is_none_or(|turn| turn <= u64::from(turn_number))
            })
            .filter_map(|modifier| modifier["cardInstanceId"].as_str().map(ToOwned::to_owned))
            .collect::<Vec<_>>();
        self.state.rule_modifiers.retain(|modifier| {
            value_kind(modifier) != Some("sacrificeAtEndStep")
                || !instance_ids
                    .iter()
                    .any(|instance_id| modifier["cardInstanceId"].as_str() == Some(instance_id))
        });
        for instance_id in instance_ids {
            self.move_permanent_to_graveyard(&instance_id, "sacrificed")?;
        }
        Ok(())
    }

    fn process_end_step_dash_returns(&mut self) -> Result<(), EngineError> {
        let required = self.state.rule_modifiers.iter().any(|modifier| {
            matches!(
                value_kind(modifier),
                Some("returnToHandAtEndStep" | "returnGraveyardCardToHandAtEndStep")
            ) && modifier["notBeforeTurn"]
                .as_u64()
                .is_none_or(|turn| turn <= u64::from(self.state.turn_number))
        });
        self.with_replacement_checkpoint(required, |engine| {
            engine.process_end_step_dash_returns_identity_inner()
        })
    }

    fn process_end_step_dash_returns_identity_inner(&mut self) -> Result<(), EngineError> {
        let turn_number = self.state.turn_number;
        let instance_ids = self
            .state
            .rule_modifiers
            .iter()
            .filter(|modifier| {
                value_kind(modifier) == Some("returnToHandAtEndStep")
                    && modifier["notBeforeTurn"]
                        .as_u64()
                        .is_none_or(|turn| turn <= u64::from(turn_number))
            })
            .filter_map(|modifier| modifier["cardInstanceId"].as_str().map(ToOwned::to_owned))
            .collect::<Vec<_>>();
        self.state.rule_modifiers.retain(|modifier| {
            value_kind(modifier) != Some("returnToHandAtEndStep")
                || !instance_ids
                    .iter()
                    .any(|instance_id| modifier["cardInstanceId"].as_str() == Some(instance_id))
        });
        for instance_id in instance_ids {
            self.return_permanent_to_hand(&instance_id)?;
        }
        let graveyard_ids = self
            .state
            .rule_modifiers
            .iter()
            .filter(|modifier| {
                value_kind(modifier) == Some("returnGraveyardCardToHandAtEndStep")
                    && modifier["notBeforeTurn"]
                        .as_u64()
                        .is_none_or(|turn| turn <= u64::from(turn_number))
            })
            .filter_map(|modifier| modifier["cardInstanceId"].as_str().map(ToOwned::to_owned))
            .collect::<Vec<_>>();
        self.state.rule_modifiers.retain(|modifier| {
            value_kind(modifier) != Some("returnGraveyardCardToHandAtEndStep")
                || !graveyard_ids
                    .iter()
                    .any(|instance_id| modifier["cardInstanceId"].as_str() == Some(instance_id))
        });
        for instance_id in graveyard_ids {
            let found = self
                .prepare_card_movement_source(&instance_id, None)?
                .filter(|source| {
                    matches!(source.zone, card_zone_transition::ObjectZone::Graveyard(_))
                })
                .map(|source| self.take_prepared_movement_card(source))
                .transpose()?;
            if let Some(card) = found {
                let owner_index = self.player_index(&card.owner)?;
                self.put_owned_cards_in_owners_private_zones(
                    vec![card],
                    card_movement::PrivateZoneDestination::Hand,
                )?;
            }
        }
        Ok(())
    }

    fn process_end_step_warp(&mut self) -> Result<(), EngineError> {
        let required = self.state.rule_modifiers.iter().any(|modifier| {
            matches!(value_kind(modifier), Some("warpExileAtEndStep"))
                && modifier["notBeforeTurn"]
                    .as_u64()
                    .is_none_or(|turn| turn <= u64::from(self.state.turn_number))
        });
        self.with_replacement_checkpoint(required, |engine| {
            engine.process_end_step_warp_identity_inner()
        })
    }

    fn process_end_step_warp_identity_inner(&mut self) -> Result<(), EngineError> {
        let turn_number = self.state.turn_number;
        let instance_ids = self
            .state
            .rule_modifiers
            .iter()
            .filter(|modifier| {
                value_kind(modifier) == Some("warpExileAtEndStep")
                    && modifier["notBeforeTurn"]
                        .as_u64()
                        .is_none_or(|turn| turn <= u64::from(turn_number))
            })
            .filter_map(|modifier| modifier["cardInstanceId"].as_str().map(ToOwned::to_owned))
            .collect::<Vec<_>>();
        self.state.rule_modifiers.retain(|modifier| {
            value_kind(modifier) != Some("warpExileAtEndStep")
                || !instance_ids
                    .iter()
                    .any(|instance_id| modifier["cardInstanceId"].as_str() == Some(instance_id))
        });
        for instance_id in instance_ids {
            let Some((player_index, card_index)) = self.permanent_position(&instance_id) else {
                continue;
            };
            let owner_id = self.state.players[player_index].battlefield[card_index]
                .owner
                .clone();
            self.exile_permanent(&instance_id)?;
            let permission = json!({
                "kind": "warpPermission",
                "action": "play",
                "cardInstanceId": instance_id,
                "normalCostsApply": true,
                "normalTimingApplies": true,
                "playerId": owner_id,
            });
            self.state.permissions.push(permission.clone());
            self.record_event(
                "warpPermissionGranted",
                Some(owner_id),
                Some(instance_id),
                permission,
            );
        }
        Ok(())
    }

